import type { Song } from './types';

export const songs: Song[] = [
  {"number": 1, "name": "Murinzi We, Vuz’ Impanda", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/1", "key": "si bémol", "references": [{"codes": "SDAH. 368"}, {"codes": "CS. 683"}, {"title": "WATCHMAN, BLOW THE GOSPEL TRUMPET"}, {"codes": "AH. 350"}, {"codes": "CH. 619"}], "body": [{"type": "verse", "number": 1, "content": "Murinzi, jy‘ uvuz’ impanda, Uhan’ umuntu wese;\nNg’ uzumv’ izo nkuru nziza, Yihan’ akizw’ ibyaha."}, {"type": "chorus", "content": "Murinzi we vuz’ impanda!\nYivuze cyane hose (hose),\nMenyesha bos’ ubutumwa,\nImbohe zibohorwe."}, {"type": "verse", "number": 2, "content": "Yivugirize mu mpinga, Mw’ ishyamba mu gisiza;\nNdetse no mu nyanja hose, Bameny’ ako gakiza."}, {"type": "verse", "number": 3, "content": "Yivugirize mu nzira, Mu rwiherero hose.\nDat’ arabategereje, Ntacy’ ataringanije."}, {"type": "verse", "number": 4, "content": "Uyivugiriz‘ indembe, Nazo zikizw’ ibyaha.\nYes’ arabatumir’ ati: Nimuze mbaboneze."}]},
  {"number": 2, "name": "Umwam’ Ageze Kw’ Irembo", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/2", "key": "sol", "references": [{"codes": "CS. 930"}, {"codes": "AH. 411"}, {"title": "THE COMING KING IS AT THE DOOR"}, {"codes": "CH. 546"}], "body": [{"type": "verse", "number": 1, "content": "Umwam’ ageze kw‘ irembo, Wabambwe ku musaraba;\nYaje gukorany’ abera, Babane mw‘ ijuru."}, {"type": "chorus", "content": "Kw‘ irembo (Kw‘ irembo), Kw‘ irembo (Kw‘ irembo),\nKw‘ irembo, Ub‘ ari kw‘ irembo;\nNukw‘ araje (araje), Nukw‘ araje (araje),\nKand‘ ageze kw‘ irembo."}, {"type": "verse", "number": 2, "content": "Ibyerekana kuza kwe, Birihuta kuboneka;\nKandi tugiye guhabwa, Kubaho kw‘ iteka."}, {"type": "verse", "number": 3, "content": "Ntabw’ intambar’ izashira, Ntabw’ amahor‘ azahora,\nKerek’ ibyaha n’ urupfu, Byatsembwe na Yesu."}, {"type": "verse", "number": 4, "content": "Maze mw‘ isi yagizwe nshya, Niho tuzabahw‘ iteka;\nKudapfa kwakuye gupfa, Dushiz’ agahinda."}]},
  {"number": 3, "name": "Nzabona Yesu", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/3", "key": "si bémol", "references": [{"codes": "SDAH. 206"}, {"codes": "CS. 361"}, {"title": "FACE TO FACE WITH CHRIST MY SAVIOR"}, {"codes": "AH. 319"}, {"codes": "HL. 512"}], "body": [{"type": "verse", "number": 1, "content": "Nzabona Yesu mu maso, Umuns’ azatujyana;\nNiho nzamwitegereza, Kw’ ari we wampfiriye."}, {"type": "chorus", "content": "Nzamurora mu maso ye, Turi kumwe mw’ ijuru;\nMeny’ uk’ ubwiza bwe busa, Nzamusingiz’ iteka."}, {"type": "verse", "number": 2, "content": "Ubu ndamutekereza, Ariko simurora;\nUmuns’ uhiriw’ uzaza, Nzamubonan’ ubwiza."}, {"type": "verse", "number": 3, "content": "Tuzishimir’ imbere ye, Ubw’ ishavu rishize;\nIbigande biganduwe, N’ ahijimye hakeye."}, {"type": "verse", "number": 4, "content": "Nzanezererw’ imbere ye, Nzamurora mumenye;\nNzabana na Yes’ unkunda, Niwe Mukiza wanjye."}]},
  {"number": 4, "name": "Har’ Amakuru Meza", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/4", "key": "mi bémol", "references": [{"codes": "SDAH. 442"}, {"codes": "CH. 669"}, {"title": "HOW SWEET ARE THE TIDINGS"}, {"codes": "CS. 914"}], "body": [{"type": "verse", "number": 1, "content": "Har’ amakuru mez’ amenywa n’ abagenzi, Bazerera kure y’ iwabo,\nKuk’ Umukiz’ agiye kuza mu bwiza bwe, Kand’ agiye kwim’ ingoma ye."}, {"type": "chorus", "content": "Azaza, ndabizi kw’ azagaruka, Nukw’ azaza rwos’ azaza.\nAbagenzi bose barembye, Bazakir’ Umukiza naza kwima."}, {"type": "verse", "number": 2, "content": "Ibituro by’ abera bos’ uko bangana, Byose bizakingurwa rwose;\nKand’ inteko z’ abasinzira mu kuzimu, Bazongera gutura kw’ isi."}, {"type": "verse", "number": 3, "content": "Nta kizadutanya mur’ iyo si nshya nziza, Tuzaririmb’ uko twakize.\nAbacunguwe bazaba bavuye hose, Baramy’ Umwami wo mw’ ijuru."}, {"type": "verse", "number": 4, "content": "Haleluy’ amina, Haleluya iteka; Nitwitonda tuzahatura.\nBa maso nezerwa, Kand’ ujye wiringira, Maz’ uzambar’ ikamba ryiza."}]},
  {"number": 5, "name": "Murinzi We Menyesh’ Igihe", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/5", "key": "mi bémol", "references": [{"codes": "SDAH. 439"}, {"codes": "CS. 245"}, {"title": "HOW FAR FROM HOME?"}, {"codes": "AH. 114"}, {"codes": "CH. 665"}], "body": [{"type": "verse", "number": 1, "content": "Murinzi we! Menyesh’ igihe! Mbes’ iwacu n’ imuhero?\nAt’ ijoro ryijimye cyane, Ariko buracya.\nNtukarire, Gumy’ ugende, Nturorere kwiringira,\nKugez’ igih’ uzasohora, Mu muns’ uhoraho."}, {"type": "verse", "number": 2, "content": "Murwanyi we! Tyo mbwira nawe! Ansubiza yitonz’ ati:\nIntambar’ igiye gushira. Guma ku rugamba.\nWibabara, Ihangane, Wirek’ imirimo yawe,\nKuko tuzabon’ ibihembo, Tumaze gutsinda."}, {"type": "verse", "number": 3, "content": "Ndacyabaz’ ibyaremwe byose, Binsubiza bitya biti:\nIy’ is’ igiye guhanguka, Haz’ ind’ idashira.\nNtukarir’ ibimenyetso, Byerekan’ aho tugeze,\nKand’ ibintu byose byaremwe, Biriteg’ impanda."}, {"type": "verse", "number": 4, "content": "Imuhir’ ubu ni bugufi, Tunezerwe mu mitima.\nDuhumure ko tuzakira, Dushir’ agahinda.\nNtukarire tuzabana, Amakub’ azab’ ashize.\nNtabwo tuzabur’ amahoro mu rugo rwa Data."}]},
  {"number": 6, "name": "Mwebw’ Abera Mube Maso", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/6", "key": "ré bémol", "references": [{"codes": "SDAH. 598"}, {"codes": "CS. 877"}, {"title": "WATCH, YE SAINTS"}, {"codes": "AH. 415"}, {"codes": "CH. 549"}], "body": [{"type": "verse", "number": 1, "content": "Mwebw’ abera mube maso, Ibyaremwe birahinda.\nMukomez’ imuri zanyu, Mwiteg’ Umwam’ ari hafi."}, {"type": "chorus", "content": "Araje Yes’ araje! Azanye n’ icyubahiro.\nYes’ aje kwim’ ingoma Ye, Araje, Yes’ araje."}, {"type": "verse", "number": 2, "content": "Wibuk’ Umuvunyi wawe, Agakiza n’ imbabazi ,\nIkamba, icyubahiro. Jya wogez’ ako gakiza."}, {"type": "verse", "number": 3, "content": "Nta bwami budahanguka; Wumv’ amagare y’ asuma.\nBwira bos’ iby’ imbabazi, Ubu n’ igihe cy’ impuhwe."}, {"type": "verse", "number": 4, "content": "Amoko yos’ azashira; Krist’ atebuts’ Ubwami bwe;\nIs’ igiye guhanguka; Nimwishim’ abahiriwe."}, {"type": "verse", "number": 5, "content": "Banyabyaha mwe nimuze! Abitwarire kuri Se .\nMwese nimugire bwangu! Imbabazi zikiriho."}]},
  {"number": 7, "name": "Ubwo Yes’ Azagaruka", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/7", "key": "mi", "references": [{"codes": "SDAH. 218"}, {"codes": "CS. 852"}, {"title": "WHEN HE COMETH"}, {"codes": "AH. 449"}, {"codes": "CH. 418"}], "body": [{"type": "verse", "number": 1, "content": "Ubwo Yes’ azagaruka, Kujyan’ abe bose,\nBemeye kumuyoboka, N’ abatoni be."}, {"type": "chorus", "content": "Bazaka nk’ inyenyeri,\nZitatse kw‘ ikamba rye;\nBazatangaza cyane,\nBakize rwose."}, {"type": "verse", "number": 2, "content": "Ubw’ azaza gukorany’ abo yatoye bose,\nBera baboneye rwose, B’ abatoni be."}, {"type": "verse", "number": 3, "content": "Yemwe bana! Yemwe bana! Bakund’ Umukiza;\nAbakunda, abakunda, Nk’ abatoni be."}]},
  {"number": 8, "name": "Abarokots’ Ibyago Byo Hasi", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/8", "key": "la bémol", "references": [{"codes": "SDAH. 216"}, {"codes": "CS. 865"}, {"title": "WHEN THE TRUMPET"}], "body": [{"type": "verse", "number": 1, "content": "Abarokots’ ibyago byo hasi bazakoranywa, Ab’ azatumir’ azajyana na bo.\nUmwami nagaruk’ ikondera rye rizavuga, Amatek’ azab’ agiye gucibwa."}, {"type": "chorus", "content": "Azaba yabararitse (…bararitse),\nUbw’ azabahamagara (…hamagara).\nAzaba yabararitse,\nAbazatumir’ azajyana na bo."}, {"type": "verse", "number": 2, "content": "Uwo muns’ abapfuye muri Kristo bazazurwa, Bazava mu bituro nka we rwose.\nAbo yitoreye bazimana na we mw’ ijuru, Ubw’ azagenda, azajyana na bo."}, {"type": "verse", "number": 3, "content": "Ni ho tuzajya dukorer’ Umwami tudahwema; Tuzajya dusingiz’ urukundo rwe.\nMaz’ ubwo tuzarangiz’ imirimo yacu mw’ isi, Tuzateranywa tujyanwe mw’ ijuru."}]},
  {"number": 9, "name": "Vuz’ Impanda Yumvikane Hose", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/9", "key": "la", "references": [{"codes": "SDAH. 213"}, {"codes": "CS. 929"}, {"title": "LIFT UP THE TRUMPET"}, {"codes": "CH. 541"}], "body": [{"type": "verse", "number": 1, "content": "Vuz’ impanda yumvikane hose, Yesu agiye kuza!\nMuririmbe bagenzi mwishima, Yesu agiye kuza."}, {"type": "chorus", "content": "Ari hafi, Ari hafi,\nUmwam’ agiye kuza."}, {"type": "verse", "number": 2, "content": "Mujye muhererekanya hose, Yesu agiye kuza!\nAzazan’ icyubahiro cyinshi, Yesu agiye kuza."}, {"type": "verse", "number": 3, "content": "Yivugirize mu nyanja hose, Yesu agiye kuza!\nYivugirize no mu bikombe, Yesu agiye kuza."}, {"type": "verse", "number": 4, "content": "Mu misoz’ uyihavugirize, Yesu agiye kuza!\nImiyag’ ijyan’ ayo makuru, Yesu agiye kuza."}, {"type": "verse", "number": 5, "content": "Amok’ ubw’ azasubiranamo, Yesu agiye kuza!\nUbwenge bwungukwa bwerekana, Ko Yes’ agiye kuza."}]},
  {"number": 10, "name": "Duhurire Ku Mugezi", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/10", "key": "mi bémol", "references": [{"codes": "SDAH. 432"}, {"codes": "CS. 907"}, {"title": "SHALL WE GATHER AT THE RIVER?"}, {"codes": "AH. 430"}, {"codes": "CH. 555"}], "body": [{"type": "verse", "number": 1, "content": "Duhurire ku mugezi, Dusang’ abamarayika;\nAmazi yaw’ atunganye, Atemb’ av’ imbere y’ Imana."}, {"type": "chorus", "content": "Nuko tujye ku mugezi!\nDuhurire n’ abera ku mugezi!\nKu mugez’ utunganye w’ Imana,\nUtemb’ imbere y’ intebe."}, {"type": "verse", "number": 2, "content": "Ku nkombe y’ uwo mugezi, Niho tuzatambagira,\nTuramy’ Umwami w’ iteka, Mu gihe cyiza kidashira."}, {"type": "verse", "number": 3, "content": "Tuzagera ku mugezi, Dutur’ imitwaro yacu;\nTuzakirishw’ imbabazi, Duhabw’ umwambaro n’ ikamba."}, {"type": "verse", "number": 4, "content": "Ubw’ umugez’ uri hafi, Urugendo ruzashira;\nTuzishima mu mitima, N’ indirimbo z’ umunezero."}]},
  {"number": 11, "name": "Mukiza Ngukurikire", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/11", "key": "la bémol", "references": [{"codes": "SDAH. 623"}, {"codes": "CS. 409"}, {"title": "I WILL FOLLOW THEE"}, {"codes": "AH. 282"}, {"codes": "CH. 266"}], "body": [{"type": "verse", "number": 1, "content": "Mukiza ngukurikire, Ah’ unshakira hose;\nAh’ ujya ngukurikire, Mwami ngukurikire."}, {"type": "chorus", "content": "Mukiza ngukurikire,\nWamviriy’ amaraso;\nNib’ utagir’ ukwitaho,\nNjye nkwikurikirire."}, {"type": "verse", "number": 2, "content": "Nahw’ inzira yazitirwa, Naho yakukumuka,\nKo wayinyuzemo mbere, Nyicamo mfit’ ishimwe."}, {"type": "verse", "number": 3, "content": "Naho naterwa n’ ibyago, Nkageragezwa cyane,\nWarageragejwe nawe, Mwami ngukurikize."}, {"type": "verse", "number": 4, "content": "Nib’ unyobora mw’ ishavu, Niba nkena nkanenwa,\nWigeze kuba ruvumwa, Nanjye ngukurikize."}]},
  {"number": 12, "name": "Har’ Isoko", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/12", "key": "do", "references": [{"codes": "SDAH. 336"}, {"codes": "CS. 146"}, {"title": "THERE IS A FOUNTAIN"}, {"codes": "AH. 135"}, {"codes": "CH. 163"}], "body": [{"type": "verse", "number": 1, "content": "Har’ isokw’ ivamw’ amaraso, Yo mu mitsi y’ Imanuweri.\nNi y’ atungany’ abanyabyaha, Bagashirahw’ inenge,\nBagatsembwahw’ ibicumuro, Byose bikabacikaho.\nNi y’ atungany’ abanyabyaha, Bagashirahw’ inenge."}, {"type": "verse", "number": 2, "content": "Igisambo ku musaraba, Kiyarabutswe cyarihannye;\nNanjye mbwiriza nkwizigire, Noye kujya ncumura;\nIbyaha mbicikeho rwose, Noye kujya nkugomera;\nNanjye mbwiriza nkwizigire, Noye kujya ncumura."}, {"type": "verse", "number": 3, "content": "Amaraso yaw’ atunganye, Ahoran’ imbaraga nyinshi;\nNi yo wacunguj’ itorero, Aritsembamw’ ibyaha;\nRyaganjij’ imbaraga yabyo. Ryarabirokotse rwose.\nNi yo wacunguj’ itorero, Yaritsembyemw’ ibyaha."}, {"type": "verse", "number": 4, "content": "Mperey’ igihe meny’ isoko, Iva mu bikomere byawe.\nNogez’ urwo rukundo rwawe, Nzahora ngusingiza;\nNzahora ngusingiz’ iteka, Nzajya ngusingiz’ iteka.\nNogez’ urwo rukundo rwawe, Nzahora ngusingiza."}, {"type": "verse", "number": 5, "content": "Mwami mpora ngucumuraho, Mpa kwizer’ imbabazi zawe!\nN’ amaraso yaw’ atunganye, Mpa kuramishwa nawe!\nMpa kuramishwa nawe Yesu! Mpa no kuramishwa nawe!\nN’ amaraso yaw’ atunganye, Mpa kuramishwa nawe!"}, {"type": "verse", "number": 6, "content": "Har’ indirimbo zera ntazi, Nzaziririmbira mw’ ijuru.\nN’aho nagobw’ ururim’ ubu, Uzarugobotora;\nUzarugobotora Yesu, Ni wow’ uzankiza rwose.\nN’aho nagobw’ ururim’ ubu, Uzarugobotora."}]},
  {"number": 13, "name": "Mwami Yesu Ndifuza K’ Umboneza", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/13", "key": "la", "references": [{"codes": "SDAH. 318"}, {"codes": "CS. 64"}, {"title": "LORD JESUS, I LONG TO BE PERFECTLY WHOLE"}, {"codes": "AH. 200"}, {"codes": "CH. 592"}], "body": [{"type": "verse", "number": 1, "content": "Mwami Yesu ndifuza k’ umboneza; Ndashaka k’ umba mu mutim’ iteka.\nNoye kujya nita ku bigirwamana. Umboneze rwose nere ndush’ ingwa."}, {"type": "chorus", "content": "Ngo nere de! Ndush’ urubura!\nMpa kwer’ ubu ngutunganire rwose!"}, {"type": "verse", "number": 2, "content": "Mwami jy’ undebera ku ntebe yawe! Mpa gutamb’ igitambo kiboneye!\nNdeke gushidikanya nitange rwose. Umboneze rwose nere ndush’ ingwa."}, {"type": "verse", "number": 3, "content": "Yesu ndagutakambira nkomeje! Ngo mbon’ uko nkwitega Mwami mwiza!\nNtunganish’ umuvu w’ amaraso yawe! Umboneze rwose nere ndush’ ingwa."}, {"type": "verse", "number": 4, "content": "Mwami ngutegereje nihanganye, Yesu ngwin’ ump’ umutim’ utunganye!\nNti wari wirengagiz’ abagushaka. Umboneze rwose nere ndush’ ingwa."}]},
  {"number": 14, "name": "Mbeg’ Ukw’ Amaturo Aturwa Neza!", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/14", "key": "do", "references": [{"codes": "CS. 573"}, {"title": "HERE THE PENNIES DROPPING"}, {"codes": "HL. 585"}, {"title": "TINTE, PIÈCE BLANCHE!"}], "body": [{"type": "verse", "number": 1, "content": "Mbeg’ ukw’ amaturo, Aturwa neza!\nYose n’ aya Yesu, Ni we dutura."}, {"type": "chorus", "content": "Tura, tura, tura, tura,\nTur’ amaturo.\nYose n’ aya Yesu,\nNi we dutura."}, {"type": "verse", "number": 2, "content": "Fungur’ ibiganza, Utang’ ituro;\nN’ ituro rya Yesu, Ryo mu bana be."}, {"type": "verse", "number": 3, "content": "Ubu turi bato, Ni yo dufite;\nUbwo tuzakura, Tuzasumbyaho."}, {"type": "verse", "number": 4, "content": "Nitugira bike, Tukwihe Mwami.\nByos’ uzabyakira, Utwikirize."}]},
  {"number": 15, "name": "Urukundo rwa Yesu", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/15", "key": "do", "references": [{"codes": "SDAH. 190"}, {"codes": "AH. 455"}, {"title": "JESUS LOVES ME THIS I KNOW"}, {"codes": "CS. 283"}], "body": [{"type": "verse", "number": 1, "content": "Urukundo rwa Yesu, Rwageze kuri twebwe;\nRudukuraho rwose, Urubanza rwo gupfa."}, {"type": "chorus", "content": "Aradukunda, Aradukunda,\nAradukunda, Yesu Mutabazi."}, {"type": "verse", "number": 2, "content": "Abatari bahabwa, Ubugingo bw’ iteka,\nTwihute tubabwire, Urukundo rwa Yesu."}, {"type": "verse", "number": 3, "content": "Koko yaradukunze, Yadupfiriye twese,\nNatwe dukunde dutyo, Abakiri mu byaha."}, {"type": "verse", "number": 4, "content": "Aho Yes’ azazira, Aje kwim’ ingoma ye,\nNi bwo tuzumv’ ijwi rye, Ati: Mwakoze neza."}, {"type": "verse", "number": 5, "content": "Akir’ uyu mutima, Weze maz’ ub’ uwawe,\nWambambiwe ku giti, Nzagukunda mb’ uwawe."}]},
  {"number": 16, "name": "Mbonez’ Intoke Zanjye", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/16", "key": "la bémol", "references": [{"codes": "AH. 318"}, {"codes": "CS. 569"}, {"title": "I WASHED MY HANDS"}, {"codes": "HL. 539"}], "body": [{"type": "verse", "number": 1, "content": "Mbonez’ intoke zanjye, Zibonere rwose;\nKo nazihaye Yesu, Ngo zimukorere."}, {"type": "chorus", "content": "Nitondesh’ intambwe,\nAho njya hose.\nNe kuyobok’ undi,\nKeretse Yesu"}, {"type": "verse", "number": 2, "content": "Nteg’ amatwi ngo numve, Nez’ umunsi wose.\nNkor’ ibikwiye numva, Ntagir’ icyo mpuga."}, {"type": "verse", "number": 3, "content": "Mpang’ amas’ amaboko, Ngo ndeb’ iby’ akora;\nNyabuze kwenderanya, Akorere Yesu."}]},
  {"number": 17, "name": "Njye Nsingiz’ Urukundo", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/17", "key": "si bémol", "references": [{"codes": "SDAH. 579"}, {"codes": "AH. 454"}, {"title": "TIS LOVE THAT MAKES US HAPPY"}], "body": [{"type": "verse", "number": 1, "content": "Njye nsingiz’ urukundo, Ni rwo rumbwiriza,\nKugirir’ abandi neza, Bakamenya Yesu."}, {"type": "chorus", "content": "Data we ko nd’ umwana wawe!\nData we Ngukurikize!\nNjye nsingiz’ urukundo,\nNi rwo rumbwiriza,\nKugirir’ abandi neza, Bakamenya Yesu."}, {"type": "verse", "number": 2, "content": "Iyi s’ ibamw’ ishavu, N’ ibyaha n’ urupfu;\nNtibimbuza kuyobora bamw’ ibwami bwawe."}, {"type": "verse", "number": 3, "content": "Maz’ ibyo nibishira, Tuzabe mw’ ijuru,\nTuzajye tuguhimbaza, Mwami w’ urukundo."}]},
  {"number": 18, "name": "Yemwe Ngabo Z’ Umwami", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/18", "key": "mi", "references": [{"codes": "SDAH. 612"}, {"codes": "CS. 656"}, {"title": "ONWARD CHRISTIAN SOLDIERS"}, {"codes": "AH. 370"}, {"codes": "CH. 360"}], "body": [{"type": "verse", "number": 1, "content": "Yemwe ngabo z’ Umwami! Nimutabare!\nTujyane na Yesu! Ni w’ utabaza.\nTwitwaz’ umusaraba! Utujy’ imbere!\nMwese nimuze tugabe! Tunesh’ Umwanzi."}, {"type": "chorus", "content": "Yemwe ngabo z’ Umwami mwese!\nDutabare twese! Tujyane na Yesu,\nDutsind’ Umwanzi."}, {"type": "verse", "number": 2, "content": "Ababisha bahunga, Babony’ intwari.\nNimuze tuneshe, Ngabo z’ Umwami!\nIntangiriro z’ isi zinyeganyezwa,\nN’ ibyishimo by’ ab’ Umwami, bamusingiza."}, {"type": "verse", "number": 3, "content": "Itorero ry’ Imana, Rirafatanya;\nRirahaguruka, Kunesh’ Umwanzi.\nNta kizaduteranya, Turakundana,\nDuhora duhuj’ inama, Twizera kimwe."}, {"type": "verse", "number": 4, "content": "Nta ngoma zidashira, Zirahanguka.\nArikw’ itorero, Rizahoraho.\nUkuzimu n’ urupfu, Ntibiririnda.\nTwarazwe na Yesu Kristo, Ntabw’ ahemuka."}, {"type": "verse", "number": 5, "content": "Nuko mugabe mwese! Tugerereze.\nTubumbire hamwe, Amajwi yacu,\nTuririmbe dushima, Umwami Yesu,\nKukw’ afit’ icyubahiro, Giheranije."}]},
  {"number": 19, "name": "Ba Mas’ Udacumura", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/19", "key": "do", "references": [{"codes": "SDAH. 605"}, {"codes": "CS. 788"}, {"title": "MY SOUL, BE ON THY GUARD"}, {"codes": "CH. 358"}], "body": [{"type": "verse", "number": 1, "content": "Ba mas’ udacumura! Ibyaha bigota,\nBihora bikwegera cyane, Ng’ utajya mw’ ijuru."}, {"type": "verse", "number": 2, "content": "Ba maso rwana senga! Nturek’ urugamba!\nUrurasany’ iminsi yose, Utabaz’ Imana."}, {"type": "verse", "number": 3, "content": "Komeza nturanesha! Wirekur’ intwaro!\nDor’ intambara ntirashira, Udahaw’ ikamba."}]},
  {"number": 20, "name": "Huguka Mutima Wanjye!", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/20", "key": "sol", "references": [{"codes": "CH. 355"}, {"codes": "CS. 793"}, {"title": "AWAKE, MY SOUL!"}], "body": [{"type": "verse", "number": 1, "content": "Huguka mutima wanjye! Shishikarir’ ibyiza!\nUkomez’ urwan’ ishyaka! Uzambikw’ ikamba."}, {"type": "verse", "number": 2, "content": "N’ Iman’ iguhamagara, Gira bwangu witabe!\nNiy’ iziher’ ibihembo, Abatsinze bose."}, {"type": "verse", "number": 3, "content": "Inteko zikurebera, Ziragutegereje,\nNtutekerez’ ah’ uvuye, Reb’ imbere yawe."}, {"type": "verse", "number": 4, "content": "Mukiza wacu dukunda, Twanesheje ku bwawe,\nUbu twaje kugushima, Turagusingiza."}]},
  {"number": 21, "name": "Ndeger’ Umusaraba", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/21", "key": "sol", "references": [{"codes": "SDAH. 307"}, {"codes": "AH. 184"}, {"title": "I AM COMING TO THE CROSS"}, {"codes": "CH. 600"}, {"codes": "CS. 109"}], "body": [{"type": "verse", "number": 1, "content": "Ndeger’ umusaraba, Naniwe nkennye mpumye,\nSingir’ icyo nitaho, Rwose nshaka gukizwa."}, {"type": "chorus", "content": "Mwami ndakwizigira, Mukiza wanjye mwiza!\nNdicuz’ imbere yawe, Mwami Yes’ unkiz’ ubu!"}, {"type": "verse", "number": 2, "content": "Nakwifujije kera, Njya mbabazwa n’ ibyaha.\nYes’ ambwira nez’ ati: Ngukiz’ ibicumuro."}, {"type": "verse", "number": 3, "content": "Ubu ndakwihereje, Simbuzwa n’ iby’ iyi si.\nMb’ uwawe rwose Mwami, Nguhay’ ibyanjye byose."}, {"type": "verse", "number": 4, "content": "Ndiringir’ iby’ uvuga, Wamviriy’ amaraso.\nUbu ndicuza cyane, Mbambanywe n’ Umukiza."}, {"type": "verse", "number": 5, "content": "Nezezwa n’ uko nkize, Yesu ni w’ unkomeza.\nNta nenge nsigaranye, Mpitam’ icyubahiro."}]},
  {"number": 22, "name": "Mwami Mp’ Umugisha Wawe", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/22", "key": "sol", "references": [{"codes": "AH. 151"}, {"codes": "CH. 208"}, {"title": "LORD, I HEAR"}, {"codes": "CS. 174"}, {"codes": "HL. 267"}], "body": [{"type": "verse", "number": 1, "content": "Mwami mp’ umugisha wawe, Uhera bos’ ubusa.\nNdakwinginga ntumpiteho! Arik’ umpire none."}, {"type": "chorus", "content": "Umpire! Umpire!\nNgo ntatahan’ ubusa."}, {"type": "verse", "number": 2, "content": "Ntunsige mubyeyi mwiza, Ibyaha byandembeje;\nNkwiriye gucibwa rwose, Arik’ umbabarire."}, {"type": "verse", "number": 3, "content": "Niba natinze mu byaha, Njya nkubabaza cyane;\nNiba ngoswe n’ iby’ iyi si, Ubinkuremo rwose."}, {"type": "verse", "number": 4, "content": "Ntumpiteho Mwuka Wera! Ni w’ uhumur’ impumyi.\nUnyemez’ uhamya Yesu! Mbwir’ ibimpumuriza."}]},
  {"number": 23, "name": "Untambe Hejuru Mwuka Wera", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/23", "key": "sol", "references": [{"codes": "SDAH. 260"}, {"codes": "AH. 152"}, {"title": "HOVER O’ER ME, HOLY SPIRIT"}, {"codes": "CH. 212"}, {"codes": "CS. 308"}, {"codes": "HL. 176"}], "body": [{"type": "verse", "number": 1, "content": "Untambe hejuru Mwuka Wera, Ngo mpirwe nawe!\nNyuzuz’ umugisha wawe, Ngwino ngwin’ unyuzure!"}, {"type": "chorus", "content": "Nyuzura! nyuzura! Yesu ngwin’ unyuzure!\nNyuzuz’ umugisha wawe! Ngwino ngwin’ unyuzure!"}, {"type": "verse", "number": 2, "content": "Ushobora kunyuzura, Ariko sinz’ uburyo.\nNdagushaka Mwuka Wera, Ngwino ngwin’ unyuzure!"}, {"type": "verse", "number": 3, "content": "Sinkomeye ndababaye, Ndunam’ imbere yawe.\nMwuka mwiza wo mw’ ijuru, Mp’ urukundo nyuzura."}, {"type": "verse", "number": 4, "content": "Ngwin’ unyeze kand’ unkize! Tuz’ umutima wanjye!\nNi w’ umpumuriz’ unkiza, Unyuzure rwos’ ubu."}]},
  {"number": 24, "name": "Ndagushak’ Iteka", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/24", "key": "la bémol", "references": [{"codes": "SDAH. 483"}, {"codes": "AH. 222"}, {"title": "I NEED THEE EVERY HOUR"}, {"codes": "CH. 258"}, {"codes": "CS. 609"}, {"codes": "HL. 359"}], "body": [{"type": "verse", "number": 1, "content": "Ndagushak’ iteka, Mwami mwiza cyane,\nIjwi ryawe ryiza, Rizan’ amahoro."}, {"type": "chorus", "content": "Ku manywa na nijoro, Ndagushak’ iteka.\nMpir’ ubu Mukiza we! Twigumanire."}, {"type": "verse", "number": 2, "content": "Ndagushak’ iteka, Jy’ ungum’ iruhande.\nNtsind’ amoshya yose, Iyo turi kumwe."}, {"type": "verse", "number": 3, "content": "Ndagushak’ iteka, Ntuje n’ iyo nganya.\nNgwin’ ubu tubane! Mbone gutungana."}, {"type": "verse", "number": 4, "content": "Ndagushak’ iteka, Nyigish’ iby’ ushaka!\nNkwinging’ unsohorez’ amasezerano!"}, {"type": "verse", "number": 5, "content": "Ndagushak’ iteka, Mwami Wera rwose,\nNyobora mb’ uwawe, Wowe munyahirwe!"}]},
  {"number": 25, "name": "Yesu Nd’ Uwawe Nyakira", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/25", "references": [{"codes": "SDAH. 309"}, {"codes": "AH. 190"}, {"codes": "CH. 573"}, {"title": "ALL TO JESUS I SURRENDER"}, {"codes": "CS. 51"}, {"codes": "HL. 489"}], "body": [{"type": "verse", "number": 1, "content": "Yesu nd’ uwawe nyakira, N’ ibyanjye mfite byose!\nNjye ngukunda nkwizigire, Nkomeze nkuyoboke."}, {"type": "chorus", "content": "Nguhaye byose (Nguhaye byose),\nNguhaye byose (Nguhaye byose).\nMucunguzi wanjye mwiza, Nguhaye byose."}, {"type": "verse", "number": 2, "content": "Yesu nd’ uwawe nyakira! Niyoroshye nkuramye.\nMpaz’ ibyishimo byo hasi, Ubu Yesu nyakira!"}, {"type": "verse", "number": 3, "content": "Yesu nd’ uwawe nyakira! Mukiza ngir’ uwawe!\nTum’ Umwuka Wer’ ambwire, Kuko naw’ ur’ uwanjye!"}, {"type": "verse", "number": 4, "content": "Yesu nguhaye byos’ ubu, Umwuk’ ampay’ umwete!\nNsingiz’ imbabazi zawe, Nkuramye bihimbaje."}]},
  {"number": 26, "name": "Ubu Nj’ Uko Ndi", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/26", "key": "mi bémol", "references": [{"codes": "SDAH. 313"}, {"codes": "AH. 191"}, {"codes": "CH. 222"}, {"title": "JUST AS I AM"}, {"codes": "CS. 145"}, {"codes": "HL. 224"}], "body": [{"type": "verse", "number": 1, "content": "Ubu nj’ uko ndi nta kindi cyankiza; Ndokoresh’ amaraso yawe.\nNitaby’ ijwi ryawe rimpamagaye, Ndaje, Ntama y’ Imana ndaje."}, {"type": "verse", "number": 2, "content": "Nj’ uko ndi nyakir’ ubu ngubu Yesu! Nyez’ umutima nkir’ ibyaha!\nWowe Nyir’ amaras’ akiza rwose, Ndaje, Ntama y’ Imana ndaje."}, {"type": "verse", "number": 3, "content": "Nj’ uko ndi mbuyerezwa n’ ubugome; Njya nanizwa n’uko nd’ intebyi,\nMfit’ ibindwanya byinshi bincogoza, Ndaje, Ntama y’ Imana ndaje."}, {"type": "verse", "number": 4, "content": "Nj’ uko ndi nd’ umuhanya, ndi n’ impumyi; Gutungana mbikesha wowe;\nIbyamboneza nabibon’ iwawe. Ndaje, Ntama y’ Imana ndaje."}, {"type": "verse", "number": 5, "content": "Nj’ uko ndi nizigiye k’ unyakira, Nizey’ isezerano ryawe;\nYuk’ uzankiza kand’ uzamboneza, Ndaje, Ntama y’ Imana ndaje."}, {"type": "verse", "number": 6, "content": "Nj’ uko ndi guhamy’ urukundo rwawe, Ko rwambohoy’ ingoyi zose.\nUherey’ ubu mbay’ uwawe rwose, Ndaje, Ntama y’ Imana ndaje."}]},
  {"number": 27, "name": "Dushim’ Imana", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/27", "key": "sol", "references": [{"codes": "AH. 157"}, {"title": "WE PRAISE THEE O GOD"}, {"codes": "CS. 396"}], "body": [{"type": "verse", "number": 1, "content": "Dushim’ Imana kubw’ Umwana wayo,\nKubw’ Umukiza waducunguye twese."}, {"type": "chorus", "content": "Haleluya Nyirigira, Haleluy’ amina;\nHaleluya Nyirigira, Twonger’ umwete."}, {"type": "verse", "number": 2, "content": "Dushim’ Imana kubw’ Umwuka Wera;\nAtubwiriza kumvir’ Iyaturemye."}, {"type": "verse", "number": 3, "content": "Dushim’ Intama yatambwe ku bwacu,\nYatway’ ibyaha byac’ adukiza rwose."}, {"type": "verse", "number": 4, "content": "Dushimir’ Iman’ imbabazi zayo,\nYaratuguz’ itugir’ abana bayo."}, {"type": "verse", "number": 5, "content": "Twonger’ umwete, Twuzuz’ urukundo;\nUmuntu wes’ akuyobokan’ ubwira."}]},
  {"number": 28, "name": "Shaka Gutungana", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/28", "key": "fa", "references": [{"codes": "SDAH. 500"}, {"codes": "AH. 276"}, {"codes": "CH. 603"}, {"title": "TAKE TIME TO BE HOLY"}, {"codes": "CS. 485"}, {"codes": "HL. 181"}], "body": [{"type": "verse", "number": 1, "content": "Shaka gutungana, Jy’ uhor’ usenga; Bana n’ Uwiteka, Ujy’ umwumvira;\nJy’ ukund’ Abakristo, Fash’ abarembye; Ntuhuge na hato, Gushak’ ihirwe."}, {"type": "verse", "number": 2, "content": "Shaka gutungana, Hagomye benshi; Horana na Yesu, Mu rwiherero.\nN’ umwitegereza, Uzaba nka we; Bose bazamenya, K’ umeze nka we."}, {"type": "verse", "number": 3, "content": "Shaka gutungana, Akuyobore. Ty’ itond’ imbere ye, N’ ugir’ ibyago,\nUk’ umera kose, Jy’ umwiyambaza. Jy’ uyoboka Yesu, Mwumvire rwose."}, {"type": "verse", "number": 4, "content": "Shaka gutungana, Tuz’ umutima. Tekerez’ ibyiza, Wihutiraho.\nJya wumvir’ Umwuka, Gwiz’ urukundo; Uzatunganira, Kuba mw’ ijuru."}]},
  {"number": 29, "name": "Ungumane", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/29", "key": "mi bémol", "references": [{"codes": "SDAH. 50"}, {"codes": "AH. 40"}, {"title": "ABIDE WITH ME"}, {"codes": "CH. 50"}, {"codes": "CS. 655"}, {"codes": "HL. 197"}], "body": [{"type": "verse", "number": 1, "content": "Ungumane ko bugiye kwira, Haj’ umwijima Mwam’ ungumane.\nUbwo bagenzi banjye bansiga, Nkaba jyenyine, Mwam’ ungumane."}, {"type": "verse", "number": 2, "content": "Mur’ iyi si byose birashira, Nta munezer’ uhaba na hato;\nNta kidapfa, nta kidahinduka; Wow’ udahinyuka, ungumane."}, {"type": "verse", "number": 3, "content": "Mwami niwe nshak’ iteka ryose, Nta moshya ntsinda tutari kumwe.\nNta wabasha kunyobora nkawe. Mwam’ iteka ryose, ungumane."}, {"type": "verse", "number": 4, "content": "N’ ungumana, nta mubisha ntinya; Ishavu rizab’ umunezero;\nImbori z’ urupfu zizashira; Ntabwo ntazanesha n’ ungumana."}]},
  {"number": 30, "name": "Ngah’ Umuns’ Urakuze", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/30", "key": "la bémol", "references": [{"codes": "SDAH. 51"}, {"codes": "AH. 41"}, {"codes": "CH. 51"}, {"title": "DAY IS DYING IN THE WEST"}, {"codes": "CS. 339"}, {"codes": "HL. 175"}], "body": [{"type": "verse", "number": 1, "content": "Ngah’ umuns’ urakuze, Burije turuhuke;\nKand’ ubw’ imuri z’ ijoro zaka turamy’ Uwiteka,\nTwebwe twese."}, {"type": "chorus", "content": "Wera, Wera, Wera, Mwam’ Imana.\nWigwij’ ahantu hose,\nNta kitaguh’ ishimwe,\nMwam’ Imana."}, {"type": "verse", "number": 2, "content": "Mwami nyir’ ubugingo, Terany’ abagushaka;\nBuzuze bos’ urukundo, Ubagir’ ubwoko bwawe,\nBakuramye."}, {"type": "verse", "number": 3, "content": "Umwijima n’ ugwira, Dukingir’ imbabazi;\nTukwegerez’ imitima, Hirya y’ ubwiza bw’ ijuru,\nNgo duhirwe."}, {"type": "verse", "number": 4, "content": "Duhe kukwiringira, Ng’ ubwo tuzapfa Mwami,\nTwongere kubon’ umucyo, Ijoro rishir’ iteka,\nTugushime."}]},
  {"number": 31, "name": "Mukiza We Niwe Mucyo Waka", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/31", "key": "fa", "references": [{"codes": "AH. 35"}, {"codes": "AH. 321"}, {"title": "SUN OF MY SOUL"}, {"codes": "CS. 775"}, {"codes": "HL. 32"}], "body": [{"type": "verse", "number": 1, "content": "Mukiza we! Ni we mucyo waka.\nNtabw’ umwijim’ uhangar’ ah’ uri,\nNyamururahw’ ibinyoshya,\nBituma nanduranya nawe."}, {"type": "verse", "number": 2, "content": "Mukiza mu gihe njya kuryama,\nNgo nduhuk’ imirimo nakoze,\nUmpe kugutekereza,\nNgo nsinzire ndi kumwe nawe."}, {"type": "verse", "number": 3, "content": "Umpagarik’ umunsi n’ ijoro;\nNtabwo nabaho tutari kumwe;\nUngumane mu makuba,\nKuko ntinya gupf’ udahari."}, {"type": "verse", "number": 4, "content": "N’ ubwo nkanguk’ ungume bugufi;\nN’ aho ndibujye gukora hose,\nKugez’ ubwo nzaz’ iwawe,\nMeny’ urukundo rwawe rwose."}]},
  {"number": 32, "name": "Yesu N’ Urutare Rwacu", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/32", "key": "fa", "references": [{"codes": "SDAH. 528"}, {"codes": "AH. 211"}, {"title": "THE LORD’S OUR ROCK"}, {"codes": "CH. 585"}, {"codes": "CS. 505"}], "body": [{"type": "verse", "number": 1, "content": "Yesu n‘ urutare rwacu, N’ ubwugamo bw’ umugaru;\nNi w’ udukiz’ amakuba, N’ ubwugamo bw’ umugaru."}, {"type": "chorus", "content": "Rutare rwisungwa n’ abantu!\nGicucu cy’ uburuhukiro!\nMuyobozi mwiz’ utayobya!\nUbwugamo bw’ umugaru."}, {"type": "verse", "number": 2, "content": "Ankiz’ amakub’ iteka, N’ ubwugamo bw’ umugaru.\nNtacyo ntinya turi kumwe, N’ ubwugamo bw’ umugaru."}, {"type": "verse", "number": 3, "content": "Imivu n’ isum’ itera, N’ ubwugamo bw’ umugaru.\nN’ Umukiza wacu mwiza, N’ ubwugamo bw’ umugaru."}, {"type": "verse", "number": 4, "content": "Rutare rwiza rushimwa! Ubwugamo bw’ umugaru!\nJy‘ utuvuna mu makuba! Ubwugamo bw’ umugaru."}]},
  {"number": 33, "name": "Ndanezerwa Kw’ Anyobora", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/33", "key": "ré", "references": [{"codes": "SDAH. 537"}, {"codes": "AH. 292"}, {"title": "HE LEADETH ME"}, {"codes": "CH. 393"}, {"codes": "CS. 677"}], "body": [{"type": "verse", "number": 1, "content": "Ndanezerwa kw’ anyobora, Arampumurish’ Ijambo rye.\nMu byo nkora, n’ aho ngenda, N’ukoboko kwa Yesu kunyobora."}, {"type": "chorus", "content": "Aranyobora nkanezerwa,\nN’ ukw’ anyoboresh’ ukuboko kwe.\nNshaka kumukorera neza,\nYuk’ ukuboko kwe kunyobora."}, {"type": "verse", "number": 2, "content": "Niba ngir’ ishavu ryinshi, Cyangwa nubwo nezerwa cyane.\nMu mahoro n’ amakuba, N’ ukuboko kwa Yesu kunyobora."}, {"type": "verse", "number": 3, "content": "Mwami nshaka ko tubana; Ntabwo nzinuba nitotomba;\nNzagumya nishime cyane, K’ ukuboko kwa Yesu kunyobora."}, {"type": "verse", "number": 4, "content": "Ndangij’ imirimo yanjye, Nesheje kubw’ imbabazi ze;\nNtacyo nzatinya n’ urupfu, K’ ukuboko kwa Yesu kunyobora."}]},
  {"number": 34, "name": "Nimbon’ Amahoro", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/34", "key": "ré bémol", "references": [{"codes": "SDAH. 530"}, {"codes": "AH. 250"}, {"codes": "CH. 313"}, {"title": "WHEN PEACE LIKE A RIVER"}, {"codes": "CS. 516"}, {"codes": "HL. 321"}], "body": [{"type": "verse", "number": 1, "content": "Nimbon’ amahoro yomboka nk’ uruzi, Naho naba mfit’ ishavu,\nUko mba kose, Njya nkunda kuvuga Nti: Nguwe neza mu mutima."}, {"type": "chorus", "content": "Ni neza (ni neza) ndatuje (ndatuje);\nKo nguwe neza mu mutima."}, {"type": "verse", "number": 2, "content": "Satani nantera, Nkagira n’ ibyago, Nkomezwa no kwiringira,\nKuko Kristo yabonye ko nd’ intebyi; Ni ko kumvir’ amaraso ye."}, {"type": "verse", "number": 3, "content": "Nshima cyane kuko mbabariw’ ibyaha, Nta na kimwe cyasigaye;\nByabambanywe nawe ku musaraba; Mutima wanjye shim’ Umwami."}, {"type": "verse", "number": 4, "content": "Mwami tebuts’ umuns’ uzagarukaho, Ubw’ ibicu bizarundwa,\nImpand’ ivuze, Umwam’ amanuke Nti: Nguwe neza mu mutima."}]},
  {"number": 35, "name": "Nkund’ Ubucuti", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/35", "key": "la", "references": [{"codes": "SDAH. 469"}, {"codes": "AH. 261"}, {"title": "WHAT A FELLOWSHIP"}, {"codes": "CH. 611"}, {"codes": "CS. 503"}], "body": [{"type": "verse", "number": 1, "content": "Nkund’ ubucuti buva mw’ ijuru, Nisung’ amaboko y’ iteka.\nNgiz’ amahirwe, mbony’ amahoro, Nisunz’ amaboko y’ iteka."}, {"type": "chorus", "content": "S. na A.: Nkiza! Nkiza! Ndokor’ amakuba yose!\nNkiza! Nkiza! Nisunz’ amaboko y’ iteka.\nT. na B.: Nkiza Yesu! Nkiza Yesu nkiza!\nNdokor’ amakuba yose!\nNkiza Yesu! Nkiza Yesu nkiza!\nNisunz’ amaboko y’ iteka."}, {"type": "verse", "number": 2, "content": "Nezerwa n’ uko Yes’ anyobora; Nisung’ amaboko y’ iteka.\nNunguk’ ishimwe, Ngakiranuka; Nisunz’ amaboko y’ iteka."}, {"type": "verse", "number": 3, "content": "Nta bwoba mfite, Nshiz’ agahinda, Nisunz’ amaboko y’ iteka.\nNguwe nez’ ubu, Ndatunganiwe. Nisunz’ amaboko y’ iteka."}]},
  {"number": 36, "name": "Ni Wowe Nizeye", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/36", "key": "mi bémol", "references": [{"codes": "SDAH. 517"}, {"codes": "AH. 204"}, {"title": "MY FAITH LOOKS UP TO THEE"}, {"codes": "CH. 246"}, {"codes": "CS. 108"}], "body": [{"type": "verse", "number": 1, "content": "Ni wowe nizeye, Ntama y’ i Kalvari,\nWe Mukiza! Ngusab’ unyumvire,\nNkiz’ ibicumuro, Mperey’ ubu Mwami,\nNkuyoboke."}, {"type": "verse", "number": 2, "content": "Nyuzuz’ imbabazi, Ngir’ inama nziza,\nNter’ umwete; Kuko wampfiriye,\nNkwerek’ urukundo, Rudatuba rwaka,\nNk’ umuriro."}, {"type": "verse", "number": 3, "content": "Ningotwa n’ ibyaha, Nkagira n’ ishavu,\nUnyobore. Nkura mu mwijima,\nNtsembahw’ amaganya, Kandi ntundekere,\nKure yawe."}]},
  {"number": 37, "name": "Nkuyoboke Mwami", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/37", "key": "sol", "references": [{"codes": "SDAH. 473"}, {"codes": "AH. 312"}, {"title": "NEARER, MY GOD, TO THEE!"}, {"codes": "CH. 382"}, {"codes": "CS. 663"}, {"codes": "HL. 368"}], "body": [{"type": "verse", "number": 1, "content": "Nkuyoboke Mwami, Nkuyoboke. N’ aho natendekwa ku musaraba,\nNaba nkiririmba: Nkuyoboke Mwami, Nkuyoboke Mwami, Nkube bugufi."}, {"type": "verse", "number": 2, "content": "Nkuyoboke Mwami, Nkuyoboke. Mu makuba yose, Mpagarikira!\nNinterwa n’ ibyago, Umpe kwihangana, Nkuyoboke Mwami, Nkube bugufi."}, {"type": "verse", "number": 3, "content": "Nkuyoboke Mwami, Nkuyoboke. Jy’ untabar’ iteka ngumye nkwizere!\nUmwanzi nantera, Ujy’ undwanirira! Nkuyoboke Mwami, Nkube bugufi."}, {"type": "verse", "number": 4, "content": "Nkuyoboke Mwami, Nkuyoboke. Wakinguy’ ijuru, Nyobor’ ah’ uri.\nMugenzi komera, Urenda gukira! Nkuyoboke Mwami, Nkube bugufi."}]},
  {"number": 38, "name": "Unambe Ku Mana", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/38", "key": "mi bémol", "references": [{"codes": "CS. 509"}, {"title": "FIRMLY STAND FOR GOD"}], "body": [{"type": "verse", "number": 1, "content": "Unambe ku Mana, ntuyimure; Bona nuterwa n’ impagarara,\nUzagarukirwa na Rutare, Iyo tugoswe n’ ibyaha."}, {"type": "chorus", "content": "Dukomerera kuri Kristo Rutare,\nNiwe Rutare twisunga.\nNitwihangana tuzab’ amahoro,\nTugez’ imbere y’ Imana."}, {"type": "verse", "number": 2, "content": "Nambir’ ukuri jya wihangana, Komez’ ubutwari no kwizera!\nRutar’ aduha kuganziriza, Mur’ iyi si y’ igomero."}, {"type": "verse", "number": 3, "content": "Nambir’ ukuri birakwiriye, We kurambirw’ uzagororerwa.\nRutare niw’ uduh’ amahoro, Tumaze gutsind’ ibyago."}]},
  {"number": 39, "name": "Nkomeze Njye Niringira", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/39", "key": "sol", "references": [{"codes": "SDAH. 522"}, {"codes": "AH. 212"}, {"title": "MY HOPE IS BUILT"}, {"codes": "CH. 581"}, {"codes": "CS. 294"}], "body": [{"type": "verse", "number": 1, "content": "Nkomeze njye niringira, Amaraso y’ Umukiza.\nSinagir’ undi niganana, Keretse Yesu wenyine."}, {"type": "chorus", "content": "Nikomeze ku Rutare,\nNahw’ ahandi n’ umusenyi;\nNahw’ ahandi n’ umusenyi."}, {"type": "verse", "number": 2, "content": "Umwijima numpumisha, Niringir’ imbabazi ze.\nMu makuba no mu byago, Ntagir’ ubw’ anzibukira."}, {"type": "verse", "number": 3, "content": "Mbonezwa n’ amaraso ye, Ampa kumukurikira.\nN’iyo nababaye rwose, Aramfasha ngakomera."}, {"type": "verse", "number": 4, "content": "Naza kw’ ijwi ry’ ikondera, Azasanga mwiteguye;\nNambaye gukiranuka, Nta nenge nzaba ngifite."}]},
  {"number": 40, "name": "Tubane N’ Umwami", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/40", "key": "fa", "references": [{"codes": "SDAH. 590"}, {"codes": "AH. 223"}, {"title": "TRUST AND OBEY"}, {"codes": "CH. 582"}, {"codes": "CS. 495"}], "body": [{"type": "verse", "number": 1, "content": "Tubane n’ Umwami, Twumvir’ Ijambo rye; Atujyana mu nzira nziza,\nTumwumviye rwose. Akabana natwe, N’ abamwizer’ uko bangana."}, {"type": "chorus", "content": "Jy’ umwumvira, Nta kandi gakiza,\nKeretse Yesu gusa; Mwizigire rwose."}, {"type": "verse", "number": 2, "content": "Ntihakingirizwa, Nta gicu gikuba, Byeyurwa no kumwenyura kwe.\nNta shiti n’ ubwoba, Bona n’ igishyika, Bimarwa n’ uko tumwizeye."}, {"type": "verse", "number": 3, "content": "Nta kitubabaza, Nta shavu tugira; Niw’ uduhembur’ imbu zose;\nNta bworo n’ isari, Nta n’ umubabaro; Tuzahirwa nitumwizera."}, {"type": "verse", "number": 4, "content": "Ntabwo twiyungura, Kugir’ ibyishimo, Kugeza ko tureka byose,\nKubw’ imbabazi ze; Impan’ ajy’ atanga, N’ ingororano z’ abizeye."}, {"type": "verse", "number": 5, "content": "Tuzajya twishima, Turi kumwe nawe. Tuzagendana naw’ iteka,\nTumwumvira rwose; Azajy’ adutuma, Ntacyo tuzaba tugitinya."}]},
  {"number": 41, "name": "Yes’ Abe Hamwe Nawe Hose", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/41", "key": "ré bémol", "references": [{"codes": "SDAH. 65"}, {"codes": "AH. 476"}, {"codes": "CH. 35"}, {"title": "GOD BE WITH YOU"}, {"codes": "CS. 504"}, {"codes": "HL. 446"}], "body": [{"type": "verse", "number": 1, "content": "Yes’ abe hamwe nawe hose! Akugir’ inama nziza!\nAgucyure mu bushyo bwe! Yes’ abe hamwe nawe hose!"}, {"type": "chorus", "content": "Kugez’ ubwo (ubwo) tuzabonana,\nUbwo tuzabana na Yesu (na Yesu).\nKugez’ ubwo (ubwo) tuzabonana,\nYes’ abe hamwe nawe hose."}, {"type": "verse", "number": 2, "content": "Yes’ abe hamwe nawe hose! Akurinde mu makuba!\nAkwongere man’ iteka! Yes’ abe hamwe nawe hose!"}, {"type": "verse", "number": 3, "content": "Yes’ abe hamwe nawe hose! Ubuyerezwa n’ ibyaha,\nAgukingir’ ukuboko! Yes’ abe hamwe nawe hose!"}, {"type": "verse", "number": 4, "content": "Yes’ abe hamwe nawe hose! Jy’ uguman’ urukundo rwe!\nTsind’ urupf’ imbere yawe! Yes’ abe hamwe nawe hose!"}]},
  {"number": 42, "name": "Iyo Turi Kumwe N’ Inshuti", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/42", "key": "si bémol", "references": [{"codes": "CS. 868"}, {"title": "WITH FRIENDS ON EARTH"}], "body": [{"type": "verse", "number": 1, "content": "Iyo turi kumwe n’ inshuti, Ntakitubabaza,\nArikw’ iyo dutandukanye, Tugir’ agahinda."}, {"type": "chorus", "content": "Mw’ ijuru ntituzatana, Tuzahahorana.\nMur’ iyo si y’ amahoro, Ntabwo tuzatana."}, {"type": "verse", "number": 2, "content": "Iyo twibuts’ inshuti zacu, Turishima cyane.\nNitumar’ imirimo yacu, Tuzaban’ iteka."}, {"type": "verse", "number": 3, "content": "Ntabwo tuzasezeranaho, Tugeze mw’ ijuru;\nTuzahahoran’ ibyishimo, Turirimb’ iteka."}]},
  {"number": 43, "name": "Gupfa Twiringiye Yesu", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/43", "key": "ré", "references": [{"codes": "AH. 477"}, {"codes": "CH. 489"}, {"title": "ASLEEP IN JESUS"}, {"codes": "CS. 846"}], "body": [{"type": "verse", "number": 1, "content": "Gupfa twiringiye Yesu,\nKu bera n’ ugusinzira.\nNtaw’ ukangurwamw’ arira,\nNtaw’ umwanz’ ashukirayo."}, {"type": "verse", "number": 2, "content": "Gusinzira muri Yesu,\nN’ uburuhukiro bwiza,\nN’ amahirwe y’ abizeye,\nKo bazahabw’ ubugingo."}, {"type": "verse", "number": 3, "content": "Gusinzira muri Yesu,\nNo gukangurwamo na we,\nN’ imbaraga y’ Umukiza;\nNtabw’ izabuzwa n’ ibyago."}, {"type": "verse", "number": 4, "content": "Gusinzira muri Yesu,\nKuzurwa n’ ijwi ry’ impanda.\nMaz’ ibituro bivemo,\nAbera bose barame."}]},
  {"number": 44, "name": "Ibyo Nkora Nkiriho", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/44", "key": "la bémol", "references": [{"codes": "CS. 849"}, {"title": "MY SAVIOR FIRST OF ALL"}], "body": [{"type": "verse", "number": 1, "content": "Ibyo nkora nkirihw’ aho bizarangirira, Ubwo kudapfa kuzakura gupfa;\nNimara gukira nzabon’ Umukiza wanjye, Kand’ azab’ anyakiran’ ibyishimo."}, {"type": "chorus", "content": "Nzamumenya, Nzamumenya;\nNzahagarar’ imbere Ye nkize.\nNzamumenya, Nzamumenya,\nMbony’ inkovu zo mu biganza bye."}, {"type": "verse", "number": 2, "content": "Nzanezerwa mbony’ uburanga bwe buhebuje, N’ amaso y’ akey’ arabagirana;\nNzajya musingiza mpimbawe n’ urukundo rwe, Ko yambonerej’ aheza mw’ ijuru."}, {"type": "verse", "number": 3, "content": "Ntabwo mpug’ abadusezeyeho bajya kure, Ubwo twatandukaniye ku cyambu.\nNitujya mw’ ijuru nta kizadutandukanya, Cyane nifuza kubon’ Umukiza."}, {"type": "verse", "number": 4, "content": "Azanjyana mu mudugud’ utabamw’ ishavu, Niho nzambarir’ imyambaro yera,\nNzaririmbana n’ aber’ indirimbo ya Mose; Cyane ndifuza kubon’ Umukiza."}]},
  {"number": 45, "name": "Umpe Bibiliya", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/45", "key": "la bémol", "references": [{"codes": "SDAH. 272"}, {"codes": "AH. 164"}, {"codes": "CH. 655"}, {"title": "GIVE ME THE BIBLE"}, {"codes": "CS. 498"}, {"codes": "HL. 135"}], "body": [{"type": "verse", "number": 1, "content": "Umpe Bibliya kukw’ ari y’ inezeza, Uyinyoboresh’ iteka Mwami.\nNta kibasha kuzimy’ umucyo wayo, Ko Yesu yaje kuyitwumvisha."}, {"type": "chorus", "content": "Umpe Bibliya kukw’ ari y’ inezeza, Nyoborwe nayo mu nzira ntoya.\nAmategeko yawe niyo meza, Agaragaz’ inzira y’ ukuri."}, {"type": "verse", "number": 2, "content": "Umpe Bibliya mu kababaro kanjye, Igihe mpigwa n’ ibyaha byanjye.\nUmpe n’ amagambo Yesu yavuze, Kukw’ ariyo mez’ ampumuriza."}, {"type": "verse", "number": 3, "content": "Umpe Bibliya ngw’ imurikir’ iteka; Kand’ indind’ imitego yo hasi;\nNiyo rumuri rwaka mu mwijima, Runyerek’ inzira y’ amahoro."}, {"type": "verse", "number": 4, "content": "Umpe Bibliya ngw’ imbwir’ iby’ ubugingo, Kand’ udukomerez’ uwo mucyo.\nNgo tumeny’ inzir’ igana mw’ ijuru, Unyerek’ ubwiza bwawe Data."}]},
  {"number": 46, "name": "Jy’ Uhor’ Undinganirije", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/46", "key": "sol", "references": [{"codes": "SDAH. 286"}, {"codes": "AH. 162"}, {"title": "SING THEM OVER AGAIN"}, {"codes": "CH. 574"}, {"codes": "CS. 74"}], "body": [{"type": "verse", "number": 1, "content": "Jy’ uhor’ undinganirije, Amagamb’ atunganye.\nUmpugure meny’ ukuri, Kw’ amagambo yawe.\nNkund’ amagambo yawe, Kw’ ampa kukwizigira."}, {"type": "chorus", "content": "Amagambo meza cyane, Anter’ ibyishimo byinshi;\nNi yo meza, ndayakunda; Ntabw’ atanezeza."}, {"type": "verse", "number": 2, "content": "Krist’ ahet’ abantu bose, Amagamb’ atunganye.\nNimwitabe banyabyaha! Mwumv’ iby’ ubugingo!\nAbayoboz’ ituza, N’ amagamb’ atunganye."}, {"type": "verse", "number": 3, "content": "Menyesha bos’ ubutumwa! N’ amagamb’ atunganye!\nNimuze mubabarirwe! Mwumv’ iby’ ubugingo!\nYesu ni we Mukiza, Utwonger’ ubugingo."}]},
  {"number": 47, "name": "Mpagaze Ku Nkengero Ya Yorodani", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/47", "key": "sol", "references": [{"codes": "SDAH. 620"}, {"codes": "AH. 419"}, {"title": "ON JORDAN’S STORMY BANKS"}, {"codes": "CH. 553"}, {"codes": "CS. 905"}], "body": [{"type": "verse", "number": 1, "content": "Mpagaze ku nkengero ya Yor’dani nubur’ amaso,\nNdor’ igihugu cyiza cy’ i Kanani, ni hw’ ibyanjye biri."}, {"type": "chorus", "content": "N’ igihugu cyiza cy’ amahoro,\nHakurya ku nkengero haratoshye;\nTuzahavugir’ indirimbo ya Mose,\nTubane na Yes’ iteka."}, {"type": "verse", "number": 2, "content": "Hakurya mur’ ibyo bibaya, Hahor’ umucy’ iteka.\nYesu Kristo ni w’ uzahaber’ umucy’ ahakur’ ijoro."}, {"type": "verse", "number": 3, "content": "Aho heza nzahagera ryari ngo mpabe mpiriwe?\nNzareba Data mu maso ryari, Nduhukiy’ ibwami bwe?"}, {"type": "verse", "number": 4, "content": "Mfit’ ibyishimo mu mutima, Sinshaka kugum’ aha.\nYorodan’ isumira hos’ ariko ntinyuka kuyambuka."}]},
  {"number": 48, "name": "Tuzishim’ Imirim’ Ishize", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/48", "key": "do", "references": [{"codes": "SDAH. 430"}, {"codes": "AH. 863"}, {"title": "O THERE WILL BE JOY"}], "body": [{"type": "verse", "number": 1, "content": "Tuzishim’ imirim’ ishize, Abasarurir’ Imana,\nBashohoj’ umusaruro, I Yerusalemu nshya."}, {"type": "chorus", "content": "Ishimwe hazabahw’ ishimwe,\nNtabw’ ishimwe rizahashira,\nUmunsi w’ ishimw’ uri hafi,\nDuteranir’ iwacu."}, {"type": "verse", "number": 2, "content": "Tuzishima no kuririmba, Tuzajya dushima Kristo.\nTuzamuhimbariza rwos’ i Yerusalemu nshya."}, {"type": "verse", "number": 3, "content": "Tuzahishimira by’ ukuri, Tuzaba mu mazu yera;\nYesu yaduteguriye, I Yerusalemu nshya."}]},
  {"number": 49, "name": "Ntabwo Ndatekereza", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/49", "key": "si bémol", "references": [{"codes": "AH. 324"}, {"codes": "CH. 352"}, {"title": "ONE SWEETLY SOLEMN THOUGHT"}, {"codes": "CS. 882"}], "body": [{"type": "verse", "number": 1, "content": "Ntabwo ndatekereza, Kw’ iwac’ ari bugufi.\nUko bukeye negereza, Gusohora mw’ ijuru."}, {"type": "chorus", "content": "Hafi y’ iwacu, Hafi yaho;\nUbu ngeze hafi y’ iwacu,\nNgiye gusohorayo."}, {"type": "verse", "number": 2, "content": "Ku rurembo rwa Data, Hariy’ amazu menshi;\nYateguriy’ abera bose, Ngo babane na Yesu."}, {"type": "verse", "number": 3, "content": "Ninjya kuger’ iwacu, Nzururuts’ umutwaro;\nNzoroherwa n’ umubabaro, Nambar’ ikamba ryiza."}, {"type": "verse", "number": 4, "content": "Ningera ku nkengero, Nzaba ngeze bugufi;\nNzaba negerey’ i muhira, Ngiye kuger’ iwacu."}]},
  {"number": 50, "name": "Har’ Igihugu Cyiza Cyane", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/50", "key": "sol", "references": [{"codes": "AH. 432"}, {"codes": "CH. 551"}, {"title": "THERE IS A LAND"}, {"codes": "CS. 879"}], "body": [{"type": "verse", "number": 1, "content": "Har’ igihugu cyiza cyane, Twasezeraniwe n’ Imana;\nTugitegereze twizera, Ko Dat’ akitubonereza."}, {"type": "chorus", "content": "Aheza (aheza) mw’ ijuru (mw’ ijuru),\nTuzahurirayo bagenzi.\nAheza (aheza) mw’ ijuru (mw’ ijuru),\nTuzahurirayo bagenzi."}, {"type": "verse", "number": 2, "content": "Tuzaririmbira mw’ ijuru, Indirimbo z’ abanyahirwe.\nNtituzongera kubabara, Tuzaba dushiz’ agahinda."}, {"type": "verse", "number": 3, "content": "Tuzasingiza Data cyane, Ku mbabazi yatugiriye,\nNo ku buntu bw’ urukundo rwe, N’ umugisha yatwungukiye."}]},
  {"number": 51, "name": "Tubatirish’ Umwuka Wera", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/51", "key": "la bémol", "references": [{"codes": "AH. 155"}, {"codes": "CH. 525"}, {"title": "BAPTIZE US ANEW"}, {"codes": "CS. 134"}], "body": [{"type": "verse", "number": 1, "content": "Tubatirishe Umwuka Wera,\nMukiza twegere, duh’ urukundo.\nGusubiramo 1, 2,3: Ubu Mwami Yesu turakwinginga,\nTubatirish’ Umwuka, Duh’ urukundo."}, {"type": "verse", "number": 2, "content": "Turatakamba, Twazize byinshi,\nUdukiz’ utweze, Twishwe n’ ibyaha."}, {"type": "verse", "number": 3, "content": "Mwuka Wera we, Tumanukire!\nDuhire rwos’ ubu, Duh’ imbabazi."}, {"type": "verse", "number": 4, "content": "Ngir’ ijwi ryiza, Ryavuze riti:\nUr’ Umwana wanjye, ni wowe nkunda.\nGusubiramo 4: Turagusingiza, turakuramya\nTuraguhimbaz’ ubu, Mwami; Amina."}]},
  {"number": 52, "name": "Ngwino Soko Y’ Umugisha", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/52", "key": "mi bémol", "references": [{"codes": "SDAH. 258"}, {"codes": "AH. 197"}, {"codes": "CH. 291"}, {"title": "COME, THOU FOUNT"}, {"codes": "CS. 398"}], "body": [{"type": "verse", "number": 1, "content": "Ngwino soko y’ umugisha, Mp’ umutim’ ugushima.\nMigez’ idakama myiza, Tugusingize cyane.\nUnyigishe kukuramy’ iteka, Kandi meny’ ubwiza bwawe.\nKwiringir’ ubwami bwawe, Kunyuzuz’ urukundo."}, {"type": "verse", "number": 2, "content": "Nshyirahw’ icyibutso cyanjye, Ni ho ngeze kubwawe.\nNdizeye yuk’ uzanjyana, Nger’ iwaw’ amahoro.\nYesu yantaruye nazimiye, Nari ndi kure y’ Imana;\nAshaka kunkiz’ urupfu, Yatanz’ ubugingo bwe."}, {"type": "verse", "number": 3, "content": "Ndimw’ ubwishyu bwawe Mwami, Bw’ imbabaz’ ungiriye.\nNyigiza bugufi bwawe, Meny’ urukundo rwawe.\nNgoswe n’ ibingerageza byinshi, Ngo ndek’ iyo Mana nkunda.\nAkir’ umutima wanjye Undinde nkire rwose."}]},
  {"number": 53, "name": "Mwuka Wera Muyobozi", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/53", "key": "sol", "references": [{"codes": "AH. 148"}, {"codes": "CH. 211"}, {"title": "HOLY SPIRIT FAITHFUL GUIDE"}, {"codes": "CS. 632"}], "body": [{"type": "verse", "number": 1, "content": "Mwuka Wera Muyobozi, Ube hafi y’ abakristo!\nMfat’ ukuboko nyobora, Nd’ umugenzi ku gahinga.\nAbananiwe bishima, Ubwo bumv’ ijwi ryiza,\nRibabwira: Bagenzi mwe, Nimuze mbagez’ iwanyu!"}, {"type": "verse", "number": 2, "content": "Ntuduhemukir’ iteka, Ntabwo wanga kudufasha.\nDukomeze tukwizere, Dukabakabe hijimye.\nAmakuba naboneka, Imitima nikuka,\nIjwi riti: Bagenzi mwe, Nimuze mbagez’ iwanyu!"}, {"type": "verse", "number": 3, "content": "Tumaz’ imirimo yacu, Dutegereze gukizwa,\nDusigarany’ iby’ ijuru, Twibaze ko twanditsweyo.\nTwikingir’ ibidutera, No kwiringira Yesu.\nIjwi riti: Bagenzi mwe, Nimuze mbagez’ iwanyu!"}]},
  {"number": 54, "name": "Harihw’ Icyo Nkwaka Mwami", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/54", "key": "si bémol", "references": [{"codes": "AH. 243"}, {"codes": "CH. 634"}, {"title": "HOLY SPIRIT FAITHFUL GUIDE"}, {"codes": "CS. 19"}], "body": [{"type": "verse", "number": 1, "content": "Harihw’ icyo nkwaka Mwami, Nubwo mpora ngucumuraho,\nUnyejeshe, unyejeshe! Amazi cyangw’ umuriro."}, {"type": "chorus", "content": "Mpanagurwe hose Mwami!\nN’ umuriro nib’ ushaka.\nNkir’ ibyaha, birimburwe.\nNkir’ ibyaha, birimburwe."}, {"type": "verse", "number": 2, "content": "Nuntunganiriz’ ubwenge, Nzanezerwa nzagusingiza;\nArik’ umutima wera, Urutaho, urutaho."}, {"type": "verse", "number": 3, "content": "Ninezw’ umutima wanjye, Ni ho nzunguk’ ubwenge bwose,\nMbubwirijwe nawe Mwami, Bwo mw’ ijuru, bwo mw’ ijuru."}, {"type": "verse", "number": 4, "content": "Njya nirind’ ibicumuro, Nkitonder’ ibyo ntekereza.\nMwami n’ ibyo nkora byose, Ntabwo nera, Ntabwo nera."}]},
  {"number": 55, "name": "Har’ Ubwo Wasanze Yesu?", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/55", "key": "la bémol", "references": [{"codes": "CS. 88"}, {"title": "HAVE YOU BEEN TO JESUS?"}], "body": [{"type": "verse", "number": 1, "content": "Har’ ubwo wasanze Yesu ng’ ukire? Se wuhagijw’ amaraso ye?\nUbu wizeye rwos’ imbabazi ze? Se wuhagijw’ amaraso ye?"}, {"type": "chorus", "content": "Wogejwe (wogejwe) na Yesu (na Yesu)?\nWatunganijwe n’ amaraso (maraso)?\nHar’ ubwo yakwuhagij’ amaraso?\nMbes’ imyambaro yaw’ irera?"}, {"type": "verse", "number": 2, "content": "Mbes’ ugendana na Yesu iteka? Se wuhagijw’ amaraso ye?\nMbes’ ujy’ ubana n’ uwari wabambwe? Se wuhagijw’ amaraso ye?"}, {"type": "verse", "number": 3, "content": "Umukwe naz’ uzab’ umwiteguye? Se wuhagijw’ amaraso ye?\nMbes’ uzakundirwa kujya mw’ ijuru? No gukizwa n’ amaraso ye?"}, {"type": "verse", "number": 4, "content": "Hung’ ibyaha jy‘ ukor’ ibitunganye! Wejeshw’ amaraso ya Yesu!\nHar’ isokw’ itemb’ ikiz’ imitima, Wejeshw’ amaraso ya Yesu!"}]},
  {"number": 56, "name": "Nahabiye Kure Y’ Imana", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/56", "key": "la", "references": [{"codes": "AH. 186"}, {"codes": "CH. 560"}, {"title": "I’VE WONDERED FAR AWAY"}, {"codes": "CS. 17"}], "body": [{"type": "verse", "number": 1, "content": "Nahabiye kure y’ Imana, Ndahabuts’ ubu.\nNari naratinze mu byaha, Noneho ndaje."}, {"type": "chorus", "content": "Reka nze, reka nze! Ntabwo nzongera.\nNyemerer‘ umbabarire! Mwami nyakira!"}, {"type": "verse", "number": 2, "content": "Narapfapfany‘ imyaka myinshi, Ndahabuts’ ubu.\nNdakwitwaraho cyane nkiza, Noneho ndaje."}, {"type": "verse", "number": 3, "content": "Ndembejwe n’ ibyaha no kugwa, Ndahabuts’ ubu.\nNiringiy’ urukundo rwawe, Noneho ndaje."}, {"type": "verse", "number": 4, "content": "Yesu yamviriy’ amaraso, Ndahabuts’ ubu.\nUbwe niwe wankiza gusa, Noneho ndaje."}, {"type": "verse", "number": 5, "content": "Wumv’ amaganya yanjy’ unkize, Ndahabuts’ ubu.\nNyeza Mwami nse n’ urubura, Noneho ndaje."}]},
  {"number": 57, "name": "Bayoboke Nimurangurure", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/57", "key": "ré", "references": [{"codes": "AH. 179"}, {"codes": "CH. 571"}, {"title": "WHOSEVER HEARETH"}, {"codes": "CS. 12"}, {"codes": "HL. 212"}], "body": [{"type": "verse", "number": 1, "content": "Bayoboke nimurangurure, Mwamamaz’ ubutumwa mw’ isi yose!\nNimukwiz’ ayo makuru mu bantu! Abashaka nibaze."}, {"type": "chorus", "content": "Uwemey’ aze! Uwemey’ aze!\nNimubimenyesh’ abatuye hasi!\nUmubyey’ aratarur’ abana be,\nAbashaka nibaze."}, {"type": "verse", "number": 2, "content": "Ushaka kuza yitindiganya, Niyinjir’ irembo riruguruye.\nUmwami ni we nzira y’ ubugingo, Abashaka nibaze."}, {"type": "verse", "number": 3, "content": "Ushaka wese nagire bwangu! Kand’ agir’ ubutwari yihangane.\nUshaka wes’ azahabw’ ubugingo, Abashaka nibaze."}]},
  {"number": 58, "name": "Jy’ Uganza Mwami W’ Iteka", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/58", "key": "sol", "references": [{"codes": "AH. 126"}, {"codes": "CH. 156"}, {"title": "ALL HAIL THE POWER"}, {"codes": "CS. 258"}], "body": [{"type": "verse", "number": 1, "content": "Jy’ uganza Mwami w’ iteka, Bose bakuramye!\nNimuzan’ ikamba ry’ ubwami bwe, Ab’ Umwami wa bose!\nNimuzan’ ikamba ry’ ubwami bwe, Kw’ ari we Mwami wa bose."}, {"type": "verse", "number": 2, "content": "Batowe mwe b’ Israeli, Mwa nkehwe mwe nkeya,\nMuramy’ ubakirish’ imbabazi, Ab’ Umwami wa bose!\nMuramy’ ubakirish’ imbabazi, Kw’ ari we Mwami wa bose."}, {"type": "verse", "number": 3, "content": "Amoko yose yo hasi, N’ imiryango yose,\nBose bajye bamwubaha cyane! Ab’ Umwami wa bose.\nBose bajye bamwubaha cyane! Kw’ ari we Mwami wa bose."}, {"type": "verse", "number": 4, "content": "Muze tumuririmbire, Tumupfukamire,\nTumusingize no kumushima, Ab’ Umwami wa bose.\nTumusingize no kumushima, Kw’ ari we Mwami wa bose."}]},
  {"number": 59, "name": "Yesu Mukunzi Wanjye", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/59", "key": "fa", "references": [{"codes": "SDAH. 490"}, {"codes": "AH. 116"}, {"title": "JESUS LOVER OF MY SOUL"}, {"codes": "CH. 401"}, {"codes": "CS. 635"}, {"codes": "HL. 256"}], "body": [{"type": "verse", "number": 1, "content": "Yesu mukunzi wanjye, Mpa kuguhungiraho.\nUbw’ umurab’ usuma, N’ umugar’ ugwa cyane,\nUmpishe Mukiza we! Kugez’ ah’ uhitira.\nUnyobor’ ahikinze, Nuk’ unkiz’ unyakire!"}, {"type": "verse", "number": 2, "content": "Nta bundi buhungiro, Mwam’ unyirokorere!\nNtunzibukire rwose, Komez’ ujy’ undengera!\nNkwizigire wenyine! Ni wow’ ump’ imbaraga,\nUhashy’ abanzi banjye, Simpugane na hato."}, {"type": "verse", "number": 3, "content": "Ngushime Mwami Yesu, K’ utagir’ icy’ unyima,\nUsindagiz’ urushye, N’ urway’ uramukiza;\nUrera bihebuje, Ntabwo ngutunganiye,\nNdi mubi bikabije, Wow’ urakiranutse."}, {"type": "verse", "number": 4, "content": "Ubabarira cyane, Kand’ imbabazi zawe,\nZirut’ ibyaha byanjye. Nyeza nkomeze nere,\nWe soko y’ ubugingo! Nkundira nkuvomemo!\nUnyuzur’ umutima, Nzagere ku bugingo."}]},
  {"number": 60, "name": "Yesu Utunezeza Twese", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/60", "key": "la", "references": [{"codes": "SDAH. 242"}, {"codes": "AH. 128"}, {"title": "JESUS, THOU JOY OF LOVING HEARTS"}, {"codes": "CH. 154"}, {"codes": "CS. 452"}], "body": [{"type": "verse", "number": 1, "content": "Yes’ utunezeza twese,\nSoko y’ ubuging’ ur’ umucyo w’ abantu;\nIbyishimo byose byo hasi, Tubicitseho tugukurikire."}, {"type": "verse", "number": 2, "content": "Tuvune turakwisunze.\nUkuri kwawe ntikugir’ impinduka;\nDutabare turakwizeye, Tukwiyeguriye tumaramaje."}, {"type": "verse", "number": 3, "content": "Mutsima w’ ubugingo we!\nDushaka guhazwa naw’ iteka ryose.\nSoko nziz’ idakam’ iteka! Tumar’ inyota mu mitima yacu!"}, {"type": "verse", "number": 4, "content": "Mu midugararo yacu,\nTukwifuz’ iteka, Mwami mwiza rwose.\nTunezerwa cyan’ umwenyuye; N’ amahirwe yac’ ubwo duhorana."}, {"type": "verse", "number": 5, "content": "Yesu bana natw’ iteka!\nDuh’ amahoro twishim’ iteka ryose!\nDukiz’ ibibi bitugota! Murika kw’ is’ umucyo wawe wera!"}]},
  {"number": 61, "name": "Nkunda Kunguk’ Ibya Yesu", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/61", "key": "la bémol", "references": [{"codes": "AH. 109"}, {"codes": "CS. 525"}, {"title": "MORE ABOUT JESUS"}, {"codes": "SDAH. 245"}], "body": [{"type": "verse", "number": 1, "content": "Nkunda kunguk’ ibya Yesu, Kwerekan’ imbabazi ze;\nKwunguk’ ubwenge bw’ ukuri, N’ urukundo rw’ Umukiza."}, {"type": "chorus", "content": "Nunguk’ ibya Yesu, Nunguk’ ibya Yesu.\nKwunguk’ ubwenge bw’ ukuri,\nN’ urukundo rw’ Umukiza."}, {"type": "verse", "number": 2, "content": "Nshishikarir’ ibya Yesu, Meny’ iby’ ashaka binkwiye,\nMwuka Wera mfuturira! Mbwir’ uko Yesu yankunze!"}, {"type": "verse", "number": 3, "content": "Nunguk’ ijambo rya Yesu, Mbane n’ Umwam’ antoneshe;\nNumvir’ iby’ ambwira byose, Mpuze na we muyoboke."}, {"type": "verse", "number": 4, "content": "Meny’ iby’ ingoma ya Yesu, Menye n’ ubwiza bwe bwose,\nMenye n’ ukw’ agiye kwima, Ni we Mwami w’ amahoro."}]},
  {"number": 62, "name": "Yesu Ndagukunze Rwose", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/62", "key": "fa", "references": [{"codes": "SDAH. 321"}, {"codes": "AH. 234"}, {"title": "MY JESUS I LOVE THEE"}, {"codes": "CH. 276"}, {"codes": "CS. 299"}], "body": [{"type": "verse", "number": 1, "content": "Yesu ndagukunze rwose, Ndakwihaye.\nIngeso mbi zose, Nzanz’ uko zingana.\nNi wowe Mukiza wanjye mwiza, Nkuyoboke.\nNtabwo nigeze kugukunda, Nk’ ubu ngubu."}, {"type": "verse", "number": 2, "content": "Ndagukunze kuko wabanje, Kunkunda,\nWaranyiguriy’ unkiriz’ i Kalwari.\nNgukundiy’ ikamba ry’ amahwa, Wahambikiwe,\nNtabwo nigeze kugukunda, Nk’ ubu ngubu."}, {"type": "verse", "number": 3, "content": "Mperey’ ubu ngukunda, Nzageza gupfa.\nNzajya ngusingiz’ iteka, Ngihumeka;\nNah’ urupfu ruzanyegurira, Nzavuga nti:\nNtabwo nigeze kugukunda, Nk’ ubu ngubu."}, {"type": "verse", "number": 4, "content": "Ubwo nzager’ aho, Waduteguriye,\nNzajya mpaguhamiriz’ itek’ iteka.\nNzaguhimbaza nambay’ ikamba, Ritunganye;\nNtabwo nigeze kugukunda, Nk’ ubu ngubu."}]},
  {"number": 63, "name": "N’ Iki Cyankiz’ Ibyaha?", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/63", "key": "sol", "references": [{"codes": "CS. 93"}, {"title": "WHAT CAN WASH AWAY MY SINS?"}], "body": [{"type": "verse", "number": 1, "content": "N’ iki cyankiz’ ibyaha? N’ amaraso yawe Yesu.\nN’ iki cyanyeza rwose? N’ amaraso yawe Yesu."}, {"type": "chorus", "content": "Maras’ atunganye, Ni y’ amboneza rwose.\nNta cyampa gukira, Nk’ amaraso y’ Umukiza."}, {"type": "verse", "number": 2, "content": "Nta kindi cyantunganya, N’ amaraso yawe Yesu.\nNta kindi cyiru mfite, N’ amaraso yawe Yesu."}, {"type": "verse", "number": 3, "content": "Nta cyantsembahw’ ibyaha, N’ amaraso yawe Yesu.\nNta byanjye byamboneza, N’ amaraso yawe Yesu."}, {"type": "verse", "number": 4, "content": "Ni wowe niringira, N’ amaraso yawe Yesu.\nNi wow’ ump’ amahoro, N’ amaraso yawe Yesu."}, {"type": "verse", "number": 5, "content": "Njye ngusingiza cyane, Ku maraso yawe Yesu.\nMukiz’ urakarama, Ku maraso wamviriye."}]},
  {"number": 64, "name": "S’ Uhagarikiy’ Ik’ Umutima?", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/64", "key": "si bémol", "references": [{"codes": "CS. 515"}, {"title": "ARE YOU WEARY?"}, {"codes": "HL. 465"}], "body": [{"type": "verse", "number": 1, "content": "S’ uhagarikiy’ ik’ umutima? Bibwire Yesu! Bibwire Yesu!\nUbabajwe no kubur’ ituza? Ihererane Yesu!"}, {"type": "chorus", "content": "Bibwire Yesu! Bibwire Yesu!\nNi we nshuti y’ ukuri;\nNtugir’ indi nshut’ ihwanye na we,\nJy’ ubana na we cyane."}, {"type": "verse", "number": 2, "content": "Mbes’ ub’ urabogoz’ amarira? Bibwire Yesu! Bibwire Yesu!\nUtotezwa n’ ibyaha wahishe? Ihererane Yesu!"}, {"type": "verse", "number": 3, "content": "Ujy’ utinya guterwa n’ ibyago? Bibwire Yesu! Bibwire Yesu!\nMbes’ ub’ uraganyishwa n’ iby’ ejo? Ihererane Yesu!"}, {"type": "verse", "number": 4, "content": "Mbes’ ujy’ ugir’ ubwoba bwo gupfa? Bibwire Yesu! Bibwire Yesu!\nMbes’ urashak’ ingoma ya Kristo? Ihererane Yesu!"}]},
  {"number": 65, "name": "Nkunda Kwiringira Yesu", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/65", "key": "la bémol", "references": [{"codes": "SDAH. 524"}, {"codes": "AH. 201"}, {"title": "‘TIS SO SWEET TO TRUST IN JESUS"}, {"codes": "CH. 588"}, {"codes": "CS. 519"}], "body": [{"type": "verse", "number": 1, "content": "Nkunda kwiringira Yesu, Nkajya mwumvira rwose,\nNo kwizer’ umurage we, N’ amateka y’ Imana."}, {"type": "chorus", "content": "Nkoyoboke Mwami rwose;\nNajyaga nshidikanya,\nYesu Yesu mwiza nkunda,\nMfasha nkwumvire rwose!"}, {"type": "verse", "number": 2, "content": "Nkunda kwiringira Yesu; Nkizwa n’ amaraso ye.\nAnsendahw’ ibicumuro, Ni y’ antunganya rwose."}, {"type": "verse", "number": 3, "content": "Nimenya kumwiringira, Sinzaba ngicumura.\nNi ho nzagir’ ubuhoro, N’ ubugingo bw’ iteka."}, {"type": "verse", "number": 4, "content": "Mpimbawe no kukumenya, Yesu Mukiza nkunda.\nNizeye k’ umpora hafi, Nuko nguman’ iteka."}]},
  {"number": 66, "name": "Nshim’ Umunsi Nakwemeye", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/66", "key": "sol", "references": [{"codes": "AH. 262"}, {"codes": "CH. 310"}, {"title": "O HAPPY DAY!"}, {"codes": "CS. 399"}, {"codes": "HL. 272"}], "body": [{"type": "verse", "number": 1, "content": "Nshim’ umunsi nakwemeye, Mwami Yesu Mukiza we!\nNshima cyane n’ umutima, Ndabwiriz’ ibinezeza."}, {"type": "chorus", "content": "Mpimbaze, mpimbaze; Yesu wankijij’ ibyaha.\nAnyigisha kumuramya, Ngo nezerw’ iminsi yose;\nMpimbaze, mpimbaze Yesu wankijij’ ibyaha."}, {"type": "verse", "number": 2, "content": "Biramaze, napfiriwe, Nd’ uwa Yesu wandokoye;\nYangiz’ uwe, Nkurikire, Nshima yuko ntowe na we."}, {"type": "verse", "number": 3, "content": "Mutima wanjye ruhuka; Reba mw’ ijur’ ahejejwe,\nNtugasig’ Umwami wawe, Bana na we mwumvikane."}, {"type": "verse", "number": 4, "content": "Iteka nzagukorera, Iby’ isi ndabizinutswe.\nNkugarutseho noneho, Sinzarorera kwishima."}, {"type": "verse", "number": 5, "content": "Ubw’ umucyo wo mw‘ ijuru uzamurikir’ iyi si.\nNsanganir’ Umwami wanjye, Tuzibanire mw‘ ijuru."}]},
  {"number": 67, "name": "Abatoni B’ Umwami", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/67", "key": "sol", "references": [{"codes": "AH. 435"}, {"codes": "CH. 640"}, {"title": "COME WE THAT LOVE THE LORD"}, {"codes": "CS. 887"}], "body": [{"type": "verse", "number": 1, "content": "Abatoni b’ Umwami! Nimuze dusakaze hos’ umunezero wacu,\nTurangururire rimwe, Dukikij’ intebe, Dukikij’ intebe."}, {"type": "chorus", "content": "Turajy’ i Siyoni, Ku murwa mwiz’ utunganye.\nTurajy’ i Siyoni, Ku murwa mwiz’ utunganye w’ Imana."}, {"type": "verse", "number": 2, "content": "Murek’ ibyigomeke, Byanga gushim’ Umwami. Arikw’ abana b’ Imana,\nArikw’ abana b’ Imana, Muhore mwishima, Muhore mwishima."}, {"type": "verse", "number": 3, "content": "Twishimir’ i Siyoni, N’ umudugudu wera; Tuzahahurira twese,\nTuzahahurira twese. Hazahor’ ituza, Hazahor’ ituza."}, {"type": "verse", "number": 4, "content": "Turirimbe cyan’ ubu, Hataba n’ umw’ urira. Tugiye kuger’ iwacu,\nTugiye kuger’ iwacu, Mu gihugu cyiza, Mu gihugu cyiza."}]},
  {"number": 68, "name": "Naguzw’ Amaraso Y’ Intama", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/68", "key": "la", "references": [{"codes": "SDAH. 338"}, {"codes": "AH. 195"}, {"title": "REDEEMED! HOW I LOVE TO PROCLAIM IT"}, {"codes": "CH. 635"}, {"codes": "CS. 199"}], "body": [{"type": "verse", "number": 1, "content": "Naguzw’ amaraso y’ Intama, Ncunguzw’ imbabazi zayo.\nUbu nd’ umwana wayo rwose, Ntaho ntazabyamamaza."}, {"type": "chorus", "content": "Nkiza (nkiza), nkiza (nkiza), N’ amaraso yawe Yesu.\nMboneza, mboneza! Nd’ umwana wawe rwos’ ubu."}, {"type": "verse", "number": 2, "content": "Mpimbaze Yesu wankijije, Nta wuz’ uko nezerewe.\nNiwe mucyo mwiz’ unyobora, Ahorana nanjy’ iteka."}, {"type": "verse", "number": 3, "content": "Ntabwo mpung’ Umukiza wanjye, Njya mutekerez’ iteka.\nNtabwo ndambirwa kumurata, Njya nsingiz’ urukundo rwe."}, {"type": "verse", "number": 4, "content": "Nzi ko nzamubonan’ ubwiza, Nezerwa n’ amateka ye.\nAndinda nez’ aho njya hose, Mutaramira ndirimba."}, {"type": "verse", "number": 5, "content": "Nizeye kw‘ ambikiy’ ikamba, Mu rugo rwe rwo mw‘ ijuru.\nMaze tuzahoran’ iteka, N’ abamuyobotse bose."}]},
  {"number": 69, "name": "Tuzaramban’ Amazi Yera", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/69", "key": "mi bémol", "references": [{"codes": "CS. 206"}, {"title": "WE WILL TARRY BY THE LIVING WATER"}], "body": [{"type": "verse", "number": 1, "content": "Tuzaramban’ amazi yera, Y’ isokw’ ibeshaho.\nNi ho Yes’ azadutegera, N’ ihuriro ryiza."}, {"type": "chorus", "content": "Tuzaramban’ amazi yera (yera),\nKuramban’ amazi yera (yera),\nKuramban’ amazi yera (yera),\nTuzatinda kw’ isoko."}, {"type": "verse", "number": 2, "content": "Imirimo niducogoza, Turuhuke hato!\nKu mazi y’ urubogobogo, Ku masoko meza."}, {"type": "verse", "number": 3, "content": "Tyo nimuze mwisunge Kristo Abah’ imbaraga,\nKandi mumeny’ ubury’ akiza! Munywe mwic’ inyota!"}]},
  {"number": 70, "name": "Igihe Yes’ Azakorany’ Amoko", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/70", "key": "fa", "references": [{"codes": "AH. 396"}, {"codes": "CH. 538"}, {"title": "WHEN JESUS SHALL GATHER"}, {"codes": "CS. 42"}], "body": [{"type": "verse", "number": 1, "content": "Igihe Yes’ azakorany’ amoko, Ngw’ ahagarar’ imbere Ye,\nTwese tuzagenzwa dute mu manza, Dutumiwe gutegekwa?"}, {"type": "chorus", "content": "Azahunik’ ingano mu bigega,\nArik’ umuram’ azawusesa.\nTwese tuzagenzwa dute mu manza,\nZ’ uwo munsi wo kuzurwa?"}, {"type": "verse", "number": 2, "content": "Nind’ uzumv’ Umukiz’ amubwir’ ati: Ur’ umugaragu mwiza?\nCyangw’ uzamarwa n’ ubwob’ ubwiwe ngo: Hoshi genda ndaguciye?"}, {"type": "verse", "number": 3, "content": "Azamwenyur’ abonany’ abana be, Icyitegererezo Cye,\nAzabambik’ ibyiza byo mw‘ ijuru, Ubwo bamupfukamire."}, {"type": "verse", "number": 4, "content": "Tube maso dutegerez’ Umwami, N’ imuri zigumye zake!\nKugira ng’ Umukwe naz’ azasange, Tumaze kumwitegura."}, {"type": "verse", "number": 5, "content": "Tujye dutekerez’ ibyo mw‘ ijuru, Urugendo nirushira,\nTuzahagarar’ imbere y’ Imana, Niba tutagamburura."}]},
  {"number": 71, "name": "Sinita Ku Butunzi", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/71", "key": "la bémol", "references": [{"codes": "AH. 281"}, {"codes": "CH. 617"}, {"title": "IS MY NAME WRITTEN THERE?"}, {"codes": "CS. 860"}], "body": [{"type": "verse", "number": 1, "content": "Sinita ku butunzi, Feza na zahabu.\nNdashak’ ibyo mw’ ijuru; Nzajyane n’ abera.\nYesu Mukiza mbwira: Igitabo cyawe,\nCyera cy’ ubwami bwawe, Mbese nanditswemo?"}, {"type": "chorus", "content": "Mbese nanditswemo, Ku mpapuro zera?\nMu gitabo cy’ ubwami, Mbese nanditswemo?"}, {"type": "verse", "number": 2, "content": "Ibyaha byanjye Mwami, Birut’ umusenyi.\nNgwino Mwam’ ubinkirish’ amaraso yawe!\nWadusezeraniye, Yukw’ ibyaha byacu,\nNibisa n’ umuhemba, Ng’ uzabyeza rwose."}, {"type": "verse", "number": 3, "content": "Mu mudugudu mwiza, N’ amazu yera de,\nN’ abera bawurimo, Barimban’ ibyera,\nNta bibi biwegera, Byakwanduz’ ibyiza,\nNiho hab’ amahoro, Mbese nanditswemo?"}]},
  {"number": 72, "name": "Har’ Imanz’ Ubu", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/72", "key": "mi bémol", "references": [{"codes": "SDAH. 416"}, {"codes": "AH. 378"}, {"title": "THE JUDGMENT HAS SET"}, {"codes": "CH. 482"}], "body": [{"type": "verse", "number": 1, "content": "Har’ imanz’ ubu; Nta kitarondorwa, Mbese tuzamera dute?\nTugez’ imbere y’ umucamanza, Abony’ ibyo twakoze byose?"}, {"type": "chorus", "content": "Tuzaba mu ruhe ruhande, Kur’ uwo munsi ukomeye?\nMbese tuzaba twiringanije? Cyangwa tuzatsindwa n’ ibyaha?"}, {"type": "verse", "number": 2, "content": "Zatangiriye mu basinziriye, Zizaza no mu bariho.\nTuzasuzumirwa mu byanditswe, Nibyo bizaduhamya rwose."}, {"type": "verse", "number": 3, "content": "Tuzavug’ iki tugeze mu manza, Ibitabo bibumbuwe,\nUmuntu wes’ abwirw’ imanza ze, Atakibon’ umurokora?"}]},
  {"number": 73, "name": "Umwami Ni We Udutumira", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/73", "key": "mi bémol", "references": [{"codes": "AH. 395"}, {"codes": "CH. 537"}, {"title": "CALLED TO THE FEAST"}, {"codes": "CS. 43"}], "body": [{"type": "verse", "number": 1, "content": "Umwami ni w’ udutumira, Ngw’ aduteranye n’ ubwoko bwe.\nAzasanga tumeze dute, Ahw’ azazira?"}, {"type": "chorus", "content": "Mwana wa Data we tyo se; Ubw’ Umwam’ azaza,\nTwebwe tuzamera dute? Umwami naza?"}, {"type": "verse", "number": 2, "content": "Tuzatamirizw’ amakamba, Uwaducunguye yimitswe,\nTuzahorana na w’ iteka, Ahw’ azazira."}, {"type": "verse", "number": 3, "content": "Nkuk’ umuraby’ ugaragara, Ni kw’ azagaragaza byose;\nAzerekan’ ibyo twakoze, Ahw’ azazira."}, {"type": "verse", "number": 4, "content": "Azishim’ ubw’ azabon’ abe, Bambay’ imyambaro yera de.\nNituganza tuzanezerwa, Ahw’ azazira."}, {"type": "verse", "number": 5, "content": "Ntabwo tuzongera gutana, Abanga kumwumvira bose,\nBazataka no kuboroga, Yes’ agarutse."}, {"type": "verse", "number": 6, "content": "Mwami ni wowe twiringiye; Twigishe kugutegereza,\nTutazatinya kukubona, Ah’ uzazira."}]},
  {"number": 74, "name": "Biba Mu Gitondo", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/74", "key": "la bémol", "references": [{"codes": "AH. 363"}, {"codes": "CH. 621"}, {"title": "SAWING IN THE MORNING"}, {"codes": "CS. 583"}], "body": [{"type": "verse", "number": 1, "content": "Biba mu gitondo, Imbuto z’ ineza!\nJy’ ubiba ku manywa n’ ikigoroba!\nRindira ko zera! Hazaz’ usarura,\nTuzishima cyane, Dutund’ imiba."}, {"type": "chorus", "content": "Dutund’ imiba, Dutund’ imiba.\nTuzishima cyane, Dutund’ imiba."}, {"type": "verse", "number": 2, "content": "Bib’ izuba riva! Biba mu gitundwe!\nNtugatiny’ ibihu, N’ imbeho nyinshi!\nMaz’ umusaruro, N’ imirim’ ishize,\nTuzishima cyane, Dutund’ imiba."}, {"type": "verse", "number": 3, "content": "Tugende turira, Tubibir’ Umwami,\nNiba tubabazwa N’ abazimira,\nUbwo tuzahozwa, Tuzakizwa na we.\nTuzishima cyane, Dutund’ imiba."}]},
  {"number": 75, "name": "Ni Ijwi Ry’ Umwungeri Numva", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/75", "key": "la bémol", "references": [{"codes": "SDAH. 361"}, {"codes": "AH. 347"}, {"codes": "CH. 625"}, {"title": "HARK TIS THE SHEPHERD’ S VOICE"}, {"codes": "CS. 561"}, {"codes": "HL. 531"}], "body": [{"type": "verse", "number": 1, "content": "N’ ijwi ry’ Umwungeri numva, Ritabariza mw’ ishyamba;\nKw’ intama ze zazimiye; Mu bushyo ni ho zavuye."}, {"type": "chorus", "content": "Nimuze, nimuze, Tuzikurikire mw’ ishyamba!\nNimuze, nimuze, Tuzigarurire Yesu!"}, {"type": "verse", "number": 2, "content": "Dutabar’ uwo Mwungeri, Dushakan’ izo nzimizi!\nTuzigarure mu bushyo, Niho zikirir’ imbeho!"}, {"type": "verse", "number": 3, "content": "Ziratakira mw’ ishyamba, Zigeze habi mu manga.\nUmwam’ arababwir’ ati: Munshakir’ intama zanjye!"}]},
  {"number": 76, "name": "Kiz’ Abanyabyaha", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/76", "key": "si bémol", "references": [{"codes": "SDAH. 367"}, {"codes": "AH. 348"}, {"title": "RESCUE THE PERISHING"}, {"codes": "CH. 623"}, {"codes": "CS. 478"}], "body": [{"type": "verse", "number": 1, "content": "Kiz’ abanyabyaha, Rwaz’ abarwayi!\nUbarokor’ ibyago n’ urupfu!\nHabur’ abahabye! Byuts’ abaguye!\nBabwire ko Yes’ azi gukiza!"}, {"type": "chorus", "content": "Kiz’ abanyabyaha, Rwaz’ abarwayi!\nYes’ umunyambabaz’ arakiza."}, {"type": "verse", "number": 2, "content": "Abamushungera, Na bo ntabanga.\nAtegerez’ abicuza rwose,\nBahate bihane, Jy’ ubasabira!\nNibizer’ azabababarira."}, {"type": "verse", "number": 3, "content": "Toz’ abazimiye! Be kuzuyaza.\nBarek’ irari ry’ ibidakwiye!\nBuzur’ urukundo, Bagire neza.\nBagarukir’ uwabacunguye!"}, {"type": "verse", "number": 4, "content": "Kiz’ abanyabyaha! Biragukwiye.\nUmwam’ azaguhet’ imbaraga,\nBos’ ubayobore mu nzira ntoya!\nMenyesh’ indushyi ko zarokowe!"}]},
  {"number": 77, "name": "Nkunda Kwogez’ Amagambo", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/77", "key": "la bémol", "references": [{"codes": "SDAH. 457"}, {"codes": "AH. 95"}, {"codes": "CH. 518"}, {"title": "I LOVE TO TELL THE STORY"}, {"codes": "CS. 476"}, {"codes": "HL. 55"}], "body": [{"type": "verse", "number": 1, "content": "Nkunda kwogez’ amagambo, Y’ ubwami bwo mw’ ijuru;\nYa Yesu n’ ishimwe rye, Ya Yesu n’ urukundo rwe.\nNi yo nkunda kwogeza, Kuko nzi kw’ ar’ ukuri;\nNi y’ amp’ ibyo nifuza, Nta handi mbibona."}, {"type": "chorus", "content": "Ni yo nkunda kwogeza;\nNkize nzaba nkivuga,\nUkw’ ab’ isi bahoranye,\nImpuhwe za Yesu."}, {"type": "verse", "number": 2, "content": "Nkunda kwogez’ amagambo, Arut’ ibintu byose;\nAhebuz’ umurimbo; N’ ibyo turigira byose,\nNi yo nkunda kwogeza. Yangiriy’ umumaro;\nSimpwema kuyarata, Ngw’ abakize namwe."}, {"type": "verse", "number": 3, "content": "Nkunda kwogez’ amagambo, Nkomeze njye nyavuga;\nAranogera cyane, Kukw’ ambwiriz’ iby’ ijuru;\nNi yo nkunda kwogeza, Nyabwir’ abatayazi,\nBameny’ ako gakiza, Kava mu nzandiko."}, {"type": "verse", "number": 4, "content": "Nkunda kwogez’ amagambo, Nyabwira n’ abayazi,\nN’ abayakennye na bo, Bose bashaka kuyumva.\nUbwo nzaba mw’ ijuru, Ndirimb’ indirimbo nshya,\nNa y’ izab’ impimbaye, Nk’ amagambo nkunda."}]},
  {"number": 78, "name": "Tujye Dusabir’ Abazimiye", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/78", "key": "si bémol", "references": [{"codes": "CS. 532"}, {"title": "SEEKING THE LOST"}, {"codes": "HL. 596"}], "body": [{"type": "verse", "number": 1, "content": "Tujye dusabir’ abazimiye, Bahabiye kure y’ Imana!\nTubahinduz’ ubutumwa bwiza, Bamenye k’ Umwam’ abakunda!"}, {"type": "chorus", "content": "S.,A. na T : Tujye hose dusang’ abantu bose!\nTugarurir’ Iman’ abazimiye!\nTubane mu bushyo bw’ Umucunguzi,\nYesu watambiy’ abanyabyaha.\nB.,A. Na :Tujye hose, …sang’ abantu bose!\nTugarurir’ …man’ abazimiye!\nTubane mu …shyo bw’ Umucunguzi,\nYesu watambiy’ abanyabyaha."}, {"type": "verse", "number": 2, "content": "Tugarurire Yes’ abahabye, Intebyi zidafit’ intege!\nTuzerek’ aho zizakirira, Zimeny’ inzira y’ ubugingo!"}, {"type": "verse", "number": 3, "content": "Tugend’ uko Yesu yadutoye, Tujye tumuyobok’ iteka!\nRwaz’ abarwayi byuts’ abaguye! Yobor’ abahabye kwa Yesu."}]},
  {"number": 79, "name": "Imirim’ Irez’ Ahantu Hose", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/79", "key": "la bémol", "references": [{"codes": "SDAH. 358"}, {"codes": "AH. 338"}, {"title": "FAR AND NEAR THE FIELDS"}, {"codes": "CH. 448"}, {"codes": "CS. 547"}], "body": [{"type": "verse", "number": 1, "content": "Imirim’ irez’ ahantu hose; N’ igihe cyo gusarura.\nUbu n’ igihe cyo gusarura, Mu bibaya n’ imusozi."}, {"type": "chorus", "content": "Mwam’ oherez’ abasaruzi!\nTuvune turagutabaza!\nBohereze baterany’ imiba!\nIgihe kiracyariho."}, {"type": "verse", "number": 2, "content": "Bohereze mu gitondo kare! Ubohereze ku manywa!\nN’ igih’ izuba ryenda kurenga, Bategeke basarure!"}, {"type": "verse", "number": 3, "content": "Tyo ntumwa y’ Umwami gir’ umwete! Uterany’ ibisarurwa!\nMaz’ ah’ uzarangiriza rwose, Uzishimira mw’ ijuru!"}]},
  {"number": 80, "name": "Dukoran’ Umwete", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/80", "key": "fa", "references": [{"codes": "HL. 538"}, {"codes": "CS. 576"}, {"title": "TO THE WORK"}], "body": [{"type": "verse", "number": 1, "content": "Dukoran’ umwete, dukorer’ Imana! Twihute dukurikiz’ Umwami wacu!\nIjambo rye ni ryo riduh’ imbaraga; Tugir’ umwete mwinshi tumuyoboke!"}, {"type": "chorus", "content": "Dukore (dukore), dukore (dukore),\nDukore (dukore), dukore (dukore).\nTwizere (twizere), twitonde (twitonde),\nDuhore twitez’ Umwami!"}, {"type": "verse", "number": 2, "content": "Dukoran’ umwete! Duhaz’ abashonje! Tuyobor’ abaremby’ aho bakirira.\nNi ko kwamamaz’ inkuru y’ Umukiza, Dukomeze twiratan’ umusaraba."}, {"type": "verse", "number": 3, "content": "Dukoran’ umwete, dutarure bose! Kukw’ ingoma zo hasi zizahanguka.\nKand’ Uwitek’ azasingizwa na bose, Abera bazaririmba ko bakize."}, {"type": "verse", "number": 4, "content": "Dukoran’ umwete, Dutebuts’ Umwami! Kukw‘ igihe cy’ isarura kiri hafi.\nTujye gutur’ iwabo w’ abacunguwe, Tuzahora turirimb’ uko twakize."}]},
  {"number": 81, "name": "Kor’ Ugifit’ Uburyo", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/81", "key": "fa", "references": [{"codes": "SDAH. 375"}, {"codes": "AH. 362"}, {"title": "WORK FOR THE NIGHT IS COMING"}, {"codes": "CH. 446"}, {"codes": "CS. 720"}, {"codes": "HL. 348"}], "body": [{"type": "verse", "number": 1, "content": "Kor’ ugifit’ uburyo, Kora hakibona!\nJy’ ukora no mu kime, Jy’ ushir’ ubute!\nKora no ku manyw’ akaze! Ntucogore rwose!\nKora bugiye kwira, Mar’ imirimo!"}, {"type": "verse", "number": 2, "content": "Kora bugiye kwira! Kor’ amanywa yose!\nKomez’ ukor’ iteka, Ntukaruhuke!\nMu bihe byos’ ukiriho, Ntugahweme rwose!\nKomeza butarira, Mar’ imirimo!"}, {"type": "verse", "number": 3, "content": "Kora bugiye kwira! Ubu harabona.\nBugiye kugoroba, Gira n’ ingoga!\nUgeze ko bwira rwose, Izuba rirenze,\nNtugatuze gukora, Mar’ imirimo!"}]},
  {"number": 82, "name": "Mu Gitondo Njya Ndirimba", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/82", "key": "fa", "references": [{"codes": "SDAH. 39"}, {"codes": "AH. 31"}, {"title": "LORD, IN THE MORNING"}, {"codes": "CH. 39"}, {"codes": "CS. 776"}], "body": [{"type": "verse", "number": 1, "content": "Mu gitondo njya ndirimba,\nNguhimbaza Mwami,\nNguh’ amasengesho yanjye,\nKuko nkwiringiye."}, {"type": "verse", "number": 2, "content": "Ku misozi ni ho Yesu,\nYajyag’ asabira;\nNo gutakambira Data,\nNgw’ adukiz’ ibyago."}, {"type": "verse", "number": 3, "content": "Mwam’ unyoboresh’ Umwuka.\nMu nzir’ itunganye.\nUntunganiriz’ ubwenge,\nMeny’ ibikwiriye."}, {"type": "verse", "number": 4, "content": "Abubah’ izina ryawe,\nUrajy’ ubumvira.\nUbakingir’ imbabazi.\nBakir’ amakuba."}]},
  {"number": 83, "name": "Mwese Musingiz’ Umwami", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/83", "key": "la", "references": [{"codes": "SDAH. 250"}, {"codes": "CS. 288"}, {"title": "O FOR A THOUSAND TONGUES"}], "body": [{"type": "verse", "number": 1, "content": "Mwese musingiz’ Umwami muti: Izina ryawe ryubahwe.\nMwami niw’ ugir’ ishimwe ryose, Izina ryawe ryubahwe."}, {"type": "chorus", "content": "Mwubah’ izina, Mwubah’ izina!\nMwubah’ izina ry’ Umwami!\nMwubah’ izina, Mwubah’ izina!\nMwubah’ izina ry’ Umwami!"}, {"type": "verse", "number": 2, "content": "Yesu zina ritumar’ ubwoba, Mwubah’ izina ry’ Umwami!\nNi nk’ inanga ku bafit’ ibyaha, Mwubah’ izina ry’ Umwami!"}, {"type": "verse", "number": 3, "content": "Adukiz’ imbaraga y’ ibyaha, Mwubah’ izina ry’ Umwami!\nAmaraso y’ adukiza rwose. Mwubah’ izina ry’ Umwami!"}]},
  {"number": 84, "name": "Dushime Nyir’ Umugisha", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/84", "key": "sol", "references": [{"codes": "SDAH. 694"}, {"codes": "AH. 13"}, {"codes": "CH. 683"}, {"title": "PRAISE GOD FROM WHOM"}, {"codes": "CS. 470"}, {"codes": "HL. 1"}], "body": [{"type": "verse", "number": 1, "content": "Dushime Nyir’ Umugisha,\nAbo mw’ isi tumushime;\nN’ abo mw’ ijuru bashime,\nDat’ Umwan’ Umwuka Wera. Amen."}]},
  {"number": 85, "name": "Nsingiz’ Imana Rurema", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/85", "key": "la", "references": [{"codes": "SDAH. 88"}, {"codes": "AH. 67"}, {"title": "I SING THE MIGHTY POWER"}, {"codes": "CH. 93"}, {"codes": "CS. 330"}], "body": [{"type": "verse", "number": 2, "content": "Nsingiz’ Imana Rurema, Yaremy’ imisozi;\nYadendej’ inyanja zose, Yahanits’ ijuru;\nNsingiz’ iyahay’ izuba, Kumurika mu munsi.\nIh’ ukwezi kubonesha, N’ inyenyer’ umucyo."}, {"type": "verse", "number": 3, "content": "Nsingiz’ ibambe ry’ Umwami, Wujuj’ is’ imyaka;\nYaremeshej’ ijambo rye, Ibizima byose.\nMwami mbon’ ibitangaza, Byaw’ aho ndeba hose,\nHano hasi no hejuru, Ntabwo bihinyuka."}, {"type": "verse", "number": 4, "content": "Nta kiriho na gitoya, Kitakwerekana.\nImvura n’ izuba biba, Kw’ itegeko ryawe.\nUh’ ibizima kubaho, Kand’ ubitunga byose.\nNtaho twahungir’ Imana, Kuko ntahw’ itaba."}]},
  {"number": 86, "name": "Muramy’ Umwami", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/86", "key": "la", "references": [{"codes": "SDAH. 83"}, {"codes": "AH. 51"}, {"title": "O WORSHIP THE KING"}, {"codes": "CH. 75"}, {"codes": "CS. 335"}], "body": [{"type": "verse", "number": 1, "content": "Muramy’ Umwami waremye byose,\nNimuhimbaze mwes’ urukundo rwe,\nN’ umuvunyi wacu niw’ Uhoraho,\nAgoswe n’ ibyiza birabagirana."}, {"type": "verse", "number": 2, "content": "Mumwamamaze! Nyir’ imbabazi!\nYihunz’ umucyo, Akwiriye hose,\nIbicu bikoranywa, N’ icyusa cye,\nAcyahish’ abant’ urusaku rw’ inkuba."}, {"type": "verse", "number": 3, "content": "Agir’ ubuntu bukwira hose,\nBwuj’ ikirere, Buba no mu mucyo,\nButemba mu misozi n’ ibisiza,\nNibw’ ikime n’ imvura biturukamo."}, {"type": "verse", "number": 4, "content": "Tur’ igitaka, Tworoshye twese.\nTurakwizera kuk’ udahemuka;\nImbabazi zawe n’ akamenyero.\nMubyey’ ugir’ ibambe, Mukiza mwiza."}]},
  {"number": 87, "name": "Data Tuj’ Ah’ Uri", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/87", "references": [{"codes": "AH. 244"}, {"codes": "CH. 599"}, {"title": "FATHER WE COME TO THEE"}, {"codes": "CS. 526"}, {"codes": "HL. 280"}], "body": [{"type": "verse", "number": 1, "content": "Data tuj’ ah’ uri, Ko tudafit’ undi, Ni wow’ udukiza, Niko kuza.\nNiba tutabana, Is’ irimw’ ishavu. Uduhumurize, Data mwiza."}, {"type": "chorus", "content": "Data tuj’ ah’ uri, Ntutubuze. Niw’ uzi gukiza, Twumvir’ ubu."}, {"type": "verse", "number": 2, "content": "Dukiz’ ababisha, Dukize n’ ibyago, Dutuz’ imitima, Mu makuba.\nNtitugir’ intege, Twuzuz’ imbaraga, Dutiz’ amaboko, Ngo tuneshe."}, {"type": "verse", "number": 3, "content": "Twuzuz’ imbabazi, Tur’ abawe rwose, Tuyobor’ iteka, Twang’ ibyaha.\nTugumane Mwami, Kand’ ubwo tuzapfa, Ntuzatwibagirwe, Tuzabane."}]},
  {"number": 88, "name": "Ntumpiteho Mukiza We", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/88", "key": "la bémol", "references": [{"codes": "SDAH. 569"}, {"codes": "AH. 187"}, {"title": "PASS ME NOT"}, {"codes": "CH. 559"}, {"codes": "CS. 87"}, {"codes": "GH. 142"}], "body": [{"type": "verse", "number": 1, "content": "Ntumpiteho Mukiza we! Wumv’ uko nganya.\nUbw’ ugenderer’ abandi, Nanjye ntunsige."}, {"type": "chorus", "content": "Yewe Mukiza! Umv’ uko nganya.\nUbw’ ugenderer’ abandi, Nanjye ntunsige."}, {"type": "verse", "number": 2, "content": "Njye neger’ intebe yawe, Mpabw’ imbabazi.\nNgupfukamire, mbabaye, Mpa kukwizera."}, {"type": "verse", "number": 3, "content": "Ntaw’ undi nakwiringira, Ni wowe nshaka.\nMvur’ ibikomere byanjye, Umbabarire."}, {"type": "verse", "number": 4, "content": "Ur’ isoko y’ amahoro, Nyir’ ubugingo.\nSingir’ undi niyambaza, Keretse wowe."}]},
  {"number": 89, "name": "Gihe Cyiza Cyo Gusenga", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/89", "key": "si", "references": [{"codes": "SDAH. 478"}, {"codes": "CH. 316"}, {"title": "SWEET HOUR OF PRAYER"}, {"codes": "CS. 741"}], "body": [{"type": "verse", "number": 1, "content": "Gihe cyiza cyo gusenga, Kintarura mu mpagarara;\nNgo nigir’ aho Dat’ ari, Muganyir’ ibyo nkennye byose.\nMu bihe by’ umubabaro, Nabony’ ibimpumuriza.\nNtsind’ ubukana bw’ Umwanzi, Mu bihe byiza byo gusenga."}, {"type": "verse", "number": 2, "content": "Gihe cyiza cyo gusenga, Jy’ unsohorez’ amasengesho,\nK’ Uwiteka ntahemuka, Aratwiteze ngw’ aduhire,\nNdamwihereje rwos’ ubu, Yuk’ ubwe yampamagaye,\nNiringiy’ imbabazi ze, Nogez’ ibihe byo gusenga."}, {"type": "verse", "number": 3, "content": "Gihe cyiza cyo gusaba, Urajy’ uhor’ umpumuriza,\nUgez’ aho nger’ iwacu, Nzataha nzamuwe mu bicu,\nMpembw’ ibihembo by’ abera, Ni byo bizaramb’ iteka.\nUbwo ni bwo nzasezera Ku bihe byiza byo gusenga."}]},
  {"number": 90, "name": "Imins’ Itandat’ Ishize", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/90", "key": "si bémol", "references": [{"codes": "AH. 384"}, {"codes": "CH. 456"}, {"title": "ANOTHER SIX DAYS WORK"}], "body": [{"type": "verse", "number": 1, "content": "Imins’ itandat’ ishize, Indi Sabat’ itangiye.\nNezezwa no kuruhuka, Mur’ uyu muns’ uhiriwe."}, {"type": "verse", "number": 2, "content": "Nimuze mushim’ Umwami, Wabahaye kuruhuka.\nUmugisha w’ uyu munsi, Urut’ uw’ iyindi yose."}, {"type": "verse", "number": 3, "content": "Tunezerwe mu mitima, Twishimir’ ibyo mw’ ijuru.\nMu buruhukiro bwacu, Ku Mwami nyir’ Isabato."}, {"type": "verse", "number": 4, "content": "Ituza riva mw’ ijuru, Ritwuzure twebwe twese,\nHos’ itorero ry’ Imana, Rikir’ imitima myinshi."}]},
  {"number": 91, "name": "Wicogora Mur’ Iki Gihe", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/91", "key": "fa", "references": [{"codes": "SDAH. 375"}, {"codes": "CS. 555"}, {"title": "WATCH FOR THE TIME IS SHORT"}, {"codes": "HL. 349"}], "body": [{"type": "verse", "number": 1, "content": "Wicogora mur’ iki gihe, Ba maso n’ imperuka.\nRind’ udatsindwa n’ iby’ iyi si, Mukristo jy’ usaba.\nUz’ uk’ umubir’ uremba, Kand’ umwanz’ arakaze.\nUtegereze nyir’ ubukwe, Ba mas’ utarambirwa."}, {"type": "chorus", "content": "Komez’ ujy’ usaba, Komez’ ujy’ usaba.\nJya wirind’ iteka ku manywa na nijoro,\nNtugahweme gusaba."}, {"type": "verse", "number": 2, "content": "Tsemb’ ibishukw’ imbere yawe, Rek’ imitima myinshi.\nUzaruhukira mw’ ijuru, Nih’ uzaturiza.\nJy’ uhor’ usaba mukristo, Umwam’ arakwiteze.\nIbuk’ uko yaguhorewe, Bamuvush’ amaraso."}, {"type": "verse", "number": 3, "content": "Ntugahweme kwambaza Yesu, Jy’ ubana naw’ iteka\nNtugahug’ ibitum’ utsinda, Tegerez’ Umwami.\nWirushy’ uzuyaza rwose, Reka gushidikanya.\nN’ igihe cyo kumwitegura, Ntugahweme kwambaza."}]},
  {"number": 92, "name": "Wibuk’ Isabato", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/92", "key": "do", "references": [{"codes": "SDAH. 388"}, {"codes": "AH. 380"}, {"title": "DON’T FORGET THE SABBATH"}, {"codes": "CH. 653"}, {"codes": "CS. 230"}], "body": [{"type": "verse", "number": 1, "content": "Wibuk’ Isabato, Umwami yahiriye.\nN’ umus’ urut’ iyindi, N’ umuns’ unezeza.\nTuruhukamw’ imirimo, Tubwirwamw’ iby’ ijuru.\nNi wo mucy’ umurika, Uva ku Mwam’ Imana"}, {"type": "chorus", "content": "Utuzanir’ amahoro, Sabato nziza rwose.\nUtuzanir’ amahoro, Sabato nziza."}, {"type": "verse", "number": 2, "content": "Jya wez’ Isabato, Maz’ uramy’ uwo Mwami,\nWabwiy’ intumwa z’ ati: Ndi Nyir’ ubugingo.\nNiba twicisha bugufi, Dukorer’ Umukiza,\nTuzajyanwa kw’ isoko, Y’ amazi y’ ubugingo."}, {"type": "verse", "number": 3, "content": "Twishime, twezwemo, Turirimbire Yesu,\nInshuti yacu nziza, Tumutekereze.\nMukiza mwiz’ udukunda, Isezerano ryawe,\nNg’ uzaba muri twebwe, Ni ryo ritunezeza."}]},
  {"number": 93, "name": "N’ Umunsi Wera Wo Kuruhuka", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/93", "key": "fa", "references": [{"codes": "AH. 389"}, {"codes": "CH. 463"}, {"title": "O DAY OF REST AND GLADNESS"}, {"codes": "CS. 386"}], "body": [{"type": "verse", "number": 1, "content": "N’ umunsi wera wo kuruhuka, Muns’ uhiriwe w’ amahoro;\nUkiz’ intebyi n’ ufit’ ishavu, Mwiz’ ushimwa mu yindi yose.\nMwami mur’ uwo munsi, Bose bagusingiza,\nNgo weze, weze, weze, Kukw’ ari w’ uhorahw’ iteka."}, {"type": "verse", "number": 2, "content": "N’ icyambu kibamw’ ituza ryinshi, Ntikibamw’ imidugararo.\nNi nk’ umurima w’ i Paradizo, Imigezi myiz’ inyuramo.\nUsa n’ isokw’ ifuka, Iy’ amapfa yacanye.\nNi nk’ aho tubonera, Igihugu cy’ isezerano."}, {"type": "verse", "number": 3, "content": "N’ umunsi twongerwamw’ imbaraga, N’ umuns’ uduter’ urukundo.\nNi w’ utuma turek’ iby’ iyi si, Tukegukir’ ibyo mw’ ijuru.\nTuboner’ imbabazi, Mur’ uyu munsi mwiza.\nDushake kuruhuka, No ku rurembo rwo mw’ ijuru."}]},
  {"number": 94, "name": "Nkunda Guterana Kw’ Isabato", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/94", "key": "mi bémol", "references": [{"codes": "CS. 608"}, {"title": "SWEET SABBATH SCHOOL"}], "body": [{"type": "verse", "number": 1, "content": "Nkunda guterana kw’ Isabato, Kwig’ Ijambo ry’ Imana.\nTeraniro ryiza ry’ abigishwa, Undutira byose."}, {"type": "chorus", "content": "Huriro (…riro) rishimwa (…shimwa),\nHuriro (…riro) rishimwa (…shimwa).\nTeraniro ryiza ry’ abigishwa,\nUndutira byose."}, {"type": "verse", "number": 2, "content": "Ni ho namenyey’ iby’ ubugingo, Mbon’ uburyo nihana,\nNitoraniriz’ ibitunganye, Ni byo binezeza."}, {"type": "verse", "number": 3, "content": "Aho ni ho Yesu yantoreye, Ambwiz’ ijwi rye ryiza.\nUbwo ni bwo namwihitiyemo, Mw’ ihuriro ryiza."}]},
  {"number": 95, "name": "Dukoze Gatandatu", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/95", "key": "sol", "references": [{"codes": "SDAH. 384"}, {"codes": "AH. 386"}, {"title": "SAFELY THROUGH ANOTHER WEEK"}, {"codes": "CH. 462"}, {"codes": "CS. 388"}, {"codes": "HL. 165"}], "body": [{"type": "verse", "number": 1, "content": "Dukoze gatandatu, Tubwirizwa n’ Imana.\nNone dushak’ ihirwe, Mu rusengero rwayo.\nN’ umuns’ urut’ iyindi, Unshuz’ ibyo mw’ ijuru.\nN’ umuns’ urut’ iyindi, Niw’ unshuz’ ibyo mw’ ijuru."}, {"type": "verse", "number": 2, "content": "Tugusab’ umugisha, Mw’ izina ry’ Umukiza.\nTugirir’ imbabazi, Udutsembehw’ ibyaha.\nDucike ku by’ iyi si, Turuhukane nawe.\nDucike ku by’ iyi si, Uruhukire muri twe."}, {"type": "verse", "number": 3, "content": "Twaje kugusingiza, Ngwino dusaban’ ubu,\nTubon’ ubwiza bwawe, Mu rusengero rwawe.\nMwam’ uduhe kumenya, Ibyiza byo mw’ ijuru.\nMwam’ uduhe kumenya, Uko bizaba mw’ ijuru."}, {"type": "verse", "number": 4, "content": "Ubutumwa bugwire, Bukiz’ abanyabyaha.\nImbabazi zihoza, Abagutakambira.\nDuhe kugusingiza, Twez’ Isabato nziza.\nDuhe kugusingiza, Tuguman’ itek’ iteka."}]},
  {"number": 96, "name": "Nshim’ Isabato Yera", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/96", "key": "sol", "references": [{"codes": "AH. 383"}, {"codes": "CH. 459"}, {"title": "WELCOME, WELCOME DAY OF REST"}, {"codes": "CS. 431"}], "body": [{"type": "verse", "number": 1, "content": "Nshim’ Isabato yera, Imana yaduhaye.\nNgo tujye turuhuka, Tuwunezererwemo."}, {"type": "verse", "number": 2, "content": "N’ umuns’ ubamw’ ituza, Uhoramw’ ibyishimo.\nBiduhuz’ agahinda, Kugeza ku mperuka."}, {"type": "verse", "number": 3, "content": "N’ umuns’ uduhimbara, Tukawizihirwamo,\nTwongerwamw’ imbaraga, Tukuzuzw’ umugisha."}, {"type": "verse", "number": 4, "content": "Kaze Sabato nziza, Munsi w’ ikiruhuko,\nDuhabwamw’ umugisha, Tukamererwa neza."}]},
  {"number": 97, "name": "Twumvis’ Inkuru Nziza", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/97", "key": "sol", "references": [{"codes": "SDAH. 340"}, {"codes": "AH. 196"}, {"title": "WE HAVE HEARD"}, {"codes": "CH. 637"}, {"codes": "CS. 78"}, {"codes": "HL. 215"}], "body": [{"type": "verse", "number": 1, "content": "Twumvis’ inkuru nziza, Ko Yesu akiza.\nKwiz’ uwo munezero, Ko Yesu akiza.\nBibwir’ abantu bose, Uzambuke n’ inzuzi.\nUmwami ngo jya hose, Ni Yesu ukiza."}, {"type": "verse", "number": 2, "content": "Ukwize no mu nyanja, Ko Yesu akiza.\nTyo bwir’ abacumuye, Ko Yesu akiza.\nHimbaz’ abo mu birwa, Kukw’ amakuru meza,\nAzumvikana hose, Ko Yesu akiza."}, {"type": "verse", "number": 3, "content": "Mw’ irasaniro muti: Ni Yesu ukiza.\nYaducunguye twese, Ni Yesu ukiza.\nRirimbir’ abatebye, Bashak’ ubatabara.\nRirimba ku bituro, Ko Yesu akiza."}, {"type": "verse", "number": 4, "content": "N’ imiyag’ ivug’ iti: Ni Yesu ukiza.\nAmoko yos’ ashime, Ko Yesu akiza.\nJy’ urangurur’ ijw’ uti: Mwese muze mukizwe!\nDusingiz’ ubutwari, Ko Yesu akiza."}]},
  {"number": 98, "name": "Ndagushaka Mukiza We", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/98", "key": "mi", "references": [{"codes": "AH. 124"}, {"title": "I MUST HAVE THE SAVIOR WITH ME"}, {"codes": "HL. 507"}], "body": [{"type": "verse", "number": 1, "content": "Ndagushaka Mukiza we! Ntabwo mbasha kwigenza.\nNdifuza k’ umpora hafi, Gumy’ unyikomereze."}, {"type": "chorus", "content": "Sinzagir’ icyo ntinya,\nUmbwiriz’ iby’ ushaka.\nNta cyambuza kuz’ ah’ uri,\nNgukurikir’ ah’ ujya."}, {"type": "verse", "number": 2, "content": "Ndagushaka Mukiza we! Kuko noroshye cyane.\nNiw’ umbwir’ ibinkomeza, Nta wundi mbitezeho."}, {"type": "verse", "number": 3, "content": "Ndagushaka Mukiza we! Aho ndi mur’ iyi si.\nMu muvumbi no ku zuba, Mu bimbabaza byose."}, {"type": "verse", "number": 4, "content": "Ndagushaka Mukiza we! Mbwiriz’ ibitunganye.\nUngeze kuri Yor’dani, Umpe no kuyambuka."}]},
  {"number": 99, "name": "Iyo Nibuts’ Umusarab’ Utangaza", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/99", "key": "fa", "references": [{"codes": "AH. 90"}, {"codes": "CH. 120"}, {"title": "WHEN I SURVEY THE WONDROUS CROSS"}, {"codes": "CS. 172"}], "body": [{"type": "verse", "number": 1, "content": "Iyo nibuts’ umusarab’ utangaza,\nUmwami nyir’ ishema yatangiyeho,\nIbyo nungukaga, ntabwo mba nkibyitayeho.\nNzinukw’ ibyo niratanaga."}, {"type": "verse", "number": 2, "content": "Reb’ inkovu zo ku mubiri we wose,\nZituma ngir’ ishavu n’ umunezero.\nHar’ ubw’ ishavu n’ ibyishimo bijya bihura.\nHar’ utak’ ikamba mu mahwa?"}, {"type": "verse", "number": 3, "content": "Nari narazimiye meze nk’ impabe.\nAriko narokotse kubw’ ibyago bye;\nNtunzibukira ntagir’ ikindi niratana,\nKerets’ umusaraba wawe."}, {"type": "verse", "number": 4, "content": "Nahw’ ibyaremwe byose byab’ ar’ ibyanjye,\nNtacyo nabona nakugereranyaho;\nUrukundo, n’ ubuntu byaturutse mw’ ijuru,\nBituma ndek’ ibyanjye byose."}]},
  {"number": 100, "name": "Nta Nshuti Nziza Nka Yesu", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/100", "key": "fa", "references": [{"codes": "SDAH. 499"}, {"codes": "AH. 271"}, {"title": "WHAT A FRIEND WE HAVE IN JESUS"}, {"codes": "CH. 320"}, {"codes": "CS. 643"}, {"codes": "HL. 320"}], "body": [{"type": "verse", "number": 1, "content": "Nta nshuti nziza nka Yesu, Atsemb’ ibyaha byacu.\nN’ amahirwe kumwizera, Kukw’ atwuzuza na Se.\nIyo tubabaye rwose, Dufit’ ishavu ryinshi,\nAdusohoza ku Mana, Yumv’ amaganya yacu."}, {"type": "verse", "number": 2, "content": "Nitugir’ ibyago byinshi, Tugatotezwa cyane,\nByoye kuduter’ ubwoba, Tumwiringire rwose;\nNta wundi wabidukiza, Abiduhemuraho.\nYes’ az’ integer nke zacu, Jya wisung’ Uwiteka."}, {"type": "verse", "number": 3, "content": "Nitugir’ ishavu ryinshi, Tukababara rwose,\nYesu ni w’ uturokora; Komez’ umwizigire.\nNibakugira ruvumwa, Wisung’ Umwami Yesu.\nNtazagir’ ubw’ aguhana, Jy’ uhor’ umwizigiye."}]},
  {"number": 101, "name": "Yesu Araguhamagara None", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/101", "key": "do", "references": [{"codes": "AH. 168"}, {"codes": "CH. 569"}, {"title": "JESUS IS CALLING"}, {"codes": "CS. 8"}, {"codes": "HL. 464"}], "body": [{"type": "verse", "number": 1, "content": "Yes’ araguhamagara none, Arakwifuz’ uyu munsi;\nN’ iki gituma wanga kwitaba, Ukayobagurika?"}, {"type": "chorus", "content": "S. na A.: Uyu munsi, uyu munsi ;\nYes’ araguhamagaran’ imbabazi ze.\nT. na B.: Uyu munsi, none, none, Uyu munsi, none, none;\nYesu Yes’ Umwami ni w’ Uguhamagaran’ imbabazi ze."}, {"type": "verse", "number": 2, "content": "Yes’ arahamagar’ abarushye, Ngw’ abaruhur’ uyu munsi;\nUmwikorez’ umutwaro wawe; Ntazagushor’ inshucu."}, {"type": "verse", "number": 3, "content": "Yes’ aragutegereje none, Musange non’ uyu munsi;\nZan’ ibyaha byaw’ ubyicujije, Ngwino witindiganya."}, {"type": "verse", "number": 4, "content": "Yes’ arakwinginga, wumv’ ijwi rye; Mwumvire non’ uyu munsi.\nAbamwiringira bazishima; Haguruk’ umusange!"}]},
  {"number": 102, "name": "Hanze Har’ Umushyitsi", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/102", "key": "ré bémol", "references": [{"codes": "CH. 566"}, {"codes": "CS. 21"}, {"title": "LET HIM IN"}, {"codes": "HL. 234"}], "body": [{"type": "verse", "number": 1, "content": "Hanze har’ umushyitsi, Kingura! (Mukingurire, mukingurire!)\nYahoz’ ategereje, Kingur’ ubu! (Mukingurire, mukingurire!)\nKingurir’ Umukiza, Ataraguhitaho; Yes’ Umwana w’ Imana;\nKingur’ ubu! (Mukingurire, mukingurire!)"}, {"type": "verse", "number": 2, "content": "Ugurur’ umutima, Kingura! (Mukingurire, mukingurire!)\nN’ uzuyaz’ aragenda, Kingur’ ubu! (Mukingurire, mukingurire!)\nNiwe nshuti - magara; Azajy’ akurengera, Kand’ akurind’ iteka:\nKingur’ ubu! (Mukingurire, mukingurire!)"}, {"type": "verse", "number": 3, "content": "Ntiwumv’ ukw’ akwinginga? Kingura! (Mukingurire, mukingurire!)\nMuhitemw‘ ubu ngubu, Kingur’ ubu! (Mukingurire, mukingurire!)\nAhagaze ku rugi; Azaguhesh’ ihirwe, Maz’ ujy’ umuhimbaza;\nKingur’ ubu! (Mukingurire, mukingurire!)"}, {"type": "verse", "number": 4, "content": "Akir’ uwo mushyitsi, Kingura! (Mukingurire, mukingurire!)\nAzasangira nawe, Kingur’ ubu! (Mukingurire, mukingurire!)\nAzakubabarira; Iby’ isi nibishira, Akujyane mw’ ijuru;\nKingur’ ubu! (Mukingurire, mukingurire!)"}]},
  {"number": 103, "name": "Ubyarw’ Ubwa Kabiri", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/103", "key": "mi bémol", "references": [{"codes": "CS. 26"}, {"title": "YE MUST BE BORN AGAIN"}], "body": [{"type": "verse", "number": 1, "content": "Harih’ uwasanze Yesu nijoro, Amubaz’ iby’ inzira y’ agakiza.\nYes’ amusubiz’ amweruriy’ ati: N’ ukuri nkubwire:"}, {"type": "chorus", "content": "Ubyarw’ ubwa kabiri (rwose);\nUbyarw’ ubwa kabiri (rwose);\nN’ ukuri, n’ ukuri, ndakubwir’ ubu\nKw’ aribw’ uzarama (rwose)."}, {"type": "verse", "number": 2, "content": "Namwe nimwite kur’ iryo jambo rye, Kuko Yesu yarivuz’ aryeruye;\nNibyo bizabagirir’ umumaro, Dor’ aravug’ ati:"}, {"type": "verse", "number": 3, "content": "Abashak’ uburuhukiro bose, No kuririmbana n’ abacunguwe,\nNo guhabw’ ubugingo buhoraho, Mwite kur’ ibi ngo:"}]},
  {"number": 104, "name": "Mucunguzi Wanjye", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/104", "key": "do", "references": [{"codes": "CS. 31"}, {"title": "COME, GREAT DELIVERER, COME"}], "body": [{"type": "verse", "number": 1, "content": "Mucunguzi wanjye, wumv’ uko ntaka; Ngwin’ unyirokorere.\nUmutima wanjy’ ugoswe n’ ibyago; Ngwin’ unyirokorere."}, {"type": "chorus", "content": "Nahabiye kure, nd’ akahebwe;\nNahabiye kure y’ iwacu.\nNyakira none, maz’ ungez’ iwacu;\nNgwin’ unyirokorere."}, {"type": "verse", "number": 2, "content": "Mwami, singira shinge na rugero; Ngwin’ unyirokorere.\nKwitabwaho nawe nibyo byanyura; Ngwin’ unyirokorere."}, {"type": "verse", "number": 3, "content": "Dore ndi jyenyine, nabay’ impabe; Ngwin’ unyirokorere.\nNubuy’ amaso ngo mbeshweho nawe; Ngwin’ unyirokorere."}, {"type": "verse", "number": 4, "content": "Ntuhinyur’ umutim’ ushenjaguwe; Ngwin’ unyirokorere,\nNyamunek’ ita ku gusenga kwanjye, Ngwin’ unyirokorere."}]},
  {"number": 105, "name": "Ashobora Gukiza", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/105", "key": "fa", "references": [{"codes": "CS. 30"}, {"title": "ABLE TO DELIVER"}], "body": [{"type": "verse", "number": 1, "content": "Ashobora gukiza! Mubyamamaze hose;\nAshobora gukiz’ umwumvira wese,\nAkamwarura mu murir’ ugurumana.\nYes’ ashobora gukiza ushaka wese."}, {"type": "chorus", "content": "Ashobora kugukiza,\nNo kukurokor’ ubu;\nMwene Data numwizera,\nAzagukiza."}, {"type": "verse", "number": 2, "content": "Ashobora gukiza! Mbese n’ ukuri koko?\nAhw’ afit’ imbarag’ ibasha kunkiza?\nMbwira, nyamuna mbwira, Mbese Kristo wishwe,\nYashobora kumbohora, akandokora?"}, {"type": "verse", "number": 3, "content": "Ashobora gukiza! Mugenzi we komera!\nNuyoboka Yesu azakurokora.\nNtugatinye Satani, Jy’ ugundira Yesu;\nReka kujy’ ushidikanya, Jy’ umwiringira."}]},
  {"number": 106, "name": "Twubake Ku Rutare Rw’ Iteka", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/106", "key": "la bémol", "references": [{"codes": "AH. 213"}, {"codes": "CH. 579"}, {"title": "BUILD ON THE ROCK"}, {"codes": "CS. 32"}], "body": [{"type": "verse", "number": 1, "content": "Twubake ku Rutare rw’ iteka, Nirwo Yes’ Umucunguzi;\nNibwo tuzabasha gushikama, Umugaru nutera."}, {"type": "chorus", "content": "Sop: Twubake kuri we, Twubake kuri we;\nTwubake ku Rutare rw’ iteka, Nirwo Yes’ Umwami.\nA. T. B.: Twubake kuri we, Niwe Rutare;\nTwubake kuri we, Niwe Rutare;\nTwubake ku Rutare rw’ iteka,\nNirwo Yes’ Umwami."}, {"type": "verse", "number": 2, "content": "Harihw’ abubaka ku musenyi, Barangamiy’ iby’ iyi si;\nAbandi bubaka ku muraba w’ ibyaha no kwikuza."}, {"type": "verse", "number": 3, "content": "Twubake ku Rutare rw’ ukuri, Nirwo rushikam’ iteka.\nKurwiringira kuzahoraho, Nirwo gakiza kacu."}]},
  {"number": 107, "name": "Menyesh’ Ibya Yesu Byose", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/107", "key": "mi bémol", "references": [{"codes": "AH. 82"}, {"codes": "CH. 534"}, {"title": "TELL ME THE STORY OF JESUS"}, {"codes": "CS. 40"}], "body": [{"type": "verse", "number": 1, "content": "Menyesh’ ibya Yesu byose, Maz’ ubinyandikemo;\nMbwir’ ibye by’ ingenzi byose, Nezezwa no kubyumva.\nMbwir’ ukw’ abamarayika baririmbye yavutse,\nNgw’ Icyubahiro ku Mana, Amahor’ abe mu b’ isi."}, {"type": "chorus", "content": "Menyesh’ ibya Yesu byose, Maz’ ubinyandikemo.\nMbwir’ ibye by’ ingenzi byose, Nezezwa no kubyumva."}, {"type": "verse", "number": 2, "content": "Mbwira n’ ibyo mu butayu, N’ iminsi yahamaze;\nN’ uburyo yageragejwe, Agatsind’ ibishuko;\nMbwira n’ iby’ imirimo ye, Vug’ uko yababajwe;\nAgahemurwa bamwanze, Agahinyurwa nk’ impabe."}, {"type": "verse", "number": 3, "content": "Mbwir’ iby’ umusaraba we, Uwo bamubambyeho,\nMbwira n’ aho bamuhambye, Mbwira n’ uko yazutse,\nN’ urukundo ruhebuje, Ntacyo narugeraho.\nDore, ndababaye, mbwira iby’ urukundo rwancunguye."}]},
  {"number": 108, "name": "Yes’ Umwungeri Mwiza", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/108", "key": "mi bémol", "references": [{"codes": "AH. 182"}, {"codes": "CH. 572"}, {"title": "LOVINGLY, TENDERLY CALLING"}, {"codes": "CS. 46"}], "body": [{"type": "verse", "number": 1, "content": "Yes’ Umwungeri mwiza, Aragutarura,\nNgo winjire mw’ ishyo rye; Ni h’ uzaruhukira.\nNgwin’ ugif’ ubusore, Ngwin’ ukiri muto;\nInjir’ uzarindwa rwose, Ntuzagir’ icy’ uganya."}, {"type": "chorus", "content": "Aragutaruran’ urukundo, ati:\nWa mpabe we, ngwino nsanga.\nDor’ Umukiz’ arategereje,\nYes’ Umwungeri wanjye."}, {"type": "verse", "number": 2, "content": "Yes’ Umwungeri mwiza, Yarakwitangiye;\nAraguhamagara ati: Nyabuna ngwino,\nGira bwang’ uve mu kaga, Ntugumye, kwijyana.\nInjir’ uzarindwa rwose, Wibere mu mahoro."}, {"type": "verse", "number": 3, "content": "Reka kuragiriza, Isega yateye,\nIshak’ intama zose, Zazimiriye kure.\nArik’ Umwungeri mwiza, Arakuburira;\nInjir’ uzarindwa rwose, Muban’ akaramata."}]},
  {"number": 109, "name": "Naratuwe Mu Gipimo", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/109", "key": "fa", "references": [{"codes": "CS. 49"}, {"title": "WEIGHED AND WANTING"}], "body": [{"type": "verse", "number": 1, "content": "Umucamanza nagera, Akarondor’ ibyacu,\nTuzamera nk’ izahabu, Cyangwa s’ inkamb’ itabwa?"}, {"type": "chorus", "content": "Naratuwe mu gipimo,\nNsangwa ntashyitse;\nNaratuwe n’ ijambo rye,\nNsangwa ntashyitse."}, {"type": "verse", "number": 2, "content": "Mbese tuzumv’ ishimwe ngo: Nuko, wakoze neza;\nCyangw’ iteka ryo gupfa ngo: Mwasanzwe mudashyitse?"}, {"type": "verse", "number": 3, "content": "Nimutyo twite kw’ ijwi rye, Igihe kikiriho.\nTureke gutindiganya, Tumaramaze rwose."}]},
  {"number": 110, "name": "Wumv’ Amagambo Y’ Umukiza", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/110", "key": "la", "references": [{"codes": "CS. 55"}, {"title": "BLESSED ARE THEY THAT DO"}], "body": [{"type": "verse", "number": 1, "content": "Wumv’ amagambo y’ Umukiza; Ni y’ aguhesh’ ubugingo.\nWa munyabyaha we, menya ko hahirw’ abakomez’ amategeko."}, {"type": "chorus", "content": "Hahirw’ abayakomeza yose,\nNibo bahirwa, barahirwa;\nHahirw’ abayakomeza yose,\nBarahirwa, barahirwa."}, {"type": "verse", "number": 2, "content": "Kuyumva gusa nta kamaro, N’ukutugwabiza rwose;\nKuyumva dutinya, ntibyadukiza, Hahirw’ abayumvira yose."}, {"type": "verse", "number": 3, "content": "Bazinjiran’ umunezero mu mudugudu w’ Imana,\nAhatab’ ishavu n’ umubabaro, Beger’ igiti cy’ ubugingo."}]},
  {"number": 111, "name": "Nta Nshuti Nziz’ Ihwanye Na Yesu", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/111", "key": "fa", "references": [{"codes": "CS. 57"}, {"title": "NO, NOT ONE"}], "body": [{"type": "verse", "number": 1, "content": "Nta nshuti nziz’ ihwanye na Yesu; Nta n’ imwe! Nta n’ imwe!\nNta wundi wabasha kudukiza; Nta wundi! Nta wundi!"}, {"type": "chorus", "content": "Yes’ az’ ibiturushya byose;\nAzabana natw’ iteka.\nNta nshuti nziz’ ihwanye na Yesu,\nNta n’ imwe! Nta n’ imwe!"}, {"type": "verse", "number": 2, "content": "Nta nshut’ ibahw’ ikomeye nka we; Nta n’ imwe! Nta n’ imwe!\nNyamara nta wiyoroshya nka we; Nta n’ umwe! Nta n’ umwe!"}, {"type": "verse", "number": 3, "content": "Nta kanya na gato tutabana; Ye nta ko! Ye nta ko!\nNta joro ryira tutari kumwe; Ye nta ryo! Ye nta ryo!"}, {"type": "verse", "number": 4, "content": "Mbese har’ uwo yigez’ ahana? Nta n’ umwe! Nta n’ umwe!\nMbese har’ umunyabyah’ aheza? Nta n’ umwe! Nta n’ umwe!"}, {"type": "verse", "number": 5, "content": "Harihw’ impano yahwana na we? Nta n’ imwe! Nta n’ imwe!\nMbese har’ uwo yavuts’ ijuru? Nta n’ umwe! Nta n’ umwe!"}]},
  {"number": 112, "name": "Kurabukw’ Umusaraba Wawe", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/112", "key": "la bémol", "references": [{"codes": "CS. 65"}, {"title": "LIFE IN A LOOK"}], "body": [{"type": "verse", "number": 1, "content": "Kurabukw’ umusaraba wawe, Mwami nibyo byambeshaho;\nSinita ku manjwe y’ iby’ isi, Ntez’ agakiza ku musaraba."}, {"type": "chorus", "content": "S. : Kurabukw’ i Golgota,\nNibyo bizambeshaho.\nMbeg’ amahirwe yanjye,\nYo kurabukwa Yesu!\nA., T. na B. : Kurabu … Go… Golgota,\nNibyo bi … mbe … mbeshaho.\nMbeg’ amahirwe yanjye …rwe yanjye,\nYo kurabukwa Yesu! …rabukwa Yesu."}, {"type": "verse", "number": 2, "content": "Ubwo nari nkibon’ Umukiza, Yanyakirany’ ibyishimo;\nNa n’ ubu ningir’ ibindwanya, Kumurabukwa nibyo byankiza."}, {"type": "verse", "number": 3, "content": "Nzajya mpang’ amas’ umusaraba, Kandi mwiringire rwose.\nNta wutumbir’ umusaraba, Wari wiger’ aneshwa n’ Umwanzi."}]},
  {"number": 113, "name": "Yesu Araguhamagaran’ Ituza", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/113", "key": "la bémol", "references": [{"codes": "SDAH. 287"}, {"codes": "AH. 169"}, {"codes": "CH. 563"}, {"title": "SOFTLY AND TENDERLY"}, {"codes": "CS. 76"}], "body": [{"type": "verse", "number": 1, "content": "Yes’ araguhamagaran’ ituza, Ub’ arahamagara;\nAtegereje k’ umwiyegurira, We kuzuyaza; ngwino."}, {"type": "chorus", "content": "Ngwino ( ngwino); Ngwino (ngwino);\nAbarushye mwese nimuze.\nYes’ araguhamagaran’ ituza, ati:\nMukundwa, ngwino."}, {"type": "verse", "number": 2, "content": "Twatinzwa n’ iki, kand’ ategereje kuturokora twese?\nTwahinyuzwa n’ ik’ imbabazi zose adufitiye twese?"}, {"type": "verse", "number": 3, "content": "Twakererew’ ibihe birahita, Aradutegereje;\nTurarindagirira mu mwijima; Nimutyo tumusange."}, {"type": "verse", "number": 4, "content": "Zirikan’ urukundo ruhebuje, Yadusezeranije;\nN’ ubwo twagomye, Tuzababarirwa; Aradutegereje."}]},
  {"number": 114, "name": "Har’ Irembo Ryuguruye", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/114", "key": "do", "references": [{"codes": "AH. 177"}, {"codes": "CH. 561"}, {"title": "THE GATE AJAR FOR ME"}, {"codes": "CS. 91"}, {"codes": "HL. 260"}], "body": [{"type": "verse", "number": 1, "content": "Har’ irembo ryuguruwe, Ryatumye mpishurirwa.\nUmusaraba wa kure, Yesu yatangiyeho."}, {"type": "chorus", "content": "Mbeg’ ineza n’ imbabazi byatumye nugururirwa!\nNugururiwe, Iman’ ihimbazwe!"}, {"type": "verse", "number": 2, "content": "Irembo ryugururiwe abashak’ agakiza;\nNgw’ abakire n’ abakene bose barinyuremo."}, {"type": "verse", "number": 3, "content": "Nshuti komez’ utwaran’ irembo ricyuguruwe.\nIkorer’ umusaraba; Nibw’ uzahabw’ ikamba."}, {"type": "verse", "number": 4, "content": "Tumaze kwambuk’ uruzi, Dute wa musaraba;\nTwambikw’ amakamba meza, Twitahire mw’ ijuru."}]},
  {"number": 115, "name": "Umukiz’ Ageze Hafi", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/115", "key": "mi bémol", "references": [{"codes": "SDAH. 254"}, {"codes": "AH. 118"}, {"title": "THE GREAT PHYSICIAN"}, {"codes": "CH. 530"}, {"codes": "CS. 30"}, {"codes": "HL. 243"}], "body": [{"type": "verse", "number": 1, "content": "Umukiz’ ageze hafi, Yes’ Umukunzi wanjye.\nYazanywe no guhembura; Mwese nimumwumvire."}, {"type": "chorus", "content": "Nta wuhwany’ izina na we, Rirut’ amazina yose.\nNta wusingizwa nka we; Yesu mwiza rwose."}, {"type": "verse", "number": 2, "content": "Icyubahiro kib’ icye; Mutyo twizere Yesu.\nNkund’ izina ry’ Umukiza; Nkund’ izina rya Yesu."}, {"type": "verse", "number": 3, "content": "Izina rye rirankiza, Rikamar’ agahinda.\nNta kinezeza nko kumva, Iryo zina rya Yesu."}, {"type": "verse", "number": 4, "content": "Naz’ azatugororera, Ikamba ry’ ubugingo.\nUbwo nibwo tuzicara, Tuvug’ iby’ agakiza."}]},
  {"number": 116, "name": "Ntacyo Wasigiye Yesu", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/116", "key": "ré", "references": [{"codes": "CS. 100"}, {"title": "NOTHING FOR JESUS"}], "body": [{"type": "verse", "number": 1, "content": "Dor’ umutima wawe, Wuzuyemw’ amaganya.\nNta mwanya wasigiye Yesu ngo yinjiremo?\nUb’ ahagaze ku rugi, Arakomanga yinginga.\nNta mwanya wasigiye Yesu ngo yinjiremo?"}, {"type": "verse", "number": 2, "content": "Upfush’ igih’ ubusa, Kand’ ar’ ingenzi rwose.\nMbese nta mwany’ ufite wo gukorera Yesu?\nNturarushy’ ugerageza gutarur’ abazimiye;\nMbese nta mwany’ ufite wo gukorera Yesu?"}, {"type": "verse", "number": 3, "content": "Mbese k’ umaranira kwishakir’ ubutunzi,\nNta gih’ ufite washishikarir’ ibya Yesu?\nDor’ uharanira kwikubir’ ibinezeza by’ isi;\nNta gih’ ufite washishikarir’ ibya Yesu?"}, {"type": "verse", "number": 4, "content": "Wabay’ ingumba nk’ igiti cy’ ibibabi gusa.\nMbese ntabwo wazerer’ Umwami Yes’ imbuto?\nNtacy’ ufite cyo kuzamumurikira nagaruka;\nMbese ntabwo wazerer’ Umwami Yes’ imbuto?"}]},
  {"number": 117, "name": "Mwami Ndumv’ Ijwi Ryawe", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/117", "key": "mi bémol", "references": [{"codes": "SDAH. 282"}, {"codes": "AH. 173"}, {"title": "I HEAR THE WELCOME VOICE"}, {"codes": "CH. 224"}, {"codes": "CS. 101"}, {"codes": "HL. 496"}], "body": [{"type": "verse", "number": 1, "content": "Mwami ndumv’ ijwi ryawe, Rindarika ngo nze,\nNuhagizwe ya maraso, Wamviriye kera."}, {"type": "chorus", "content": "Mukiza ndaje, Ubu nj’ ah’ uri!\nNyejesha ya maraso, Wamviriye kera."}, {"type": "verse", "number": 2, "content": "N’ ubwo nje nahindanye, Ntunyirengagize;\nAhubw’ umboneze rwose, Mb’ umweru waka de."}, {"type": "verse", "number": 3, "content": "Yesu niw’ unkomeza, Niw’ umpa gutsinda;\nNg’ urukundo n’ amahoro, Binsabemo rwose."}, {"type": "verse", "number": 4, "content": "Mwese nimwishimire! Ya maras’ akiza,\nYatwujuje na Rurema, Ngo tub’ abana be."}]},
  {"number": 118, "name": "Ndumv’ Umukiz’ Ambwira", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/118", "key": "mi bémol", "references": [{"codes": "SDAH. 184"}, {"codes": "AH. 119"}, {"title": "JESUS PAID IT ALL"}, {"codes": "CH. 527"}], "body": [{"type": "verse", "number": 1, "content": "Ndumv’ Umukiz’ ambwira, Ko mbuz’ imbaraga;\nNgo: Njye museng’ iteka, Ntacyo nzamuburana."}, {"type": "chorus", "content": "Yanndihiriye imyenda yose;\nYambabariy’ ibyaha, Bihinduk’ umweru."}, {"type": "verse", "number": 2, "content": "Niw’ ufit’ imbaraga, Zihagije rwose;\nZo gukiz’ ababembe, Zikoroshy’ umutima."}, {"type": "verse", "number": 3, "content": "Ubwo nta cyiza nkora, Nibesherejweho;\nN’ ubuntu bwawe gusa, Ni wowe nkesha byose."}, {"type": "verse", "number": 4, "content": "Imbere ya ya ntebe, Nzahahagarara;\nNzaba njyany’ iminyago, Nyishyikirize Yesu."}]},
  {"number": 119, "name": "Harihw’ Isokw’ Itukura", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/119", "key": "mi bémol", "references": [{"codes": "SDAH. 332"}, {"codes": "AH. 375"}, {"title": "THE CLEANSING WAVE"}, {"codes": "CH. 598"}, {"codes": "CS. 110"}], "body": [{"type": "verse", "number": 1, "content": "Harihw’ isokw’ itukura, Ivamw’ amaraso;\nNi y’ Umwami yamviriye, Ngw’ ayandokoreshe."}, {"type": "chorus", "content": "Nduz’ umuvu w’ amaraso;\nNdayogamo nere rwose!\nHaleluya! Aranyeza,\nAranyeza, Aranyeza!"}, {"type": "verse", "number": 2, "content": "Mpinduts’ icyaremwe gishya, Mbyaw’ ubwa kabiri.\nNtsinze kamere ya kera, Nzahora ndi mushya."}, {"type": "verse", "number": 3, "content": "Nsigaye mvirwa n’ umucyo, Sinkirindagira;\nNshitse ku ngoyi z’ umwanzi, Mbatuwe na Yesu."}, {"type": "verse", "number": 4, "content": "Mbeg’ ubuntu butangaje! Kwejeshw’ amaraso!\nByanyujuje n’ Umukiza, Yesu wambambiwe."}]},
  {"number": 120, "name": "Data Ndambuy’ Amaboko", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/120", "key": "sol", "references": [{"codes": "SDAH. 486"}, {"codes": "CH. 670"}, {"title": "I DO BELIEVE"}, {"codes": "CS. 186"}, {"codes": "HL. 274"}], "body": [{"type": "verse", "number": 1, "content": "Data, ndambuy’ amaboko; Nta wundi wamfasha;\nIy’ unyivumburiy’ ukamvaho, Mbes’ ahandi najya ni he?"}, {"type": "verse", "number": 2, "content": "Nizey’ Umwana waw’ ubu, Undem’ umutima;\nUjy’ unkenur’ umar’ ubukene, Nkomeze nemerwe nawe."}, {"type": "verse", "number": 3, "content": "Nyir’ ukwizera ni wowe, Nuburiy’ amaso;\nIcyamp’ ukangwiriza kwizera, Kuko ntagufite napfa."}, {"type": "verse", "number": 4, "content": "Ntuzantererane ngo mpfe, Ahubw’ umbesheho;\nNibwo nzacika ku kinyoma, Mbishobojwe n’ Umwuka wawe."}, {"type": "verse", "number": 5, "content": "Nakwishima cyane rwose, Nibaniye nawe;\nMaze nkakumv’ umpumuriz’ umbwira ko nagiriw’ ubuntu."}, {"type": "verse", "number": 6, "content": "Nizeye rwos’ ubu yuko, Yesu yampfiriye;\nKandi kubw’ amaraso ye yeza, Nzabaturwa mve mu byaha."}]},
  {"number": 121, "name": "Nzasingiz’ Urukundo Rwa Yesu", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/121", "key": "si bémol", "references": [{"codes": "AH. 111"}, {"codes": "CH. 529"}, {"title": "I WILL SING OF JESUS’S LOVE"}], "body": [{"type": "verse", "number": 1, "content": "Nzasingiz’ urukundo rwa Yesu, Wambambiwe;\nYemeye kumanuka, Azanywe no kumpfira."}, {"type": "chorus", "content": "Nzasingiz’ urukundo rwe;\nMpimbaze, Yaramfiriye,\nAshaka kumbeshaho;\nNzahora muhimbaza."}, {"type": "verse", "number": 2, "content": "Yesu yambabarijwe, Ntararushya mbabara;\nYahoze ansabira, Ntarameny’ iyo bijya."}, {"type": "verse", "number": 3, "content": "Urukundo rw’ Imana, Mbega ngo rurankiza!\nIbyaha byanjye byose, Bikantamururwaho!"}, {"type": "verse", "number": 4, "content": "Nta cyiza nakoreye, Umwami wankunz’ atyo;\nNone maze kwemezwa, Mwami nguhaye byose."}]},
  {"number": 122, "name": "Nyigiza Hafi", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/122", "key": "ré bémol", "references": [{"codes": "AH. 313"}, {"codes": "CH. 390"}, {"title": "NEARER, STILL NEARER"}, {"codes": "CS. 262"}, {"codes": "HL. 284"}], "body": [{"type": "verse", "number": 1, "content": "Nyigiza hafi, mbane nawe; Nta cyandutira kubana nawe.\nNgumisha mu gituza cyawe; Mpisha nibere mu buhungiro;\nMpisha nibere mu buhungiro."}, {"type": "verse", "number": 2, "content": "Nyigiza hafi, ntacyo mfite; Ntacyo nzanyehw’ ituro ry’ Umwami,\nKerets’ umutim’ ushavuye; Mpa kuhagizw’ amaraso yawe;\nMpa kuhagizw’ amaraso yawe."}, {"type": "verse", "number": 3, "content": "Nyigiza hafi, Mwami wanjye; Nishimiye gucika ku byaha.\nNdeke kwikuza n’ ubwibone; Umpe Yes’ Umwami wambambiwe;\nUmpe Yes’ Umwami wambambiwe."}, {"type": "verse", "number": 4, "content": "Nyigiza hafi, ngihumeka; Kugez’ ubwo nzager’ ibudapfa;\nMaze mu bihe bidashira, Nzibere hafi y’ Umwami wanjye;\nNzibere hafi y’ Umwami wanjye."}]},
  {"number": 123, "name": "Har’ Izina Rihebuje", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/123", "key": "fa", "references": [{"codes": "CS. 217"}, {"title": "THE HOLIEST NAME"}], "body": [{"type": "verse", "number": 1, "content": "Har’ izina rihebuje, Rirut’ ayandi yose nzi;\nNiry’ Imana yaturemye yis’ Umwana way’ ikunda."}, {"type": "chorus", "content": "Niryo zina ryera ( izina );\nNiryo zina ryera ( ryera de )!\nRyakomotse ku Mana, Riza mw’ isi,\nMaze riririmbwa ( izina ) n’ abamarayika ( ryera de ).\nIryo zina n’ irya Yesu."}, {"type": "verse", "number": 2, "content": "Niryo rimpesh’ umugisha; Nkunda kuryogez’ iteka.\nSimpwema kuriririmba, Mvug’ ukuntu rihebuje."}, {"type": "verse", "number": 3, "content": "Icyampa nkaririmbana n’ abamarayika bera,\nNkajya nsingiza rya zina rihebuj’ ayandi yose!"}]},
  {"number": 124, "name": "Yesu Gusa", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/124", "key": "mi bémol", "references": [{"codes": "SDAH. 570"}, {"codes": "AH. 231"}, {"title": "NOT I, BUT CHRIST"}, {"codes": "CH. 271"}, {"codes": "CS. 230"}], "body": [{"type": "verse", "number": 1, "content": "Yesu gusa, ni w’ ukwiriy’ ikuzo;\nNaho jyewe, ntacyo ndi cyo rwose;\nSinkwiriye kub’ ari jyew’ uratwa;\nYesu gusa, ni w’ uzajy’ uvugwa."}, {"type": "verse", "number": 2, "content": "Yesu gusa, ni w’ umar’ agahinda;\nNaho jyewe nd’ uwo gushavura.\nSinshobora kwikorer’ ibindushya;\nNaho Yesu nta kimushengura."}, {"type": "verse", "number": 3, "content": "Yesu gusa, ab’ ari we wogezwa;\nSinkwiriye kwiratan’ ibyanjye.\nYesu gusa, ni w’ uzambonekamo;\nKugez’ ubwo nzahinduka nka we."}, {"type": "verse", "number": 4, "content": "Yesu gusa ni w’ umar’ ubukene;\nNi we gusa nkesh’ ibyanjye byose.\nYesu gusa, ni w’ undutira byose;\nYesu Mwami twibanir’ iteka."}]},
  {"number": 125, "name": "Nk’ Ukw’ Izuba Rituvira", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/125", "key": "la", "references": [{"codes": "AH. 256"}, {"codes": "CH. 612"}, {"title": "SUNLIGHT IN THE HEART"}, {"codes": "CS. 229"}], "body": [{"type": "verse", "number": 1, "content": "Nk’ukw’ izuba rituvira, Rikarabagirana,\nNi k’ umucyo wo mw’ ijuru wansabye mu mutima,\nWawukuyemw’ iby’ amanjwe, Utangaz’ ibihishwe;\nKuko mu mutima wanjye, Nahatuj’ Umukiza."}, {"type": "chorus", "content": "Mbeg’ umucyo w’ agatangaza,\nWansabye mu mutima!\nIneza y’ Umwami Yesu,\nYambereye nk’ umucyo."}, {"type": "verse", "number": 2, "content": "Natay’ agahinda kose; Ntabwo nkikitayeho;\nKuk’ unyambik’ amahoro, Ameze nk’ umwitero,\nNkwerekejeh’ umutima, Ndakwishimiye cyane.\nNzagezw’ iwawe mw’ ijuru, Na rwa rukundo rwawe."}, {"type": "verse", "number": 3, "content": "Mukiza warancunguye; Nd’ uwaw’ uko ndi kose.\nNyemerera nguhimbaze, Nkuber’ umucyo waka.\nNkwerekejeh’ umutima, Ndakwishimiye cyane.\nNzagezw’ iwawe mw’ ijuru, Na rwa rukundo rwawe."}]},
  {"number": 126, "name": "Njya Nkunda Kuririmb’ Indirimbo", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/126", "key": "sol", "references": [{"codes": "AH. 194"}, {"codes": "CH. 638"}, {"title": "I HAVE A SONG I LOVE TO SING"}, {"codes": "CS. 236"}], "body": [{"type": "verse", "number": 1, "content": "Njya nkunda kuririmb’ indirimbo, Ngo yarancunguye.\nNi we waciy’ ingoyi z’ umwanzi, Maz’ arambatura."}, {"type": "chorus", "content": "Sop: Kuk’ ubwe yancunguye; Kuk’ ubwe yancunguye,\nNzahimbaz’ izina rye. Kuk’ ubwe yancunguye,\nNzaririmbir’ uwandokoye.\nA. T. B.: Kuk’ ubwe yancunguye; Kuk’ ubwe yancunguye;\nKuk’ ubwe yancunguye, Nzahimbaz’ izina rye.\nKuk’ ubwe yancunguye, Kuk’ ubwe yancunguye;\nNzaririmbir’ uwandokoye."}, {"type": "verse", "number": 2, "content": "Mfit’ Umukiz’ unogeye rwose, Ni we wancunguye.\nMpimbazwa no gukor’ iby’ ashaka, Kuko yancunguye."}, {"type": "verse", "number": 3, "content": "Nzahora mpamya ntacyo nikenga, Y’uko yancunguye.\nSinzashidikanya ngo ncogore, Kuko yancunguye."}, {"type": "verse", "number": 4, "content": "Mfit’ aho yanteguriye heza, Kuko yancunguye.\nNi ho nzibanira na w’ iteka, Kuko yancunguye."}]},
  {"number": 127, "name": "Iman’ Ikund’ Utunyoni", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/127", "key": "fa", "references": [{"codes": "AH. 456"}, {"codes": "CS. 252"}, {"title": "HE LOVES ME TOO"}], "body": [{"type": "verse", "number": 1, "content": "Iman’ ikund’ utunyoni, Tuba mur’ iyi si;\nUbwo yita ku tunyoni, Nzi ko nanjy’ inkunda."}, {"type": "chorus", "content": "Irankunda, irankunda;\nNzi ko nanjy’ inkunda;\nKukw’ ikund’ utuntu duto,\nNzi ko nanjy’ inkunda."}, {"type": "verse", "number": 2, "content": "Ni y’ irimbish’ uburabyo, Buhumura neza;\nUbw’ ikund’ uburaby’ ityo, Nzi ko nanjy’ inkunda."}, {"type": "verse", "number": 3, "content": "Imana yaremye byose, Ntigir’ icy’ isobwa.\nNzi kw’ ikund’ abana bose, Nzi ko nanjy’ inkunda."}]},
  {"number": 128, "name": "N’ Igihe Cyo Gusenga", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/128", "key": "mi bémol", "references": [{"codes": "AH. 265"}, {"codes": "CH. 324"}, {"title": "BLESSED HOUR OF PRAYER"}, {"codes": "CS. 270"}], "body": [{"type": "verse", "number": 1, "content": "N’ igihe cyo gusenga, Twicishe bugufi, Duteraniye hamwe turamya Yesu,\nNituza tumwizeye, Azajy’ aturinda; Mbeg’ ihumure ryiza, ryo kwibanira na we!"}, {"type": "chorus", "content": "N’ igihe cyiza cyo kuramy’ Umwami,\nMbeg’ ihumure ryiza, ryo kwibanira na we!"}, {"type": "verse", "number": 2, "content": "N’ igihe cyo gusenga, Umwam’ ari hafi, Kand’ adufitiy’ ibambe rya kibyeyi.\nTumuganyir’ ibyacu, Dushir’ agahinda; Mbeg’ ihumure ryiza, ryo kumvikana na we!"}, {"type": "verse", "number": 3, "content": "N’ igihe cyo gusenga, no gushyikirana, N’ Imana yac’ ihor’ ituzirikana,\nIturem’ agatima, tub’ indahangarwa; Mbeg’ ihumure ryiza, ryo kumvikana na we!"}, {"type": "verse", "number": 4, "content": "N’ igihe cyo gusenga, twiringiye Yesu. Twizeye kw‘ azaduh’ ibyo, tumusaba,\nKukw’ atangan’ ubuntu, ataziganije. Mbeg’ ihumure ryiza, ryo gutabarwa nawe!"}]},
  {"number": 129, "name": "Yesu Waduhay’ Isezerano", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/129", "key": "la bémol", "references": [{"codes": "AH. 272"}, {"codes": "CH. 602"}, {"title": "JESUS COME AND BLESS US"}, {"codes": "CS. 278"}], "body": [{"type": "verse", "number": 1, "content": "Yesu waduhaye isezerano, K’ uzabana natwe, niduterana,\nNaho twaba babiri, Cyangwa batatu,\nUzab’ uri kumwe n’ abana bawe."}, {"type": "chorus", "content": "Yesu, ngwin’ uduhire, Tutarava hano;\nYesu ngwin’ uduhire ubu, Tuban’ iteka."}, {"type": "verse", "number": 2, "content": "Wateranye natwe, mu bindi bihe, Ariko na n’ ubu turakwifuza.\nNgwino, Mubyeyi mwiza, Turakwinginze;\nTwumvir’ utwemere, Duhirwe nawe."}, {"type": "verse", "number": 3, "content": "Wakir’ indirimbo z’ ishimwe ryacu, Uduhe gusenga tubyitayeho.\nTwongerere kwizera, No kwiringira;\nDukundane rwose, Dushyire hamwe."}]},
  {"number": 130, "name": "Nd’ Uwawe, Mwami", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/130", "key": "la bémol", "references": [{"codes": "SDAH. 306"}, {"codes": "AH. 235"}, {"title": "I AM THINE, O LORD"}, {"codes": "CH. 594"}, {"codes": "CS. 282"}], "body": [{"type": "verse", "number": 1, "content": "Nd’ uwawe Mwami, Ubu nditanze; Numvis’ ubury’ udukunda.\nNsingiriz’ amabok’ untabare, Njye nibanire nawe."}, {"type": "chorus", "content": "S. A.: Hafi yawe, Ni byo nifuza, Ku musaraba wawe.\nHafi yawe, Mwami, tuban’ iteka, Njye nibanira nawe.\nT. B.: Hafi yawe cyane, ni byo nifuza, Ku musaraba wawe.\nHafi yawe, Mwami, tuban’ iteka, Njye nibanira nawe."}, {"type": "verse", "number": 2, "content": "Nkwiyeguriye namaramaje, Nkoresh’ umurimo wawe;\nNkwerekejeh’ umutima wanjye, Ng’ uhor’ ugengwa nawe."}, {"type": "verse", "number": 3, "content": "Kubana nawe birahebuje, Ni byo bindutira byose.\nIyo mpfukamye, nkakuganyira, Dusabana nk’ inshuti."}, {"type": "verse", "number": 4, "content": "Sinashobora kukurondora, Ngo meny’ urukundo rwawe.\nRuzahishurwa turi mw’ ijuru, Aho twateguriwe."}]},
  {"number": 131, "name": "Ndusheho Gusa Nawe", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/131", "key": "fa", "references": [{"codes": "CS. 286"}, {"title": "MORE LIKE JESUS"}], "body": [{"type": "verse", "number": 1, "content": "Ndusheho gusa nawe, Yesu Mukiza wanjye;\nNyuzuz’ ubugwaneza, Mp’ urukundo ruhebuje.\nNdusheho kumera nkawe, Aho ngenda hose, Mwami;\nNdiyoroheje rwose, Mwami njye ngukurikiza."}, {"type": "verse", "number": 2, "content": "Nib’ irind’ icyanira, Ikamenya n’ igishwi;\nSinshidikanya rwose, Nanjy’ ihor’ inyitayeho.\nIzanyigisha kwitonda, Imbabarir’ amafuti;\nNdiyoroheje rwose, Mwami njye ngukurikiza."}, {"type": "verse", "number": 3, "content": "Ndusheho gusa nawe, Ndusheh’ uko bukeye;\nNyigiza hafi yawe, Ahw’ amahor’ adashira.\nUhor’ umpindura mushya, Kubw’ urukund’ ungirira;\nNdiyoroheje rwose, Mwami njye ngukurikiza."}]},
  {"number": 132, "name": "Yesu, Unkomereze Ku Musaraba", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/132", "key": "fa", "references": [{"codes": "SDAH. 312"}, {"codes": "AH. 240"}, {"title": "NEARER THE CROSS"}, {"codes": "CH. 595"}, {"codes": "CS. 289"}], "body": [{"type": "verse", "number": 1, "content": "Yes’ unkomereze, Ku musaraba wawe;\nHar’ isokw’ ibeshaho, Itemb’ i Kal’vari."}, {"type": "chorus", "content": "Umusaraba wa Yesu nzawirata,\nKugez’ ubwo nzabona uburuhukiro."}, {"type": "verse", "number": 2, "content": "Hafi y’ umusaraba, Mpaboner’ iteka,\nImbabazi n’ impuhwe, Bitarondoreka."}, {"type": "verse", "number": 3, "content": "Hafi y’ umusaraba, Intama y’ Imana,\nNi yo yahangejeje, Ntsind’ ibimbabaza."}, {"type": "verse", "number": 4, "content": "Hafi y’ umusaraba, Ni ho ntegereje;\nNiringiye kugera, Mu bwami bw’ Imana."}]},
  {"number": 133, "name": "Nyemerera Ngendane Nawe", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/133", "key": "la bémol", "references": [{"codes": "SDAH. 554"}, {"codes": "AH. 284"}, {"title": "O LET ME WALK WITH THEE"}, {"codes": "CH. 395"}, {"codes": "CS. 295"}], "body": [{"type": "verse", "number": 1, "content": "Nyemerera ngendane nawe, Mana, Nk’ ukw’ Enoki yagenje.\nNyoboresh’ ukuboko kwawe, Unyerekez’ ah’ ushaka hose.\nNubw’ inzir’ itagaragara, Nkomeze njyane nawe, Mwami."}, {"type": "verse", "number": 2, "content": "Ntabwo nahangara kugenda, Ntari kumwe nawe, Mukiza;\nNagoswe n’ abanz’ igihumbi; Dor’ imitegw’ intaye hagati.\nBurije rwose, ntihabona, Nkomeze njyane nawe, Mwami."}, {"type": "verse", "number": 3, "content": "Ninguma mu maboko yawe, Sinzaba ncyitaye ku by’ isi;\nNta kindi nziratana rwose, Keretse wa musaraba wawe,\nNgez’ ubwo nzager’ i Siyoni, Nkomeze njyane nawe, Mwami."}]},
  {"number": 134, "name": "Icyampa Nkarangurura", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/134", "key": "do", "references": [{"codes": "AH. 123"}, {"codes": "CH. 650"}, {"title": "WONDERFUL LOVE OF JESUS"}, {"codes": "CS. 245"}], "body": [{"type": "verse", "number": 1, "content": "Icyampa nkarangurura, Ngahimbaz’ Umwami wanjye,\nAriko ni nde wabasha kuririmb’ ishimwe rya Yesu?"}, {"type": "chorus", "content": "Urukundo ruhebuje! Urukundo rwa Yesu!\nUrukundo ruhebuje! Urukundo rwa Yesu!"}, {"type": "verse", "number": 2, "content": "Ni we munezero wanjye, Ni na w’ umpesh’ amahoro.\nMu makuba no mu byago, Yesu ni w’ umber’ ihumure."}, {"type": "verse", "number": 3, "content": "Ni we byiringiro byanjye, Byo kuzahabw’ ubugingo.\nMu mwijim’ amber’ umucyo, Yesu ni w’ umber’ ihumure."}]},
  {"number": 135, "name": "Mwami Nzi Kw’ Ari We Nkunda", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/135", "key": "do", "references": [{"codes": "CH. 301"}, {"title": "I LOVE THEE BETTER"}], "body": [{"type": "verse", "number": 1, "content": "Mwami, nzi kw’ ari We nkunda, Kurut’ iby’ iyi si;\nKuko wampay’ amahoro, Atagir’ impinduka."}, {"type": "chorus", "content": "Urukundo rwankijije (ngakira),\nNtirurondoreka.\nNtitwarusobanukirwa (na hato),\nKuko ruhebuje (ruhebuje)."}, {"type": "verse", "number": 2, "content": "Nzi k’ uhor’ unzirikana, Undutira byose,\nMwami, kugutekereza bindutir’ ibyiratwa."}, {"type": "verse", "number": 3, "content": "Wanyujuj’ umunezero, Natay’ umuruho.\nKumenya k’ unkunda cyane, Ni byo bimpumuriza."}, {"type": "verse", "number": 4, "content": "Mucunguzi wanjye mwiza, Icyakunyereka!\nNgo tuzabane mw’ ijuru, Ahatab’ agahinda."}]},
  {"number": 136, "name": "Ahw’ Azanyobora Hose", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/136", "key": "mi bémol", "references": [{"codes": "CH. 305"}, {"title": "I REMEMBER CALVARY"}], "body": [{"type": "verse", "number": 1, "content": "Ahw’ azanyobora hose, Ni ho nzishimira kujya;\nKukw’ ari jye yapfiriye, Akanzir’ atacumuye."}, {"type": "chorus", "content": "Yes’ azanyobor’ iteka,\nMaz’ angez’ iw’ amahoro;\nKukw’ ar’ inshuti y’ ukuri,\nItigeze guhemuka."}, {"type": "verse", "number": 2, "content": "Nishimira kw’ antegeka, Nishimira kw’ anyobora.\nNishimira kumwumvira, Kukw’ ari jye yapfiriye."}, {"type": "verse", "number": 3, "content": "Singishidikanya rwose, Kuko ndi kumwe na Yesu.\nNizigiye ko vub’ aha, Nzamureba duhanganye."}]},
  {"number": 137, "name": "Isi Ndayihararutse, Mpisemo Yesu", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/137", "key": "fa", "references": [{"codes": "SDAH. 329"}, {"codes": "AH. 104"}, {"title": "TAKE THE WORLD, BUT GIVE ME JESUS"}, {"codes": "CH. 596"}, {"codes": "CS. 315"}], "body": [{"type": "verse", "number": 1, "content": "Isi ndayihararutse, Mpisemo Yesu gusa.\nMpaz’ umunezero wayo, Uzashirana na yo."}, {"type": "chorus", "content": "Imbabazi zidashira,\nN’ urukundo rw’ iteka,\nNi byo bijya binyemeza,\nKo nzaramishwa na we."}, {"type": "verse", "number": 2, "content": "Isi ndayihararutse, Mpisemo Yesu gusa.\nMu kaga ni we humure; Nzahora nezerewe."}, {"type": "verse", "number": 3, "content": "Isi ndayihararutse, Mpisemo Yesu gusa.\nIcyamp’ akamwenyurira, Nkamurikirwa na we."}, {"type": "verse", "number": 4, "content": "Isi ndayihararutse, Mpisemo Yesu gusa.\nNzirat’ umusaraba we, Yatangiyeho kera."}]},
  {"number": 138, "name": "Mwami Wanjye, Nyakira", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/138", "key": "ré", "references": [{"codes": "AH. 230"}, {"codes": "CH. 273"}, {"title": "TAKE MY LIFE AND LET IT BE"}, {"codes": "CS. 316"}], "body": [{"type": "verse", "number": 1, "content": "Mwami wanjye nyakira, Ndakwiyeguriy’ ubu;\nNgay’ amaboko yanjye, Yakoresh’ uk’ ushaka."}, {"type": "chorus", "content": "Nyuhagiz’ amaraso yawe ( nere rwose );\nMaz’ anyezehw’ inenge yose ( nere rwose );\nIbyanjye byose ndabikweguriye, None n’ iteka ryose."}, {"type": "verse", "number": 2, "content": "Ngib’ ibirenge byanjye, Byerekez’ ah’ ushaka.\nNgir’ ijwi ryanjye na ryo, Rijye riguhimbaza."}, {"type": "verse", "number": 3, "content": "Nguhay’ akanwa kanjye; Mwami, kakuvugire.\nNgub’ ubutunzi bwanjye, Sinzagir’ icyo nkwima."}, {"type": "verse", "number": 4, "content": "Nguhay’ igihe cyanjye, Sinzakiguteraho;\nNguhay’ ubwenge bwanjye, Bukoresh’ uk’ ushaka."}, {"type": "verse", "number": 5, "content": "Ngiy’ imigambi yanjye; Igengwe nawe, Mwami.\nNguy’ umutima wanjye, Ube uwawe rwose."}, {"type": "verse", "number": 6, "content": "Mwam’ urukundo rwanjye, Ni wowe nzarukunda;\nNkwihaye nimazeyo, None n’ iteka ryose."}]},
  {"number": 139, "name": "Nabony’ Inshut’ Ihebuje", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/139", "key": "la", "references": [{"codes": "SDAH. 186"}, {"codes": "AH. 113"}, {"title": "I’VE FOUND A FRIEND"}, {"codes": "CH. 531"}, {"codes": "CS. 332"}, {"codes": "HL. 518"}], "body": [{"type": "verse", "number": 1, "content": "Nabony’ inshut’ ihebuje! Yankunze ntarabaho;\nYanyiyegereshej’ ineza, N’ urukundo rw’ iteka,\nBituma dushyikirana, Ubudatandukana;\nKuko nd’ uwe na we n’ uwanjye, Ibihe bidashira."}, {"type": "verse", "number": 2, "content": "Nabony’ inshut’ ihebuje! Yamberey’ impongano.\nUrets’ ibyo kump’ ubugingo, Yaranyitangiriye.\nNtacyo mfite nit’ icyanjye, Kuko tubisangiye.\nNdamwiyeguriye burundu; Ibihe bidashira."}, {"type": "verse", "number": 3, "content": "Nabony’ inshut’ ihebuje! Nyir’ ubutware bwose!\nNi bw’ indindish’ uko bukeye; Izangeza mw’ ijuru.\nIbyiza byanshyizw’ imbere, Binsubizamw’ intege;\nReka nkore, noye kwiganda, Ngez’ ubw’ izanduhura."}, {"type": "verse", "number": 4, "content": "Nabony’ inshut’ ihebuje! Y’ impuhwe n’ urukundo.\nNi y’ indind’ ikanyunganira; Ni y’ indenger’ iteka.\nMbese n’ iki cyadutanya, Ko dukundana rwose?\nN’ iby’ iyi si, cyangwa s’ urupfu? Oya nzab’ uw’ iteka."}]},
  {"number": 140, "name": "Numvise Yesu Ambwira Ati", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/140", "key": "ré", "references": [{"codes": "AH. 171"}, {"codes": "CH. 301"}, {"title": "THE VOICE OF JESUS"}, {"codes": "CS. 359"}], "body": [{"type": "verse", "number": 1, "content": "Numvise Yes’ ambwir’ ati: Ngwino nkuruhure.\nZan’ ibikurushya byose, Mbikwikorerere.\nMusanga, mez’ uko nari ndi, Ndushye, mfite n’ ishavu;\nAmber’ uburuhukiro, Maz’ aranezeza."}, {"type": "verse", "number": 2, "content": "Numvise Yes’ ambwir’ ati: Ndaguher’ ubuntu,\nAmaz’ azakubeshaho, Unyw’ uram’ iteka.\nNuko nsanga Yesu maz’ ampa ya mazi y’ ubugingo,\nNshir’ inyota, Ndahembuka; Nzahorana na we."}, {"type": "verse", "number": 3, "content": "Numvise Yes’ ambwir’ ati: Ni jye Mucyo w’ isi.\nN’ undeb’ uramurikirwa, Ntuzarindagira.\nMaze muhanz’ amaso koko, Mbon’ ar’ izuba ryanjye;\nRizamvir’ iminsi yose y’ ubugingo bwanjye."}]},
  {"number": 141, "name": "Mwami Mb’ Uwawe Maramaje", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/141", "key": "la bémol", "references": [{"codes": "SDAH. 308"}, {"codes": "AH. 236"}, {"title": "I WOULD BE, DEAR SAVIOUR, WHOLLY THINE"}, {"codes": "CH. 597"}, {"codes": "CS. 595"}], "body": [{"type": "verse", "number": 1, "content": "Mwami, mb’ uwawe maramaje, Nyigisha, nyigisha.\nNkor’ iby’ ukunda, Mwami wanjye; Komez’ umfashe."}, {"type": "chorus", "content": "Mb’ uwawe ( Mwami ) ; Mb’ uwawe ( Mwami ) ;\nNi yo migambi yanjye ;\nMb’ uwawe ( Mwami ) ; Mb’ uwawe ( Mwami ) ;\nMb’ uwawe Mwami, None."}, {"type": "verse", "number": 2, "content": "Iby’ iyi si byamarir’ iki, Ntari kumwe nawe?\nByose nzabihara kubwawe, Ntungishwe nawe."}, {"type": "verse", "number": 3, "content": "Ndets’ umunezero w’ iyi si, Ngwino twibanire;\nNibyo bizajya binogera, Bimpumurize."}]},
  {"number": 142, "name": "Mbeg’ Umuns’ Urush’ Indi Kwera", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/142", "key": "mi bémol", "references": [{"codes": "AH. 382"}, {"codes": "CH. 458"}, {"title": "HOW SWETT!"}, {"codes": "CS. 778"}], "body": [{"type": "verse", "number": 1, "content": "Mbeg’ umuns’ urush’ indi kwera; Ni wo wa karindwi!\nNg’ uratuma ndek’ iby’ isi, Nkibwir’ iby’ ijuru!"}, {"type": "verse", "number": 2, "content": "Mbeg’ uyu munsi wa karindwi, Turuhukiramo,\nNg’ uradutera kuramya Data, Wo mw’ ijuru!"}, {"type": "verse", "number": 3, "content": "Ni mutyo turamy’ Uhoraho, Watuzirikanye,\nAgaherakw’ akaduha, Uyu munsi wera."}, {"type": "verse", "number": 4, "content": "Ni w’ utugobotor’ ibyaha, Bikaducikaho,\nKukw’ atugirir’ ubuntu, Buvuye mw’ ijuru."}]},
  {"number": 143, "name": "Udusezeresh’ Umugisha Wawe", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/143", "key": "mi", "references": [{"codes": "SDAH. 69"}, {"codes": "AH. 22"}, {"title": "LORD, DISMISS US"}, {"codes": "CH. 33"}, {"codes": "HL. 145"}], "body": [{"type": "verse", "number": 1, "content": "Udusezeresh’ umugisha wawe; Mwam’ utwuzuz’ amahoro;\nUrukundo rwawe rudusabemo, Tubone kunesha rwose.\nNgwin’ uduhembure, Ngwin’ uduhembure;\nTukiri mur’ iyi si y’ igomero."}, {"type": "verse", "number": 2, "content": "Tuguhay’ ishimwe no kukuramya, Kubw’ ubutumwa bw’ imvaho,\nBwagukomotseho bukadukiza, Bunyur’ imitima yacu;\nTubushikamemo, Tubushikamemo;\nTugundir’ ukuri, Tudacogora."}, {"type": "verse", "number": 3, "content": "Mbeshwaho n’ imbabazi zawe nyinshi, None ndakwiyeguriye.\nNgwin’ uduhumurish’ impuhwe zawe, Duhore turwan’ ishyaka;\nTuzager’ i wawe, Tuzager’ iwawe;\nTukubone nta kidukingirije."}]},
  {"number": 144, "name": "Mukiza, Ndamaramaje", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/144", "key": "la bémol", "references": [{"codes": "SDAH. 625"}, {"codes": "AH. 317"}, {"title": "HIGHER GROUND"}, {"codes": "CH. 631"}, {"codes": "CS. 489"}], "body": [{"type": "verse", "number": 1, "content": "Mukiza, ndamaramaje, Ndatwaranira kugera,\nKu rugero runkwiriye; Mwami mfasha ngo ndusheho."}, {"type": "chorus", "content": "Nzamura maze nger’ aho wangeneye,\nMwami wanjye; Ku rugero rusumbyeho;\nMwami mfasha ngo ndusheho."}, {"type": "verse", "number": 2, "content": "Ntabwo ngifit’ umutima, Wo kuguma mu by’ iyi si;\nN’ubwo bamwe babikunda, Ngambiriye kujya mbere."}, {"type": "verse", "number": 3, "content": "Ndashaka gusumb’ iby’ isi, N’ubw’ umwanz’ anyibasiye;\nKuko namaze kwizera, Yukw’ Iman’ izandengera."}, {"type": "verse", "number": 4, "content": "Ndashaka kumaranira, Kurabukw’ ubwiza bwawe;\nAriko nkomeze nsenge, Ngez’ ubwo nzager’ iwawe."}]},
  {"number": 145, "name": "Ntushak’ Urwitwazo", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/145", "key": "mi", "references": [{"codes": "CS. 513"}, {"title": "ASK NOT TO BE EXCUSED"}], "body": [{"type": "verse", "number": 1, "content": "Ntushak’ urwitwazo, Harihw’ imirimo,\nAhubw’ itegure gukorer’ Imana.\nYakwinginze kenshi, Kand’ ikurarika;\nWitinda kwemera, Bizakunezeza."}, {"type": "chorus", "content": "Itaba! ( none ); Ntushak’ urwitwazo;\nItaba! ( none ); Wigingimiranya.\nNtushak’ urwitwazo, Udasubizwa ngo:\nHoshi wampinyuye; Nkuvukij’ ubwami."}, {"type": "verse", "number": 2, "content": "Ntushak’ urwitwazo urahamagawe;\nDor’ aho wangiye, Noneho witabe.\nImirim’ ireze, Hagumy’ abakozi;\nNgwin’ umukorere; Uzagororerwa."}, {"type": "verse", "number": 3, "content": "Ntushak’ urwitwazo, Kuko nib’ utinze,\nBizagukoraho, Izakwivumbura.\nImbabazi zayo, Ntabwo zirashira;\nHaguruka bwangu, Ubibabarirwe."}]},
  {"number": 146, "name": "Yesu Mwami W’Abami", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/146", "key": "mi bémol", "references": [{"codes": "SDAH. 316"}, {"codes": "AH. 247"}, {"title": "LIVE OUT THY LIFE WITHIN ME"}, {"codes": "CH. 279"}, {"codes": "HL. 73"}], "body": [{"type": "verse", "number": 1, "content": "Yesu Mwami w’ abami, Ngwin’ ube muri jye!\nHe kub’ ari jy’ uvuga, Ujy’ umvugiramo.\nUnsabe mu mutima, Ngengwe nawe rwose,\nMaz’ abajya bandeba, Bajye bakubona."}, {"type": "verse", "number": 2, "content": "Ndakwiyeguriy’ ubu, Ez’ ibyaha byanjye;\nNgaragareh’ ubwiza bwawe buhebuje.\nNgir’ umutim’ utuje, Ne guteraganwa;\nNiyoroshye nganduke, Ngo nkoreshwe nawe."}, {"type": "verse", "number": 3, "content": "Ingingo zanjye zose, Zijye zikumvira;\nUzikoreshereze, Zikubahirize.\nNe kujya nivovota, Ngo mpore ku nkeke.\nY’ ibimbaho nishama, Nta mahoro mfite."}, {"type": "verse", "number": 4, "content": "Ni wowe ntegereje, Ungenz’ uk’ ushaka.\nUbwanjye nditeguye, Simfit’ ikinziga.\nYesu Mwami w’ abami, Ngwin’ ube muri jye!\nMaz’ ibyo nkora byose, Mbikoreshwe nawe."}]},
  {"number": 147, "name": "Data Mwiza, Nyigiza Hafi", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/147", "key": "la", "references": [{"codes": "AH. 314"}, {"codes": "CH. 632"}, {"title": "DRAW ME CLOSER TO THEE"}, {"codes": "CS. 534"}], "body": [{"type": "verse", "number": 1, "content": "Data mwiza, nyigiza hafi; Nkube mu gituza;\nNi wowe buhungiro bwanjye, N’ uburuhukiro."}, {"type": "chorus", "content": "S. na A : Data, nyigiza hafi, Ndifuza ko tubana;\nData, ndifuza ko tubana.\nT. na B : Data, Data, nyigiza hafi,\nNdifuza cyane ko tubana;\nData, nyigiza hafi; ndifuza ko tubana,\nNdifuza ko tubana."}, {"type": "verse", "number": 2, "content": "Data mwiza, nyigiza hafi; Nkomeza ntundeke;\nNakwishimira ko tubana, Ne kuraragira."}, {"type": "verse", "number": 3, "content": "Data mwiza, nyigiza hafi; Ngez’ ubwo nsa nawe;\nMpembur’ unyuhagir’ unyeze, Mb’ umuziranenge."}]},
  {"number": 148, "name": "Aho Njyanye Na Yesu", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/148", "key": "ré", "references": [{"codes": "SDAH. 508"}, {"codes": "AH. 224"}, {"title": "ANYWHERE WITH JESUS"}, {"codes": "CH. 589"}, {"codes": "CS. 535"}], "body": [{"type": "verse", "number": 1, "content": "Aho njyanye na Yesu mb’ amahoro, Ahw’ anyobora hose mur’ iyi si.\nAho njya tutajyanye nta kinyura, Iyo njyanye na Yesu ntacyo ntinya."}, {"type": "chorus", "content": "Aho njyanye na we, nta kintinyisha,\nAho njyanye na Yesu mb’ amahoro."}, {"type": "verse", "number": 2, "content": "Aho njyanye na Yesu sinigunga, Nubw’ izindi nshuti zampemukira;\nNubw’ anyobora mu nzir’ iruhije, Aho njyanye na Yesu ndanezerwa."}, {"type": "verse", "number": 3, "content": "Njyanye na Yesu sinatiny’ urupfu, N’ iyo ngoswe n’ umwijima w’ icyago,\nNzi ko nzakanguk’ ubutazongera, Kujarajarira mur’ iy’ isi mbi."}]},
  {"number": 149, "name": "Nshuti Jy’ Ugendera Mu Mucyo", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/149", "key": "ré", "references": [{"codes": "CS. 540"}, {"title": "WALK IN THE LIGHT"}], "body": [{"type": "verse", "number": 1, "content": "Nshuti jy’ ugendera mu mucyo, Woye kurindagira;\nUmwuka Wera wo mw’ ijuru, Ajy’ akuyobora."}, {"type": "chorus", "content": "S. na A : Gendera mu mucyo, Gendera mu mucyo;\nGendera mu mucyo, Mu mucyo waka w’ Imana.\nT. na B. : Gendera mu mucy’ utangaje w‘ Imana;\nGendera mu mucy’ utangaje w‘ Imana;\nGendera mu mucy’ utangaje w‘ Imana;\nMu mucyo waka w‘ Imana;"}, {"type": "verse", "number": 2, "content": "Gendera mu mucyo w’ ukuri, Ko mw’ Ijambo ry’ Imana;\nUzajy’ ukuyobor’ iteka, Ukwizez’ Imana."}, {"type": "verse", "number": 3, "content": "Jy’ ugendera mu mucy’ iteka, Ujy’ ukumurikira;\nMaz’ utamurur’ umwijima, Hose hatangaze."}, {"type": "verse", "number": 4, "content": "Gendera mu mucyo ng’ umenye, Urukundo rw’ Imana,\nN’ uburyo yakunze ab’ isi, Ikabarokora."}]},
  {"number": 150, "name": "Mbes’ Abasaruzi Bari He?", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/150", "key": "sol", "references": [{"codes": "SDAH. 366"}, {"codes": "AH. 360"}, {"title": "WHERE ARE THE REAPERS?"}, {"codes": "CH. 620"}, {"codes": "CS. 548"}], "body": [{"type": "verse", "number": 1, "content": "Mbes’ abasaruzi bari hehe, Bo gusarur’ abakiranutsi?\nBakomeye ku kuri kw’ Imana; Kandi ntibab’ ar’ abanyabute."}, {"type": "chorus", "content": "Abasaruzi se bari he?\nNgo bafatanye natwe gusarura,\nMaze twishime, Turi kumwe,\nIsarura nirirangira."}, {"type": "verse", "number": 2, "content": "Mushakire mu mihana yose; N’ubw’ urwiri rwarenga ku ngano;\nMuzishake kuko zirurimo, Zose muzisarurir’ Imana."}, {"type": "verse", "number": 3, "content": "Dor’ imirima yereye rimwe, Kandi bose bitez’ isarura; Arikw’\nabasaruzi ni bake, Umurimo wab’ urabasaze."}, {"type": "verse", "number": 4, "content": "Mwitwaj’ intwaro z’ Umwuka Wera; Musarur’ igihe kirageze!\nMushishikare Umwam’ araje; Dor’ abazaniy’ ingororano!"}]},
  {"number": 151, "name": "Ngamij’ Iby’ Igihugu Cy’ Igikundiro", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/151", "key": "la", "references": [{"codes": "AH. 355"}, {"codes": "CH. 626"}, {"title": "WILL THERE BE ANY STARS"}, {"codes": "CS. 552"}], "body": [{"type": "verse", "number": 1, "content": "Ngamij’ iby’ igihugu cy’ igikundiro; Nzageray’ izuba rirenze.\nAriko s’ ikamba Yes’ azamperayo, Azaritakahw’ inyenyeri?"}, {"type": "chorus", "content": "Mbes’ ikamba ryanjye Yes’ azamperayo,\nAzaritakahw’ inyenyeri (inyenyeri)?\nNingir’ amahirwe, Nkabana na Yesu,\nAzaritakahw’ inyenyeri (inyenyeri)?"}, {"type": "verse", "number": 2, "content": "Reka nkore, nsenge, mbiheshejwe nawe, Mugarurir’ abazimiye.\nNagaruka kuri wa munsi w’ ubwiza, Nzatakwehw’ inyenyeri nyinshi."}, {"type": "verse", "number": 3, "content": "Mbeg’ umunezer’ uhebuje nzagira, Nimwerek’ abo nakijije,\nMfite n’ ibyishimo bitavugwa, Mbonye inyenyeri kw’ ikamba ryanjye."}]},
  {"number": 152, "name": "Ngwino Yesu", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/152", "key": "mi bémol", "references": [{"codes": "CS. 554"}, {"title": "SPEAK TO MY SOUL"}], "body": [{"type": "verse", "number": 1, "content": "Ngwino Yes’ uvugane, N’ umutima wanjye: Maz’ umpumuriz’ uti: Ntabwo nagusize.\nNyugurur’ umutima, Nihutire kumva, Ijwi ryawe ry’ impuhwe, Nyuzuz’ ibyishimo."}, {"type": "chorus", "content": "Mbwiz’ ijwi ryongorera, Mbwiran’ urukundo;\nUt’ uzanesh’ iteka, Ub’ umudendezo.\nVugana nanjy’ iteka, Mbwir’ ubudahwema,\nReka numv’ uk’ umbwira ngo: Sinaguhanye."}, {"type": "verse", "number": 2, "content": "Yobora abana bawe, Uvugane na bo; Ubuzuz’ ibyishimo, Bige kugusenga.\nMwami, Bitange rwose, Bakwiyegurire; Tebuts’ ubwami bwawe, Twibanire nawe."}, {"type": "verse", "number": 3, "content": "Ngwin’ uvugane natwe, Uduhishurire, Iby’ imigambi yawe, N’ inshingano yacu,\nDuhe kuguhimbaza, Tukubahirize, Tujye tunezererwa gukor’ iby’ ushaka."}]},
  {"number": 153, "name": "Mwami, Sinsabir’ Iby’ Ejo", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/153", "key": "sol", "references": [{"codes": "AH. 270"}, {"codes": "CH. 604"}, {"title": "JUST FOR TODAY"}, {"codes": "CS. 563"}], "body": [{"type": "verse", "number": 1, "content": "Mwami, sinsabir’ iby’ ejo, Mfasha none,\nNdind’ urukongi rw’ ibyaha, Uyu munsi.\nNe gucumuz’ ururimi, Mputiyeho;\nMwami, rind’ iminwa yanjye, Uyu munsi."}, {"type": "verse", "number": 2, "content": "Njye nshunguz’ ubury’ umwete, No gusenga;\nNgwe neza mu buryo bwose, Uyu munsi.\nNkomeze nkor’ iby’ ushaka, Ngire bwangu;\nMwami, nemere kwitanga, Uyu munsi."}, {"type": "verse", "number": 3, "content": "Urupfu niruntungura, Mbe ntunganye;\nAmasezerano yawe, Ndayiteze;\nMwami, sinsabir’ iby’ ejo, Mfasha none;\nNdind’ unkomez’ undagire, Uyu munsi; Amen."}]},
  {"number": 154, "name": "Murinzi We, Ngaho Mbwira", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/154", "key": "sol", "references": [{"codes": "AH. 409"}, {"codes": "CH. 180"}, {"title": "WATCHMAN, TELL ME"}, {"codes": "CS. 734"}, {"codes": "HL. 403"}], "body": [{"type": "verse", "number": 1, "content": "Murinzi we, ngaho mbwira, Mbese bugiye gucya?\nNta bimenyets’ urabona, K’ Umwami yegereje?\nMugenzi we haguruka! Umusek’ uratambitse;\nTyo kenyera, maz’ ukeshe, Haguruka; bwakeye!"}, {"type": "verse", "number": 2, "content": "Murinzi we, dor’ umucyo, Ukomeje gukwira!\nReba naw’ ibimenyetso, Bitangaza kuza kwe.\nUbw’ impanda zizavuga, Abapfuye bazazuka.\nUbutazongera gupfa, Bibanire n’ Umwami."}, {"type": "verse", "number": 3, "content": "Murinzi we, vuz’ impundu, Igihe kirageze!\nMwese nimurangurure, Mubyamamaze hose.\nMugenzi we, nawe reba; Ubwami bugeze hafi;\nNgiriya Yerusalemu, Irarabagirana."}, {"type": "verse", "number": 4, "content": "Murinzi, mur’ uwo murwa, W ’ igikundiro rwose,\nNih’ Umwami w’ i Siyoni, Adutegerereje.\nUbwami bwe buragutse, Buhetuy’ iyi si yose;\nN’ ubwami budahanguka; Hahirw’ ababujyamo."}, {"type": "verse", "number": 5, "content": "Murinzi dor’ igihugu, Cy’ uburumbuke cyane,\nGihora kimeze neza, Nka Edeni ya kera.\nGira bwangu ntuzarire, Hasigay’ igihe gito,\nAbacungujw’ amaraso bakagerayo vuba."}]},
  {"number": 155, "name": "Aho Nzahamagarwa Hose", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/155", "key": "fa", "references": [{"codes": "AH. 352"}, {"codes": "CS. 566"}, {"title": "I’LL GO WHERE YOU WANT ME TO GO"}], "body": [{"type": "verse", "number": 1, "content": "Aho nzahamagarwa hose, Ari no mu misozi,\nCyangwa ku rugamba rukaze, Mubyeyi, nunkenera,\nUkambwiz’ ijwi ryawe ritoya, Ukanyuz’ inzira ntazi,\nNzakwishyira mu maboko, mvuge nti: Nzajy’ ah’ unshakira hose."}, {"type": "chorus", "content": "Nzajy’ ah’ unshakira hose, Mwami;\nMu misozi no mu bibaya.\nNzavug’ iby’ ushaka ko mvuga Mwami,\nKandi nzaba nk’ uk’ ushaka."}, {"type": "verse", "number": 2, "content": "Ahari Yes’ ashaka yuko muvugir’ uyu munsi;\nAhari habonek’ impabe, Nkwiriye guhabura;\nMurokozi wanjye, nunyobora, N’ ahar’ ibihanamanga;\nSinzareka kogez’ inkuru yawe; Nzajy’ ah’ unshakira hose."}, {"type": "verse", "number": 3, "content": "Ntabwo nshidikanya, Har’ aho Mwam’ ushaka ko nkora,\nMu kubaho kwanjye kugufi, Nkorer’ Uwambambiwe.\nMwami, nkubikij’ ibyanjye byose, Nzi k’ unkunda bitangaje.\nNzakor’ iby’ ushaka, mbikunze cyane; Nzajy’ ah’ unshakira hose."}]},
  {"number": 156, "name": "Amagambo Y’ Umujinya", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/156", "key": "mi bémol", "references": [{"codes": "CS. 581"}, {"title": "ANGRY WORDS! OH, LET THEM NEVER"}, {"codes": "HL. 106"}], "body": [{"type": "verse", "number": 1, "content": "Amagambo y’ umujinya, Ntakabave mu kanwa!\nAhubw’ umutim’ uyacuby’ atararushy’ asohoka."}, {"type": "chorus", "content": "S. na A.: Mukundane rwose; Yes’ aravug’ ati:\nNgir’ itegeko ryanjye mbahaye:\nMukundane rwose, Yes’ aravug’ ati:\nBana banjye, mukundane.\nT. na B.: Mukundane, Mukundane;\nNgir’ itegeko ryanjye :\nMukundane, Mukundane; n’ itegeko rye."}, {"type": "verse", "number": 2, "content": "Urukundo n’ imbonera, N’ ubucuti, birera;\nByab’ ishyano kubyicisha, Ubupfu bw’ akanya gato."}, {"type": "verse", "number": 3, "content": "Amagambo y’ intonganya, Ntaregama mu kanwa,\nIjambo rimwe ry’ intonganya, Ritandukany’ inshuti."}]},
  {"number": 157, "name": "N’ Igihe Cy’ Isarura", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/157", "key": "mi bémol", "references": [{"codes": "AH. 353"}, {"codes": "CH. 627"}, {"title": "HARVEST TIME"}, {"codes": "CS. 588"}], "body": [{"type": "verse", "number": 1, "content": "Nib’ umunt’ agend’ arira, Asohoy’ imbuto nziza,\nNtacogora ngw’ agw’ isari, Ahirwa n’ Uwiteka."}, {"type": "chorus", "content": "Yemwe ga ngo zirakura!\nReba uko zingana!\nImirima yos’ ireze,\nN’ igihe cy’ isarura."}, {"type": "verse", "number": 2, "content": "Ikime kiva mw’ ijuru, N’ umucy’ urabagirana.\nBizatum’ imbuto zera, Kubw’ ubuntu bw’ Imana."}, {"type": "verse", "number": 3, "content": "Bib’ imbuto wicogora, Woye gukuk’ umutima,\nN’ ubw’ iby’ ubon’ ar’ umwaku, Uzasarur’ ishimwe."}]},
  {"number": 158, "name": "Isarura Ry’ Isi Riregereje", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/158", "key": "mi bémol", "references": [{"codes": "CS. 589"}, {"title": "HASTEN ON, GLAD DAY"}], "body": [{"type": "verse", "number": 1, "content": "Isarura ry’ isi riregereje, Yes’ arahamagar’ abasaruzi.\nDor’ imirim’ irez’ ahantu hose, Nimuzan’ imihoro musarure!"}, {"type": "chorus", "content": "S. : Mugire bwangu, muhunik’ imiba;\nMugire bwangu, nimuze.\nA. T. B. : Mugire bwangu mwese, Nimuze;\nMuhunik’ imiba ye, Nimuze.\nMugire bwangu mwese;\nNimuze mwese nimuze."}, {"type": "verse", "number": 2, "content": "Uwo muns’ utazabamw’ amarira, Uhora wegerej’ uko bukeye.\nImyaka yararitswe n’ umuyaga, Nimugire bwangw’ imvur’ itaragwa."}, {"type": "verse", "number": 3, "content": "Urukundo ni nk’ isokw’ idakama, Ituruka mw’ ijuru ku Muremyi;\nNi rwo ruturarikira gukora, Rukadukomeza ntitugw’ isari."}]},
  {"number": 159, "name": "Nyabun’ Uburyo Ngukennye!", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/159", "key": "sol", "references": [{"codes": "AH. 221"}, {"codes": "CH. 578"}, {"title": "HOW MUCH I NEED THEE"}, {"codes": "HL. 377"}], "body": [{"type": "verse", "number": 1, "content": "Nyabun’ uburyo ngukennye! Nd’ umukene n’ impumyi;\nMfat’ ukubok’ unyobore, Ni wow’ ump’ imbaraga."}, {"type": "chorus", "content": "Ku manywa na nijoro;\nMwami ndagushak’ iteka;\nKu manywa na nijoro;\nMwam’ unyikomereze."}, {"type": "verse", "number": 2, "content": "Nyambik’ urukundo rwawe, Nahindanye nd’ intebyi.\nUbu mfit’ intege nkeya, Nyongeramw’ imbaraga."}, {"type": "verse", "number": 3, "content": "Nzab’ amahor’ unyoboye, Sinakwiyiringira.\nYes’ ujy’ ungend’ iruhande, Kuk’ undutira byose."}, {"type": "verse", "number": 4, "content": "Nubw’ ibind’ imbere byose, Byankoma mu nkokora,\nNzakomeza komatana nawe, Mwana w’ Imana."}]},
  {"number": 160, "name": "Icyampa Nkab’ Uwawe", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/160", "key": "mi bémol", "references": [{"codes": "CS. 598"}, {"title": "KEPT FOR JESUS"}], "body": [{"type": "verse", "number": 1, "content": "Icyampa nkab’ uwawe, Yesu Mwami wanjye;\nNe kononwa n’ iby’ isi, Nkwikurikirire."}, {"type": "chorus", "content": "Icyampa nkab’ uwawe,\nNitanze maramaje.\nJye ntacyo maze, Ntacyo, Ntacyo;\nNi we mpay’ ikuzo."}, {"type": "verse", "number": 2, "content": "Icyampa nkab’ uwawe, Yesu Mwami wanjye.\nUnkoresh’ uk’ ushaka, Njye nkubahiriza."}, {"type": "verse", "number": 3, "content": "Icyampa nkab’ uwawe, Yesu Mwami wanjye;\nNtandukanya n’ iby’ isi, Umboneze rwose."}, {"type": "verse", "number": 4, "content": "Icyampa nkab’ uwawe, Yesu Mwami wanjye;\nMb’ uwaw’ uko ndi kose, Nta kintu kinziga."}]},
  {"number": 161, "name": "Mfit’ Inshuti Y’ Ukuri", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/161", "key": "fa", "references": [{"codes": "SDAH. 453"}, {"codes": "AH. 112"}, {"title": "I HAVE A FRIEND SO PRECIOUS"}, {"codes": "CH. 532"}, {"codes": "CS. 599"}], "body": [{"type": "verse", "number": 1, "content": "Mfit’ inshuti y’ ukuri y’ inkoramutima,\nIrankunda bihebuje, Nzi kw’ itazampāna.\nNtabwo nayiv’ iruhande, Nkunda ko tubana,\nIyo nshuti ni Yesu, Umukiza."}, {"type": "verse", "number": 2, "content": "Iyo nguy’ agacuho, Ameny’ uko meze;\nNtanyirengagiza rwose: Aransindagiza,\nAkanyobora mu nzira, Yo gukiranuka;\nN’ inshuti nkunda cyane, Yes’ Umwami."}, {"type": "verse", "number": 3, "content": "Mutur’ umubabaro, Mubwir’ ibyishimo;\nMubwir’ ibinyura na byo, N’ ibindushya byose.\nAngaragariz’ uburyo, Nkwiriye kwifata;\nNkunda kwiganirira, Na w’ iteka."}, {"type": "verse", "number": 4, "content": "Az’ imigambi yanjye, Yo gukiz’ abandi;\nNiko kunshing’ umurimo, Wo kumuvugira,\nNo kwamamaz’ urukundo, Rwatumy’ adupfira;\nYewe, mukunda rwose, Bihebuje!"}]},
  {"number": 162, "name": "Umukiz’ Aranyobora", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/162", "key": "la bémol", "references": [{"codes": "SDAH. 516"}, {"codes": "AH. 296"}, {"title": "ALL THE WAY"}, {"codes": "CH. 259"}, {"codes": "CS. 611"}], "body": [{"type": "verse", "number": 1, "content": "Umukiz’ aranyobora, Birampagije rwose.\nSinshidikany’ impuhwe ze, Kuko njya nzibonaho.\nAmahoro yo mw’ ijuru, Yanyuzuy’ umutima;\nSinzatinya na hatoya, Kuko Yes’ anyobora;\nSinzatinya na hatoya, Kuko Yes’ anyobora."}, {"type": "verse", "number": 2, "content": "Umukiz’ aranyobora, Akanampumuriza;\nIyo ngeze mu makuba, Ntamvirira na hato;\nBona nubwo nateguza, Yandamir’ akamfasha;\nAhor’ anyitahw’ iteka, Ntacyo nzamuburana;\nAhor’ anyitahw ‘ iteka, Ntacyo nzamuburana."}, {"type": "verse", "number": 3, "content": "Umukiz’ aranyobora, Niryo humure ryanjye!\nNiw’ uzampaz’ uburame, Njye mpora musingiza.\nNta cyatuma ntiny’ urupfu, Mfit’ iryo sezerano;\nNzajya ndirimb’ iteka, Nti: Yesu niw’ unyobora;\nNzajya ndirimb’ iteka, Nti: Yesu niw’ unyobora."}]},
  {"number": 163, "name": "Yes’ Arahamagar’ Ati:", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/163", "key": "ré", "references": [{"codes": "SDAH. 359"}, {"codes": "AH. 341"}, {"title": "HARK! THE VOICE OF JESUS CALLING"}, {"codes": "CH. 447"}, {"codes": "CS. 641"}], "body": [{"type": "verse", "number": 1, "content": "Yes’ arahamagar’ ati: Nind’ unkorera none?\nIsarura rirageze, Nind’ uri busarure?\nUmv’ ukw’ aduhamagara; Kand’ azagororera.\nUmusubiza wes’ ati: Ndi hano Mwami ntuma."}, {"type": "verse", "number": 2, "content": "Nutabasha kujya kure, Ngo wambuke n’ inyanja;\nN’ ino har’ abapagani, Wagarurira Yesu.\nNutabasha gushyanuka, Ngo wigishe nka Paulo,\nWakogez’ iby’ urukundo rw’ Umukiza wabambwe."}, {"type": "verse", "number": 3, "content": "Wabura kub’ umurinzi, Ku nkike z’i Siyoni,\nWafashish’ amasengesho, No gutur’ amaturo;\nUkayobora n’ abandi, Mu nzir’ ijya mw’ ijuru,\nNk’ ukw’ Aroni yakomeje amaboko ya Mose."}, {"type": "verse", "number": 4, "content": "Abantu bari mu kaga; Yes’ aragutabaza.\nNtukagir’ ubw’ uvug’ uti: Ntacyo nakora rwose.\nIshimire gukoreshwa, Hitam’ umurimo we;\nMaz’ usubize bwang’ uti: Ndi hano, Mwami ntuma."}]},
  {"number": 164, "name": "Nicay’ Imbere Ya Yesu", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/164", "key": "fa", "references": [{"codes": "AH. 287"}, {"codes": "CH. 618"}, {"title": "AT THE FEET OF JESUS"}, {"codes": "CS. 648"}, {"codes": "HL. 381"}], "body": [{"type": "verse", "number": 1, "content": "Nicay’ imbere ya Yesu, Mpaboner’ ihumure;\nN’ ahantu h’ igikundiro; Icyampa nkahibera.\nIyo nicay’ imbere ye, Nimenyah’ ubugoryi;\nKumuhang’ amaso nibyo, Bimpa gukiranuka."}, {"type": "verse", "number": 2, "content": "Kwicar’ imbere ya Yesu, Nta mahirw’ arut’ ayo;\nNi ho nsig’ ibimbabaza, Nkumva nduhutse rwose.\nIyo nicay’ imbere ye, Nkunda kumuganyira;\nNa w’ ababarana nanjye, Maz’ akampumuriza."}, {"type": "verse", "number": 3, "content": "Yesu mp’ umugisha wawe; Dore, Ndategereje;\nNdeban’ imbabazi zawe, Menye k’ unyitayeho.\nMp’ umutima wawe, Yesu; Nyeza nkubonerere;\nBigaragarir’ abandi, Yuko mporana nawe."}]},
  {"number": 165, "name": "Ndagukunda, Mwami", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/165", "key": "mi bémol", "references": [{"codes": "SDAH. 236"}, {"codes": "AH. 357"}, {"title": "I LOVE THEE"}, {"codes": "CH. 343"}, {"codes": "CS. 650"}], "body": [{"type": "verse", "number": 1, "content": "Ndagukunda, Mwami; Uzi ko ngukunda;\nNdagukunda Yesu, Bihebuje rwose.\nNdagukunda Yesu, Naw’ urabizi;\nImirimo yanjy’ izabyerekana."}, {"type": "verse", "number": 2, "content": "Nishimye, nishimye; Rwose bitavugwa.\nIbyishimo byanjye, Nta wabirondora.\nNdareb’ ubutunzi buri mw’ ijuru,\nNzagabirwa nawe kubw’ ubuntu bwawe."}, {"type": "verse", "number": 3, "content": "Yesu Mwami wanjye, Ni we nkesha byose;\nAr’ ugucungurwa, Ari n’ ubugingo.\nNzakogez’ iteka, Nkuririmbire,\nKuk’ Ubuntu bwawe bwandemy’ umutima."}, {"type": "verse", "number": 4, "content": "Naguhwanya nande, Mucunguzi wanjye?\nUhoran’ ineza, Ntugir’ impinduka.\nNzajya nguhimbaza, Nkubahirize;\nUmutima wanjye, Wuzuy’ ibyishimo."}]},
  {"number": 166, "name": "Ayi Rutare Rw’ Imana", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/166", "key": "si bémol", "references": [{"codes": "SDAH. 300"}, {"codes": "AH. 237"}, {"title": "ROCK OF AGES"}, {"codes": "CH. 474"}, {"codes": "CS. 654"}], "body": [{"type": "verse", "number": 1, "content": "Ayi Rutare rw’ Imana, Reka nguhungireho!\nKubw’ imbabazi zawe, Kera waramenewe,\nNon’ ubu nkwihishemo, Umujinya w’ Imana."}, {"type": "verse", "number": 2, "content": "Ibyo twakora byose, N’ umwete wacu wose,\nN’ agahinda gasāze, N’ amarir’ adashira,\nByose ntibyashobora, Kudukurahw’ ibyaha."}, {"type": "verse", "number": 3, "content": "Yes’ ibyo mfite byose, Nta mumaro bigira.\nSinabasha kwikiza, Ndagushakah’ ubuntu,\nUnyuhagir’ imbyiro, Mutabazi ne gupfa."}, {"type": "verse", "number": 4, "content": "Nuko nkiri muzima, Mwami nguhungireho.\nNo ku munsi w’ imanza, Ninger’ imbere yawe,\nAyi Rutare rw’ Imana, Uzandeke nkwisunge!"}]},
  {"number": 167, "name": "Mwa Bera B’ Umwami", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/167", "key": "sol", "references": [{"codes": "AH. 215"}, {"codes": "CH. 255"}, {"title": "HOW FIRM A FOUNDATION"}, {"codes": "CS. 664"}], "body": [{"type": "verse", "number": 1, "content": "Mwa bera b’ Umwami, Mwishimir’ Ijambo rye;\nNi ryo rufatiro rwo kwizera kwanyu.\nDore yababwiye byose, Ntacyo yabahishe.\nNtitwabasha kongera kur’ iryo jambo ryiza,\nCyangwa kuritubya, Kukw’ ar’ iry’ Imana."}, {"type": "verse", "number": 2, "content": "Nugera mu kaga, Yesu yasezeranye,\nKw’ azakugoboka, Akakurengera;\nAmakuba yawe yos’ akuber’ umugisha;\nNi y’ azakweza rwose, Maz’ atum’ ushikama;\nNi y’ azakweza rwose, Agukomeze."}, {"type": "verse", "number": 3, "content": "Ibigeragezo nibikugwa gitumo,\nUbuntu bwanjye buzaba buhagije.\nIbirimi by’ umuriro, Ntibigutinyishe;\nBizakongor’ ibyaha, Usigar’ utunganye;\nBizakongor’ ibyaha, Bikuboneze."}, {"type": "verse", "number": 4, "content": "Unamba ku Mana, Ntizamuhemukira;\nNtizamuharir’ umubisha na hato.\nN’ubw’ ingabo zose z’ umwanzi zamusatira,\nNtizamuhemukira, Ntizamuhemukira,\nNtizamuhemukira, Haba na gato."}]},
  {"number": 168, "name": "Uwiteka Ni We Mwungeri Wanjye", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/168", "key": "sol", "references": [{"codes": "AH. 295"}, {"codes": "CH. 405"}, {"title": "THE LORD IS MY SHEPHERD"}, {"codes": "HL. 62"}], "body": [{"type": "verse", "number": 1, "content": "Uwiteka ni we Mwungeri wanjye, Sinzakena;\nAndyamisha mu cyanya cy’ ubwatsi butoshye cyane;\nAnyobor’ iruhande rw’ amaz’ adasuma;\nUwitek’ asubiz’ intege mu bugingo bwanjye."}, {"type": "verse", "number": 2, "content": "Nanyura no mu gikombe cy’ igicucu cy’ urupfu,\nSinatiny’ ikibi cyose, kuko ndi kumwe nawe;\nInshyimbo yawe n’ inkoni, bimp’ ihumure;\nNta kaga kazantungura, ndi kumwe nawe, Mwami."}, {"type": "verse", "number": 3, "content": "Untunganiriz’ ameza mu gihe cy’ amakuba.\nUnshagijehw’ imbabazi, zimeze nk’ amavuta;\nWanyujurij’ igikombe, cyuzur’ ubuntu.\nMwami, ntacyo wisigiye, ng’ ubon’ uk’ ukingomwa."}, {"type": "verse", "number": 4, "content": "Mana y’ ubuntu, n’ ukuri, Ineza wangiriye,\nN’ imbabazi bizanyomahw’ iminsi yanjye yose;\nNzakomeza nkuyoboke, Sinzateshuka;\nKandi nzaba mu nzu y’ Uwiteka iteka ryose."}]},
  {"number": 169, "name": "Wa Muragwa We", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/169", "key": "si bémol", "references": [{"codes": "SDAH. 594"}, {"codes": "AH. 413"}, {"title": "HEIR OF THE KINGDOM"}, {"codes": "CH. 185"}, {"codes": "CS. 679"}], "body": [{"type": "verse", "number": 1, "content": "Wa muragwa we, mbese k’ uhunikira?\nK’ ucogoy’ ugiye kugerayo?\nKanguka bwangu, Shak’ intwaro zawe;\nWizarira, dore byatinze rwose!"}, {"type": "verse", "number": 2, "content": "Amahanga yose yasubiranyemo;\nBose baradagadwa bihebye.\nUmv’ ukw’ amagar’ ahindira hose;\nWa muragwa we, Wigumya gutinda!"}, {"type": "verse", "number": 3, "content": "Ntugwabizwe n’ iby’ iyi si biguhenda;\nReb’ ubwiza bwabyo burashira.\nC’ ingoy’ Umwanzi yakubohesheje;\nWa muragwa we, Zicikeho bwangu!"}, {"type": "verse", "number": 4, "content": "Nyamuneka, ntugir’ imitim’ ibiri;\nBa mas’ Umwam’ atagutungura;\nDor’ umucy’ utangiye gutangaza;\nMuragwa we, vuz’ impundu, wishime!"}]},
  {"number": 170, "name": "Mwami Mana Yanjye", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/170", "key": "ré", "references": [{"codes": "SDAH. 15"}, {"codes": "AH. 54"}, {"title": "MY MAKER AND MY KING"}, {"codes": "CH. 71"}, {"codes": "CS. 689"}], "body": [{"type": "verse", "number": 1, "content": "Mwami Mana yanjye, Ni wow’ umbeshaho;\nUbuntu bwawe n’ isoko nkesh’ ibyiza byose.\nUbuntu bwawe n’ isoko nkesh’ amahirwe yose."}, {"type": "verse", "number": 2, "content": "Ni wowe wandemye, Nta wakundutira;\nIneza yawe ni nyinshi, Ntacyo nayinganya;\nIneza yawe ni nyinshi ntacyo nayigeraho."}, {"type": "verse", "number": 3, "content": "Mwami, Natur’ iki, Ko byos’ ar’ ibyawe?\nKerets’ umutim’ ushima, Wo kuguhimbaza;\nKerets’ umutim’ ushima, Wo kukuramya, Mwami."}, {"type": "verse", "number": 4, "content": "Umpe gushikama, Kubw’ ubuntu bwawe;\nNkweguriy’ ibyanjye byose, Mbay’ uwawe rwose;\nNkweguriy’ ibyanjye byose, Mb’ uwaw’ akaramata."}]},
  {"number": 171, "name": "Murinzi We W’ i Siyoni", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/171", "key": "ré", "references": [{"codes": "AH. 418"}, {"codes": "CH. 184"}, {"title": "WHAT OF THE NIGHT"}, {"codes": "CS. 705"}, {"codes": "HL. 536"}], "body": [{"type": "verse", "number": 1, "content": "Murinzi we, w’ i Siyoni, Ijoro rigeze he?\nMbes’ umusek’ uri hafi? Ntiburatandukana?\nNtacy’ ushishoz’ iburasira-zuba?\nNtacy’ ushishoz’ iburasira-zuba?"}, {"type": "verse", "number": 2, "content": "Nyamuneka tumenyeshe, K’ urugendo rushize;\nMbese tugeze ku cyambu, Tugiye kugerayo?\nMbese koko, Ubwami buri hafi?\nMbese koko, Ubwami buri hafi?"}, {"type": "verse", "number": 3, "content": "Burakey’ umuns’ uraje! Tubyamamaze hose;\nDor’ izuba rirarashe, Mwese nimurirebe!\nMwa bera mwe, Mugiye gucungurwa!\nMwa bera mwe, Mugiye gucungurwa!"}, {"type": "verse", "number": 4, "content": "Tugeze ku rugabano, Rw’ igihugu tujyamo,\nNimukabuze twihute, Icyambu kiri hafi.\nNimurangurure ya majwi yanyu!\nNimurangurure ya majwi yanyu!"}]},
  {"number": 172, "name": "Ngabo, Muhaguruke", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/172", "key": "si bémol", "references": [{"codes": "SDAH. 618"}, {"codes": "AH. 368"}, {"title": "STAND UP! STAND UP FOR JESUS"}, {"codes": "CH. 354"}, {"title": "(Sung To Tune How Long?)"}, {"codes": "HL. 347"}], "body": [{"type": "verse", "number": 1, "content": "Ngabo, muhaguruke! Murwanire Yesu;\nMurind’ ingabe yanyu, Mutazayinyagwa.\nMu nzira yo kunesha, Tuyoborwa na Yesu,\nTujyane na w’ iteka, Ni ho tuzanesha."}, {"type": "verse", "number": 2, "content": "Impanda ziravuze, Muze mwebwe mwese.\nIkamba ry’ ubugingo, N’ ibihembo byanyu.\nNimwangwa n’ ababisha, Mukomere, murwane;\nMwonger’ umwete mwinshi, Muganze Satani."}, {"type": "verse", "number": 3, "content": "Mubyuke mutabare, Mudashidikanya.\nHe kugir’ umw’ usiba, Murebe kwa Yesu.\nKandi mujye mutwara, Intwaro zo kwizera.\nMuhabwe ukunesha, N’ ibyishimo byinshi."}, {"type": "verse", "number": 4, "content": "Mubyuke vuba vuba, Murwane iteka,\nMwizer’ izina ryera, Ni ho muzanesha;\nMaz’ izo ntwaro zose, Muzih’ Umwami Yesu,\nMuzabon’ amahoro y’ iteka mw’ ijuru."}]},
  {"number": 173, "name": "Icyampa Nkizera Rwose", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/173", "key": "la bémol", "references": [{"codes": "AH. 203"}, {"codes": "CH. 245"}, {"title": "O FOR A FAITH"}, {"codes": "SDAH. 533"}], "body": [{"type": "verse", "number": 1, "content": "Icyampa nkizera rwose, Ubutadohoka;\n(Sintinyishwe) Sintinyishwe n’ ubukene,\nCyangw’ ibyago byose, Cyangw’ ibyago byose."}, {"type": "verse", "number": 2, "content": "Sinivovote, mbabajwe, N’ igihano cyawe;\n(Ahubwo ni…) Ahubwo nimba mu kaga,\nNkunambeho Mwami, Nkunambeho Mwami."}, {"type": "verse", "number": 3, "content": "Mpabwe gushikama cyane, Umugaru nugwa;\n(Ne guhindi…) Ne guhindishw’ umushitsi,\nN’ ibyago bitera, N’ ibyago bitera."}, {"type": "verse", "number": 4, "content": "Ne gukangishwa n’ ab’ isi, N’ igitsure cyabo;\n(N’ ubwo bangi…) N’ ubwo bangir’ urw’ amenyo,\nNoye kubyitaho, Noye kubyitaho."}, {"type": "verse", "number": 5, "content": "Mwami, ben’ uko kwizera, Ni ko ngutezeho;\n(Niringiye) Niringiye ko nzahabwa,\nkwibera mw‘ ijuru, kwibera mw‘ ijuru."}]},
  {"number": 174, "name": "Hahirw’ Ufit’ Ibyiringiro", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/174", "key": "mi", "references": [{"codes": "CH. 387"}, {"title": "HOW CHEERING"}], "body": [{"type": "verse", "number": 1, "content": "Sop: Hahirw’ ufit’ ibyiringiro bishyitse, Akiri mu miruho y’ iyi si.\nBimukomez’ agatsind’ ibishuko by’ Umwanzi.\nBimukomez’ agatsind’ ibishuko n’ amakuba menshi.\nAlto: Hahirw’ ufit’ ibyiringiro bishyitse, Akiri mu miru… y’ isi. …Bishuko\nby’ Umwanzi. Bimukome… …gatsind’ ibishuko n’ amaku… menshi.\nTenor: Hahirw’ ufit’ ibyi - byiringiro bishyitse, Aki… miruho y’ iyi si.\n…Z’ agatsind’ ibishuko by’ Umwa… by’ Umwanzi.\nBi - ko - z’ agatsind’ i - ko, n’ amaku… menshi.\nBass: Hahirw’ ufit’ ibyi – byi - ngiro bishyitse, Akiri mu mi - miruho y’ iyi si.\nBimukome… Bimukomez’ agatsind’ ibishuko\nBi - kome… …gatsind’ ibishuko n’ amaku… menshi."}, {"type": "verse", "number": 2, "content": "Sop: Nibyo bitwibuts’ iby’ uburuhukiro, Ahw’ abakiranutsi bazaba;\nBakibanira n’ inshut’ ubudatandukana.\nBakibanira n’ inshut’ iteka ntibazatandukane.\nAlto: Nibyo bitwibutsi - tsi buruhukiro, Ahw’ abakiranu… …zaba.\n…Budatandukana. Bakibani… n’ inshut’ iteka ntibazata - kane.\nTenor: Nibyo bitwibutsi – ts’ iby’ uburuhukiro, Ahw’ a - ranutsi bazaba;\n…Ra n’ inshut’ ubudatanduka… …ndukana.\nBa - ba - ra n’ inshuti ntibazata - kane.\nBass: Nibyo bitwibutsi – tsi …buruhukiro, Aho abakiranutsi bazaba;\nBakibani… Bakibanir’ ubudatandukana.\nBa – ban’i… n’ inshut’ iteka ntibazata - kane."}, {"type": "verse", "number": 3, "content": "Sop: N’ igihugu kitazarangwamw’ icyaha. Ahw’ ibishuko bitazagera;\nNi nahw’ ibyishimo bitazagir’ impinduka.\nNihw’ ibyishimo bitazongera kugira kirogoya.\nAlto: N’ igihugu kita - tarangwa mw’ icyaha. Ahw’ ibishuko bi - gera;\n…Zagir’ impinduka. Nihw’ ibyishi… bitazongera kugira ki - goya.\nTenor: N’ igihugu kita - tazarangwa mw’ icyaha. Ahw’ i - ko bitazagera.\n…Shimo bitazagir’ impindu… …mpinduka.\nN’ ibyi - mo bitazo… kugira ki - goya.\nBass: N’ igihugu kita - tarangwa mw’ icyaha. Aho ibishuko bitazagera.\nNi nahw’ ibyi…, Ni nahw’ ibyishimo bidahinduka.\nN’ ibyishi… bitazongera kugira ki - goya."}, {"type": "verse", "number": 4, "content": "Sop: Nta n’ umw’ uzahabogorez’ amarira; Ntabw’ urupfu ruzahahangara;\nAbaturage baho baziberahw’ iteka.\nAbaturage baho bazamera nk’ abamarayika.\nAlto: Nta n’ umw’ uzahabo - borez’ amarira; Ntabw’ urupfu ruza - ngara;\n…Ziberahw’ iteka. Abatura… baho bazamera nk’ abama - yika.\nTenor: Nta n’ umw’ uzahabo - bogorez’ amarira; Ntabw’u… ruzahahangara;\n…Ge baho baziberahw’ ite… hw’iteka. A – tu - ge baho ba - ra nk’ abama - yika.\nBass: Nta n’ umw’ uzahabo - borez’ amarira; Ntabwo urupfu ruzahahangara.\nAbatura… Abaturage bazabahw’ iteka. A - tura… baho bazamera nk’ abama - yika."}, {"type": "verse", "number": 5, "content": "Sop: Icyaduh’ igihe kikihuta bwangu! Tukabon’ Umukiza wac’ aje!\nAkatujyana muri cya gihugu cy’ ibyiza.\nAkatugez’ aho tuzibanira n’ Umukiza wacu.\nAlto: Icyaduh’ igihe …he …kihuta bwangu! Tukabon’ Umuki… …c’ aje!\n… gihugu cy’ ibyiza. Akatuge - ho tuzibanira n’ Umuki… wacu.\nTenor: Icyaduh’ igihe …he kikihuta bwangu! Tuka… Mukiza wac’ aje!\n…Na muri cya gihugu cy’ ibyi… cy’ ibyiza. A - tu - zaho tuzi - ra n’ Umuki… wacu.\nBass: Icyaduh’ igihe …he …kihuta bwangu! Tukabona Umukiza wac’ aje!\nAkatujya… Akatujyana mu gihugu cyiza.\nA - tuge - ho tuzibanira n’ Umuki… wacu."}]},
  {"number": 175, "name": "Nyagasani, Turakwiragije", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/175", "key": "mi bémol", "references": [{"codes": "SDAH. 545"}, {"codes": "AH. 294"}, {"title": "SAVIOR LIKE A SHEPHERD"}, {"codes": "CH. 394"}, {"codes": "CS. 729"}, {"codes": "HL. 553"}], "body": [{"type": "verse", "number": 1, "content": "Nyagasani, Turakwiragije, Turagukennye cyane;\nTuragire mu bwatsi butoshye, Turakwiyeguriye;\nNyagasani, Nyagasani, Ni we waducunguye;\nNyagasani, Nyagasani, Ni we waducunguye."}, {"type": "verse", "number": 2, "content": "Ubu tur’ abawe rwose Mwami, Tureban’ imbabazi;\nTurinde tur’ umukumbi wawe, Twe guteshuk’ inzira;\nNyagasani, Nyagasani, Nyamuneka twumvire;\nNyagasani, Nyagasani, Nyamuneka twunvire."}, {"type": "verse", "number": 3, "content": "Wasezeranye k’ uzatwakira, N’ubwo tur’ abangizi;\nUdufitiy’ imbabazi nyinshi, N’ ubuntu buhebuje;\nNyagasani, Nyagasani, Turakugarukira;\nNyagasani, Nyagasani, Turakugarukira."}]},
  {"number": 176, "name": "Ibyiringiro Dufite", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/176", "key": "fa", "references": [{"codes": "AH. 308"}, {"codes": "CH. 379"}, {"title": "THERE IS A BLESSED HOPE"}, {"codes": "CS. 743"}, {"codes": "GH. 48"}], "body": [{"type": "verse", "number": 1, "content": "Ibyiringiro dufite bigir’ agaciro cyane;\nKurut’ iby’ iyi si by’ imburamumaro,\nBijya bishimisha benshi."}, {"type": "verse", "number": 2, "content": "Twabony’ umucy’ utangaje, Utamurur’ umwijima,\nWazanywe n’ uk’ urupfu rwiganzuy’ isi,\nNone twaretse kwiheba."}, {"type": "verse", "number": 3, "content": "Twumvis’ ijwi ry’ ihumure, Rinyur’ imitima yacu;\nRidutinyura rwose, rikatwizeza,\nYukw’ Iman’ ar’ urukundo."}, {"type": "verse", "number": 4, "content": "Iryo jwi n’ irya Rurema, Uwo mucyo n’ Ijambo rye;\nIbyo byiringiro n’ ukuragw’ ijuru,\nNtitwongere gupf’ ukundi."}]},
  {"number": 177, "name": "Mu Gihugu Cy’ Ibyiza", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/177", "key": "mi bémol", "references": [{"codes": "SDAH. 427"}, {"codes": "AH. 421"}, {"title": "IN THE LAND OF FADELESS DAY"}, {"codes": "CH. 558"}, {"codes": "CS. 862"}, {"codes": "HL. 592"}], "body": [{"type": "verse", "number": 1, "content": "Mu gihugu cy’ ibyiza, Har’ umurwa wera;\nUzahorahw’ iteka: Nta joro rihaba."}, {"type": "chorus", "content": "S.: Nta marir’ azabayo, Nta rupfu cyangw’ ubwoba;\nIbihe ntibibarwayo, Kuko ntabwo bwira.\nA., T. na B : Nta marir’ azabayo, Nta rupfu cyangw’ ubwoba;\nIbihe ibihe ntibibarwayo, Kuko ntabwo bwira."}, {"type": "verse", "number": 2, "content": "Inkike z’ uwo murwa, Zose n’ izahabu;\nN’ inzira na zo n’uko; Nta joro rihaba."}, {"type": "verse", "number": 3, "content": "Kand’ amarembo yawo, Ntabwo yugarirwa;\nUruzi rw’ ubugingo, Ruzawutembamo."}, {"type": "verse", "number": 4, "content": "Ntuzagomba kuvirwa, N’ izuba n’ ukwezi;\nKand’ Umwana w’ Intama, Ni we mucyo wawo."}]},
  {"number": 178, "name": "Ahar’ Azaza Umusek’ Utambitse", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/178", "key": "ré", "references": [{"codes": "SDAH. 207"}, {"codes": "AH. 402"}, {"title": "CHRIST RETURNETH"}, {"codes": "CH. 536"}, {"codes": "CS. 867"}], "body": [{"type": "verse", "number": 1, "content": "Ahar’ azaza, umusek’ utambitse, Igih’ umucy’ utamurur’ umwijima;\nAzany’ icyubahiro kitarondorwa, Aje kurokor’ intore ze."}, {"type": "chorus", "content": "Tuzageza ryari, Mwami tugutegereje?\nUrakaza, Haleluya, Haleluy’ amina! Haleluy’ amina!"}, {"type": "verse", "number": 2, "content": "Ahar’ azaza, nko ku manywa y’ ihangu; Cyangwa s’ azaza mu gicuku hagati;\nUmucy’ usab’ impande zose z’ iyi si, Aje kurokor’ intore ze."}, {"type": "verse", "number": 3, "content": "Mbeg’ ibyishimo, Nasanga tukiriho! Tutarwaye, Tutaririwe twapfuye;\nMaz’ akadutumbagirana mu bicu, Aje kurokor’ intore ze."}]},
  {"number": 179, "name": "Mbes’ Uzaba Witeguye?", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/179", "key": "la", "references": [{"codes": "CS. 868"}, {"title": "BEHOLD THE BRIDEGROOM"}], "body": [{"type": "verse", "number": 1, "content": "Mbes’ uzaba witeguye, Yes’ aje, Yes’ aje?\nMbes’ uzaba witeguye, Yes’ aje, Yes’ aje?\nDore araje! Dore araje!\nItegure, dor’ Umukw’ araje!"}, {"type": "chorus", "content": "Dore Umukwe araje, Araje!\nDore Umukwe araje, Araje!\nDore araje! Dore araje!\nItegure, Dor’ Umukw’ araje!"}, {"type": "verse", "number": 2, "content": "Muringaniz’ amatara, Araje, Araje!\nMuringaniz’ amatara, Araje, Araje!\nDore araje! Dore araje!\nItegure, Dor’ Umukw’ araje!"}, {"type": "verse", "number": 3, "content": "Mutyo, tumusanganire, Araje, Araje!\nMutyo, tumusanganire, Araje, Araje!\nAraje koko! Araje koko!\nItegure, Dor’ Umukw’ araje!"}, {"type": "verse", "number": 4, "content": "Turirimbe: Haleluya; Araje, Araje!\nTuririmbe: Haleluya; Araje, Araje!\nAraje koko! Araje koko!\nTuririmbe: Haleluy’ araje!"}]},
  {"number": 180, "name": "Ntituz’ Umunsi", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/180", "key": "do", "references": [{"codes": "SDAH. 604"}, {"codes": "AH. 400"}, {"title": "WE KNOW NOT THE HOUR"}, {"codes": "CH. 540"}, {"codes": "CS. 878"}], "body": [{"type": "verse", "number": 1, "content": "Ntituz’ umunsi Yesu azagaruka, Arikw’ igihe, cyo kiri hafi cyane,\nIbimenyetso byagaragaye byose, N’ umunsi tutazi."}, {"type": "chorus", "content": "Azaza (azaza), duhore twiteguye. Azaza (azaza),\nHaleluya! Haleluya! Azaza ku bicu,\nAfit’ ubwiza bwa Se, N’ umunsi tutazi."}, {"type": "verse", "number": 2, "content": "Abitondera, igitabo cy’ Imana, Ukuri kwayo, nimwo bakubonera,\nIbyahanuwe bitangaza kuza kwe, N’ umunsi tutazi."}, {"type": "verse", "number": 3, "content": "Imuri zacu ntizigahweme kwaka, Tujye dukora, dutegerej’ Umwami,\nTumuhimbaze, twe kujya turambirwa, N’ umunsi tutazi."}]},
  {"number": 181, "name": "Ntituz’ Igihe Azazira", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/181", "key": "mi bémol", "references": [{"codes": "AH. 398"}, {"codes": "CH. 542"}, {"title": "WAITING AND WATCHING"}, {"codes": "CS. 885"}], "body": [{"type": "verse", "number": 1, "content": "Ntituz’ igihe azazira, Ku manywa cyangwa nijoro;\nAhar’ azaza bugorobye, Cyangw’ umusek’ utambitse.\nAratwihanangiririza kuba mas’ iteka ryose;\nKugira ng’ ubw’ azatunguka, Azasange twiteguye."}, {"type": "chorus", "content": "S. : Tumwitegure, Tumwitegure, Tumwitegure; Dore, Turamwiteguye.\nA,. T. na B.: Tumwitegure, tumwitegure, Tumwitegure, tumwitegure,\nTumwitegure, tumwitegure, Dore, Turamwiteguye."}, {"type": "verse", "number": 2, "content": "Ndibuk’ uburyo yadukunze, Akaduharira byose;\nYasiz’ ubwiza bwe mw’ ijuru, Yitangira kudupfira.\nAzanezerwa nagaruka, Kujyan’ abo yacunguye,\nNib’ azasanga bari maso, Bamaze kumwitegura."}, {"type": "verse", "number": 3, "content": "Ayi Yesu Mwana w’ Imana, Dor’ uz’ ibyo ndangamiye;\nNizigiye ko nzakubona, Nkurebesh’ amaso yanjye;\nN’ ubwo bamwe bazaguhunga, Babony’ igitsure cyawe,\nJye, nzakuramutsa nk’ inshuti; N’ ubu ndagutegereje."}]},
  {"number": 182, "name": "Umunsi W’ Ihumur’ Uregereje", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/182", "key": "sol bémol", "references": [{"codes": "SDAH. 205"}, {"codes": "AH. 394"}, {"title": "GLEAMS OF THE GOLDEN MORNING"}, {"codes": "CH. 547"}, {"codes": "CS. 892"}], "body": [{"type": "verse", "number": 1, "content": "Umunsi w’ ihumur’ uregereje; Yes’ azazaho.\nNi bw’ azajyan’ abana be bizeye, Bigir’ iwabo."}, {"type": "chorus", "content": "Umusek’ utangiye gutambika,\nWeyuyeh’ umwijima!\nUmusek’ utangiye gutambika,\nBugiye gucya!"}, {"type": "verse", "number": 2, "content": "Ubutumwa bwiza nibuhetura iyi si yacu,\nUmwam’ azashok’ aza bidatinze, Atujyan’ iwe."}, {"type": "verse", "number": 3, "content": "Naz’ ashagawe n’ abamarayika batabarika,\nAzatsembahw’ ibihumanya byose; Ntabw’ azasobwa."}, {"type": "verse", "number": 4, "content": "Abazaba baratandukanijwe, Bazabonana;\nBe kongera kubogoz’ amarira, Bagubwe neza."}]},
  {"number": 183, "name": "Yesu Yadusezeraniy’ Ati:", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/183", "key": "sol", "references": [{"codes": "SDAH. 600"}, {"codes": "AH. 333"}, {"title": "SWEET PROMISE IS GIVEN"}, {"codes": "CH. 548"}], "body": [{"type": "verse", "number": 1, "content": "Yesu yadusezeraniy’ ati: Dore ndaza vuba kujyan’ abanjye;\nKomez’ icy’ ufit’ utakinyagwa; Komeza wizere, we kurambirwa."}, {"type": "chorus", "content": "Komez’ icy’ ufit’ utakinyagwa;\nSo yiteguye kuguh’ ubwami.\nNgwino, Winjire mu munezero;\nUrahabw’ ikamba ritangirika."}, {"type": "verse", "number": 2, "content": "Tuzajye tuba maso dusenga, Kukw’ azaza nk’ umujura w’ ijoro;\nNtituz’ umunsi, cyangwa s’ igihe; Icyo tuzi n’ uko ari bugufi."}, {"type": "verse", "number": 3, "content": "Dufit’ ijambo ritwiringiza y’uko, Tuzaragw’ ubwami bw’ Imana;\nN’ isezerano ridakuka ngo: Dore ndaza vuba, we kurambirwa."}]},
  {"number": 184, "name": "Mwese, Nimuvuz’ Impundu", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/184", "key": "ré", "references": [{"codes": "SDAH. 125"}, {"codes": "AH. 403"}, {"title": "JOY TO THE WORLD"}, {"codes": "CH. 189"}, {"codes": "CS. 895"}], "body": [{"type": "verse", "number": 1, "content": "Mwese, nimuvuz’ impundu! Dor’ Umwam’ araje!\nMwitegure mwiboneze, Musangwe mwinonosoye.\nIsi yos’ iririmbe ( isi yos’ iririmbe)!\nIsi yose niririmbe ( yose niririmbe)!\nNawe juru, wishim’ uririmbe cyane!"}, {"type": "verse", "number": 2, "content": "Mwese, nimuvuz’ impundu! Dor’ Umwam’ araje!\nAzim’ ingom’ ihoraho, Ntabw’ izahanguka rwose.\nMuvuz’ ijwi ry’ impundu ( vuz’ ijwi ry’ impundu),\nNimuvuz‘ ijwi ry‘ impundu ( vuz’ ijwi ry’ impundu),\nNimwishime mwese muririmbe cyane."}, {"type": "verse", "number": 3, "content": "Azanatsembahw’ icyaha, Is’ igubwe neza;\nImibabar’ izashira, Habehw’ amahoro masa,\nNta mivum’ izabayo ( Nta mivum’ izabayo),\nNtabwo hazab’ imivumo ( Ntabwo hazab’ imivumo),\nNtayo rwose, Nta mivum‘ izarangwayo."}, {"type": "verse", "number": 4, "content": "Azategekesh’ ubuntu no gukiranuka;\nNgw’ ab’ isi bose bamenye, K’ Uwitek’ agira neza,\nUrukundo rwe rwinshi ( urukundo rwe rwinshi),\nUrukundo rutangaje ( urukundo rutangaje ),\nUrukundo rwe rwinshi rurahebuje."}]},
  {"number": 185, "name": "Mbese Ko Tujya Tuvuga", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/185", "key": "sol", "references": [{"codes": "SDAH. 434"}, {"codes": "AH. 422"}, {"title": "WE SPEAK OF THE REALMS"}, {"codes": "CH. 199"}, {"codes": "CS. 902"}], "body": [{"type": "verse", "number": 1, "content": "Mbese, Ko tujya tuvuga, Iby’ igihugu cy’ ihirwe;\nTukogez’ ubwiza bwaho; Kubayo bizacur’ iki?\nKo tuvug’ inzira zaho, Zasizw’ izahabu nziza;\nAr’ ukugenekereza; Tugezeyo, hacur’ iki?"}, {"type": "verse", "number": 2, "content": "Ko tuvug’ uko hameze, Kw‘ ari nta byaha n’ urupfu,\nCyangw’ ibishuko bibayo, Tugezeyo hacur’ iki?\nKo tuvug’ iby’ urukundo, N’ ibishura bizambarwa,\nTukabyishimira cyane; Kubayo bizacur’ iki?"}, {"type": "verse", "number": 3, "content": "Tuvuga n‘ iby‘ igitondo, Kizaba gitamanzuye,\nTukazabona wa murwa, Umanuk‘ urimbishijwe.\nUmurw‘ urabagirana, Utarangwamw‘ agahinda,\nNtubemo n‘ imibabaro, Har‘ umunezero gusa."}, {"type": "verse", "number": 4, "content": "N’ ubwo ngoswe n’ ibishuko, Ntunganiriza kujyayo;\nNgo nanjye njye niyumvamo, Uko kubayo byamera;\nNi bwo tuzatambagira, Icyo gihugu cy’ ihirwe,\nHamwe n’ abamarayika, Na Yes’ Umukiza wacu."}]},
  {"number": 186, "name": "Data Mwiza Tugarutse Kugushengerera", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/186", "key": "fa", "references": [{"codes": "AH. 308"}, {"codes": "CH. 26"}, {"title": "AGAIN WE MEET"}, {"codes": "CS. 743"}], "body": [{"type": "verse", "number": 1, "content": "Data mwiza, Tugarutse kugushengerera none;\nTwicishije bugufi, twiyoroheje, Twifuza kubabarirwa."}, {"type": "verse", "number": 2, "content": "Twongeye kugushimira, Kuko waturinze twese;\nUkatuzirikana ukaduhira, Ukatugarura hano."}, {"type": "verse", "number": 3, "content": "Ayi, twagushij’ ishyano; Tur’ abo kwangw’ urunuka;\nDore tujya duteshuk’ inzira yawe, Noneho turahabutse."}, {"type": "verse", "number": 4, "content": "Mana y’ imigisha yose, Ni w’ utang’ utaziganya;\nTureban’ imbabazi, turakwinginze; Uduhaz’ ijambo ryawe."}]},
  {"number": 187, "name": "Mwam’ Ubwo Tukigushengereye", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/187", "key": "la bémol", "references": [{"codes": "AH. 25"}, {"codes": "CH. 34"}, {"title": "OUR PARTING HYMN"}, {"codes": "CS. 382"}], "body": [{"type": "verse", "number": 1, "content": "Mwam’ ubwo tukigushengereye,\nTukuririmbirir’ icyarimwe\nIyi ndirimbo yac’ iheruka,\nTwicishije bugufi, duhire."}, {"type": "verse", "number": 2, "content": "Mwami dusezerer’ amahoro;\nDuherekeze, tujyane nawe;\nTurindir’ iminwa n’ imitima,\nNgo yoye kujy’ igukoz’ isoni."}, {"type": "verse", "number": 3, "content": "Amahoro yaw’ abane natwe;\nAb’ ari y’ ajy’ aduh’ ihumure.\nMaze n’ uturuhur’ imiruho,\nTuzongere kuyabon’ iwawe."}]},
  {"number": 188, "name": "N’ Ubwo Nsazwe N’ Ibyaha", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/188", "key": "la bémol", "references": [{"codes": "SDAH. 295"}, {"codes": "AH. 188"}, {"title": "CHIEF OF SINNERS"}, {"codes": "CH. 238"}], "body": [{"type": "verse", "number": 1, "content": "N’ ubwo nsazwe n’ ibyaha, Yesu yarankijije,\nYamviriy’ amaraso, Angura n’ urupf’ atyo.\nTuzab’ akaramata, Ak’ ishami n’ igiti."}, {"type": "verse", "number": 2, "content": "Urukundo rwa Yesu, Rusaguts’ ikirere.\nNtacyo twarugeraho, Ruzagumahw’ iteka;\nNi we warumbwirije, Jye ntabwo nari nduzi."}, {"type": "verse", "number": 3, "content": "N’ ubwo nsazwe n’ ibyaha, Yes’ andutira byose;\nAz’ ibyo nkennye byose, Ankiz’ umubabaro.\nNamuberey’ imbata, Nta cyago cyampangara."}]},
  {"number": 189, "name": "Twabuze Gakondo Mur’ Iyi Si", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/189", "key": "sol", "references": [{"codes": "AH. 417"}, {"codes": "CH. 308"}, {"title": "NO ABIDING CITY HERE"}, {"codes": "CS. 925"}], "body": [{"type": "verse", "number": 1, "content": "Twabuze gakondo mur’ iyi si;\nTuyirimo tur’ abasuhuke;\nArikw’ ikitunezeza,\nN’uko dushaka gakondo,\nIrushaho kuba nziza."}, {"type": "verse", "number": 2, "content": "Twabuze gakondo mur’ iyi si;\nTugamij’ iy’ iwacu mw’ ijuru;\nNi yo Siyon’ ihoraho,\nIfit’ umucy’ udashira,\nIhor’ irabagirana."}, {"type": "verse", "number": 3, "content": "Mbeg’ uburyo tuzanezererwa;\nAhw’ abagenzi bat’ umuruho.\nIcyamp’ amababa none,\nNkaguruka, Nkigirayo,\nNkibanira nawe, Mwami."}, {"type": "verse", "number": 4, "content": "Mutima wanjye, reka kuganya!\nDor’ igih’ Imana yangeneye,\nNi cyo cyiza, ni cyo cyiza;\nNjye nkomeza kwiringira,\nNgez’ ubw’ izampamagara."}]},
  {"number": 190, "name": "Mw’ Ijuru No Mw’ Isi Yose", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/190", "key": "la bémol", "references": [{"codes": "SDAH. 474"}, {"codes": "AH. 100"}, {"title": "PRECIOUS NAME"}, {"codes": "CH. 523"}, {"codes": "CS. 216"}, {"codes": "HL. 290"}], "body": [{"type": "verse", "number": 1, "content": "Mw’ ijuru no mw’ isi yose, Nta zina nk’ irya Yesu;\nNtaryo nkunda ku mutima, Nk’ iry’ uwaducunguye."}, {"type": "chorus", "content": "N’ izina ( n’ izina ) rya Yesu ( rya Yesu ),\nNi ryo ritwiringiza; N’ izina ( n’ izina ),\nRy’ Umukiza, Riduhesh’ amahirwe."}, {"type": "verse", "number": 2, "content": "Nihagir’ umunt’ ushimwa, Akarutishw’ abandi,\nN’ abarush’ icyubahiro, Yes’ aramuhebuza."}, {"type": "verse", "number": 3, "content": "Abamarayika bose, Bitw’ amazina meza,\nAriko nta zina ryabo, Ribasha kunnezeza."}, {"type": "verse", "number": 4, "content": "Yes’ ankiz’ ibyago byose, Kandi ni w’ unkomeza;\nN’ iyo nagiz’ intege nke, Anyonger’ imbaraga."}]},
  {"number": 191, "name": "Ngiz’ Amahirwe Nd’ Uwa Yesu", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/191", "key": "sol", "references": [{"codes": "SDAH. 462"}, {"codes": "AH. 260"}, {"title": "BLESSED ASSURANCE"}, {"codes": "CH. 608"}, {"codes": "CS. 205"}], "body": [{"type": "verse", "number": 1, "content": "Ngiz’ amahirwe, nd’ uwa Yesu; N’ ubu mfit’ umunezero mwinshi!\nNdazw’ agakiza; ndacunguwe; Mbyawe n’ Umwuka, ndatunganye."}, {"type": "chorus", "content": "Ni byo ndirimba, ni byo mvuga;\nNshim’ Umukiz’ ubudasiba;\nNi byo ndirimba, ni byo mvuga;\nNshim’ Umukiz’ ubudasiba."}, {"type": "verse", "number": 2, "content": "Nditanze, ndamwiyeguriye; Ndumv’ ibyishimo binsabye rwose.\nNarokotse kubw’ ubuntu bwe, None ntegerej’ iby’ ijuru."}, {"type": "verse", "number": 3, "content": "Sinkir’ uwanjye, ndamwihaye, Ni we wambohoy’ arambatura.\nMbe maso nsenge, ntegereze; Maz’ ubuntu bwe bunyuzure."}]},
  {"number": 192, "name": "Reba Yesu Ku Musaraba", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/192", "key": "la bémol", "references": [{"codes": "CS. 300"}, {"title": "GLORY TO HIS NAME"}], "body": [{"type": "verse", "number": 1, "content": "Reba Yesu ku musaraba, Reb’ uko twatumy’ agirirwa;\nHuguk’ araguhamagara, Ngwin’ umusange."}, {"type": "chorus", "content": "Duhimbaz’ izina rye, Duhimbaz’ izina rye;\nYaducunguj’ amaraso ye; Yes’ ahimbazwe!"}, {"type": "verse", "number": 2, "content": "Yesu yambatuye mu byaha, Atura mu mutima wanjye;\nNi w’ uwuzanamw’ ihumure; Yes’ ahimbazwe!"}, {"type": "verse", "number": 3, "content": "Ni we Sokw’ inyezahw’ ibyaha; Narayiyuhagije ndera;\nNzi yukw’ ineza y’ izaramba; Yes’ ahimbazwe!"}, {"type": "verse", "number": 4, "content": "Muze kw’ Isoko y’ Agakiza; Maze muyiyuhagiremo;\nIrabezahw’ ibyaha byose; Yes’ ahimbazwe!"}]},
  {"number": 193, "name": "Mbes’ Urumv’ Ushaka Gutunganira Yesu?", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/193", "key": "sol", "references": [{"codes": "CS. 58"}, {"title": "HIS WAY WITH THEE"}], "body": [{"type": "verse", "number": 1, "content": "Mbes’ urumv’ ushaka gutunganira Yesu?\nNg’ ugendane na we mu nzira ntoya?\nAkwikorerer’ imitwaro yawe yose ?\nEmer’ ugengwe na we."}, {"type": "chorus", "content": "Azagutungany’ akuboneze,\nAmaraso y’ akwezehw’ ibyaha,\nAkuzuz’ urukundo rwe rwinshi;\nNiwemera kujy’ ugengwa na we."}, {"type": "verse", "number": 2, "content": "Mbes’ urashaka kw’ akubatura mu byaha?\nNgw’ aguh’ amahoro yo mu mutima?\nAjy’ akuramira, we guhor’ ugwaguza?\nEmer’ ugengwe na we."}, {"type": "verse", "number": 3, "content": "Mbes’ urashaka kugabana ku bugingo?\nNgo wibere mu bwami bwo mw‘ ijuru?\nUrashaka kumaramaza muri byose?\nEmer’ ugengwe na we."}]},
  {"number": 194, "name": "I Muhira Hahirwa", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/194", "key": "la bémol", "references": [{"codes": "SDAH. 652"}, {"codes": "CS. 580"}, {"title": "LOVE AT HOME"}, {"codes": "HL. 432"}], "body": [{"type": "verse", "number": 1, "content": "I muhira hahirwa, Har’ urukundo; Byose bib’ amahoro, Har’ urukundo.\nNtihab’ impagarara, N’ urutoto n’ inkeke; Hab’ ibyishimo gusa, Har’ urukundo."}, {"type": "chorus", "content": "Ineza mu rugo, Ni y’ izan’ ibyishimo, Har’ urukundo."}, {"type": "verse", "number": 2, "content": "Ivundi ryanezeza, har’ urukundo; Ntihaba kirogoya, Har’ urukundo,\nIbiri mu nzu byose byahinduk’ inyamibwa, Hab’ ibyishimo gusa, Har’ urukundo."}, {"type": "verse", "number": 3, "content": "Yes’ akunda kuhaba, Har’ urukundo; Isi yos’ irishima, Har’ urukundo.\nIsanzure ry’ ijuru, Ryuzur’ umucyo waka, N’ Iman’ ikamwenyura, Har’ urukundo."}]},
  {"number": 195, "name": "Icyamp’ Umuriro Waka", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/195", "key": "si bémol", "references": [{"codes": "SDAH. 264"}, {"codes": "AH. 149"}, {"title": "OH FOR THAT FLAME!"}, {"codes": "CH. 210"}, {"codes": "CS. 166"}], "body": [{"type": "verse", "number": 1, "content": "Icyamp’ umuriro waka, Wajyag’ urabagiranira.\nMu bera ba kera bose, Ukabagir’ intwari z’ Imana."}, {"type": "verse", "number": 2, "content": "Mwam’ icyampa wa mutima, Aburahamu yahoranye;\nWari no muri Pawulo, Ukamutera kwiyumanganya."}, {"type": "verse", "number": 3, "content": "Ntukiban’ intore zawe, Nk’ uko wabanye na Eliya?\nUgahumuriza Yobu, Ageze mu kaga katavugwa."}, {"type": "verse", "number": 4, "content": "Ibuka, Mwam’ aba kera, Uko wabagendereraga;\nAb’ ari k’ ujy’ utugenza, Utwuzuz’ Umwuka wawe Wera."}]},
  {"number": 196, "name": "Mbes’ Urashaka Kunesh’ Ibyaha?", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/196", "key": "si bémol", "references": [{"codes": "AH. 294"}, {"title": "THERE IS A POWER IN THE BLOOD"}, {"codes": "CS. 27"}], "body": [{"type": "verse", "number": 1, "content": "Mbes’ urashaka kunesh’ ibyaha? Izer’ amaraso ya Yesu.\nMbes’ urashaka kumeny’ intsinzi? N’ amaraso y’ Umukiza."}, {"type": "chorus", "content": "S. na A. : Har’ imbaraga mu maraso,\nY’ Umwana w’ Intama;\nHar’ imbaraga mu maraso,\nYa Yes’ Umwana w’ Imana .\nT. na B. : Koko har’ imbaraga mu maraso…;\nY’ Umwana… w’ Intama;\nKoko har’ imbaraga mu maraso,\nYa Yes’ Umwana w’ Imana."}, {"type": "verse", "number": 2, "content": "S’ urashaka gukir’ ubwibone? Izer’ amaraso ya Yesu;\nNgwin’ umusange ku musaraba, Akwejesh’ amaraso ye."}, {"type": "verse", "number": 3, "content": "Mbes’ urashaka kujya wera de? Izer’ amaraso ya Yesu.\nIcyakwez’ ibizinga by’ ibyaha, N’ amaraso y’ Umukiza."}, {"type": "verse", "number": 4, "content": "Urashaka gukorera Yesu? Izer’ amaraso y’ akiza.\nUrashaka kujy’ umusingiza? Izere ya maraso ye."}]},
  {"number": 197, "name": "Yesu Naz’ Umwijim’ Uzahunga", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/197", "key": "fa", "references": [{"codes": "SDAH. 218"}, {"codes": "CS. 854"}, {"title": "THERE WILL BE NO DARK VALLEY"}], "body": [{"type": "verse", "number": 1, "content": "Yesu naz’ umwijim’ uzahunga, Yesu naz’ umwijim’ uzahunga,\nImpundu zizavuga Yes’ aje, Gukorany’ intore ze."}, {"type": "chorus", "content": "Gukorany’ abakunzi be ( bose );\nGukorany’ abakunzi be ( bose );\nImpundu zizavuga Yes’ aje,\nGukorany’ intore ze."}, {"type": "verse", "number": 2, "content": "Imibabaro yos’ izashira, Imibabaro yos’ izashira;\nUbw’ Umwami Yes’ azagaruka, Gukorany’ intore ze."}, {"type": "verse", "number": 3, "content": "Nta wuzongera kurir’ ukundi, Nta wuzongera kurir’ ukundi;\nUmwami Yesu naza ku bicu, Gukorany’ intore ze."}, {"type": "verse", "number": 4, "content": "Hazab’ indirimbo z’ indamutso, Hazab’ indirimbo z’ indamutso;\nZ’ abakijijwe Yes’ agarutse, Gukorany’ intore ze."}]},
  {"number": 198, "name": "Yesu Ni We Nshut’ Ihebuje", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/198", "key": "sol", "references": [{"codes": "CH. 528"}, {"title": "THE BEST FRIEND IS JESUS"}, {"codes": "CS. 50"}], "body": [{"type": "verse", "number": 1, "content": "Yesu ni we nshut’ ihebuje, Iy’ amagany’ agucogoje.\nNi we womor’ inguma zo mu mutima wawe;\nYesu ni we nshut’ ihebuje."}, {"type": "chorus", "content": "Yesu n’ inshut’ ihebuje (ihebuje);\nYesu n’ inshut’ ihebuje (ihebuje);\nNugw’ azakuramira, Nutak’ agutabare;\nYesu ni we nshut’ ihebuje."}, {"type": "verse", "number": 2, "content": "Nasanz’ ar’ inshut’ ihebuje, Kukw’ atampana mu makuba;\nNindek’ akanyobora, Sinzagir’ icyo ntinya;\nYesu ni we nshut’ ihebuje."}, {"type": "verse", "number": 3, "content": "N’ ubwo natahirwa n’ ibyago, Bikantera byiyungikanya,\nSinzakuk’ umutima, Kukw’ ampor’ iruhande;\nYesu ni we nshut’ ihebuje."}, {"type": "verse", "number": 4, "content": "Ubwo tuzagera mw’ ijuru, Tugahura n’ abo twatanye,\nImpundu zizavuga, Tumusingiz’ iteka:\nYesu ni we nshut’ ihebuje."}]},
  {"number": 199, "name": "Imana Ihimbarizw’ Ibyo Yakoze", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/199", "key": "la bémol", "references": [{"codes": "SDAH. 341"}, {"codes": "AH. 144"}, {"title": "TO GOD BE THE GLORY"}, {"codes": "CH. 647"}, {"codes": "CS. 191"}], "body": [{"type": "verse", "number": 1, "content": "Iman’ ihimbarizw’ ibyo yakoze; Yakunz’ ab’ is’ itang’ Umwana wayo;\nNi we Yesu waducunguye twese, Akaducir’ icyanzu ngo dukire."}, {"type": "chorus", "content": "Dushime, dushime, Yes’ Umwami wacu;\nDushime, dushime, Twese tumushime.\nNi we watwujuje n’ Imana yacu;\nTumuhimbariz’ iyo neza nyinshi."}, {"type": "verse", "number": 2, "content": "Yesu yaducunguj’ amaraso ye, Maz’ aduca kuri kamere yacu;\nNgo n’ ubwo twaba twarashayishije, Tube nk’ abatigeze gucumura."}, {"type": "verse", "number": 3, "content": "Ibyo yadukoreye ntibigerwa, Twakiran’ Umwana w’ Imana ishimwe;\nAriko tuzarushaho kwishima, Nitumurebesh’ aya maso yacu."}]},
  {"number": 200, "name": "Ur’ Uwera Wera", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/200", "key": "mi", "references": [{"codes": "SDAH. 73"}, {"codes": "AH. 30"}, {"title": "HOLY, HOLY, HOLY"}, {"codes": "CH. 73"}, {"codes": "CS. 327"}], "body": [{"type": "verse", "number": 1, "content": "Ur’ Uwera wera, Man’ ikomeye!\nMu gitondo tujye tukuririmbira.\nN’ubw’ ukomey’ ute, Ugir’ imbabazi;\nIngoma yawe ntizahanguka."}, {"type": "verse", "number": 2, "content": "Ur’ Uwera wera, Abera bose,\nBaguhimbazanya n’ abamarayika!\nIbyaremwe byose bikuramye, Mwami,\nWahozeho, Kand’ uzahoraho."}, {"type": "verse", "number": 3, "content": "Ur’ Uwera wera, Ubwiza bwawe,\nN’ ubwo butarebwa n’ inkozi z’ ibibi,\nUhor’ ur’ Uwera, Nta wundi mwahwanya,\nKugira neza, No gutungana."}]},
  {"number": 201, "name": "Uhoraho Nyobora", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/201", "key": "sol", "references": [{"codes": "SDAH. 538"}, {"codes": "SP. 3"}, {"title": "GUIDE ME, O THOU GREAT"}], "body": [{"type": "verse", "number": 1, "content": "Uhoraho nyobora, Kuko nd’ umugenzi mu butayu,\nNd’ umunyantege nke, Ariko wowe ur’ umunyambaraga.\nMutsima wo mw’ ijuru we, Nshaka guhazwa nawe (guhazwa nawe),\nNshaka cyane guhazwa nawe."}, {"type": "verse", "number": 2, "content": "Twifuza kumarw’ inyota nawe, Wowe sokw’ idakama,\nTuyoboresh’ inkingi y’ igicu, Tuzarangiz’ urugendo.\nUr’ umutabazi wacu, N’ ingab’ idukingira ( idukingira),\nTuber’ ingab’ idukingira."}, {"type": "verse", "number": 3, "content": "Ningera ku nkombe ya Yordani, Umutim’ uzatuza,\nMaz’ unyambuts’ amasumo yaho, Ngere hakury’ i Kanani.\nNzaririmba, Nzaririmba, Nzagusingiz’ iteka (iteka),\nNzagusingiz’ iteka ryose. Amen."}]},
  {"number": 202, "name": "Urugo Runezerewe", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/202", "key": "sol", "references": [{"codes": "SDAH. 655"}, {"codes": "CH. 413"}, {"title": "HAPPY THE HOME"}], "body": [{"type": "verse", "number": 1, "content": "Urugo runezerewe, Iman’ irubamo,\nIyo bahuj’ imigambi yo kujya mw’ ijuru."}, {"type": "verse", "number": 2, "content": "Urugo rurimo Yesu, Rugir’ amahoro,\nAbana biga kuvuga, Bahoh’ izina rye."}, {"type": "verse", "number": 3, "content": "Urugo runezerewe, Bahora basenga,\nAhw’ ababyeyi bakunda, Ijambo ry’ Imana."}, {"type": "verse", "number": 4, "content": "Mukiza fash’ ingo zacu, Zigir’ amahoro,\nUzuz’ imitima yacu, Urukundo rwawe."}]},
  {"number": 203, "name": "Munsi Y’ Amababa Ye", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/203", "key": "ré bémol", "references": [{"codes": "SDAH. 529"}, {"codes": "CH. 587"}, {"title": "UNDER HIS WINGS"}], "body": [{"type": "verse", "number": 1, "content": "Munsi y’ amababa ye ni hw’ ampisha,\nN’ ubw’ ijoro ryakwijima cyane,\nNtacyo nzatinya nzi kw’ azankomeza,\nUbu nd’ umwana we yacunguye."}, {"type": "chorus", "content": "Munsi y’ ayo mababa ye,\nHavuy’ urukundo rwinshi,\nMu mababa ni ho nzibera,\nMu mahor’ iteka ryose."}, {"type": "verse", "number": 2, "content": "Munsi y’ amababa ye nta gahinda,\nN’ uburuhukiro bw’ umutima,\nMur’ iyi si ntiharimw’ agakiza,\nMpirwa ndi mu mababa ye gusa."}, {"type": "verse", "number": 3, "content": "Munsi y’ amababa ye ni ho heza,\nNzajya mpihish’ ibishuko byose,\nNi ho buhungiro nta cyampangara,\n,Nzibanira na Yes’ amahoro."}]},
  {"number": 204, "name": "Mwami, Umurab’ Urakaze!", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/204", "key": "do", "references": [{"codes": "AH. 205"}, {"title": "MASTER, THE TEMPEST IS RAGING!"}, {"codes": "HL. 375"}], "body": [{"type": "verse", "number": 1, "content": "Mwam’ umurab’ urakaze, Urahorera cyane.\nNta buhungiro nta bwugamo, Bw’ umuzajoro nk’uyu.\nMbese ko tugiye gupfa, Nawe wiryamiye?\nDor’ umuraba wabay’ icyago, Tugiye kurengerwa."}, {"type": "chorus", "content": "S. na A.: Umurab’ uranyumvira rwose; Utuze.\nT. na B.: Umurab’ uranyumvira rwose.\nUtuze ...ze ...tuze\nBose: Nib’ ar’ umurab’ usheg’ utyo,\nCyangwa dayimoni cyangwa s’ abantu,\nNta mazi yabasha kurengera\nUbwat’ Umwami wa byos’ arimo.\nDore byose biranyumvira; Bituze, Bituze.\nDore byose biranyumvira, Biratuza."}, {"type": "verse", "number": 2, "content": "Mwami mfit’ agahind’ ubu, N’ umubabaro mwinshi,\nUmuraba urandengeye, Mwami tebuk’ unkize.\nIsuri y’ ibyaha byanjye, Dor’ irantembanye,\nNdarenganye, Ndarenganye rwose, Mwami tebuk’ unkize."}, {"type": "verse", "number": 3, "content": "Mwam’ umurab’ uratuje, Ubu nta bwoba mfite.\nHamaze no gutamuruka, Mfit’ ibyishimo byinshi.\nNuko, Mwami ndakwinginze, Ntunsige njyenyine,\nNduhukire mur’ iki cyambu, Kirimw’ amahoro masa."}]},
  {"number": 205, "name": "Nkweguriy’ Ubugingo Bwanjye", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/205", "key": "fa", "references": [{"codes": "SDAH. 330"}, {"codes": "GH. 273"}, {"title": "TAKE MY LIFE AND LET IT BE"}], "body": [{"type": "verse", "number": 1, "content": "Nkweguriy’ ubugingo bwanjye, Ng’ ubugenz’ uk’ ushaka Mukiza,\nNkweguriy’ amaboko yanjye, Ng’ uyakoresh’ uk’ ushaka Mwami,\nNg’ uyakoresh’ uk’ ushaka."}, {"type": "verse", "number": 2, "content": "Nkweguriy’ ibirenge byanjye, Bijye bijyan’ ubutumwa bwiza,\nNkweguriy’ ijwi ryanjye na ryo, Ngo rijye rigusingiz’ iteka,\nNgo rijye rigusingiza."}, {"type": "verse", "number": 3, "content": "Nkweguriye akanwa kanjye, Kuzuz’ ubutumwa bwawe Mwami,\nNkweguriy’ ubutunzi bwanjye, Ntacyo nshaka kwisigaranira,\nNtabwo nagir’ icyo nkwima."}, {"type": "verse", "number": 4, "content": "Nkweguriy’ imigambi yanjye, Yikoresh’ uk’ ushaka Mukiza,\nNkweguriy’ umutima wanjye, Maz’ uwimike mu Bwami bwawe,\nWimike mu Bwami bwawe."}, {"type": "verse", "number": 5, "content": "Nkweguriy’ urukundo rwanjye, Sinshaka kugir’ icyo nguhisha,\nNguhay’ impagarike yanjye, Nkweguriy’ ibyanjye byose Mwami,\nNkweguriy’ ibyanjye byose."}]},
  {"number": 206, "name": "Abazacungurwa Bazaririmba", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/206", "key": "do", "references": [{"codes": "S. 1020"}, {"title": "THEY SING A NEW SONG"}], "body": [{"type": "verse", "number": 1, "content": "Abazacungurwa bazaririmba, Bazashyir’ amakamba yabo hasi,\nImibabaro yab’ izab’ ishize, Bazahora banezerew’ iteka."}, {"type": "chorus", "content": "S. na A.: Bazaririmbir’ iyo Ntama y’ i Kalvari\nBaririmbire Yes’ Umwami Uhoraho.\nT. na B.: Bazaririmba, Bazaririmba, ...ma y’ i Kalvari\nNtama y’ i Kalvari,\nBaririmbire, baririmbire ...mi, Uhoraho."}, {"type": "verse", "number": 2, "content": "Indirimbo y’ urukund’ itangaje, Izab’ iririmbanyw’ umunezero,\nTuzabanayo n’ Umukiza wacu, Tuzahora tunezerew’ iteka."}, {"type": "verse", "number": 3, "content": "Abamesh’ ibishura byabo ni bo, Bazegera ya ntebe ye ya cyami,\nIbyaha tuzabikizwa na Yesu, Tuzahora tunezerew’ iteka."}]},
  {"number": 207, "name": "Ku Musozi Kure", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/207", "key": "si bémol", "references": [{"codes": "SDAH. 159"}, {"title": "THE OLD RUGGED CROSS"}, {"codes": "CH. 533"}, {"title": "(On a Hill Far Away)"}], "body": [{"type": "verse", "number": 1, "content": "Ku musozi kure har’ umusaraba, Ubabaj’ ukojej’ isoni,\nNdawukunda cyane kuko wabambweho, Uwacunguy’ abanyabyaha."}, {"type": "chorus", "content": "Nzogeza uwo musaraba (musaraba),\nKugez’ ubwo nzat’ umuruho,\nNzikomeza ku musaraba (musaraba),\nKugez’ ubwo nzambikw’ ikamba."}, {"type": "verse", "number": 2, "content": "Mbeg’ umusarab’ ab’ isi bahinyuye, Ng’ uranyur’ umutima wanjye!\nUmwana w’ Intama yarets’ ikuzo rye, Awikorer’ ajy’ i Kalvari."}, {"type": "verse", "number": 3, "content": "Umusaraba wavushij’ amaraso, Ya Yesu Umwana w’ Imana,\nKuri wo ni h’ Umukiza yatangiye, Maz’ ubwo mbabarirw’ ibyaha."}, {"type": "verse", "number": 4, "content": "Kubw’ umusaraba, Nzab’ umunyakuri, Nihanganir’ isoni zawo,\nKugez’ ubw’ uzanjyan’ iwacu mw’ ijuru, Tunezeranw’ iteka ryose."}]},
  {"number": 208, "name": "Yes’ Umukiza Yari Mu Gituro!", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/208", "key": "do", "references": [{"codes": "S. 152"}, {"title": "CHRIST AROSE!"}, {"codes": "HL. 80"}], "body": [{"type": "verse", "number": 1, "content": "Yes’ Umukiza yari mu gituro, Ahategerereje ko bucya."}, {"type": "chorus", "content": "Mu gitond’ arazuka (arazuka),\nAtsinz’ umwanzi bitangaje (bitangaje),\nYaneshej’ ubutware bw’ umwijima,\nAzabana n’ aber’ iteka ryose.\nYazutse (yazutse), Yazutse (yazutse)!\nUmwami Yes’ ariho."}, {"type": "verse", "number": 2, "content": "Barindiy’ ubusa Yes’ Umukiza, Bakinz’ igituro ngw’ aheremo."}, {"type": "verse", "number": 3, "content": "Umukiza Yesu, Ntiyaheranywe, N’ ingoyi z’ urupfu, Yarazutse."}]},
  {"number": 209, "name": "Ahar’ Uburuhukiro", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/209", "key": "ré bémol", "references": [{"codes": "SDAH. 495"}, {"title": "NEAR TO THE HEART OF GOD"}, {"codes": "AH. 252"}, {"title": "(There is a Place of Quiet Rest)"}], "body": [{"type": "verse", "number": 1, "content": "Ahar’ uburuhukiro, Ni hafi y’ Imana,\nAhw’ icyaha kitarangwa, Ni hafi y’ Imana."}, {"type": "chorus", "content": "Mwami Yesu Mukiza watumwe n’ Imana,\nDukomereze twese bugufi bw’ Imana."}, {"type": "verse", "number": 2, "content": "Ahatab’ impagarara, Ni hafi y’ Imana,\nAhw’ icyaha kitarangwa, Ni hafi y’ Imana."}, {"type": "verse", "number": 3, "content": "Ahahor’ umudendezo, Ni hafi y’ Imana,\nAhahor’ umunezero, Ni hafi y’ Imana."}]},
  {"number": 210, "name": "Iteraniro Ry’ Abera", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/210", "key": "do", "references": [{"codes": "S. 1024"}, {"title": "TEN THOUSAND TIMES TEN THOUSAND"}], "body": [{"type": "verse", "number": 1, "content": "Iteraniro ry’ abera, Inzovu n’ ibihumbi,\nIngabo z’ abacunguwe, Barabagirana nk’ umucyo,\nBarwany’ uko babasha, None baratsinze,\nMwagurir’ amarembo, Kugira ngo binjire."}, {"type": "chorus", "content": "Haleluya, Haleluya, Dusingiz’ Umwana w’ Intama,\nHaleluya, Haleluya, Nimusingiz’ Uwazutse."}, {"type": "verse", "number": 2, "content": "Ikobe ry’ indirimbo, Rirangira mu kirere,\nUrusobe rw’ amajwi y’ inanga, Zizacurangw’ urwunge,\nMbeg’ umuns’ utangaje, Ni nk’ uwo kurema,\nMbega ng’ umubabar’ uratsindwa bitavugwa!"}, {"type": "verse", "number": 3, "content": "Hanezerew’ abari mu mirenge y’ i Kanani,\nIgitey’ ubwuzu kandi, N’ uko batazatandukana,\nYa maso yariraga uzasang’ akeye,\nNta mpfubyi nta n’ impfusha bizarangw’ i Kanani."}, {"type": "verse", "number": 4, "content": "Iteraniro ry’ abera, Batsinze wa mubisha,\nNimwumv’ izo ndirimbo nziza, Ni nk’ iz’ abamarayika,\nHehe n’ imibabaro, Bayisezeyeho,\nNtibazongera gusuhuz’ imitim’ ukundi."}]},
  {"number": 211, "name": "Nimwuname Imbere Ya Yehova", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/211", "key": "ré", "references": [{"codes": "SDAH. 82"}, {"codes": "AH. 1"}, {"title": "BEFORE JEHOVAH’S AWFUL THRONE"}, {"codes": "CH. 1"}], "body": [{"type": "verse", "number": 1, "content": "Nimwunam’ imbere ya Yehova,\nYemwe mahanga yo mw’ isi,\nMumenye yuk’ Uhorahw’ ari we Mana,\nNi we soko y’ ubugingo."}, {"type": "verse", "number": 2, "content": "Kand’ imbaraga ze zitangaje,\nZaturemye mu butaka,\nNdets’ igihe twazimiraga nk’ intama,\nYatugaruye mu bushyo."}, {"type": "verse", "number": 3, "content": "Tumusingirize mu ndirimbo,\nDuhanik’ amajwi yacu,\nKand’ indim’ ibihumbi zo mw’ isi yose,\nZizasingiz’ Uhoraho."}, {"type": "verse", "number": 4, "content": "Amateka y’ ageng’ isi yose,\nNta wager’ urukundo rwe,\nUkuri kwe gushikamye nk’ urutare,\nUkw’ ibihe bih’ ibindi."}]},
  {"number": 212, "name": "Mb’ Uwawe, Mwami", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/212", "key": "mi bémol", "references": [{"codes": "AH. 239"}, {"title": "HAVE THINE OWN WAY, LORD"}, {"codes": "CH. 272"}], "body": [{"type": "verse", "number": 1, "content": "Mb’ uwawe Mwami mbane nawe,\nNi wow’ umbumba, Jye nd’ ibumba,\nNgenz’ uk’ ushaka mere nkawe,\nMwam’ ubu ndakwiyeguriye."}, {"type": "verse", "number": 2, "content": "Mb’ uwawe Mwami mbane nawe,\nNdondora Mwam’ ungerageze,\nUnyeze nere nk’ urubura,\nNjye ngusenga niyoroheje."}, {"type": "verse", "number": 3, "content": "Mb’ uwawe Mwami mbane nawe,\nUbu ndagusab’ untabare,\nWowe Nyir’ imbaraga zose,\nNkorah’ umvure we Mukiza."}, {"type": "verse", "number": 4, "content": "Mb’ uwawe Mwami mbane nawe,\nNkomeza kuko nteraganwa,\nNyuzuz’ Umwuka wawe Wera,\nNgo bose bambonemo Yesu."}]},
  {"number": 213, "name": "Mutuze", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/213", "key": "si bémol", "references": [{"codes": "SDAH. 479"}, {"title": "BE SILENT, BE SILENT"}, {"codes": "CH. 601"}, {"codes": "HL. 163"}], "body": [{"type": "verse", "number": 1, "content": "Mutuze, Mutuze, Mwe guhwihwisa,\nMwite kw’ ijambo ryose mwumvir’ aha."}, {"type": "chorus", "content": "Mwitonde (mwitonde),\nMwitonde (mwitonde),\nHar’ Uhoraho, Muze (muze) hafi ye, v ……..\nMumwubashye cyane."}, {"type": "verse", "number": 2, "content": "Mutuze, Mutuze, Aha n’ ahera,\nTurahumvir’ ubutumwa bukiza."}, {"type": "verse", "number": 3, "content": "Mutuze, Mutuze, Mwiyoroheje,\nDusangir’ ibyiza byo mur’ Edeni."}, {"type": "verse", "number": 4, "content": "Mutuze, Mutuze, Tubabarirwe,\nMutuze, Turi kumwe n’ Uhoraho."}]},
  {"number": 214, "name": "Mbes’ Ushaka Guhirwa?", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/214", "key": "ré", "references": [{"codes": "AH. 345"}, {"title": "WOULD YOU WIN A SAVIOR’S BLESSINGS?"}, {"codes": "CH. 479"}], "body": [{"type": "verse", "number": 1, "content": "Mbes’ ushaka guhirwa? Tang’ unezerewe.\nBizakwiz’ ubutumwa, Tang’ unezerewe.\nNtukikanyize rwose, Tanga unezerewe.\nFatanya n’ Imana, Tyo tang’ unezerewe."}, {"type": "verse", "number": 2, "content": "Reka wikwikanyiza, Tang’ unezerewe.\nRekur’ impano zawe, Tang’ unezerewe.\nMbes’ utunze bikeya? Tanga unezerewe.\nIzaguh’ imigisha, Tang’ unezerewe."}, {"type": "verse", "number": 3, "content": "Kwiza hos’ ubutumwa, Tang’ unezerewe.\nMaz’ umucyo wihute, Tang’ unezerewe.\nMbes’ ushak’ imigisha wahabwa n’ Uhoraho?\nNuko rero mwumvire, Tang’ unezerewe."}]},
  {"number": 215, "name": "Rangurur’ Indirimbo", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/215", "key": "la bémol", "references": [{"codes": "SDAH. 34"}, {"title": "WAKE THE SONG"}, {"codes": "AH. 464"}], "body": [{"type": "verse", "number": 1, "content": "Rangurur’ indirimbo y’ ibyishimo n’ umunezero,\nWikwiheba shir’ agahinda, Ririmban’ ibyishimo.\nRirimbir’ Uwaturinze, Waduhuje n’ inshuti,\nUwatuyoboy’ inzira, Itugeza mw’ ijuru."}, {"type": "chorus", "content": "Ririmba (ririmba), Ririmba (ririmba),\nRirimban’ ibyishimo,\nRirimba (ririmba), Ririmba (ririmba),\nN’ ibyishimo byinshi."}, {"type": "verse", "number": 2, "content": "Turirimbe dutway’ amabendera tunezerewe,\nTuririmba hoziana z’ umunezero w’ iteka.\nTuririmbir’ Umukiza, Turanguruy’ amajwi,\nTuvug’ ibyabaye kera, By’ urukundo rw’ Imana."}, {"type": "verse", "number": 3, "content": "Turagushima Data Wera, Kubw’ imbabazi zawe,\nUko duteraniye hamwe, Turagushima cyane.\nTuragushima Mukiza, Kuko waducunguye,\nUduhe Umwuka Wera, Atwegerez’ Imana."}]},
  {"number": 216, "name": "Nshikamye Ku Masezerano", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/216", "key": "si bémol", "references": [{"codes": "SDAH. 518"}, {"title": "STANDING ON THE PROMISES"}, {"codes": "SP. 41"}], "body": [{"type": "verse", "number": 1, "content": "Nshikamye ku masezerano meza, Y’ Umukiza wanjye, Mpora nsingiza,\nNzahora musingiza, Ndanguruye, Nshikamye ku masezerano."}, {"type": "chorus", "content": "S.: Nshikamye ku masezerano, Y’ Umucunguzi wanjye,\nNshikamye ku masezerano, Y’ Umucunguzi.\nA.,T. na B.: Nshikamye ku masezerano,\nMasezerano y’ Umucunguzi wanjye,\nNshikamye ku maserano, Y ’ Umucunguzi.\nMasezerano y’ Umucunguzi."}, {"type": "verse", "number": 2, "content": "Nshikamye ku masezerano meza, N’ ubwo naba mbuz’ epfo na ruguru,\nIjambo ry’ Imana rimpa gutsinda, Nshikamye ku masezerano."}, {"type": "verse", "number": 3, "content": "Nshikamye ku masezerano meza, Kuko nejeshejw’ amaras’ akiza,\nNiy’ atuma mpora mu mudendezo, Nshikamye ku masezerano."}, {"type": "verse", "number": 4, "content": "Nshikamye ku masezerano meza, Nkomezwa n’ umurunga w’ urukundo,\nMpora neshesh’ inkota y’ Umwuka We, Nshikamye ku masezerano."}, {"type": "verse", "number": 5, "content": "Nshikamye ku masezerano meza, Numv’ Umwuka We Wer’ ampamagara,\nNgo ngume mu Mukiza nkesha byose, Nshikamye ku masezerano."}]},
  {"number": 217, "name": "Niba Mvug’ Ijambo Rito", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/217", "key": "sol", "references": [{"codes": "CH. 629"}, {"title": "IF ANY LITTLE WORD OF MINE"}, {"codes": "SP. 197"}], "body": [{"type": "verse", "number": 1, "content": "Niba mvug’ ijambo rito, Rihumuriz’ abandi,\nNiba ndirimb’ indirimbo, Ntibongere kwiheba."}, {"type": "chorus", "content": "Mana mfasha mvuge neza,\nMpa n’ indirimbo nziza,\nMbashisha kurangurura,\nNgo byumvikane hose."}, {"type": "verse", "number": 2, "content": "Niba urukundo rwanjye, Rwahumuriz’ abandi,\nNiba nagir’ icyo nkora, Kikunganir’ abandi."}, {"type": "verse", "number": 3, "content": "Niba nakor’ umurimo, Ukaruhur’ abandi,\nMana mp’ urukundo rwinshi, Rutume mfash’ abandi."}]},
  {"number": 218, "name": "Umwami Yesu Yikorer’ Umusaraba?", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/218", "key": "sol", "references": [{"codes": "SDAH. 328"}, {"codes": "AH. 106"}, {"title": "MUST JESUS BEAR THE CROSS ALONE?"}], "body": [{"type": "verse", "number": 1, "content": "Umwami Yesu yikorer’ umusaraba wenyine?\nUmuntu wese yikorer’ uwe, Nanjye har’ uwanjye."}, {"type": "verse", "number": 2, "content": "Nzawikorera ngeze igihe azawunduhura,\nAnjyan’ iwacu anyambik’ ikamba yanteguriye."}, {"type": "verse", "number": 3, "content": "Nzarambik’ ikamba ryanjye iruhande rw’ Umukiza,\nHaba hashashe izahabu, Nzogeza izina rye."}]},
  {"number": 219, "name": "Umwami Yesu Yazutse", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/219", "key": "do", "references": [{"codes": "SDAH. 166"}, {"codes": "AH. 94"}, {"title": "CHRIST THE LORD RISEN TODAY"}, {"codes": "CH. 134"}], "body": [{"type": "verse", "number": 1, "content": "Umwami Yesu yazutse, Mwese nimwishime Haleluya,\nAbaremwe bamuramye, Mwese nimwishime Haleluya,\nTwese tumusingize, Mwese nimwishime Haleluya,\nIsi n’ ijuru bimusingize, Mwese nimwishime Haleluya."}, {"type": "verse", "number": 2, "content": "Umukiza wac’ ariho, Mwese nimwishime Haleluya,\nYaneshej’ urupfu rwose, Mwese nimwishime Haleluya,\nNi we waducunguye, Mwese nimwishime Haleluya,\nYatsinz’ imbaraga z’ igituro, Mwese nimwishime Haleluya."}, {"type": "verse", "number": 3, "content": "Yaducunguj’ urukundo, Mwese nimwishime Haleluya,\nYaturwaniy’ intambara, Mwese nimwishime Haleluya,\nYiganzura n’ urupfu, Mwese nimwishime Haleluya,\nYatwugururiye Paradizo, Mwese nimwishime Haleluya."}, {"type": "verse", "number": 4, "content": "Twishimire kujy’ ahw’ ari, Mwese nimwishime Haleluya,\nTuger’ ikirenge mu cye, Mwese nimwishime Haleluya,\nAzatuzura nka we, Mwese nimwishime Haleluya,\nTubikeshej’ umusaraba we, Mwese nimwishime Haleluya."}]},
  {"number": 220, "name": "Mbese Yesu Ajy’ Anyitaho?", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/220", "key": "do", "references": [{"codes": "SDAH. 181"}, {"codes": "AH. 122"}, {"title": "DOES JESUS CARE?"}], "body": [{"type": "verse", "number": 1, "content": "Mbese Yesu ajy’ anyitaho, Mu byago no mu mahoro,\nMu mibabaro no mu miruho, No mu rugendo rurushya?"}, {"type": "chorus", "content": "Anyitaho, Arandinda,\nMu mibabaro yanjye,\nMu bihe merewe nabi,\nUmukiza wanjy’ anyitaho."}, {"type": "verse", "number": 2, "content": "Mbese Yesu ajy’ anyitaho, Iyo ngenda mu mwijima,\nN’ iy’ umwijima w’ akag’ ungose, Mbese Yes’ amba bugufi?"}, {"type": "verse", "number": 3, "content": "Mbese Yesu ajy’ anyitaho, Iyo nguye mu bishuko,\nIyo mbabaye, N’ iyo mbogoza, Mbese Yes’ arantabara?"}, {"type": "verse", "number": 4, "content": "Mbese Yesu ajy’ anyitaho, Iyo nsezeye ku nshuti,\nIyo mbabazwa, Simpumurizwe, Mbese Yes’ ab’ abireba?"}]},
  {"number": 221, "name": "Hanga Amaso Umukiza", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/221", "key": "fa", "references": [{"codes": "GH. 23"}, {"title": "TURN YOUR EYES UPON JESUS"}, {"codes": "HL. 526"}], "body": [{"type": "verse", "number": 1, "content": "Iyo utewe n‘ ibyago bigatuma wiyunamira,\nIyo kwiheba kukugezeh’ ubwoba bukagutaha."}, {"type": "chorus", "content": "Hang’ amaso Umukiza,\nNgwin’ arakureba neza,\nUzumv’ uhumurijwe kandi,\nAzakwemera akwakire."}, {"type": "verse", "number": 2, "content": "Iy‘ usatiriwe n‘ umuraba byose bihungabanye,\nIy‘ ibyawe byose byagushijeh‘ ubwoba bwagutashye."}, {"type": "verse", "number": 3, "content": "Iy’ ur‘ arakazuyaz‘ ubuz‘ urukundo rwawe rwa mbere,\nIy‘ icyaha wakoze kigutotez‘ ijoro n‘ umunsi."}, {"type": "verse", "number": 4, "content": "Iyo ugiz‘ ibiguc‘ intege mu murimo wa Yesu.\nIyo mu rugendo rwawe mw‘ isi utakimeny‘ inzira."}]},
  {"number": 222, "name": "Mfasha Ngo Ndusheho", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/222", "key": "sol", "references": [{"codes": "SDAH. 458"}, {"codes": "AH. 311"}, {"title": "MORE LOVE TO THEE, O CHRIST"}], "body": [{"type": "verse", "number": 1, "content": "Mfasha ngo ndusheho kugukunda,\nIcyo ni cyo ngusaba mpfukamye.\nMbigusabye cyane mfasha Mwami Yesu,\nNgo ndusheho kugukunda."}, {"type": "verse", "number": 2, "content": "Nashats’ iby’ iyi si ngo nezerwe,\nUbu ndabiretse, Ng’ ump’ ibyiza.\nIcyo nsaba gusa, Mfasha Mwami Yesu,\nNgo ndusheho kugukunda."}, {"type": "verse", "number": 3, "content": "Mfit’ umubabaro n’ agahinda,\nNzishimira cyan’ intumwa zawe.\nIyo ndirimbana na zo biramfasha,\nNkarushaho kugukunda."}, {"type": "verse", "number": 4, "content": "Mu marembera y’ ubu bugingo,\nNzagushima cyane ngusingize.\nNzakuririmbira maze mvuge nsenga,\nNgo ndusheho kugukunda."}]},
  {"number": 223, "name": "Yes’ Aje Yasanga Twiteguye?", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/223", "key": "si bémol", "references": [{"codes": "S. 791"}, {"title": "WILL JESUS FIND US WATCHING?"}], "body": [{"type": "verse", "number": 1, "content": "Yes’ aje yasanga twiteguye, Yasanga turi maso?\nIgihe cyose yagarukamo, Se twaba twiteguye?"}, {"type": "chorus", "content": "Mbese mugenzi twavuga tuti:\nUbu turiteguye?\nMbes’ ah’ Umwam’ azasanga wowe nanjye,\nTukimutegereje?"}, {"type": "verse", "number": 2, "content": "Mbese naz’ umusek’ utambitse akaduhamagara,\nUmunt’ akabazw’ icyo yakoze, Mbes’ ahw’ azadushima?"}, {"type": "verse", "number": 3, "content": "Mbese tujya tub’ abanyakuri, cyangwa turinezeza?\nNiba tuboneye mu mitima, Tuzagera mw’ ijuru."}, {"type": "verse", "number": 4, "content": "Hahirw’ ab’ Umwami azasanga bakimutegereje,\nMbese nagaruka mu gicuku, Tuzaba turi maso?"}]},
  {"number": 224, "name": "Izuba Nirirenga", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/224", "key": "mi bémol", "references": [{"codes": "S. 939"}, {"title": "WE’LL MEET EACH OTHER THERE"}], "body": [{"type": "verse", "number": 1, "content": "Izuba nirirenga turangij’ imirimo,\nUbwo tuzaba tunaniwe,\nUhorah’ utwara byose ni w’ uzadukiza,\nDuhurire kuri Siyoni."}, {"type": "chorus", "content": "Tuzahurirayo, Koko tuzahurirayo,\nTuzibanira na Yesu, Muri cya gihugu cyiza,\nTuzahurirayo, Koko tuzahurirayo,\nTwibanire (twibanire), mw’ ikuzo rye."}, {"type": "verse", "number": 2, "content": "Tunyura mu gicucu, No mu mugaru mwinshi,\nTugoswe n’ umwijim’ ukaze,\nAriko Uhoraho, Ni w’ uzatuyobora,\nAb’ ari w’ utugez’ iwacu."}, {"type": "verse", "number": 3, "content": "N’ubw’ amaso yacu yuzuyemo amarira,\nDufit’ ubwoba mu mitima,\nAriko Umukiza agiye kutujyana,\nAho tuzashir’ agahinda."}]},
  {"number": 225, "name": "Narebye Yesu", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/225", "key": "mi bémol", "references": [{"codes": "S. 863"}, {"title": "I LOOKED TO JESUS"}, {"codes": "HL. 66"}], "body": [{"type": "verse", "number": 1, "content": "Narebye Yes’ igihe nari ndembejwe n’ ibyaha,\nNari nabuz’ uko ngira, Maz’ arampumuriza."}, {"type": "chorus", "content": "S.: Ye, ni koko, Nareby’ Umwami Yesu;\nArambona, Nzabana na w’ iteka.\nA., T. na B.: Ye n’ iby’ ukuri koko,\nNanjye nareby’ Umwami Yesu,\nMaz’ arambona, Nanjye rwose,\nNzabana na w’iteka."}, {"type": "verse", "number": 2, "content": "Nabony’ Umwami Yes’ ambambiwe ku musaraba,\nNizera yukw’ ibyaha byanjye bibambanywe na we."}, {"type": "verse", "number": 3, "content": "Nabony’ Umwami Yesu, Azukany’ icyubahiro,\nNiringir’ imbabazi ze, N’ ibyahanuwe kera."}, {"type": "verse", "number": 4, "content": "Yandebany’ impuhwe, Umutima wanjy’ uranyurwa,\nMaz’ anyiher’ ikimenyetso cy’ Umwuka We Wera."}, {"type": "verse", "number": 5, "content": "Tuzabana n’ Umwami Yesu Krist’ ibihe byose,\nMutezeho byose, Mbe nk’ umwana wiringira se."}]},
  {"number": 226, "name": "Ntugire Icy’ Utinya", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/226", "key": "do", "references": [{"codes": "HL. 522"}, {"title": "NE CRAINS RIEN, JE T’AIME"}], "body": [{"type": "verse", "number": 1, "content": "Ntugire icyo utinya, Ndi kumwe nawe, Ni isezerano ryo kwizera kwanjye.\nUmwijima ntuzigera unter’ ubwoba, Ndahumurijwe, Ngendana n’ Umukiza wanjye."}, {"type": "chorus", "content": "Ntabwo nzigunga, Sinzigera nigunga,\nYesu arandinda, Ntabwo ajy’ ansiga jyenyine.\nNtabwo nzigunga, Sinzigera nigunga,\nYesu arandinda, Ntabwo ajy’ ansiga jyenyine."}, {"type": "verse", "number": 2, "content": "Umusek’ umurik’ iyo hakeye neza, Yes’ umucyo wanjy’ amurikir’ iteka,\nIyo ncitse intege, Yes’ arandamira, Mucyo weyur’ ibicu, Azangeza mw’ ijuru."}, {"type": "verse", "number": 3, "content": "Iyo ibyago bituruts’ impande zose, Iyo nugarijwe Yes’ amba bugufi,\nAmbwira ati: Komera, Humura “Nijye”, Ntutinye komera ndi kumwe nawe iteka."}]},
  {"number": 227, "name": "Mbeg’ Inteko!", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/227", "key": "do", "references": [{"codes": "S. 159"}, {"title": "WHAT A GATHERING!"}], "body": [{"type": "verse", "number": 1, "content": "Umwana w’ umunt’ azaz’ igitondo gitangaje, Nibwo twese tuzabon’ ikuzo rye.\nAzakur’ abantu be mu moko yose yo mw’ isi, Iyo nteko nini iratangaje!"}, {"type": "chorus", "content": "S. na A.: Mbeg’ inteko nini nziza!\nInteko nini y’ abacunguwe na Yesu ubwe!\nMbeg’ inteko nini y’ abantu!\nBazahora banezerew’ iteka!\nT. na B.: Mbeg’ inteko, mbeg’ inteko! Nini nziza, nini nziza!\nInteko nini y’ abacunguwe na Yesu ubwe!\nMbeg’ inteko, mbeg’ inteko! nini y’ abantu!\nBazahora banezerew’ iteka!"}, {"type": "verse", "number": 2, "content": "Abasinziriye muri Yesu bazakanguka, N’ ubwo bab’ ikuzimu no mu nyanja,\nBahabw’ imibiri imeze nk’ iy’ abo mw’ ijuru, Iyo nteko nini izatangaza!"}, {"type": "verse", "number": 3, "content": "Tuzabon’ umudugud’ urimw’ amazu yera de, N’ uruzi rwa ya mazi y’ ubugingo.\nAbazaba baratandukanye bazabonana, Izab’ ar’ inteko nin’ itangaje!"}, {"type": "verse", "number": 4, "content": "N’ ukuri Yes’ agiye kugaruka bidatinze, Uwo muns’ uzab’ umuns’ uhiriwe,\nTwese tuzahindurwa mu kanya nk’ ako guhumbya! Iyo nteko nin’ izab’ itangaje!"}]},
  {"number": 228, "name": "Umutima Wanjye Wari Wihebye", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/228", "key": "mi bémol", "references": [{"codes": "SP. 100"}, {"title": "HE BROUGHT ME OUT"}], "body": [{"type": "verse", "number": 1, "content": "Umutima wanjye wari wihebye, Ibyaha byanjye byantaye mu rwobo,\nNtakambir’ Uhoraho ndi mw’ isayo, Maz’ araz’ ankuramo, None ndiho."}, {"type": "chorus", "content": "Yankuyemo yaransayuye,\nMaz’ ampagarika ku Rutare,\nKand’ anyigisha kuririmba,\nNdamwogeza, Haleluya."}, {"type": "verse", "number": 2, "content": "Yanyigije hafi ye ku Rutare, Nimpaguma ntabwo nzongera kugwa,\nByatumy’ intambwe zanjye zishikama, Nzahaguma nzahambikirw’ ikamba."}, {"type": "verse", "number": 3, "content": "Ni we wanyigishij’ indirimbo nshya, Nyiririmba ku manywa na nijoro,\nUbu nibereye mu mudendezo, Nzakomeza nsingiz’ Uwankijije."}, {"type": "verse", "number": 4, "content": "Nzaririmb’ ibitangaza bya Yesu, Nzamusingiza bose babimenye,\nNzajya ndirimb’ agakiza k’ iteka, Kugez’ ubwo bose bameny’ Imana."}]},
  {"number": 229, "name": "Ibihe By’ Imibabaro", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/229", "key": "fa", "references": [{"codes": "SDAH. 476"}, {"title": "BURDENS ARE LIFTED AT CALVARY"}, {"codes": "GH. 6"}, {"title": "(Days are Filled with Sorrow)"}], "body": [{"type": "verse", "number": 1, "content": "Ibihe by’ imibabaro bitey’ agahinda,\nByose nabituy’ i Kalvari, Yes’ ari bugufi."}, {"type": "chorus", "content": "Byose nabituy’ i Kalvari,\nKalvari, Kalvari,\nByose nabituy’ i Kalvari ,\nYes’ ari bugufi."}, {"type": "verse", "number": 2, "content": "Muture Yes’ amaganya yanyu uyu munsi,\nByose nabituy’ i Kalvari, Yes’ ari bugufi."}, {"type": "verse", "number": 3, "content": "Mutim’ ubabaye cyane, Humura witinya,\nByose nabituy’ i Kalvari, Yes’ ari bugufi."}]},
  {"number": 230, "name": "Wibuk’ Imigisha Wahawe", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/230", "key": "mi bémol", "references": [{"codes": "CS. 524"}, {"title": "COUNT YOUR BLESSINGS"}, {"codes": "S. 745"}], "body": [{"type": "verse", "number": 1, "content": "N’ ubwo waterway n’ amakuba menshi, Maz’ akagutera kwiheba cyane,\nIbuk’ imigisha yose wahawe, Ibyo yakoze biragutangaza."}, {"type": "chorus", "content": "S. na A. : Wibuk’ imigisha wahawe, Wibuk’ imigisha y’ Imana,\nImigisha Iman’ iguha, Ibyo yakoze biragutangaza.\nT. na B. : Wibuk’ imigisha, …gisha wahawe,\nWibuk’ imigisha, …gisha y’ Imana,\nImigisha yose Iman’ iguha,\nIbyo yakoze biragutangaza."}, {"type": "verse", "number": 2, "content": "Uhor’ uremerewe n’ amaganya, Umusarab’ urakuremereye,\nIbuk’ imigisha yose wahawe, Uhor’ ubiririmb’ uko bukeye."}, {"type": "verse", "number": 3, "content": "Nubon’ abandi bafit’ ubutunzi, Wibuk’ ubwo Yesu yasezeranye,\nWibuk’ imigisha yos’ utagura, Ingororano yaw’ iri mw’ ijuru."}, {"type": "verse", "number": 4, "content": "N’ ubwo wab’ utewe n’ impagarara, Ntizizaguhagarik’ umutima,\nWibuke k’ ufit’ abamarayika, Bazakurinda baguhumurize."}]},
  {"number": 231, "name": "Mana Data, Ushobora Byose", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/231", "key": "mi bémol", "references": [{"codes": "CH. 504"}, {"title": "GOD OF OUR FATHERS WHOSE ALMIGHTY HAND"}], "body": [{"type": "verse", "number": 1, "content": "Mana Data, Ushobora byose, Duhe Mwami, Kurabagirana,\nTukuririmbire tugushima, Kukw’ ari w‘ ushobora byose."}, {"type": "verse", "number": 2, "content": "Watuyoboy‘ ibihe byashize, Tuyobore no mur‘ iki gihe,\nDukingire imyambi y‘ umwanzi, Tuyoboreshe ijambo ryawe."}, {"type": "verse", "number": 3, "content": "Intambara ziraduc‘ intege, Tuber‘ ingabo idukingira,\nDuhe kwizer‘ imbaraga yawe, Dukeney‘ ubuntu bwawe Mwami."}, {"type": "verse", "number": 4, "content": "Duhembure mur‘ urugendo, Tuyobore amanywa n‘ ijoro,\nDuhe kuguma bugufi bwawe, Guhimbazwa n‘ ibyawe iteka."}]},
  {"number": 232, "name": "Urukundo Rw’ Umukiza", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/232", "key": "ré bémol", "body": [{"type": "verse", "number": 1, "content": "Ubu mpagaz’ imbere ya Yesu w’ i Nazareti,\nNtangazwa n’ ukw’ ankunda, Kandi nandujwe n’ ibyaha!"}, {"type": "chorus", "content": "Urukundo rw’ Umukiza\nNzahora nduririmba,\nUrukundo Yes’ ankunda,\nRuhebuj’ ibintu byose."}, {"type": "verse", "number": 2, "content": "Ari mu gashyamb’ asenga, Ni jye yagiriraga,\nBya byuya by’ amaraso, Yabibize kukw’ ankunda."}, {"type": "verse", "number": 3, "content": "Maz’ abamarayika baza kumuhumuriza,\nKuko yar’ ababajwe n’ imibabaro y’ abantu."}, {"type": "verse", "number": 4, "content": "Tuzamureb’ iteka, Abazaba bacunguwe,\nDuhore turirimba Urukundo yadukunze."}]},
  {"number": 233, "name": "Amarembo Niyugururwa", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/233", "key": "sol", "references": [{"codes": "S. 970"}, {"title": "WHEN THE BEAUTIFUL GATES UNFOLD"}], "body": [{"type": "verse", "number": 1, "content": "Ntituzongera kuba mu mwijima, Amarembo niyugururwa.\nAhubwo tuzaba muri rwa rurembo, Rumurikirwa n’ Imana."}, {"type": "chorus", "content": "S. na A. : Amarembo niyugururwa, Amarembo niyugururwa.\nMbeg’ umunezero tuzahagirira, Amarembo yuguruwe!\nT. na B. : Amarembo niyu...ru... ...gururwa,\nAmarembo Niyu... ru... gururwa,\nMbeg’ umunezero tuzahagirira, Amarembo yuguruwe!"}, {"type": "verse", "number": 2, "content": "Inshuti zizandindira ku cyambu, Amarembo niyugururwa.\nNzajya kwiber’ ahatazarangw’ icyaha, Amarembo yuguruwe."}, {"type": "verse", "number": 3, "content": "Nta ndwara no kuribwa bizabayo, Amarembo niyugururwa.\nTuziganirira n’ abakunzi bacu, Amarembo yuguruwe."}, {"type": "verse", "number": 4, "content": "Nzagir’ umunezer’ utarondorwa, Amarembo niyugururwa.\nNzahora nirebera Yesu mu maso, Amarembo yuguruwe."}, {"type": "verse", "number": 5, "content": "Tuzagendera mu mucyo w’ Imana, Amarembo niyugururwa.\nTuzaba turirimban’ umunezero, Amarembo yuguruwe."}, {"type": "verse", "number": 6, "content": "Ntabwo nzongera kuvunwa n’ ishavu, Amarembo niyugururwa.\nNzabana n’ Umwami Yes’ iteka ryose, Amarembo yuguruwe."}]},
  {"number": 234, "name": "Nind’ Uzagera Mu Rurembo?", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/234", "key": "fa", "references": [{"codes": "CH. 568"}, {"title": "SHALL YOU? SHALL I?"}, {"codes": "CS. 5"}, {"title": "(Someone Will Enter the Pearly Gate)"}, {"codes": "SP. 79"}], "body": [{"type": "verse", "number": 1, "content": "Nind’ uzagera mu rurembo, Ruhorahw’ ibihe byose,\nAkabon’ ibyiza bihari, Mbese ni jye, Cyangwa wowe?\nAkahabon’ inzira zose zisizemw’ izahabu nziza,\nAgahora mu munezero, Mbese ni jye, Cyangwa wowe?"}, {"type": "verse", "number": 2, "content": "Nind’ uzatur’ umusaraba, Ngw’ aruhuk’ iteka ryose,\nUmwizer’ azahabw’ ikamba, Mbese ni jye, Cyangwa wowe?\nAzareb’ Umwami mu maso, Akiz’ imibabaro yose,\nAbane na w’ iteka ryose, Mbese ni jye, Cyangwa wowe?"}, {"type": "verse", "number": 3, "content": "Kandi har’ uzakingiranwa, Ubutazakingurirwa,\nAzabwirwa ngo ntabwo nkuzi, Mbese ni jye, Cyangwa wowe?\nAzahamagarir’ ubusa, Urugi ruzaba rwakinzwe,\nBazagororerw’ asigare, Mbese ni jye cyangwa wowe?"}, {"type": "verse", "number": 4, "content": "Harih’ uzishimir’ intsinzi, Anesheje, Anesheje,\nAri hamwe n’ abacunguwe, Mbese ni jye, Cyangwa wowe?\nHar’ uzaramukanya n’ abe, Batandukanijwe n’ ibyago,\nBe kongera gutandukana, Mbese ni jye, Cyangwa wowe?"}]},
  {"number": 235, "name": "Ngufitiy’ Ubutumwa", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/235", "key": "sol", "references": [{"codes": "S. 411"}, {"title": "LOOK AND LIVE"}], "body": [{"type": "verse", "number": 1, "content": "Ngufitiy’ ubutumwa, Haleluya, N’ ubutumwa bw’ Umukiza,\nBwanditse mw‘ Ijambo rye, Haleluya, Muhugukire urakizwa."}, {"type": "chorus", "content": "Tyo reba ( tyo reba),maz’ ukire ( maz’ ukire ),\nReba Yes’ Urakizwa.\nByanditswe mw’ Ijambo rye, Haleluya,\nMuhugukire urakizwa."}, {"type": "verse", "number": 2, "content": "Ngufitiy’ ubutumwa bw’ urukundo, Mwene Data, Haleluya,\nButurutse mw’ ijuru, Haleluya, Bwatanzwe n’ Umukiza Yesu."}, {"type": "verse", "number": 3, "content": "Weguriw’ ubugingo, Haleluya, Buhorahw’ iteka ryose,\nN’ uhanga Yes’ amaso, Haleluya, Ni we wenyine ugukiza."}]},
  {"number": 236, "name": "Ndi Mu Murima Njyenyine", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/236", "key": "la bémol", "references": [{"codes": "SDAH. 487"}, {"title": "IN THE GARDEN"}, {"codes": "HL. 593"}], "body": [{"type": "verse", "number": 1, "content": "Ndi mu murima njyenyine, Ikime gitonze ku byatsi,\nNumv’ ijwi rivuga riti: Umwana w’ Iman’ aratungutse."}, {"type": "chorus", "content": "Turakomeza turagendana,\nMaz’ ambwira ko yantoye,\nMbeg’ ibyishimo twari dufite,\nBitigeze bibaho!"}, {"type": "verse", "number": 2, "content": "Aravuga maz’ ijwi rye, ryiza ryikirizwa n’ inyoni,\nIndirimbo nziza namwumvanye, Ntabw’ izamva ku mutima."}, {"type": "verse", "number": 3, "content": "Tugumana mu murima, Kuk’ ubwire bwari bukubye,\nMaze anyoherez’ ankangara, Arikw’ ar’ ukumpwitura."}]},
  {"number": 237, "name": "Ntabwo Ndamenya", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/237", "key": "ré", "references": [{"codes": "SDAH. 511"}, {"title": "I KNOW WHOM I HAVE BELIEVED"}, {"codes": "CS. 290"}, {"title": "(I Know Not Why God’s Wondrous Grace)"}, {"codes": "SY. 44"}, {"codes": "HL. 95"}], "body": [{"type": "verse", "number": 1, "content": "Ntabwo ndamenya nez’ icyatumye Iman’ ingirir’ ubuntu,\nBigatum’ ingir’ uwo mu muryango w’ abana bayikunda!"}, {"type": "chorus", "content": "Kuko nzi nez’ uwo nizeye,\nKand’ ari we ushobora byose,\nNi we undindir’ ubugingo,\nKugeza urya munsi."}, {"type": "verse", "number": 2, "content": "Ntabwo nzi nez’ uburyo yampaye, Uko kwizera gukiza,\nN’ ubury’ Ijambo rye ryampaye amahoro yo mu mutima!"}, {"type": "verse", "number": 3, "content": "Sinzi ubury’ Umwuka yihanisha abanyabyaha nkanjye,\nKumenyesh’ abandi ibya Yesu, Bidutera kumwizera."}, {"type": "verse", "number": 4, "content": "Ntabwo nz’ icyo nateganirijwe, Ar’ icyiza cyangw’ ikibi,\nImibabaro n’ iminsi myiza, Byose bir’ imbere yawe."}, {"type": "verse", "number": 5, "content": "Sinzi igih’ Umwam’ azazira, Ndetse n’ ahw’ azaturuka,\nNiba mbana na Yesu mur’ iki gihe, Nzamusanganira."}]},
  {"number": 238, "name": "Nguhay’ Umwanya", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/238", "key": "fa", "references": [{"codes": "S. 35"}, {"title": "ROOM FOR THEE"}], "body": [{"type": "verse", "number": 1, "content": "Wavuye mw’ ijuru usig’ ubwami bwawe, Uza mur’ iyi si ku bwanjye,\nI Betelehemu, Ntiwabonay’ icumbi, Kand’ ur’ Umwami w’ abami."}, {"type": "chorus", "content": "Nguhay’ umwanya mu mutima,\nUwiberemw’ ibihe byose,\nNdawukweguriye Mwami wanjye,\nUwiberemw’ ibihe byose."}, {"type": "verse", "number": 2, "content": "Abamarayika bakuririmbiraga, Bogez’ icyubahiro cyawe,\nMaz’ ugeze mw’ isi uvuk’ ur’ umukene, Wicisha bugufi cyane."}, {"type": "verse", "number": 3, "content": "Ingunzu zitahiraga mu myobo yazo, Inyoni zirara mu byari,\nAriko woweho wararaga butunda, Mw’ ishyamba ry’ i Galilaya."}, {"type": "verse", "number": 4, "content": "Wazaniy’ abantu Ijambo rihoraho, Ngo rizabah’ umudendezo,\nMaze barakwanga bakujyan’ i Kalvari, Bakwambikiray’ amahwa."}, {"type": "verse", "number": 5, "content": "Ubw’ uzagaruka mw’ ikobe ry’ indirimbo, Uje mu cyubahiro cyawe,\nNdifuza cyane yuko wazampamagara, Ut’ icar’ iburyo bwanjye."}]},
  {"number": 239, "name": "Mucunguzi Wanjye", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/239", "key": "mi bémol", "references": [{"codes": "HL. 341"}, {"title": "O MON SAUVEUR!"}], "body": [{"type": "verse", "number": 1, "content": "Mukiza wanjye nshaka kub’ uwawe, Ngwin’ uture mu mutima wanjy’ iteka.\nUwukuremo ibigirwamana, Uwubonez’ ushiremo inenge."}, {"type": "chorus", "content": "Nyejesh’ amaraso yawe,\nNere rwose kurush’ urubura."}, {"type": "verse", "number": 2, "content": "Mwami Yesu ntiwemere na gato, Yukw’ icyaha cyabon’ akanya na gato;\nKo kunyuramo cyiza mu mutima, Ntama w’ Imana, nyejesh’ amaraso."}, {"type": "verse", "number": 3, "content": "Data nubwo ntagira kivurira, Unyitaho ugatuma Mwuka Wera;\nAkanyobora agatuma ntsinda, Maz’ umutima wanjye ukabonera."}, {"type": "verse", "number": 4, "content": "Mwami dore ntegereje nizeye, Ndeger’ umusaraba wambambiweho.\nNgo mpumurizwe, mbyarw’ ubwa kabiri, Nzishimir’ iteka kwiber’ iwawe."}, {"type": "verse", "number": 5, "content": "Haleluya! Kwizera kunsubiza ishusho iboneye waturemanye.\nShimirw’ imirimo yaw’ itangaje, Warandemye, untaka icyubahiro."}, {"type": "chorus", "content": "Amaraso yawe Mwami,\nNiy’ abonez’ umutima wanjye."}]},
  {"number": 240, "name": "Uko Ndushaho Kumukorera", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/240", "key": "la bémol", "references": [{"codes": "GH. 17"}, {"title": "THE LONGER I SERVE HIM"}, {"codes": "AYS. 182"}], "body": [{"type": "verse", "number": 1, "content": "Aho menyey’ Umukiza, Nkanagengwa na we,\nUko ndushaho kumukorera, Nikw’ arushaho kunyuzuramo."}, {"type": "chorus", "content": "Uko njya ndushaho kumukorera,\nNa we, nikw’ arushaho kunyuzura,\nKandi uko ndushaho kumukunda,\nNa we nikw’ arushaho kunyuzuramo."}, {"type": "verse", "number": 2, "content": "Angirir’ ubuntu bwinshi, Nkamererwa neza,\nUko ndushaho kumuyoboka, Nikw’ arushaho kunyuzuramo."}]},
  {"number": 241, "name": "Nabonye Kuza Kwa Yesu", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/241", "key": "do", "references": [{"codes": "SDAH. 647"}, {"title": "MINE EYES HAVE SEEN THE GLORY"}], "body": [{"type": "verse", "number": 1, "content": "Nabonye kuza kwa Yesu afit’ icyubahiro,\nAmaze gusenya rwos’ ububiko bw’ umujinya,\nYadukijije n’ ubugi bw’ inkot’ ityaye cyane,\nNi w’ utuyobora."}, {"type": "chorus", "content": "Nasingizwe, Haleluya, Nasingizwe, Haleluya,\nNasingizwe, Haleluya, Ni w’ utuyobora."}, {"type": "verse", "number": 2, "content": "Namubonye no mu mazu y’ abantu benshi cyane,\nBamwubakiramw’ ibicaniro nimugoroba,\nNongera kumubon’ ac’ imanza zitarenganya,\nNi w’ utuyobora."}, {"type": "verse", "number": 3, "content": "Akomeje guhamagaz’ abant’ ijwi ry’ impanda,\nArateguriz’ abantu bose gucirw’ imanza.\nMutima wanjye mwitabe vuba unezerewe,\nNi w’ utuyobora."}]},
  {"number": 242, "name": "Mbeg’ Umunsi Mwiza!", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/242", "key": "la bémol", "references": [{"codes": "HL. 504"}, {"title": "OH! QUEL BEAU JOUR"}], "body": [{"type": "verse", "number": 1, "content": "Yemw’ umuns’ abacunguwe, Bazahagarar’ imbere y’ Imana!\nBaririmb’ indirimbo z’ urwunge, Kubw’ ikuzo n’ ubuntu bwayo."}, {"type": "chorus", "content": "Inteko zingana n’ umusenyi,\nZingana n’ umusenyi mwinshi,\nAbacunguwe bazangana n’ umusenyi,\nUmusenyi bangana n’ umusenyi."}, {"type": "verse", "number": 2, "content": "Ndareb’ ingabo zitabarika, Zerekan’ umucyo w’ ijuru,\nZifit’ amahoro atangaje, Ku maremb’ arabagirana."}, {"type": "verse", "number": 3, "content": "Numv’ ijwi ryiza ry’ Umucunguzi, Riva ku ntebe ye y’ ubwami,\nNimuz’ abahiriwe na Data. Mwambikw’ ikamba ryo kunesha."}, {"type": "verse", "number": 4, "content": "Abera bazaririmba n’ abamarayika batabarika,\nIsi izahind’ umushyitsi, Kand’ ibyago bizaba bishize."}]},
  {"number": 243, "name": "Nimutyo Turirimban’ Umunezero", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/243", "key": "fa", "references": [{"codes": "SDAH. 626"}, {"title": "IN A LITTLE WHILE WE’RE GOING HOME"}, {"codes": "SY. 146"}, {"title": "(Let us Sing a Song)"}, {"codes": "S. 832"}], "body": [{"type": "verse", "number": 1, "content": "Nimutyo turirimban’ umunezero, Twegereje kuger’ iwacu,\nAho ni ho tuzaban’ iteka ryose, Ubu tugiye kugerayo."}, {"type": "chorus", "content": "S. na T. : Mu gihe gito, Mu gihe gito, Tuzaba tugezeyo,\nTugiye kuban’ ubudatandukana,\nUbu tugiye kugerayo.\nA. na B. : Mu gihe gito, Mu gihe gito, Tuzaba tugezeyo,\nTugiye kuban’ ubudatandukana,\nUbu tugiye kugerayo."}, {"type": "verse", "number": 2, "content": "Mutyo dushishikare dukore neza, Twegereje kuger’ iwacu,\nKand’ Imana yiteguye kutwakira. Ubu tugiye kugerayo."}, {"type": "verse", "number": 3, "content": "Dukomez’ urugendo twe gucogora, Twegereje kuger’ iwacu,\nNimutyo twamamaz’ iyo nkuru nziza, Ubu tugiye kugerayo."}, {"type": "verse", "number": 4, "content": "Mbeg’ umunezero tuzagirirayo! Twegereje kuger’ iwacu,\nNtituzongera kubogoz’ amarira, Ubu tugiye kugerayo."}]},
  {"number": 244, "name": "Muze Dusingiz’ Umwami", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/244", "key": "sol", "references": [{"codes": "AH. 14"}, {"title": "COME, BLESS THE LORD YE PEOPLE"}], "body": [{"type": "verse", "number": 1, "content": "Muze dusingiz’ Umwami, Abera muz’ imbere ye,\nAbahora mumuramya, Mwamamaz’ ububasha bwe."}, {"type": "verse", "number": 2, "content": "Mumusingiriz’ ahera, Muririmbe mwisanzuye,\nNimumuramye mwunamye, Mumwubahe kukw’ abumva."}, {"type": "verse", "number": 3, "content": "Murahoran’ ubuntu bwe butemba buv’ i Siyoni,\nN’ Umuremyi, N’ Uhoraho, Bose nibamusingize."}]},
  {"number": 245, "name": "Ahw’ Umukiza Anyobora", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/245", "key": "sol", "references": [{"codes": "S. 544"}, {"title": "WHERE MY SAVIOR LEADS"}], "body": [{"type": "verse", "number": 1, "content": "Ahw’ Umukiza anyobora, Nzemera mukurikire,\nNzamukurikir’ iteka, Sinzakorwa n’ isoni."}, {"type": "chorus", "content": "Ahw’ Umukiza anyobora,\nNzemera mukurikire,\nAhw’ azanyobora hose,\nNzajya mukurikira."}, {"type": "verse", "number": 2, "content": "N’ ubwo haba mu mwijima, Nkagenda nyobagurika,\nNzumv’ ijwi ry’ uwo Mukiza rinsubizemw’ intege."}, {"type": "verse", "number": 3, "content": "N’ ubw’ isi yambushabusha, Nkabur’ epfo na ruguru,\nMukiza uzandamira, Ntabwo nzarambarara."}, {"type": "verse", "number": 4, "content": "Ibi byago nibishira, Azanyijyanir’ iwacu,\nNtihabay’ umubabaro, Nzaba ntanye n’ ibyaha."}]},
  {"number": 246, "name": "Twumvire Mwami", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/246", "key": "ré", "references": [{"codes": "SDAH. 684"}, {"codes": "AH. 48"}, {"title": "HEAR OUR PRAYER O LORD"}, {"codes": "CH. 688"}], "body": [{"type": "verse", "number": 1, "content": "Twumvire Mwami, Turakuramya,\nUduteg’ amatwi, Duh’ amahoro. Amen."}]},
  {"number": 247, "name": "Nzinutsw’ Ibyo Mw’ Isi", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/247", "key": "mi bémol", "references": [{"codes": "AH. 233"}, {"title": "FADE, FADE EACH EARTHLY JOY"}, {"codes": "CH. 277"}], "body": [{"type": "verse", "number": 1, "content": "Nzinutsw’ ibyo mw’ isi, Mpisemo Yesu!\nSinzifatanya na byo, Mpisemo Yesu!\nN’ isi y’ umwijima, Nta buruhukiro,\nYesu ni we mugisha, Mpisemo Yesu!"}, {"type": "verse", "number": 2, "content": "Wa si we, winshuka, Mpisemo Yesu!\nNzabana na w’ iteka, Namuhisemo,\nIbyo mw’ isi byose, n’ iby’ igihe gito,\nBimeneka nk’ ibumba, Mpisemo Yesu!"}, {"type": "verse", "number": 3, "content": "Iby’ isi n’ inzozi, Mpisemo Yesu!\nNi we umber’ umucyo, Mpisemo Yesu!\nNashatse kwikiza, Binsubiz’ inyuma,\nYesu ni we wanyuze, Ni we mpisemo!"}, {"type": "verse", "number": 4, "content": "Ntabwo ntiny’ urupfu, Mpisemo Yesu!\nNshaka kubahw’ iteka, Mpisemo Yesu!\nNdashaka kugera, Aho nzab’ iteka,\nNzaba mu gituza cye, Mpisemo Yesu."}]},
  {"number": 248, "name": "Mutima Wanjye Ucururuke", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/248", "key": "fa", "references": [{"codes": "S. 599"}, {"title": "O BLESSED LIFE!"}], "body": [{"type": "verse", "number": 1, "content": "Mutima wanjye ucururuke, Nugir’ ibiguter’ impagarara,\nWiringire Ishobora byose, N’ imigambi yayo myiza."}, {"type": "verse", "number": 2, "content": "Mutima wanjy’ iby’ ari byo byose, N’ ubw‘ibihe byagenda bihinduka,\nImbabazi, zayo ntizishira, Zihorahw’ ibihe byose."}, {"type": "verse", "number": 3, "content": "Mutima wanjye uremerewe, N’ ubwo wab’ utew’ ubwoba n’ urupfu,\nNi wiheba wisung’ Uwiteka, Agukingurir’ ijuru."}, {"type": "verse", "number": 4, "content": "Mutima wanjy’ uhereye kera, Ntiwigeze ubur’ umudendezo,\nIsung’ Imana izakwakira, Wemere kugengwa na yo."}, {"type": "verse", "number": 5, "content": "Ubugingo bwiza buboneye, Bushishikarira gukor’ ibyiza,\nMukiza mfasha ngo mbugereho, Ump’ umutim’ utunganye."}]},
  {"number": 249, "name": "Ikuzo Ni Iryawe!", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/249", "key": "si bémol", "references": [{"codes": "HL. 42"}, {"title": "A TOI LA GLOIRE!"}], "body": [{"type": "verse", "number": 1, "content": "Ikuzo n’ iryawe Data wa Twese, Nari nahabiye kure yawe,\nWangejeje mu mucyo w’ itangaza, Umvana mu bubata ndakira."}, {"type": "chorus", "content": "Mbeg’ urukundo ruhebuje!\nNababariwe, N’ inkuru nziza kuri twe."}, {"type": "verse", "number": 2, "content": "Mbeg’ urukundo rutarondoreka! Rwatumye Yesu aza kunshaka.\nNar’ umuhanya sinari nkwiriye, Gukira ngukesha Yesu gusa."}, {"type": "verse", "number": 3, "content": "Akir’ uyu mutima wanjye Mwami, Nkweguriy’ imibereho yanjye,\nWowe wanyitangiye ukankiza, Wanyejeshej’ amaraso yawe."}, {"type": "verse", "number": 4, "content": "Mana yanjye nkingira ndakwinginze, Sinashobora kwirwanirira,\nKugira ngo nzanezererw’ iteka, Twishimye, Dusingiza Umwami."}]},
  {"number": 250, "name": "Umukiza Ni W’ Unyobora", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/250", "key": "si bémol", "references": [{"codes": "SDAH. 551"}, {"codes": "CH. 398"}, {"title": "JESUS, SAVIOR, PILOT ME"}], "body": [{"type": "verse", "number": 1, "content": "Umukiza ni w’ unyobor’ iyo ndi mu bishuko,\nN’ iy’ amakub’ angose, Amber’ ubuhungiro,\nNi w’ unkingir’ ibishuko, Yesu nyiyoborera."}, {"type": "verse", "number": 2, "content": "Uhosh’ umuraba nk’ umubyey’ uhoz’ umwana we,\nNdets’ uranawutegek’ ubwaw’ ukakumvira,\nMwami wanjye Yesu nkunda, Ujy’ Unyiyoborera."}, {"type": "verse", "number": 3, "content": "Iyo negerey’ inkengero ngashy’ ubwoba,\nNkakwihishamo, Ndaruhuka; Nkumv’ umpumuriz’ uti:\nWitinya ntacy’ uteze kuba, Nzajya nkuyobora."}]},
  {"number": 251, "name": "Yesu Araduhamagara!", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/251", "key": "la bémol", "references": [{"codes": "SDAH. 285"}, {"codes": "SP. 76"}, {"title": "JESUS CALLS US!"}], "body": [{"type": "verse", "number": 1, "content": "Yes’ araduhamagara, Ashaka kudukiza,\nAtubwiz’ ijwi rye ati: Mukristo nkurikira."}, {"type": "verse", "number": 2, "content": "Yes’ araduhamagara, Ngo tuve mu by’ iyi si,\nAraduhamagar’ ati: Mukristo nkunda cyane."}, {"type": "verse", "number": 3, "content": "Iyo tumerewe neza, Cyangwa se tubabaye,\nAraduhamagar’ ati: Mukristo nkunda rwose."}, {"type": "verse", "number": 4, "content": "Yes’ araduhamagara, Mwami turakwitabye,\nDuhe kukumvira, Tugukunde kuruta byose."}]},
  {"number": 252, "name": "Nimucane Amatabaza", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/252", "key": "mi bémol", "references": [{"codes": "SDAH. 595"}, {"title": "LET EVERY LAMP BE BURNING"}, {"codes": "CH. 183"}], "body": [{"type": "verse", "number": 1, "content": "Nimucan’ amatabaza, Umwijim’ ubay’ icyago,\nHazab’ umwijim’ ukaze, Umwam’ ataragaruka."}, {"type": "chorus", "content": "Mubonez’ amatabaza,\nKandi nimwubah’ Imana,\nKuza kw’ Umwami kuri hafi,\nMubonez’ amatabaza."}, {"type": "verse", "number": 2, "content": "Abant’ ibihumbi byinshi, Bahinyur’ ubu butumwa,\nNatwe tubushikamyemo, Dutegerez’ Umukiza."}, {"type": "verse", "number": 3, "content": "Ijambo rye n’ itabaza, Ntituzigera tuyoba,\nN’ ubw’ amakub’ ari hose, Ntabw’ Iman’ izaduhana."}, {"type": "verse", "number": 4, "content": "Dukor’ imirimo myiza, Twe guh’ ab’ iy’ is’ urwaho,\nTuzabiherw’ imigisha, Nidukomeza kwizera."}]},
  {"number": 253, "name": "Ujy’ Uvug’ Ibya Yesu", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/253", "key": "ré", "references": [{"codes": "CH. 522"}, {"title": "NOW JUST A WORD FOR JESUS"}], "body": [{"type": "verse", "number": 1, "content": "Ujy’ uvug’ ibya Yesu, Inshuti y’ ukuri,\nNgwin’ uduhumurish’ ibyo yagukoreye."}, {"type": "chorus", "content": "Vuga Yesu gusa, Bizakuyobor’ iteka,\nJy’ ubivug’ uririmba, Kandi unasenga."}, {"type": "verse", "number": 2, "content": "Ujy’ uvug’ ibya Yes’ uzumv’ ubabariwe,\nNo kubw’ ubuntu bwe tuzagera mw’ ijuru."}, {"type": "verse", "number": 3, "content": "Sinabura kuvug’ iby’ umusaraba we,\nNkund’ uwo Mukiza, Kuko yanyitangiye."}, {"type": "verse", "number": 4, "content": "Uvug’ ibya Yesu, Ntupfush’ igih’ ubusa,\nKutita ku nshingano, Bitesh’ agaciro."}, {"type": "verse", "number": 5, "content": "Ujy’ uvug’ ibya Yesu, N’ ubwo wacogora,\nVa mu ntege nke zawe, Umwiyegurire."}]},
  {"number": 254, "name": "Ushimirw’ Ibyiza Byose", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/254", "key": "fa", "references": [{"codes": "SDAH. 423"}, {"codes": "AH. 434"}, {"title": "GLORIOUS THINGS OF THEE ARE SPOKEN"}], "body": [{"type": "verse", "number": 1, "content": "Ushimirwe ibyiza byose, Siyoni murwa w’ Imana,\nItavuguruzwa yakugiz’ ubuturo bwayo bwite,\nWubatswe ku Rutare rw’ iteka, N’ iki cyaguhangara?\nUgoteshejw’ inkike z’ agakiza, Reka gutiny’ abanzi bawe."}, {"type": "verse", "number": 2, "content": "Dore amazi y’ ubugingo, Atemb’ ava mu rukundo,\nNi y’ abeshahw’ abana bawe, Imibabar’ igashira.\nNinde se wacogora, Har’ uwo mugez’ umar’ inyota?\nUbuntu bw’ uwo Mutanga-bugingo, Ntabwo buzagir’ iherezo."}, {"type": "verse", "number": 3, "content": "Ahazenguruts’ uwo murwa, Har’ ibicu n’ umuriro,\nByerekana ko kugaruka kw’ Umwami kuri bugufi,\nHahirw’ abazatur’ i Siyoni, Bejeshejw’ amaraso,\nBiyeguriye Yes’ abahindur’ abami, N’ abatambyi b’ Imana."}, {"type": "verse", "number": 4, "content": "Ndi mu muryango w’ i Siyoni, Kubw’ ubuntu bwawe Mwami,\nN’ ubwo bampindur’ urw’ amenyo, Nzasingiz’ izina ryawe,\nIbinezeza byo mur’ iyi si, Bihita nk’ umuyaga,\nUmunezero uhoraho, Wateguriw’ abana b’ i Siyoni."}]},
  {"number": 255, "name": "Mbes’ Aho Tuzahurira Ku Cyambu?", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/255", "references": [{"codes": "S. 913"}, {"title": "SHALL WE MEET BEYOND THE RIVER?"}], "body": [{"type": "verse", "number": 1, "content": "Mbes’ aho tuzahurira ku cyambu cya rwa ruzi,\nAhahor’ umucy’ iteka, Ntihab’ umubabaro?"}, {"type": "chorus", "content": "Se koko tuzahurira hakurya y’uruzi?\nTuzabonanirayo tuhanezererw’ iteka?"}, {"type": "verse", "number": 2, "content": "Tuzahurira ku cyamb’ urugendo rurangiye?\nMbes’ aho tuzahurirayo, Maze twiruhutse?"}, {"type": "verse", "number": 3, "content": "Mbes’ aho twese tuzahurira mu mudugudu,\nWubatswe n’ Uhoraho, Urimbishijwe yasipi?"}, {"type": "verse", "number": 4, "content": "Abacunguwe bose, Bazaririmb’ indirimbo,\nKand’ ibiremwa byose bizasingiz’ Uhoraho."}, {"type": "verse", "number": 5, "content": "Mbes’ aho tuzabonana n’ abo twakundanaga,\nMaze twumv’ amajwi yabo tubareba mu maso?"}, {"type": "verse", "number": 6, "content": "Mbese tuzabonana na Krist’ Umukiza wacu,\nAje kujyan’ intore ze, Mu bwami buhoraho?"}]},
  {"number": 256, "name": "Abatuye Mw’ Isi Mwese", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/256", "key": "sol", "references": [{"codes": "AH. 5"}, {"codes": "S. 9"}, {"title": "ALL PEOPLE THAT ON EARTH"}, {"codes": "HL. 1"}], "body": [{"type": "verse", "number": 1, "content": "Abatuye mw’ isi mwese, Muririmbir’ Uhoraho,\nMumukorere mwishima, Mwogez’ icyubahiro cye."}, {"type": "verse", "number": 2, "content": "Mumenye kw’ ari we Mana, Kukw’ ari we waturemye,\nTwese tur’ umukumbi we, Turagiwe n’ Uhoraho."}, {"type": "verse", "number": 3, "content": "Muze mwese mu rugo rwe, Muze mwese mumushima,\nMuhanik’ amajwi yanyu, Kukw’ ari byo bikwiriye."}, {"type": "verse", "number": 4, "content": "Mwabaza muti: ni kuki? Nuk’ Uhoraho ari mwiza,\nN’ impuhwe ze zikaramba, Nta n’ ubwo zizashiraho."}]},
  {"number": 257, "name": "Yesu Mucunguzi Wanjye", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/257", "key": "sol", "references": [{"codes": "AH. 613"}, {"codes": "CH. 257"}, {"title": "O JESUS MY REDEEMER"}, {"codes": "HL. 380"}], "body": [{"type": "verse", "number": 1, "content": "Yesu Mucunguzi wanjye, Ni we byishimo byanjye,\nNi wowe ujy’ ungoboka, Mu bihe by’ amakuba."}, {"type": "chorus", "content": "Yesu Mucunguzi wanjye,\nNi we ndirimbo yanjye,\nNta yindi nshuti nabona,\nNagereranya na we."}, {"type": "verse", "number": 2, "content": "Wagumye kumpumuriza, Mu bihe bibi byose,\nUbwo nari nshumbirijwe, Ngoswe n’ imibabaro."}, {"type": "verse", "number": 3, "content": "Ur’ ibyiringiro byanjye, Ndayob’ ukanyobora,\nNi wowe nshuti y’ ukuri, Undutir’ abo mw’ isi."}, {"type": "verse", "number": 4, "content": "Ni wow’ undem’ umutima, Mur’ iyi si y’ ibyaha,\nNzakomeza ngusingize, Ngez’ ubwo nzaz’ iwawe."}]},
  {"number": 258, "name": "Yasezeranye Kuduh’ Imvura", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/258", "key": "la bémol", "references": [{"codes": "SDAH. 195"}, {"codes": "AH. 153"}, {"title": "SHOWERS OF BLESSING"}, {"codes": "HL. 128"}], "body": [{"type": "verse", "number": 1, "content": "Yasezeranye kuduha, Imvura y’ umugisha,\nIri sezerano ryayo, Ryaturutse mw’ ijuru."}, {"type": "chorus", "content": "Duh’ umugisha, Turifuz’ umugisha,\nUvuy’ iwawe mw’ ijuru,\nNyabuneka wuduhe."}, {"type": "verse", "number": 2, "content": "Yasezeranye kuduha, Imvura y’ umugisha,\nYitugoborer’ uyu muns’ ikwir’ impande zose."}, {"type": "verse", "number": 3, "content": "Yasezeranye kuduha, Imvura y’ umugisha,\nTurayifuz’ uy’ umunsi, Sohoz’ ibyo wavuze."}, {"type": "verse", "number": 4, "content": "Yasezeranye kuduha, Imvura y’ umugisha,\nIcyayiduh’ uyu munsi, Mana tubabarire."}]},
  {"number": 259, "name": "Inkomangiro Yawe Yafata?", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/259", "key": "fa", "references": [{"codes": "SDAH. 534"}, {"title": "WILL YOUR ENCHOR HOLD"}, {"codes": "AH. 208"}], "body": [{"type": "verse", "number": 1, "content": "Inkomangiro yawe yafata, Umuraba w’ ibyag’ uguteye?\nUkagukanagira nk’ ingoyi, Inkomangiro yaw’ izashikama?"}, {"type": "chorus", "content": "Dufit’ inkomangir’ itsika, Imiraba yiyungikanya,\nIkomangiye ku Rutare, Rushikamye, Umukiza wacu."}, {"type": "verse", "number": 2, "content": "Nib’ itsitse ntizateraganwa, Ifashwe n’ ukuboko k’ Umwami,\nImirunga ye iraduhuza, Bitewe n’ imbaraga y’ ikomeye."}, {"type": "verse", "number": 3, "content": "Izashikama mu gihe kibi, Ubw’ imivumb’ izab’ ihurura,\nUmuyaga w’ ishuher’ usheze, Ntabwo bizarenga ku bwato bwacu."}, {"type": "verse", "number": 4, "content": "Ndetse no mu gihe kibi cyane, Twifuz’ amazi yaduhembura,\nTuzatsika ku nkombe z’ ijuru, Umugar’ ushire buheriheri."}, {"type": "verse", "number": 5, "content": "Ubw’ igitondo kizatangaza, N’ amarembo arabagirana,\nTuzatsika ku nkombe z’ ijuru, Umugar’ ushire buheriheri."}]},
  {"number": 260, "name": "Nta Rindi Zina Nka Yesu", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/260", "key": "fa", "references": [{"codes": "SDAH. 253"}, {"codes": "AH. 98"}, {"title": "THERE’S NO OTHER NAME LIKE JESUS"}], "body": [{"type": "verse", "number": 1, "content": "Nta rindi zina nka Yesu, N’ izina rihebuje,\nRihimbar’ abo mw’ ijuru, N’ abakristo bo mw’ isi."}, {"type": "chorus", "content": "Zina (zina) ryiza (ryiza),\nNta rihwanye n’ irya Yesu,\nZina (zina) ryiza (ryiza),\nNta rihwanye n’ irya Yesu."}, {"type": "verse", "number": 2, "content": "Nta rindi zina nka Yesu, Rimar’ imibabaro,\nNta zina ryahwana n’ irye, Ndetse no mu mahoro."}, {"type": "verse", "number": 3, "content": "Mfit’ ibyiringiro byo kuzamubon’ agarutse,\nNizeye kw’ azanyakira, Maz’ akampumuriza."}, {"type": "verse", "number": 4, "content": "Nib’ ashaka ko mukorera mu ruzabibu rwe,\nAzampira mu byo nkora, Kand’ ahir’ ibyo mvuga."}, {"type": "verse", "number": 5, "content": "Nah’ urupfu rwanyegura, Kuko nd’ umukungugu,\nNtacyo bizaba bintwaye, Niringiy’ Umukiza."}]},
  {"number": 261, "name": "Singizwa Yesu", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/261", "key": "mi", "references": [{"codes": "HL. 81"}, {"title": "A TOI LA GLOIRE"}], "body": [{"type": "verse", "number": 1, "content": "Singizwa Yesu, Umukiza Yazutse, Yesu yaneshej’ urupfu, Iteka ryose,\nMarayik’ ufit’ umucyo, Aramanuka, Yakinguye igituro, Yesu aranesha,\nSingizwa Yesu, Umukiza Yazutse, Yesu yaneshej’ urupfu, Iteka ryose."}, {"type": "verse", "number": 2, "content": "Itegereze: Ni Yesu Umukiza, Umucunguzi w’ abantu, Ntushidikanye,\nIshime kand’ uririmbe! Yesu ariho! Ongera ubyamamaze, Yesu ni muzima.\nItegereze: Ni Yesu Umukiza, Umucunguzi w’ abantu, Ntushidikanye."}, {"type": "verse", "number": 3, "content": "Nta bwoba mfite! Yesu ni muzima pe! Nzajya musingiz’ iteka, Mahoro yanjye.\nYesu yaraneshereje ni we nizeye. Ni Yesu umbeshejeho, Sinzigera ntinya,\nNta bwoba mfite! Yesu ni muzima pe! Nzajya musingiz’ iteka, Mahoro yanjye."}]},
  {"number": 262, "name": "Nyir’ Impuhwe Nyinshi", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/262", "key": "do", "references": [{"codes": "HL. 271"}, {"title": "MISERICORDE INSONDABLE"}], "body": [{"type": "verse", "number": 1, "content": "Nyir‘ impuhwe nyinshi cyane, Iman‘ ibabarira,\nKwibagirw‘ ibyaha ikababarir‘ uwagomye."}, {"type": "chorus", "content": "S. na A.: Ndaje Yesu, Ndakwitabye,\nUko ndi kos‘ unyemere,\nNdaje Yesu ndakwitabye, Mukiz‘ unyakire.\nT. na B.: Ndaje Yesu, Ndakwitabye,\nUko ndi ko… unyemere,\nNdaje Yesu, Ndakwitabye, Mukiz‘ unyakire."}, {"type": "verse", "number": 2, "content": "Nari kure y‘ uwo nkunda, Mbabaj‘ umutima we,\nKuko namwimag’ ahw‘ aba, N‘ uwanjye yampfiriye."}, {"type": "verse", "number": 3, "content": "Yesu ndakwiyeguriye, Ndashaka kubaturwa,\nIcyaha cyose cyambase, Maze ngikire rwose."}, {"type": "verse", "number": 4, "content": "Haleluya yanduhuye, Ubu sinshidikanya,\nNderekez‘ iyo mw‘ ijuru, Nejejwe no kubayo."}]},
  {"number": 263, "name": "Bazany’ Amaturo Yabo", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/263", "key": "fa", "references": [{"codes": "AH. 346"}, {"title": "THEY BROUGHT THEIR GIFTS TO JESUS"}, {"codes": "CS. 189"}], "body": [{"type": "verse", "number": 1, "content": "Bazany’ amaturo yabo, Kuyatur’ Umwami Yesu,\nKuko bari bamukunze, Maze barayamutura.\nIyo neza n’ urukundo, Byafashij’ umukene,\nN’ amaturo yose batuye, Yar’ ay’ agaciro."}, {"type": "chorus", "content": "Muture Yes’ amaturo, Biramunezeza rwose,\nMuhay’ umutima wanjye, Ndamwiyeguriye."}, {"type": "verse", "number": 2, "content": "Umukene yar’ ahagaze, Kure y’ abaturaga,\nMaz’ abony’ uburyo batura, Agir’ umunezero.\nYuzurwa n’ ibyishimo, By’ ayo maturo batuye,\nWe, yar’ afit’ ituro rito, Imbere y’ Umwami."}, {"type": "verse", "number": 3, "content": "Abwiran’ Umwam’ agahinda, Ati: Nz’ ineza yawe,\nAkir’ iri turo ngutuye, Ni ryo mutima wanjye,\nYes’ asubiza yitonze, Ati: S’ ituro rito,\nN’ ubw’ abandi batuye menshi, Urabarengeje."}]},
  {"number": 264, "name": "Ari Hafi Kuza", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/264", "key": "ré", "references": [{"codes": "HL. 111"}, {"title": "IL VA BIENTOT VENIR"}], "body": [{"type": "verse", "number": 1, "content": "Ari hafi kuza, Nahimbazwe Yesu,\nAzakorany’ abatoni be, Bajyane mw’ ijuru;\nTurebe mw’ ijuru, Twishime araje!\nAje mu cyubahiro cye, Mucunguzi wacu."}, {"type": "verse", "number": 2, "content": "Ari hafi kuza, Nahimbazwe Yesu,\nImibabaro yacu yose, Ntizibukw’ ukundi,\nYes’ azakuraho, Urupfu burundu,\nAzaza tuban’ iteka, Mucunguzi wacu."}, {"type": "verse", "number": 3, "content": "Ari hafi kuza, Nahimbazwe Yesu,\nAzaz’ atungutse ku bicu, Ntidutinye rwose,\nTwubure amaso, Nguriya araje!\nAje kujyana njye nawe, Mucunguzi wacu."}]},
  {"number": 265, "name": "Ndakwifuza Yesu Mwiza", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/265", "key": "fa", "references": [{"codes": "SDAH. 484"}, {"codes": "AH. 320"}, {"title": "I NEED THEE PRECIOUS JESUS"}, {"codes": "HL. 40"}], "body": [{"type": "verse", "number": 1, "content": "Ndifuza Yesu Mwiza, Ndagukennye cyane,\nNd’ umushyitsi n’ umwimukira, Singira gakondo,\nNdifuz’ urukundo, Rwawe rumpumuriza,\nRunyobora ngakomera cyane, Sintezuke."}, {"type": "verse", "number": 2, "content": "Ndifuz’ umutima wa Yesu ngo nduhuke,\nNg’ untere kumutur’ imibabaro yanjye yose,\nNdifuz’ Umwuka Wera, Ngw’ ambwir’ icyo ndi cyo,\nArusheho kunyereka Umwana w’ Intama."}, {"type": "verse", "number": 3, "content": "Ndakwifuza Yesu, Nshaka kuzakubona,\nUgoswe n’ umukororombya ku ntebe ya cyami,\nNzahora nezeranywe n’ abo wacunguye,\nNzahora ngusingiz’ iteka, Ndi kumwe nawe."}]},
  {"number": 266, "name": "Iby’ Ushaka Nibibeho", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/266", "key": "la bémol", "references": [{"codes": "S. 718"}, {"title": "THY WILL BE DONE"}], "body": [{"type": "verse", "number": 1, "content": "Mukiza naraguhemukiye, Ndanakwimura ku mpamvu nkeya,\nUtungany’ umutima wanjy’ iby’ ushaka bibe."}, {"type": "chorus", "content": "Iby’ ushaka (ushaka), nibibeho (bibeho),\nUtungany’ umutima wanjye,\nIby’ ushaka bibe."}, {"type": "verse", "number": 2, "content": "Nari mfit’ imibabaro myinshi, Ntakir’ inshuti nahemukiye,\nN’ ubu ngubu ndacyavuga, Nt’ iby’ ushaka bibe."}, {"type": "verse", "number": 3, "content": "Umwuka waw’ utangir’ ubuntu, Agenderer’ umutima wanjye,\nHumuriz’ umutima wanjy’ ibyushaka bibe."}, {"type": "verse", "number": 4, "content": "Hindur’ ubugingo bwanjye bushya, Ubutegeke bub’ uk’ ushaka,\nNdind’ ibimbuza kuvuga, Iby’ ushaka bibe."}]},
  {"number": 267, "name": "Haba Ubwo Umwijima Ubudika", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/267", "key": "la bémol", "references": [{"codes": "AH. 318"}, {"title": "THE ROCK THAT IS HIGHER"}, {"codes": "SP. 169"}, {"title": "(O Sometimes the Shadows are Deep)"}], "body": [{"type": "verse", "number": 1, "content": "Hab’ ubw’ umwijim’ ubudika, Maze nkabur’ inzira pe,\nIbyago bikiyongeranya, Bikantera no kwiheba."}, {"type": "chorus", "content": "Nzahungira kuri Yesu (kuri Yesu),\nKukw’ ari w’ undush’ imbaraga (imbaragaa),\nNzahungira kuri Yesu (kuri Yesu),\nKukw’ ari w’ undush’ imbaraga."}, {"type": "verse", "number": 2, "content": "Hab’ umunsi umbera mubi, Natambuka ngateguza,\nNuko nkumva nguy’ agacuho, Maze nkisunga Rutare."}, {"type": "verse", "number": 3, "content": "Nzanikomeza ku Rutare, Nibwo nzashir’ agahinda,\nNi rwo ruzanshoboz’ inzira, Zirimw’ ibihanamanga."}]},
  {"number": 268, "name": "Nimusingize Umukiza", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/268", "key": "mi bémol", "references": [{"codes": "SP. 75"}, {"codes": "SDAH. 371"}, {"title": "LIFT HIM UP"}], "body": [{"type": "verse", "number": 1, "content": "Nimusingiz’ Umukiza, Mumurebe mukire,\nNi w’ ukiz’ inzimizi zazimiriye mu byaha;\nAbacits’ intege bose, Abonger’ imbaraga,\nAbah’ amazi y’ ubugingo mez’ amar’ inyota."}, {"type": "chorus", "content": "Abantu bose basingiz’ Umukiza wazutse,\nMusingiz’ uwo Mukiza, Ubavana mu byaha."}, {"type": "verse", "number": 2, "content": "Nimusingiz’ uwo Mukiza, Mwese mumuramye,\nAbamushakan’ umwete, Na bo azabakira,\nBavuy’ impande zose, Bihuta banezerewe,\nBatwaye umusaraba wa Yesu, Abakize."}, {"type": "verse", "number": 3, "content": "Nimumuh’ icyubahiro, Niwe Mwana w’ Imana,\nNdetse n’ abatamwitaho, Arabiyegereza,\nNgo bajye bibuk’ umusaraba yatangiyeho,\nBib’ uruhererekane mu bantu, Bamuramye."}, {"type": "verse", "number": 4, "content": "Mumusingize mu ndirimbo, No mu masengesho,\nUmucunguzi wikoreye ibyaha by’ abantu,\nAbato n’ abakuru bamwubahe, Bamuramye,\nAbafit’ ubumuga bazakizwa kubwa Yesu."}]},
  {"number": 269, "name": "Hari Igihugu Kibamo Umucyo", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/269", "key": "si bémol", "references": [{"codes": "S. 984"}, {"title": "THE BRIGHT FOR EVERMORE"}], "body": [{"type": "verse", "number": 1, "content": "Har’ igihugu kibamw’ umucyo urabagirana,\nNtabwo habayo umwijima, Yesu n’ umucyo waho."}, {"type": "chorus", "content": "S. na A.: Twemer’ umusaraba,\nTuzambikw’ ikamba,\nDukomez’ iby’ ukuri,\nNibwo tuzagerayo.\nT. na B.: Twemer’ u ... sa - saraba,\nTuzambikw’ ika... ikamba,\nDukome... by’ u... by’ ukuri,\nNi bwo tuzagerayo."}, {"type": "verse", "number": 2, "content": "Ibihe byaho ni byiza rwose, Nta mpinduk’ ibayo,\nNtabwo habay’ impagarara, Tuhabik’ ubutunzi."}, {"type": "verse", "number": 3, "content": "Mw’ ijuru hariy’ amazu meza arabagirana,\nTuzahahurira n’ inshuti, Twakiranw’ ibyishimo."}, {"type": "verse", "number": 4, "content": "Twifuza cyane kwimuka vuba, Mur’ iyi s’ ishaje,\nTujye guturana n’ abera, Maze dut’ umuruho."}]},
  {"number": 270, "name": "Nyobora Mwami Wanjye", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/270", "key": "ré bémol", "references": [{"codes": "S. 537"}, {"title": "LEAD ME, SAVIOR"}, {"codes": "HL. 499"}], "body": [{"type": "verse", "number": 1, "content": "Nyobora Mwami wanjye (Mwami wanjye),\nNe kurorongotana (mbane nawe),\nMb’ amahor’ unyoboye (unyoboye),\nIyo nkuri bugufi (nkuri bugufi)."}, {"type": "chorus", "content": "Mukiza we, Mpabura nahabiye kure,\nUnyambutse mw’ isumo (mw’ isumo),\nMwami ngendane nawe (nawe )."}, {"type": "verse", "number": 2, "content": "Iyo ngeze mu kaga (ncits’ intege)\nUmber’ ubuhungiro (buhungiro),\nNyakiran’ imbabazi (imbabazi),\nNezerwa turi kumwe (turi kumwe)."}, {"type": "verse", "number": 3, "content": "Ntabara Mwami mwiza (Mwami mwiza),\nMu mibabaro yanjye (yanjye yose ),\nKugez’ ubwo nzager’ aho (nzager’ aho ),\nNtazarir’ ukundi (ntazarir’ ukundi)."}]},
  {"number": 271, "name": "Mbese Ngend’ Imbokoboko?", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/271", "key": "ré", "references": [{"codes": "S. 789"}, {"title": "MUST I GO AND EMPTY HANDED?"}], "body": [{"type": "verse", "number": 1, "content": "Mbese ngend’ imbokoboko, Nsanganiy’ Umukiza wanjye?\nNta cyiza namukoreye, Mbese ngend’ imbokoboko?"}, {"type": "chorus", "content": "Mbese ngende ntacyo mfite,\nNsanganir’ uwo Mwami wanjye,\nNta n’ umwe namukirije,\nMbese ngende ntacyo mfite?"}, {"type": "verse", "number": 2, "content": "Sinterw’ ubwoba n’ urupfu, Umukiza yarankijije.\nKu musanga ntacyo mfite, Numva binkojej’ isoni."}, {"type": "verse", "number": 3, "content": "Napfushij’ igih’ ubusa, Nakoz’ ibyangwa n’ Umukiza,\nUbu ndamutakambira, Musaba kumbabarira."}, {"type": "verse", "number": 4, "content": "Mwebw’ abera mushishikare, Mukore hakiri kare,\nDor’ ijoro riraguye, Mutarakiz’ imitima."}]},
  {"number": 272, "name": "Umwana W’ Imana", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/272", "key": "ré", "references": [{"codes": "HL. 597"}, {"title": "LE FILS DE DIEU"}], "body": [{"type": "verse", "number": 1, "content": "Umwana w’ Imana yaje mw’ isi kumpfira kukw’ ankunda;\nEse s’ igitangaza gihebuj’ urukundo rwe rwinshi?"}, {"type": "chorus", "content": "Yesu yarankunze bihebuje rwose :"}, {"type": "verse", "number": 1, "content": "Yabambwe ku musaraba, Yesu yarankunze."}, {"type": "verse", "number": 2, "content": "Yarazutse ku bwanjye, Koko Yes’ arankunda."}, {"type": "verse", "number": 3, "content": "Yampeshej’ icyubahiro, Yesu yarankunze."}, {"type": "verse", "number": 4, "content": "Yabambwe ku musaraba, Yesu yarankunze."}, {"type": "verse", "number": 2, "content": "Iteka ryos’ amaraso atunganye niy’ anyejesha;\nKubw’ impuhwe za Yesu, Yangiz’ umwana w’ iteka ryose."}, {"type": "verse", "number": 3, "content": "Uzi kamere yanjye yose, Unyobora buri munsi.\nNgendera mu mucyo waw’ iteka, Kubw’ urukundo rwawe."}, {"type": "verse", "number": 4, "content": "Yesu Kristo ntahinduka, Aragukiz’ uk’ uri kose.\nZan’ umutim’ umenetse, Arakwakir’ uk’ uri kose."}]},
  {"number": 273, "name": "Yesu Ntabwo Yakwanga", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/273", "key": "si bémol", "references": [{"codes": "S. 406"}, {"title": "JESUS WILL NOT CAST YOU OUT"}], "body": [{"type": "verse", "number": 1, "content": "Yesu ntabwo yakwanga, N’ ubw’ ur’ umunyabyaha,\nNi we nshut’ ihebuje, Ntazanga kukwakira,\nImana yatanze Yesu, Kugira ngo ducungurwe,\nN’ ubwo wamuhemukiye, Ntazanga kukwakira."}, {"type": "verse", "number": 2, "content": "N’ ubw’ ujy’ umugayisha, Ntazakwirengagiza,\nNi we nzira n’ umucyo, Ntazanga kukwakira,\nAzagusendahw’ ibyaha, maz’ usigar’ utunganye,\nAzagukiz’ urupfu, Ntabw’ azakwirengagiza."}, {"type": "verse", "number": 3, "content": "Ngaho ngwin’ utiganda, Ntazanga kukwakira,\nGana ku musaraba, Ntazanga kukwakira,\nNumara gusanga Yesu, Ntuzasubira mu byaha,\nNgwino uhabw’ ubugingo, Butagir’ iherezo."}]},
  {"number": 274, "name": "Uhoraho Iyo Nitegereje", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/274", "key": "si bémol", "references": [{"codes": "SDAH. 86"}, {"title": "HOW GREAT THOU ART"}, {"codes": "GH. 19"}, {"title": "(O Mighty God, When I Behold The Wonder)"}], "body": [{"type": "verse", "number": 1, "content": "Uhoraho, Iyo nite gereje, Ibitangaza by’ ibyo wakoze,\nAr’ izuba, ukwezi n’ inyenyeri, N’ ibindi bintu byose waremye."}, {"type": "chorus", "content": "Nishimira kukuririmbira,\nMana nkuru y’ urukundo;\nNishimira kukuririmbira,\nMana nkuru, y’ urukundo."}, {"type": "verse", "number": 2, "content": "Mana nkunda, Iyo nitegereje, Igiti cyose mu byo waremye,\nBinyibutsa igiti cy’ i Kalvari, Umwana wawe yambambiweho."}, {"type": "verse", "number": 3, "content": "Iyo numva inyoni ziririmba mu biti byiza yaturemeye,\nUrusobe rw’ amajwi yazo meza n’ urw’ amasumo biranezeza."}, {"type": "verse", "number": 4, "content": "Igih’ ibyago bizaba bishize, Abera bose bagukikije,\nTuzagusingiza iteka ryose, Kandi turamy’ Uwatwitangiye."}]},
  {"number": 275, "name": "Nzasa Na Yesu", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/275", "key": "sol", "references": [{"codes": "SP. 144"}, {"title": "I WOULD BE LIKE JESUS"}, {"codes": "SDAH. 311"}, {"title": "( Earthly Pleasures Vainly Call Me )"}], "body": [{"type": "verse", "number": 1, "content": "N’ ubw’ ibyiza by’ isi byanshuka, Nzasa na Yesu,\nNtacyo mw’ isi kizampindura, Nzasa na Yesu."}, {"type": "chorus", "content": "Nzasa na Yesu rwose, Ni yo ndirimbo yanjye,\nNdi hanze n’ imuhira, Nzajya nsa na Yesu."}, {"type": "verse", "number": 2, "content": "Nabohow’ ingoyi z’ umwanzi, Nzasa na Yesu,\nNzarushaho kumukorera, Nzasa na Yesu."}, {"type": "verse", "number": 3, "content": "Naba mw’ isi cyangwa mw’ ijuru, Nzasa na Yesu,\nNzahora mbyamamaz’ iteka, Nzasa na Yesu."}, {"type": "verse", "number": 4, "content": "Kugira ngo nzajye mw’ ijuru, Nzasa na Yesu,\nKuko nifuza kuzashimwa, Nzasa na Yesu."}]},
  {"number": 276, "name": "Iyi Si Ni Iya Data", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/276", "key": "mi", "references": [{"codes": "SDAH. 92"}, {"codes": "CH. 646"}, {"title": "THIS IS MY FATHER’S WORLD"}], "body": [{"type": "verse", "number": 1, "content": "Iyi si n’ iya Data, Kand’ iyo ntez’ amatwi,\nNumv’ ibiremwa bisingiza izina rye mu ndirimbo,\nIsi n’ iya Data, Mpora mbitekereza,\nIby’ Uhoraho yaremye byose, Ni byiza bitangaje."}, {"type": "verse", "number": 2, "content": "Iyi si n’ iya Data, Inyoni ziririmba,\nUmuseke wa mu gitondo, N’ impumuro y’ uburabyo,\nIbimera byose, Hamwe n’ ibyo mw’ ijuru,\nByose bigaragaz’ ububasha, N’ imbaraga ze nyinshi."}, {"type": "verse", "number": 3, "content": "Iyi si n’ iya Data, N’ ubwo yuzuy’ ibyaha,\nNta kizaganz’ imbaraga ze, Azahor’ ari ku ngoma,\nIsi n’ iya Data, Mbese nakwiganyira?\nImana yac’ izahora ku ngom’ ibihe bidashira."}, {"type": "verse", "number": 4, "content": "Iyi si n’ iya Data, Ntabwo nzabyibagirwa,\nN’ ubw’ ibyaha biyuzuyemo, Imana n’ umuyobozi,\nIsi n’ iya Data, Ni kuki nababara?\nData ni we uri ku ngoma, Ijuru n’ isi byishime."}]},
  {"number": 277, "name": "Duhaguruke", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/277", "key": "si bémol", "references": [{"codes": "HL. 648"}, {"title": "LEVONS - NOUS"}], "body": [{"type": "verse", "number": 1, "content": "Nimuhaguruke mwa bantu mwe, Yes’ arabayobora (nimuze)!\nRangurura bwoko bukomeye, I Siyoni hadaterwa\n(Siyoni heza hadaterwa)."}, {"type": "chorus", "content": "(Nimuririmb’ indirimbo);\nNimuririmb’ indirimbo, Nk’ inkubi yo mu nyanja;\nKo twakijijwe na Yesu, Uturusha kunesha.\nAturusha kunesha (n’ umuneshi),\nAturusha kunesha (kunesha n’ umuneshi).\nKo twakijijwe na Yesu, Uturusha kunesha."}, {"type": "verse", "number": 2, "content": "Abera n’ intwari baririmbe, Baranesheje cyane (nk’ intwari).\nDor’ ibendera ritur’ imbere, Banesheje muri Yesu\n( ry’ abanesheje muri Yesu)."}, {"type": "verse", "number": 3, "content": "Benshi bayobejwe na Satani, Babuz’ ubatabara (nimuze)!\nNimwambar’ intwari mutabare, Muyobowe n’ Umukiza\n(Muyobowe n’ uwo Mukiza)."}, {"type": "verse", "number": 4, "content": "Nimurangurur’ amajwi yanyu, Ko Yesu yanesheje (Satani).\nMutarur’ izo nzimizi zose, Zirebe ku musaraba\n(Zize zireb’ umusaraba)."}]},
  {"number": 278, "name": "Bona N’ Ubwo Ngoswe N’ Ibicu", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/278", "key": "la bémol", "references": [{"codes": "S. 711"}, {"title": "JESUS ONLY"}, {"codes": "CS. 615"}, {"title": "(What thou, Clouds are Hov’ring o’er Me)"}], "body": [{"type": "verse", "number": 1, "content": "Bona n’ ubwo ngoswe n’ ibicu, Kandi nkab’ inkehwe,\nKandi nkaba ndembejwe n’ amaganya menshi cyane.\nGubiramo: Nagira Yesu wenyine, Byose byatamuruka,\nNi we zuba ryaka nk’ inyenyeri y’ i Betelehemu."}, {"type": "verse", "number": 2, "content": "N’ ubw’ urugendo rwo mw’ isi rwantera gucogora,\nNajya gusingir’ uburabyo, Ngasingir’ amahwa."}, {"type": "verse", "number": 3, "content": "N’ ubw’ umutima wanjye, Wazirikan’ Uwankunze,\nBigatuma ngir’ agahinda, Kenshi nkababara."}, {"type": "verse", "number": 4, "content": "Nzirikany’ icyubahiro, Ntegereje kwinjira,\nNavuga Yesu wenyine, Byose byatamuruka."}]},
  {"number": 279, "name": "Intama Mirongo Cyenda N’ Icyenda", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/279", "key": "la bémol", "references": [{"codes": "S. 97"}, {"title": "THE NINETY AND NINE"}, {"codes": "CH. 673"}], "body": [{"type": "verse", "number": 1, "content": "Intama mirongo cyenda n’ icyenda, Zari mu kiraro cyazo,\nImwe yazimiye yararagiye, Yagiye mu bihanamanga,\nDor’ irazerera mu kidaturwa, Yasiz’ Umwungeri w’ impuhwe nyinshi,\nYasiz’ Umwungeri w’ impuhwe nyinshi."}, {"type": "verse", "number": 2, "content": "Ufite mirongo cyenda n’ icyenda, Mbese warets’ iyo Mwami,\nAransubiz’ ati : Na yo n’ iyanjye, Ibarirwa mu ntama zanjye,\nBona nahw’ inzira yakukumuka, Ndayikurikira mu kidaturwa,\nNdebe ko nabasha kuyibonayo."}, {"type": "verse", "number": 3, "content": "Nta muntu wamenya uko yarushye, N’ uko yambuts’ imigezi,\nRyar’ ijoro ribi kandi ntaw’ uzi, Uko yataruy’ iyo ntama,\nYumvis’ ijwi ryayo mu kidaturwa, Ntabwo yagirag’ uwayitabara,\nRwose yar’ isigaje hat’ igapfa."}, {"type": "verse", "number": 4, "content": "Mwami nyerek’ inzira wanyuzemo, Mbonemw’ amaraso yawe,\nYavuye ku bwacu twarazimiye, Maz’ utugarura mu bushyo,\nNyereka za nkovu zo mu biganza, Wakomerekejwe mur’ iryo joro,\nN’ igihe bakwambikaga ya mahwa."}, {"type": "verse", "number": 5, "content": "Ku misozi hose no mu bikombe, No ku bitare ku manga,\nHar’ ijwi rirenga ngo nimwishime, Intama yanjye yabonetse,\nAbamarayika bavuga bati: Nimwishim’ Umwam’ abony’ intama ye,\nNimwishim’ Umwam’ abony’ intama ye."}]},
  {"number": 280, "name": "Mu Gihugu Cyiza Twasezeraniwe", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/280", "key": "si bémol", "references": [{"codes": "SY. 142"}, {"codes": "AH. 420"}, {"title": "WE ARE NEARING HOME!"}, {"codes": "CH. 642"}, {"title": "(In The Promised Land)"}], "body": [{"type": "verse", "number": 1, "content": "Mu gihugu cyiza twasezeraniwe,\nHariy’ ururembo rwera rw’ Imana,\nTuzamuk’ imisozi tunaniwe,\nTukarabukw’ aho tuzab’ iteka."}, {"type": "chorus", "content": "S. na A. : Tugeze hafi, Hafi y’ iwacu,\nDore hararabagirana cyane,\nHar’ umucy’ uturuka mu marembo,\nAho ni ho tuzab’ iteka ryose,\nTuririmbana n’ abamarayika,\nTuri hafi yaho.\nT. na B. : Tuge… tugeze y’ iwacu, Hafi y’ iwacu,\nDore hararabagirana cyane,\nHar’ umucy’ uturuka mu marembo,\nAho ni ho tuzab’ iteka ryose,\nTuririmbana n’ abamarayika,\nTuri, turi hafi …ho."}, {"type": "verse", "number": 2, "content": "Mu bitabo by’ abahanuzi tubwirwa,\nIby’ umudugudu wera w’ Imana,\nN’ inzira zaho zisizwe zahabu,\nAmazu yahw’ ararabagirana."}, {"type": "verse", "number": 3, "content": "Abazajyayo n’ abizera bakeya,\nBakomez’ amategeko y’ Imana,\nTuzahora turangurur’ amajwi,\nTuririmb’ indirimbo z’ ibyishimo."}, {"type": "verse", "number": 4, "content": "Mbese tuzahurirayo bene Data,\nMu gihugu kirasirwa n’ izuba?\nNimwemera ubutumwa bw’ Imana,\nYesu naza azabahamagara."}]},
  {"number": 281, "name": "Wiringir’ Umwam’ Imana", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/281", "key": "la bémol", "references": [{"codes": "S. 563"}, {"title": "PUT YOUR TRUST IN GOD"}], "body": [{"type": "verse", "number": 1, "content": "Wiringir’ Umwam’ Imana, Kukw’ ari y’ izakuyobora,\nIzere Nyir’ imigisha, Ni w’ uzagukenura."}, {"type": "chorus", "content": "Izer’ uko yakubwiye, Yihang’ amas’ iteka ryose,\nUyiringire ibihe byose, Ni yo Mwungeri wawe."}, {"type": "verse", "number": 2, "content": "Wiringir’ Umwam’ Imana, Umushukanyi nakwegera,\nWiringir’ Umwam’ Imana, Ujy’ uyihungiraho."}, {"type": "verse", "number": 3, "content": "Wiringir’ Umwam’ Imana, Mu birushya no mu makuba,\nWiringir’ Umwam’ Imana, Yih’ umutwaro wawe."}, {"type": "verse", "number": 4, "content": "Wiringir’ Umwam’ Imana, Mu mibereho yawe yose,\nWiringir’ Umwam’ Imana, Kugez’ ahw’ azazira."}]},
  {"number": 282, "name": "Habuka Wa Mpabe We", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/282", "key": "la bémol", "references": [{"codes": "S. 1196"}, {"title": "CLOSE THY HEART NO MORE"}], "body": [{"type": "verse", "number": 1, "content": "Habuka wa mpabe we, Urahamagarwa,\nRek’ ibyaha byawe ngwino, Wikwinangira."}, {"type": "chorus", "content": "Ngwino hakirih’ umucyo,\nYes’ aragutegereje,\nAramburiy’ amaboko,\nAbe bahabye."}, {"type": "verse", "number": 2, "content": "Umukiz’ arakwinginga, Ntiwinangire,\nUmv’ araguhamagara, Mukingurire."}, {"type": "verse", "number": 3, "content": "Uraritswe n’ ubutumwa, We kwinangira,\nBukuzaniy’ agakiza, Bukingurire."}, {"type": "verse", "number": 4, "content": "We kwigomw’ umunezero, Ngo winangire,\nNibw’ uzagir’ amahoro, Mukingurire."}]},
  {"number": 283, "name": "Yesu Ndagutakambiye", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/283", "key": "mi bémol", "references": [{"codes": "S. 476"}, {"title": "TAKE ME AS I AM"}], "body": [{"type": "verse", "number": 1, "content": "Yesu ndagutakambiye, Kuk’ utantabaye napfa,\nUngeze ku gakiza kawe, Unyakir’ uko ndi."}, {"type": "chorus", "content": "Unyakir’ uko ndi, Unyakir’ uko ndi,\nMwami wanjye warampfiriye,\nUnyakir’ uko ndi."}, {"type": "verse", "number": 2, "content": "Ntabwo ngira kivurira, Arikw’ amaraso yawe,\nNi yo yangize uk’ ushaka, Unyakir’ uko ndi."}, {"type": "verse", "number": 3, "content": "Sinabasha kwitegura, Nguhay’ imigambi yanjye,\nUnkize kubw’ izina ryawe, Unyakir’ uko ndi."}, {"type": "verse", "number": 4, "content": "Dore Mwami nje ku birenge byaw’ ungir’ uk’ ushaka,\nUtungany’ umurimo wawe, Unyakir’ uko ndi."}]},
  {"number": 284, "name": "Yesu Ni Umukiza Wanjye", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/284", "key": "ré", "references": [{"codes": "SDAH. 520"}, {"title": "A WONDERFUL SAVIOR IS JESUS MY LORD"}, {"codes": "SP. 103"}], "body": [{"type": "verse", "number": 1, "content": "Yesu n’ Umukiza wanjy’ utangaje, Kuko andutira byose,\nNi we wampagaritse ku Rutare, Mpaboner’ umunezero."}, {"type": "chorus", "content": "Ni we wampagaritse ku Rutare, Mu gihugu cy’ umutarwe,\nKand’ ampisha mu rukundo rwe rwinshi,\nAndindish’ ukuboko kwe, Andindish’ ukuboko kwe."}, {"type": "verse", "number": 2, "content": "Yesu n’ Umukiza wanjy’ utangaje, Antur’ imitwaro yose,\nArankomeza sinzanyeganyega, Kukw’ ahor’ ambumbatiye."}, {"type": "verse", "number": 3, "content": "Ansesurahw’ imigisha nk’ ikamba, Anyuzuz’ ubugwaneza,\nNdirimba ntikenga nsingiz’ Imana, Ni yo Mucunguzi wanjye."}, {"type": "verse", "number": 4, "content": "Ninambara kurabagirana kwe, Nibwo nzamusanganira,\nNzajya ndirimbana n’ abacunguwe, Indirimbo y’ agakiza."}]},
  {"number": 285, "name": "Isi Ni Iy’ Uhoraho", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/285", "key": "ré", "references": [{"codes": "SP. 181"}, {"title": "THE WHOLE WIDE WORLD FOR JESUS"}], "body": [{"type": "verse", "number": 1, "content": "Isi n’ iy’ Uwiteka, Tumusingize twese, Imisozi n’ inyanja n’ ibirimo byose,\nIsi n’ iy’ Uwiteka, Bose bamuramye, Imidugudu n’ ibiyaga byose n’ ibye."}, {"type": "chorus", "content": "Isi yose, Isi yose, Yamamaz’ ubutumwa bwiza bwa Yesu,\nMutwar’ umusaraba, Mushing’ ibendera,\nKugez’ ubw’ abantu bose bazihana.\nAmen. (Ku gice cya 3)."}, {"type": "verse", "number": 2, "content": "Isi n’ iy’ Uwiteka tuyibimenyeraho, Mpabe nimuhabuke mwe kuyob’ inzira,\nIsi n’ iy’ Uwiteka ntimugacogore, Umusaraba ni wo watuneshereje."}, {"type": "verse", "number": 3, "content": "Isi n’ iy’ Uwiteka, Itegeko n’ iri ngo: Mugende, Mwamamaze ubutumwa bwiza,\nIsi n’ iy’ Uwiteka, Ganz’ iteka Mwami, Amahanga yose ahor’ agusingiza."}]},
  {"number": 286, "name": "Yesu Arakomang’ Ubu", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/286", "key": "fa", "references": [{"codes": "CH. 565"}, {"codes": "CS. 20"}, {"title": "SHALL I LET HIM IN?"}, {"codes": "S. 470"}], "body": [{"type": "verse", "number": 1, "content": "Yesu arakomang’ ubu, Mukingurire?\nAringing’ umutima wanjye, Se mukingurire?\nMuri wo harimw’ ibyaha, N’ umwijima n’ agahinda.\nKristo ashaka ko musanga, Se mukingurire?"}, {"type": "verse", "number": 2, "content": "Se mubwiran’ urukundo, Mukingurire?\nNakir’ uwo Mwami w’ ubuntu, Se mukingurire?\nNtantererana na hato, Ambabarir’ ubugome.\nMbese namwimura burundu, Cyangwa munambeho?"}, {"type": "verse", "number": 3, "content": "Umutima w’ ubwibone, Ndawukinguye.\nMwakirany’ ibyishimo byinshi, Ndamukinguriye.\nMukiza mwiza tubane, Undind’ ibishuko byose,\nMb’ amahor’ iyo turi kumwe, Ngwino Mwami Yesu."}]},
  {"number": 287, "name": "Nimushimir’ Imbabazi Za Yesu", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/287", "key": "sol", "references": [{"codes": "S. 508"}, {"title": "IF GOD BE FOR US"}], "body": [{"type": "verse", "number": 1, "content": "Nimwishimir’ imbabazi za Yesu, Kuko yatwicunguriye,\nNtacyo twatinya Yes’ ashobora byose, Ni we Mukiza wacu."}, {"type": "chorus", "content": "Sop.: Mbese ubw’ Imana, Iri mu ruhande rwacu,\nUmubisha wacu ninde! Ninde? Umubisha wacu Se ninde?\nAlto: Mbese ubw’ Imana, Iri mu ruhande rwacu,\nUmubisha wacu ninde! Ninde? Yaba nde koko?\nUmubisha wacu Se ninde?\nT. na B.: Mbes’ ubw’ Imana yac’ iri mu ruhande rwacu,\nUmubisha wacu ni - se! Ninde? Yaba nde koko?\nUmubisha wacu Se ninde?"}, {"type": "verse", "number": 2, "content": "Mukomerere mu Mwami wacu Yesu mub’ abakiranutsi,\nMu kaga kose muhagarare mushikamy’ azabakomeza."}, {"type": "verse", "number": 3, "content": "Nimwiringire Yesu mukomez’ amategeko ye by’ ukuri,\nIs’ izashira arikw’ amategeko y’ azahorahw’ iteka."}, {"type": "verse", "number": 4, "content": "Tuzibanira n’ Umwami wacu Yesu azaduh’ ubugingo,\nKandi nta muntu wabasha kudutesh’ uwo Mukiz’ umez’ atyo."}]},
  {"number": 288, "name": "Har’ Ijwi Rihamagara", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/288", "key": "la bémol", "references": [{"codes": "AYS. 162"}, {"title": "(There’s Call Comes Ringing o’re)"}, {"codes": "S. 1082"}, {"title": "SEND THE LIGHT"}], "body": [{"type": "verse", "number": 1, "content": "Har’ ijwi rihamagar’ abarushye, Mubamurikire (Mubamu-rikire),\nHarihw’ abatabaza ngo bakizwe, Mubamurikire (Mubamu-rikire)"}, {"type": "chorus", "content": "S. na A. : Nimubamurikishirize umucyo w’ ubutumwa,\nBamenyeshe ko Yes’ ari we wabapfiriye bose.\nT. na B. : Nimubamurikishirize ...cyo w’ ubutumwa,\nBamenyeshe ko Yes’ ari we, ....pfiriye bose."}, {"type": "verse", "number": 2, "content": "Harihw’ abatabariza gukizwa, Mubamurikire (Mubamu-rikire),\nTuzan’ amaturo ku musaraba, Ngo bamurikirwe (Ngo bamu-rikirwe)."}, {"type": "verse", "number": 3, "content": "Ubuntu bwa Yesu bugwire hose, Mubamurikire (Mubamu-rikire),\nKand’ Umwuka wa Yes’ ukwire hose, Mubamurikire (Mubamu-rikire)."}, {"type": "verse", "number": 4, "content": "Twe gucogorera gukora neza, Tubamurikire (Tubamu-rikire),\nTwitegurire kuzahabw’ ikamba, Tubamurikire (Tubamu-rikire)."}]},
  {"number": 289, "name": "Mutim’ Ufit’ Intege Nke", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/289", "key": "do", "references": [{"codes": "AH. 258"}, {"title": "WAIT, AND MURMUR NOT"}, {"codes": "CH. 616"}, {"title": "(O Weary Heart, There Is a Home)"}, {"codes": "S. 710"}], "body": [{"type": "verse", "number": 1, "content": "Mutim’ ufit’ intege nke, Harih’ uburuhukiro,\nN’ iwacu hadahinduka, Se ntiwifuza kubayo?"}, {"type": "chorus", "content": "S. na A.: Wa munyantege nke we, Tegereza,\nKandi nturambirwe, B’ uretse,\nTegereza, Ntukivovote (Alto: Ntukivo… Ntukivovote).\nT. na B.: Wa mu…, Wowe munyantege nke we, Tegereza n’ ukuri;\nKandi nturambirwe, B’ uretse, B’ uretse,\nTege – Utege - reza, Tenor: Ntukivo - Ntukivovote.\nBass: Ntuki - vote."}, {"type": "verse", "number": 2, "content": "Ubw’ uzatur’ umutwaro, Ibyo mw’ isi birangiye,\nUzashyikir’ agakiza, Tegerez’ utivovota."}, {"type": "verse", "number": 3, "content": "Nib’ amahw’ ari mu nzira, Tekerez’ uwayambitswe,\nN’ ubabara wibuke k’ Uwera, Nawe yababajwe."}, {"type": "verse", "number": 4, "content": "Ujy’ uhora wihanganye, Ntukibagirwe gusenga,\nHarih’ ubw’ uzaruhuka, Tegerez’ utivovota."}]},
  {"number": 290, "name": "Ubugingo Bw’ Abantu", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/290", "key": "la", "references": [{"codes": "S. 1044"}, {"title": "FLITTING AWAY"}], "body": [{"type": "verse", "number": 1, "content": "Ubugingo bw’ abantu, Buhita nk’ igicucu,\nImbere yawe Mwami Mana, Buhita n’ ingoga."}, {"type": "chorus", "content": "Ye ni koko, Burihuta,\nRwose bwihuta nk’ igicucu,\nN’ iby’ ukuri nta mumaro,\nUbugingo bwacu n’ ubusa."}, {"type": "verse", "number": 2, "content": "Umunt’ ab’ afit’ izina rimutey’ ishema,\nImyaka yamara guhita, Rikibagirana."}, {"type": "verse", "number": 3, "content": "Ya nyenyeri y’ Umukiza y’ i Betelehemu,\nNatw’ ibasha kutuyobora, Tukamugeraho."}, {"type": "verse", "number": 4, "content": "Mwami Mana komez’ iyo nyenyer’ imurike,\nUmucyo way’ ukwire hose, Umwijim’ uhunge."}]},
  {"number": 291, "name": "Ndabatuwe Sinkibabaye", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/291", "key": "la", "references": [{"codes": "SDAH. 292"}, {"title": "JESUS, I COME"}, {"codes": "AH. 185"}, {"title": "(Out of my Bandage, Sorrow and Night)"}], "body": [{"type": "verse", "number": 1, "content": "Ndabatuwe sinkibabaye, Yesu ndaje, Yesu ndaje,\nNje mu munezero iwawe, Ubu Yesu ndaje,\nNje nifuza gufashwa nawe, Ngutuy’ intege nke zanjy’ unkize,\nMvuye mu byaha nje nkugana, Ubu Yesu ndaje."}, {"type": "verse", "number": 2, "content": "Nkijijw’ isoni sinihebye, Yesu ndaje, Yesu ndaje,\nNemey’ umusaraba wawe, Ubu Yesu ndaje,\nMvuye mu mibabaro y’ isi, Ubu ngeze mu mahoro yawe,\nSimbabaye ndanezerewe, Ubu Yesu ndaje."}, {"type": "verse", "number": 3, "content": "Nkiz’ imiruho n’ ubwibone, Yesu ndaje, Yesu ndaje,\nNje kuba mu mahoro yawe, Ubu Yesu ndaje,\nNje kuba mu rukundo iwawe, Sinkihebye nje mu munezero,\nNj’ ah’ uri nguruka nk’ inuma, Ubu Yesu ndaje."}, {"type": "verse", "number": 4, "content": "Wamaz’ ubwoba bw’ igituro, Yesu ndaje, Yesu ndaje,\nNje mu munezero w’ iwawe, Ubu Yesu ndaje,\nWanyaruye mw’ irimbukiro, Ungeza mu mahor’ adashira,\nNgo mpore nkureba mu maso, Ubu Yesu ndaje."}]},
  {"number": 292, "name": "Ni Wowe Gusa", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/292", "key": "si bémol", "references": [{"codes": "AH. 103"}, {"title": "ONLY THEE"}, {"codes": "SP. 99"}], "body": [{"type": "verse", "number": 1, "content": "Ni wowe gusa nkeneye, Nta wundi Mwami.\nHar’ undi mfite mw’ ijuru, Mwam’ atari wowe?"}, {"type": "chorus", "content": "Ni wowe (ni wowe), Ni wowe (ni wowe),\nWanyerets’ urukundo, Ni wowe (ni wowe),\nNi wowe (ni wowe), Ntaw’ uhwanye nawe."}, {"type": "verse", "number": 2, "content": "N’ ubwo mfit’ inshuti nyinshi, N’ ibyiza byinshi,\nUtabirimo Mukiza, Nta mumaro wabyo."}, {"type": "verse", "number": 3, "content": "Mbese harih’ umutima wuzuy’ ineza?\nCyangw’ ijwi ryiza nakumva rikampumuriza?"}, {"type": "verse", "number": 4, "content": "Iby’ isi ntabwo byantanya nawe Mukiza,\nIbyo mur’ iyi si byose, Nta mumaro wabyo."}]},
  {"number": 293, "name": "Munsi Mwiza Wejejwe", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/293", "key": "sol", "references": [{"codes": "S. 476"}, {"title": "HOLY DAY, JEHOVAH’S REST"}], "body": [{"type": "verse", "number": 1, "content": "Munsi mwiza wejejwe, W’ icyumweru cyo kurema,\nWagizw’ uwa karindwi, Wahiriwe n’ Imana."}, {"type": "chorus", "content": "Ngwino Sabato, Sabato nziza,\nTuboner’ imigisha, Mu munsi w’ Uhoraho."}, {"type": "verse", "number": 2, "content": "Irangije kurema, Ishyiraho n’ Isabato,\nIman’ irayihira, Natwe tuyiruhuke."}, {"type": "verse", "number": 3, "content": "Benshi barwany’ Imana, Baruhuka kuwa mbere.\nShaka mu Byanditsw’ urasanga nta habihamya."}, {"type": "verse", "number": 4, "content": "Abanyakuri bazi ko wahinduwe n’ umuntu,\nNtabw’ Ijambo ry’ Imana rikwiye guhinduka."}, {"type": "verse", "number": 5, "content": "Nashatse mu Byanditswe, Nsang’ ari yo yategetswe.\nMpera ko nyiruhuka, Kukw’ ari yo y’ ukuri."}]},
  {"number": 294, "name": "Gitare Kirekire", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/294", "key": "mi bémol", "references": [{"codes": "SDAH. 525"}, {"title": "O SAFE TO THE ROCK"}, {"codes": "SP. 108"}], "body": [{"type": "verse", "number": 1, "content": "Gitare kirekire njya mpungiraho,\nNi wow’ umutima wanjye wifuza,\nNd’ umunyantege nke nshaka kukwisunga,\nWowe Gitare cyanjye, Nkwihishemo."}, {"type": "chorus", "content": "Nkwihishemo, Nkwihishemo,\nWowe Gitare cyanjye, Nkwihishemo."}, {"type": "verse", "number": 2, "content": "Ngiz’ imibabaro ku manywa y’ ihangu,\nNizingiweho n’ ibigeragezo,\nNdengewe n’ imiraba yiyungikanya,\nWowe Gitare cyanjye, Nkwihishemo."}, {"type": "verse", "number": 3, "content": "Umwanz’ anyibasiye ndi ku rugamba,\nNi wowe mpungiraho nkaruhuka,\nIyo nibasiwe n’ ibigeragezo,\nNiwe nihishamo, Gitare cyanjye."}]},
  {"number": 295, "name": "Mpisemo Umukiza Yesu", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/295", "key": "do", "references": [{"codes": "SDAH. 327"}, {"title": "I’ D RATHER HAVE JESUS"}], "body": [{"type": "verse", "number": 1, "content": "Mpisem’ Umukiza Yesu gusa, Kurut’ ubutunzi bwo mur’ iyi si,\nAndutir’ ifeza n’ izahabu, Ikiganza cye cyarambambiwe."}, {"type": "chorus", "content": "Rwos’ aho kwitw’ umunt’ ukomeye,\nKandi nd’ umunyabyaha;\nNahitamo kub’ uworoheje,\nAriko nd’ uwa Yesu."}, {"type": "verse", "number": 2, "content": "Mpisemo Yesu kurut’ ikuzo, No kumukorera nivuy’ inyuma,\nAndutir’ icyubahiro cy’ isi, Nkunda kwitirirwa izina Rye."}, {"type": "verse", "number": 3, "content": "Arush’ ibiremwa byos’ ubwiza, Anyur’ umutima kuruta byose,\nAzah’ umutima wanjy’ ibyiza, Nimwemerera akanyobora."}]},
  {"number": 296, "name": "Amahoro masa", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/296", "key": "la bémol", "references": [{"codes": "SDAH. 466"}, {"title": "PEACE! WONDERFUL PEACE!"}, {"codes": "S. 658"}], "body": [{"type": "verse", "number": 1, "content": "Umutima wanjy’ urasingiz’ Imana, Mu ndirimbo y’ umunezero,\nNifitiy’ amahoro ava mw’ ijuru, Yuzuye mu mutima wanjye."}, {"type": "chorus", "content": "Amahoro masa, Aturuka ku Mana gusa,\nNyamuneka tungany’ ubugingo bwanjye,\nN’ urukundo rutarondorwa."}, {"type": "verse", "number": 2, "content": "Nifitiy’ amahor’ arut’ ubutunzi, Yuzuye mu mutima wanjye,\nKandi nta muntu wabasha kuyanyaga, Ntawe n’ aho yakwigir’ ate!"}, {"type": "verse", "number": 3, "content": "Yambereye ubuhungiro nijoro, Bituma mb’ uwa Yesu gusa,\nNta cyampangara ku manywa na nijoro, Ntacyo rwose haba na gito!"}, {"type": "verse", "number": 4, "content": "Reka mvug’ ibya wa mudugudu mwiza, Uwo nzabona nkanezerwa,\nMu ndirimb’ abera bazaharirimbir’ imwe n’ iyi ngiyi wumva ngo:"}, {"type": "verse", "number": 5, "content": "N’ ubwo nanyuraga mu makuba y’ isi, Nkabur’ umunt’ umpumuriza,\nUmukiza wanjye n’ inshuti y’ ukuri, Yangoteshej’ amaboko ye."}]},
  {"number": 297, "name": "Yesu Ni We Niringira", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/297", "key": "ré", "references": [{"codes": "HL. 292"}, {"title": "JESUS, MON ESPERANCE"}], "body": [{"type": "verse", "number": 1, "content": "Yesu ni we niringira, Ni we butunzi bwanjye,\nNzakwishingikirizaho, Kugez’ igihe nzapfa,\nNi wowe umbeshejeho kuko ump’ amahoro,\nNi wow’ ump’ umunezero, Ur’ ubuzima bwanjye."}, {"type": "verse", "number": 2, "content": "Niba bikwiriye kureb’ umusaraba wawe,\nNgira intungane nkunde amategeko yawe,\nNtawe unaniza ngw’ akor’ ibyo adashoboye,\nNtacyo wasaba ng’ umuntu abon’ icyakwitura."}, {"type": "verse", "number": 3, "content": "Njye ndashaka kugendera mu mucyo wawe Yesu,\nNgo nzazuke nigira iwawe mw’ ijuru heza.\nAho ni ho hari igihugu nzabamw’ iteka,\nNi ho Yesu azanyakira ari mu ngoro ye."}]},
  {"number": 298, "name": "Igitekerezo Cyiza", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/298", "key": "mi bémol", "references": [{"codes": "S. 1136"}, {"title": "THE SWEET STORY OF OLD"}], "body": [{"type": "verse", "number": 1, "content": "Igitekerezo cyiza cya Yesu Mukiza, Kivug’ uburyo yahoranye n’ abantu,\nN’ uko yahamagarag’ abana nk’ intama ze, Maze bigatuma nkumbura Yesu,\nNumva nifuza kw’aba yaranshyizehw’ ibiganza, Ngw’abe yaranzengurukij’ amaboko,\nYemwe mba narahiriw’ iyo numv’ avug’ ati: Nimurek’ abana bato bansange!"}, {"type": "verse", "number": 2, "content": "Nzeger’ intebe ye ngo mutur’ amasengesho, Maze musabe kuba mu rukundo rwe,\nKand’ uko ndushaho kumushaka mur’ iyi si, Nizeye ko nzamubona mw’ ijuru.\nYagiye mw’ ijuru guteguray’ amazu meza, Azaturwamo n’ abacunguwe gusa.\nAbana benshi bazaba bateraniyeyo, Kuk’ ubwami bwo mw’ ijuru ar’ ubwabo."}, {"type": "verse", "number": 3, "content": "Abantu benshi bazimiriye mur’ iyi si, Ntabwo barumv’ inkuru y’ iwacu heza,\nNdifuza ko bamenya ko har’ umwanya wabo, Kandi Yesu ni w’ ubahamagara.\nNdifuza kuzishima kur’ uwo munsi mukuru, Uzab’ ar’ umuns’ urut’ iyindi yose.\nUbw’ abana bo mw’ isi yose bazaterana, Akabaher’ umugish’ icyarimwe."}]},
  {"number": 299, "name": "Urukundo Yes’ Ankunda", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/299", "key": "sol", "references": [{"codes": "S. 648"}, {"title": "MORE THAN TONGUE CAN TELL"}], "body": [{"type": "verse", "number": 1, "content": "Urukundo Yes’ ankunda, Rwatumy’ abambwa ku giti,\nKugira ngo nkomeze kubaho, Ntawarurondora."}, {"type": "chorus", "content": "Yankunz’ urukundo rwinshi (urukundo rwinshi),\nYankunz’ urukundo rwinshi (urukundo rwinshi),\nUrukundo Umukiz’ ankunda, Nta warurondora."}, {"type": "verse", "number": 2, "content": "Uburyo yambabarijwe, Yambitsw’ ikamba ry’ amahwa,\nKugira ngo nkomeze kubaho, Nta wabirondora."}, {"type": "verse", "number": 3, "content": "Mfit’ amahoro muri we, Kukw’ ansabira kuri Se,\nUko yankirishij’ amaraso, Nta wabirondora."}, {"type": "verse", "number": 4, "content": "Iyo ndi kumwe na Yesu, Amber’ uburuhukiro,\nIbyiringiro mfite muri We, Nta wabirondora."}]},
  {"number": 300, "name": "Umwami Arakomanga", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/300", "key": "do", "references": [{"codes": "HL. 472"}, {"title": "THE LORD IS AT THE DOOR"}], "body": [{"type": "verse", "number": 1, "content": "Umwam‘ arakomanga,\nAshaka kubana nawe,\nMbeg‘ ibyishimo kubana na we!\nKingurira uwo Mwami."}, {"type": "verse", "number": 2, "content": "Witinya kumusanga!\nAraguh‘ ibyiringiro,\nN‘ ibyishimo mu mutima wawe.\nEse ntubona umucyo?"}, {"type": "verse", "number": 3, "content": "Kumwakira ni byiza,\nN‘ ukubabarirwa na we,\nN‘ ijuru Imana iguhaye,\nAraguha amahoro."}, {"type": "verse", "number": 4, "content": "Ahagaze ku rugi,\nAshak‘ umutima wawe.\nMbeg‘ ibyishimo umwakiriye,\nAkakubera Umwami."}]},
  {"number": 301, "name": "Reka Yesu Yinjire Mu Mutima Wawe", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/301", "key": "la bémol", "references": [{"codes": "CS. 25"}, {"title": "LET JESUS COME INTO YOUR HEART"}], "body": [{"type": "verse", "number": 1, "content": "Reka Yesu yinjire mu mutima wawe maz’ akuruhure,\nNiba wifuz’ ubugingo bushya, Umwakire mu mutima."}, {"type": "chorus", "content": "Ubu wishidikanya, Reka kumwihakana,\nMuh’ umutima wawe, Wumwegurire burundu."}, {"type": "verse", "number": 2, "content": "Nib’ ushaka kumutunganira, Umwemerere akuzemo,\nHafi yawe har’ isoko yeza, Sanga Yes’ agutunganye."}, {"type": "verse", "number": 3, "content": "Nushaka kuzamuririmbira, Umwemerere akuzemo,\nNib’ ushaka kuzabana na we, Umwakire mu mutima."}]},
  {"number": 302, "name": "Umunsi W’ Umuzuko", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/302", "key": "ré", "references": [{"codes": "CH. 135"}, {"title": "THE DAY OF RESURRECTION"}], "body": [{"type": "verse", "number": 1, "content": "Umunsi w‘ umuzuko, Umuns‘ utangaje,\nHazab‘ umunezero, Tuzabon‘ Imana,\nAbera bazakangurwa, Bazamurwe mu bicu,\nBaririmb‘ indirimbo, Nziza yo kunesha."}, {"type": "verse", "number": 2, "content": "Tuzezwa imitima, Tuzabona Yesu,\nTuzabana n‘ Imana mu mucy‘ utazima,\nTuzahora duhimbaza, Dushim‘ Imana yacu,\nYo yatuneshereje, Iduh‘ agakiza."}, {"type": "verse", "number": 3, "content": "Wa juru we ishime, Wa si we ririmba,\nAbanambye ku Mana, Baranesherejwe,\nIbindi biremwa na byo, Byishime binezerwe,\nUmwami wacu Yesu, Nasingizw‘ iteka."}]},
  {"number": 303, "name": "Ntukumvir’ Umubi", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/303", "key": "si bémol", "references": [{"codes": "AH. 468"}, {"title": "YIELD NOT TO TEMPTATION"}, {"codes": "CH. 498"}], "body": [{"type": "verse", "number": 1, "content": "Ntukumvir’ umubi ujy’ agushuka, Umwumviye wese ab’ acumuye,\nWamutsinda none kubw’ Umukiza, Byagufash’ ubundi kujy’ umunesha."}, {"type": "chorus", "content": "Saba Yes’ agufashe, Kand’ aguhumurize,\nYemeye kukurinda, Azatum’ utsinda."}, {"type": "verse", "number": 2, "content": "Wirind’ ubucuti bw’ abantu babi, Bakunda kukoshya gukor’ ibibi.\nNtukavug’ ijambo ritey’ isoni, Ujye wubaha izina ry’ Imana."}, {"type": "verse", "number": 3, "content": "Ujy’ ugira neza, Ufash’ abandi, Wirinde kubeshya, Ahubw’ ujy’ uba,\nInyangamugayo kukw’ iby’ aribyo, Bikundwa na Yesu, Uzagufasha."}, {"type": "verse", "number": 4, "content": "Unesha Satani yandikiwe ko, Azahabw’ ikamba n’ Umukiza we,\nTugir’ intege nke, Ariko Yesu, Ni we Mutabazi, Udushoboza."}]},
  {"number": 304, "name": "Nzabana N’ Umwami", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/304", "key": "la bémol", "references": [{"codes": "S. 917"}, {"title": "FOR EVER WITH THE LORD!"}], "body": [{"type": "verse", "number": 1, "content": "Nzabana n’ Umwam’ ibihe bidashira,\nIryo jambo rivuga ngo: Nzatur’ ibudapfa,\nN’ ubwo nkingiranywe mur’ uyu mubiri,\nBuzacya negereje gutah’ iwacu heza."}, {"type": "chorus", "content": "Iwacu, Iwacu, Ngeze hafi yaho."}, {"type": "verse", "number": 2, "content": "Mu rugo rw’ Umwami ndahararikira,\nKwizera ni ko kunyerek’ amarembo yaho,\nN’ ubwo njya ncogora s’ ukutahashaka,\nIyo gakondo y’ abera ni Yerusalemu."}, {"type": "verse", "number": 3, "content": "Njya ngotwa n’ ibyaha, Nkumva ndacogoye,\nNkabur’ aho mfata nka ya numa yo mu nkuge,\nIbicu byeyutse, Umukororombya,\nW’ ihumure urasira mu mutima wanjye."}, {"type": "verse", "number": 4, "content": "Nkund’ izo ndirimbo zihora mw’ ijuru,\nIzo mw’ isi yacu ni nk’ indimi z’ i Babeli,\nHarihw’ icyo nkunda, Nukw’ abazazuka,\nBazongera kubana na Yesu, Yee, Amina."}]},
  {"number": 305, "name": "Mwami Yesu Mugenga", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/305", "key": "mi bémol", "references": [{"codes": "SDAH. 240"}, {"title": "FAIREST LORD JESUS"}, {"codes": "SP. 72"}, {"codes": "HL. 190"}], "body": [{"type": "verse", "number": 1, "content": "Mwami Yesu Mugenga w’ ibi bintu byose,\nWambay’ ubumuntu ku bwacu.\nNdakwiyeguriye, nzakubaha;\nKuk’ ur’ ikuzo n’ ikamba ryanjye."}, {"type": "verse", "number": 2, "content": "Icyanya ni cyiza, n’ amashyamba ni meza,\nN’ ibimera na byo ni byiza;\nYes’ urabirusha, kand’ uraboneye;\nUturuhur’ imitima."}, {"type": "verse", "number": 3, "content": "Umucyo ni mwiza, Umwez’ ukawurusha,\nN’ umucyo w’ inyenyeri n’uko.\nYes’ urabirusha, kand’ uraboneye,\nKurush’ abamarayika."}]},
  {"number": 306, "name": "Umwami Arahamagara", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/306", "key": "la bémol", "references": [{"codes": "SS. 476"}, {"title": "THE SAVIOR IS CALLING"}, {"codes": "S. 756"}], "body": [{"type": "verse", "number": 1, "content": "Umwam’ arahamagara abasaruzi bitanze,\nIbisarurwa bireze abasaruzi ni bake."}, {"type": "chorus", "content": "Nimuhaguruke mushikame,\nMw’ izina ry’ uwo Mwami,\nMuvuge inkuru y’ agakiza,\nMuyamamaze hose."}, {"type": "verse", "number": 2, "content": "Nimwihute mutabare abari mu byaha bose,\nMubatabaz’ amaboko muc’ ingoyi zibaboshye."}, {"type": "verse", "number": 3, "content": "Nimumenyesh’ abakene na bo baze mu birori,\nYes’ umutsim’ uhoraho yiteguye kubakira."}, {"type": "verse", "number": 4, "content": "Nimwihute dor’ igihe cy’ isarura kirashize,\nHagiye kuzab’ igihe tutazabasha gukora."}]},
  {"number": 307, "name": "Urukundo Rw’ Imana Yacu", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/307", "key": "mi bémol", "references": [{"codes": "SY. 7"}, {"title": "THE LOVE OF GOD"}], "body": [{"type": "verse", "number": 1, "content": "Urukundo rw’ Imana yacu, Nta muntu warurondora,\nRusaguts’ ikirere cyose, Rugera no munsi y’ isi.\nAbantu bose bacumuye, Bacunguwe na Yesu,\nUmwana we wese wahabye, Yaramwicunguriye."}, {"type": "chorus", "content": "Mbeg’ urukundo rutangaje, Rutagir’ urugero,\nAbera bazaruririmba, Ibihe bidashira."}, {"type": "verse", "number": 2, "content": "Ubw’ ibihe bizah’ ibindi, N’ ubwami bw’ isi bwashize,\nAbantu bakanga gusenga, Amabuy’ azaririmba.\nUrukundo rw’ Imana yacu, Ntabwo rurondoreka,\nRwacunguy’ abo mw’ isi bose, Ruzaririmbw’ iteka."}, {"type": "verse", "number": 3, "content": "Inyanja zose zaba wino, N’ ijuru ryab’ impapuro,\nTukandikisha agati kose, Umuntu wes’ akandika,\nUrukundo rw’ Imana yacu, Rwakamy’ inyanja zose,\nNtabwo rwabon’ aho rukwirwa, Rusaguts’ ikirere."}]},
  {"number": 308, "name": "Umukiza Aragutegereje", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/308", "key": "fa", "references": [{"codes": "SDAH. 289"}, {"title": "THE SAVIOUR IS WAITING"}, {"codes": "GH. 125"}], "body": [{"type": "verse", "number": 1, "content": "Umukiza aragutegereje, Ntiwamusanga none?\nNtaby’ isi bigomba kumukuvutsa, Mbes’ ub’ uribaz’ iki ?"}, {"type": "chorus", "content": "Umukiz’ aragutegereje,\nAracyagutegereje,\nNgw’ arebe ko wemera gukingura,\nMbeg’ ubury’ abyifuza."}, {"type": "verse", "number": 2, "content": "Nshuti ter’ intambw’ ugan’ Umukiza, Agutez’ ibiganza,\nNumwemerera arakuruhura, Muban’ iteka ryose."}]},
  {"number": 309, "name": "Ubutumwa Bw’ Ubuntu", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/309", "key": "sol", "references": [{"codes": "S. 490"}, {"title": "THE GOSPEL OF THY GRACE"}], "body": [{"type": "verse", "number": 1, "content": "Ubutumwa bw’ ubuntu bwanyuz’ umutima,\nImana yadutangiy’ Umwana wayo."}, {"type": "chorus", "content": "Ng’ umwizera wes’ adapf’\nAhubw’ ahabw’ ubugingo,\nAhubw’ ahabw’ ubugingo bw’ iteka."}, {"type": "verse", "number": 2, "content": "Nk’ uko Mose yamanits’ inzoka ku giti,\nNiko Yesu yamanitswe ngo tubeho."}, {"type": "verse", "number": 3, "content": "Numvise yuk’ ukor’ ibyaha wes’ azapfa,\nNone ndahabutse kubw’ Ijambo ryawe."}, {"type": "verse", "number": 4, "content": "Yesu ntabwo yaje kuducirahw’ iteka,\nAhubwo yaj’ atuzaniy’ agakiza."}, {"type": "verse", "number": 5, "content": "Mwami ndakwinginz’ ongera kwizera kwanjye,\nNakir’ iby’ ubutumwa bwawe bumbwira."}]},
  {"number": 310, "name": "Hariho Uburuhukiro Muri Paradizo", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/310", "key": "mi bémol", "references": [{"codes": "S. 989"}, {"title": "THERE IS A PARADISE OF REST"}], "body": [{"type": "verse", "number": 1, "content": "Hariho uburuhukiro muri paradizo,\nAhatazab’ umubabar’ ukundi, Tuzahurirayo."}, {"type": "chorus", "content": "S. : Tuzateranirayo, Tuzahurirayo\nKuri rwa ruzi, Tuzateranirayo,\nMu musek’ igitondo gitangaje.\nA., T. na B.: Tuzate..., nirayo, Tuzahurirayo\nKuri rwa ruzi, Tuzate… nirayo,\nMu musek’ igitondo gitangaje."}, {"type": "verse", "number": 2, "content": "Hariy’ umudugudu mwiza utatswem’ umucyo,\nAho ni hw’ abakiranutsi bazibanira n’ Umwami."}, {"type": "verse", "number": 3, "content": "Hariyo amakamba meza, Ayo tuzambikwa,\nKristo yateguriy’ abamutegereje bihanganye."}, {"type": "verse", "number": 4, "content": "Jy’ ukiranuk’ ibihe byose, N’ubwo wabizira,\nYesu yasezeranye kw’ azaguh’ ikamba ry’ ubugingo."}]},
  {"number": 311, "name": "Mukristo Ube Maso", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/311", "key": "mi bémol", "references": [{"codes": "AH. 603"}, {"codes": "S. 687"}, {"title": "WATCH AND PRAY"}], "body": [{"type": "verse", "number": 1, "content": "Mukristo ube maso, Nturuhuke na hato,\nAkaga kari hafi, Usenge!"}, {"type": "verse", "number": 2, "content": "Ababisha b’ Imana bajya bakubikira,\nBaguciriy’ ibico, Usenge!"}, {"type": "verse", "number": 3, "content": "Kenyer’ intwaro zawe ku manywa na nijoro,\nDor’ umwanz’ arakaze, Ba maso!"}, {"type": "verse", "number": 4, "content": "Umv’ abatsinze kera iyo ntambar’ urwana,\nBarakubwira bati: Usenge!"}, {"type": "verse", "number": 5, "content": "Umva Umwami wawe, Yesu wagupfiriye,\nNi we wategets’ ati: Wirinde!"}, {"type": "verse", "number": 6, "content": "Bik’ iryo jambo ryiza, Mu mutima wemera,\nKandi unabikore usenga."}]},
  {"number": 312, "name": "Mbese Wahereye Ryari?", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/312", "key": "la bémol", "references": [{"codes": "GH. 20"}, {"title": "HOW LONG HAS IT BEEN?"}], "body": [{"type": "verse", "number": 1, "content": "Mbese wahereye ryari uvugana n’ Umwam’ umutakambira?\nMbese wahereye ryar’ usenga, Ugez’ ubw’ ukesh’ ijoro?\nMbese wamaz’ igihe kingan’ iki wumva yuk’ utay’ umuruho?\nSe wamwit’ inshuti, Wamenye ryari, Kw’ akurind’ akakwitaho?"}, {"type": "verse", "number": 2, "content": "Mbese wahereye ryar’ upfukam’ useng’ Uhorah’ uri mw’ ijuru?\nSe wameny’ ute ko wasubijwe, Akakurinda bugacya?\nUkamenya ko wiriz’ uwo munsi, Mbese wamwit’ inshuti yawe?\nMbese wamenye ryari kw’ akwitaho, Kandi akanakurinda?"}]},
  {"number": 313, "name": "Igihe Cyo Kugaruka K’ Umwami", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/313", "key": "mi bémol", "references": [{"codes": "SDAH. 212"}, {"title": "TIS ALMOST TIME FOR THE LORD TO COME"}, {"codes": "CH. 182"}], "body": [{"type": "verse", "number": 1, "content": "Igihe cyo kugaruka k’ Umwami kiregereje rwose,\nInyenyeri zicwekereye, Kubw’ umucyo w’ igitondo gitangaje."}, {"type": "chorus", "content": "Mbes’ aho ntiburi hafi gucya!\nMbes’ aho ntiburi hafi gucya!\nMbese ntabw’ ubona k’ umusek’ utambitse!\nMbese k’ ubanza bugiye gucya!"}, {"type": "verse", "number": 2, "content": "Ibimenyetso byose byahanuwe ku zuba no ku kwezi,\nBirahamiriz’ umuntu wese ko kuza k’ Umwami kutwegereye."}, {"type": "verse", "number": 3, "content": "Iki n’ igihe rwos’ itorero rikwiye guhaguruka,\nKandi rikwiriye kuba maso, Kuko bidatinze bugiye gucya."}, {"type": "verse", "number": 4, "content": "Nimusohoke mujye mu nzira ngari no mu nzira ntoya,\nNimubwir’ ibirema n’ impumyi ko kuza kw’ Umwami kutwegereye."}]},
  {"number": 314, "name": "Ye Byose Biba Byiza", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/314", "references": [{"codes": "HL. 523"}, {"title": "OUI, TOUT EST BIEN"}], "body": [{"type": "verse", "number": 1, "content": "Ye byose biba byiza sinzatinya,\nNkeney’ urukundo ruhebuje,\nImiyaga n’ imigaru biratuza.\nImana yacu y’ impuhwe nyinshi itwitaho."}, {"type": "chorus", "content": "Mu mibabar’ idusagiriz’ ibyiza,\nIradukunda, Iraturinda;\nMu makuba, Iradukomeza;\nKukw’ Imana yacu yumva gutaka kwacu,\nIrindira igihe cyayo kuzagez’ imperuka."}, {"type": "verse", "number": 2, "content": "Byose biba byiz’ Iman’ inyitaho,\nMunsi y’ amababa ye sintinya.\nNta cyago cyankuraho amahoro ye.\nIyo niringiy’ Imana mu mutima wanjye."}, {"type": "verse", "number": 3, "content": "Biba byiza Yesu, Yabibwiy’ abe.\nMukumbi wanjye muto ntutinye.\nIman’ iri ku ngoma is’ irabizi.\nIsi n’ ijuru bizuzura ikuzo ryayo."}]},
  {"number": 315, "name": "Harih’ Umunt’ Umwe", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/315", "key": "fa", "references": [{"codes": "AH. 48"}, {"title": "THERE WAS ONE WHO WAS WILLING"}, {"codes": "CH. 123"}], "body": [{"type": "verse", "number": 1, "content": "Harih’ umunt’ umwe wapfuye ku bwanjye,\nKandi ntibyari bikwiriye,\nYemeye kujyanw’ ajya ku musaraba,\nKubwo kumbabarir’ ibyaha."}, {"type": "chorus", "content": "Byarabambwe byose, Byarabambwe byose,\nYemw’ uko yabyikorey’ ubwe!\nYemwe ngo arababara cyan’ ajyayo!\nAjyanyweyo n’ ibyaha byanjye."}, {"type": "verse", "number": 2, "content": "N’ umugwaneza kand’ arankunda cyane,\nYez’ umutima wanjy’ ibyaha,\nSincirw’ urubanza, Mfit’ umudendezo,\nKuko yambabariy’ ibyaha."}, {"type": "verse", "number": 3, "content": "Nzabana n’ Umukiza akaramata,\nNzajya ngendana na w’ iteka,\nNdirimbish’ umunwa n’ umutima wanjye,\nKuko nababariw’ ibyaha."}]},
  {"number": 316, "name": "Yesu Araje", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/316", "key": "si bémol", "references": [{"codes": "S. 178"}, {"title": "JESUS IS COMING"}], "body": [{"type": "verse", "number": 1, "content": "Yes’ araje nimubyamamaze, Aje kujyan’ abo yacunguye,\nAzanywe no kwimik’ ingoma ye, Yesu agiye kuza."}, {"type": "chorus", "content": "Yes’ agiye kugaruka vuba,\nYesu agiye kuza ( agiye kuza ),\nNimubyamamaz’ ahantu hose, Agiye kugaruka."}, {"type": "verse", "number": 2, "content": "Yes’ araj’ abapfuye bazuke, Maz’ abatoni be baterane,\nBahurire na we mu kirere, Yesu agiye kuza."}, {"type": "verse", "number": 3, "content": "Yes’ azanywe no gukiz’ abera, Azanywe no gutang’ amahoro,\nImibabaro yos’ izashira, Yesu agiye kuza."}, {"type": "verse", "number": 4, "content": "Yes’ araje nk’ uko yabivuze, Ni bande batowe bamwizeye,\nBamutegereje bari maso? Yesu agiye kuza."}]},
  {"number": 317, "name": "Mfite Umukiza", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/317", "key": "fa", "body": [{"type": "verse", "number": 1, "content": "HAVE YOU A SAVIOUR?"}, {"type": "verse", "number": 1, "content": "Mfit’ Umukiz’ ukomey’ undind’ iteka?\nUnyobor’ intambwe ngo ntayob’ inzira,\nNi w’ uyobora buri ntambwe y’ uhabye,\nMbes’ ufit’ Umukiza nk’ uwo?"}, {"type": "chorus", "content": "Mfit’ Umukiza umez’ atyo (atyo)!\nSe nawe n’ Umukiza wawe ( ...kiza wawe)?\nYanyinjiyemo, Ntabwo ateze kumvamo,\nSe nawe n’ Umukiza wawe ( ...kiza wawe)?"}, {"type": "verse", "number": 2, "content": "N’ Umukiza niringir’ ibihe byose,\nMu byago n’ amakub’ ampor’ iruhande,\nNo mu bishukw’ arandinda bitangaje,\nMbes’ ufit’ Umufasha nk’ uwo?"}, {"type": "verse", "number": 3, "content": "Mfit’ Umwungeri mwiz’ ukund’ intama ze,\nAzihamagara mu mazina yazo,\nAzih’ ubwatsi bwiza n’ amazi meza,\nMbes’ ufit’ Umwungeri nk’ uwo?"}]},
  {"number": 318, "name": "Ngwin’ Umukiz’ Aragushaka", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/318", "key": "si bémol", "references": [{"codes": "S. 413"}, {"title": "COME TO THE SAVIOR, HEAR HIS LOVING VOICE"}], "body": [{"type": "verse", "number": 1, "content": "Ngwin’ ub’ Umukiz’ aragushaka, N’ inshuti nziza y’ ukuri,\nUbu ngub’ aragutegereje, Arakwinginga ngwino."}, {"type": "chorus", "content": "Umukiz’ ahagaze ku rugi,\nGira bwang’ umusab’ imbabazi,\nWitindigany’ arategereje,\nGira n’ ingoga ngwino."}, {"type": "verse", "number": 2, "content": "Umv’ amagambo ye y’ ihumure, Yesu n’ inshuti y’ ukuri,\nMusange n’ isoko y’ ubugingo, Ntabw’ uzabur’ umwanya."}, {"type": "verse", "number": 3, "content": "Umvir’ uwo Mwuk’ ukongorera, Wisuzugur’ uwo Mwami,\nMwakire vuba witindiganya, Hahirw’ umwakiriye."}]},
  {"number": 319, "name": "Isengesho Ryanjye", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/319", "key": "sol", "references": [{"codes": "GH. 57"}, {"title": "MY PRAYER"}], "body": [{"type": "verse", "number": 1, "content": "Isengesho ryanjye Mwami nyumvira, Nyobora mu nzira,\nMu birushya byo mur’ ubu buzima, Jy’ umpor’ iruhande."}, {"type": "verse", "number": 2, "content": "Har’ ibigeragezo byinshi mpura na by’ aho njya hose,\nMfash’ umpe kub’ umunyakuri, Kandi mb’ umukiranutsi."}, {"type": "verse", "number": 3, "content": "Igih’ ub’ ubuzima buzaba bugeze kw’ iherezo,\nNdagusaby’ uzampe kubana nawe mu bwami bw’ ijuru."}]},
  {"number": 320, "name": "Bibiliya Ibumburiw’ Isi", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/320", "key": "si bémol", "references": [{"codes": "S. 262"}, {"title": "AN OPEN BIBLE FOR THE WORLD"}], "body": [{"type": "verse", "number": 1, "content": "Bibliy’ ibumburiw’ isi, Iyo ni yo ntego yayo;\nTumenyesh’ abant’ ukuri, Twamamaz’ inkuru nziza."}, {"type": "chorus", "content": "Jambo ry’ Imana murika,\nHos’ imusozi no mu nyanja;\nMaz’ abahabye bahabuke,\nBasang’ Imana Rurema."}, {"type": "verse", "number": 2, "content": "Ahw’ igeze hak’ umucyo, Hab’ amazi y’ ubugingo.\nNta mwijim’ uyihangara, Ihishur’ ibyaha byose."}, {"type": "verse", "number": 3, "content": "Iyobor’ abantu bose, Mu bwiza bw’ Imana yacu.\nIbyuts’ abaguye bose, Ni y’ ivug’ iby’ agakiza."}, {"type": "verse", "number": 4, "content": "Ni y’ iruhur’ imitima, Igahoz’ abahogoye.\nIgobok’ abacogoye, Bakagir’ ibyiringiro."}]},
  {"number": 321, "name": "Reb’ Ibimenyetso", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/321", "key": "sol", "references": [{"codes": "SDAH. 596"}, {"title": "LOOK FOR THE WAY MARKS"}], "body": [{"type": "verse", "number": 1, "content": "Reb’ ibimenyetso by’ urugendo, Reb’ ibimenyetso birashira,\nBy’ imyak’ ishize by’ ubwami bune, Twe turi hehe? Reb’ urugendo."}, {"type": "chorus", "content": "Reba ibimenyetso by’ ubuhanuzi,\nBy’ ibihe byashize by’ ubwami bune,\nReba ibimenyetso by’ ubuhanuzi,\nByose byarangiye."}, {"type": "verse", "number": 2, "content": "Banyababloni bategets’ isi, Haz’ Abamedi n’ Abaperesi,\nAbagiriki batway’ iyi si, Haz’ Abaroma, Twe turi hehe?"}, {"type": "verse", "number": 3, "content": "Ko turi mu bihe by’ intege nke, Iby’ ibumba n’ icyuma byavanzwe;\nNuko tuzareb’ uko bizaba Yes’ agarutse, Kwim’ ingoma ye."}]},
  {"number": 322, "name": "Uwiteka N’ Umwungeri Wanjye", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/322", "key": "fa", "references": [{"codes": "SDAH. 552"}, {"title": "THE LORD’S MY SHEPHERD"}], "body": [{"type": "verse", "number": 1, "content": "Uwiteka n’ Umwungeri wanjye, Sinzakena na hato,\nAndyamisha mu cyanya cy’ iruhande rw’ amaz’ adasuma."}, {"type": "verse", "number": 2, "content": "Asubiz’ intege mu bugingo bwanjye mu gihe ntebye,\nAnyobor’ inzira yo gukiranuka kubw’ izina rye."}, {"type": "verse", "number": 3, "content": "N’ aho nanyura no mu gikombe cy’ igicucu cy’ urupfu,\nSinzatiny’ ikibi cyose Mwami kuko ndi kumwe nawe."}, {"type": "verse", "number": 4, "content": "Untunganiriza ameza mu maso y’ abanzi banjye,\nUnsize amavuta mu mutwe maze aratonyanga."}, {"type": "verse", "number": 5, "content": "Kugirirwa neza n’ imbabazi bizanyomahw’ iteka,\nNanjye nzaba mu nzu y’ Uwiteka ibihe bidashira."}]},
  {"number": 323, "name": "Nari Nararohamye Mu Byaha", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/323", "key": "si bémol", "references": [{"codes": "GH. 122"}, {"title": "LOVE LIFTED ME"}], "body": [{"type": "verse", "number": 1, "content": "( I Was Sinking Deep In Sin )"}, {"type": "verse", "number": 1, "content": "Nari nararohamye mu Nyanja y’ ibyaha,\nNta byiringiro nari mfite byo kuvamo,\nMaz’ Umukiza yumva gutabaza kwanjye,\nAb’ ari w’ unkuramo none ndiho."}, {"type": "chorus", "content": "Urukundo rwankuyemo,\nUbwo nari nabuze uwamfasha,\nUrukundo rwankuyemo,\nNari nabuz’ umfasha, Mbona Yesu."}, {"type": "verse", "number": 2, "content": "Muhay’ umutima wanjye mushikamyeho,\nNzajya ndirimb’ iteka icyubahiro cye,\nUrukundo nyakuri nzajya nduririmba,\nNi we nkesha kwizera n’ urukundo."}, {"type": "verse", "number": 3, "content": "Mutim’ ubabaye reba Yes’ agukize,\nNi w’ uzakurokora, Mu murab’ ukaze,\nAtegek’ inyanja zose zikamwumvira,\nArashaka kugukiz’ uyu munsi."}]},
  {"number": 324, "name": "Mbega Igitambo!", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/324", "key": "sol", "references": [{"codes": "SDAH. 198"}, {"title": "AND CAN IT BE?"}], "body": [{"type": "verse", "number": 1, "content": "Mbega igitambo cy’ amaraso,\nY’ Umukiza wapfuy’ ari njy’ azira!\nYambambiwe ku musaraba,\nAbitewe n’ ukw’ ankunda cyane,\nN’ urukundo rutangaje Mwami wanjye,\nKugira ngo wemere kubabara no kumpfira."}, {"type": "chorus", "content": "S. : Urukundo ruhebuje,\nNi rwo rwamuteye kumpfira,\nMbeg’ urukundo rutangaje,\nNgo ruratum’ ancungura!\nA., T. na B. : Urukundo ruhebuje, Ni rwo rwamute… kumpfira,\nMbeg’ uruku…rutangaje, Ngo ruratum’ ancungura."}, {"type": "verse", "number": 2, "content": "Yasiz’ intebe y’ ubwami ya Se,\nYemera kunyitangira ngo nkire,\nNari mbuz’ epfo na ruguru,\nImbabazi ze zirangoboka,\nMaz’ urukundo rwe runter’ umunezero,\nMperako mererwa neza mu mutima wanjye."}, {"type": "verse", "number": 3, "content": "Nari maz’ igihe kirekire,\nMboshywe n’ umwijima w’ ibyaha byanjye,\nMaze kumeny’ ineza yawe,\nNgukurikira mfit’ ibyishimo,\nKuko nari mbohowe ingoyi z’ ibyaha,\nMperako ndahaguruka, Ndagukurikira."}, {"type": "verse", "number": 4, "content": "Nta teka ncirwaho kuko ndi muri Yesu,\nNa w’ akab’ ari muri jye,\nNi we nkesha kubaho kwanjye,\nNkeger’ intebe ye ntacyo ntinya,\nNkambikw’ ikamba mbikesha uwancunguye,\nNtabwo nzahwema kumusingiz’ iteka ryose."}]},
  {"number": 325, "name": "Impanda Iravuze", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/325", "key": "do", "references": [{"codes": "HL. 115"}, {"title": "LA TROMPETTE A RETENTI"}], "body": [{"type": "verse", "number": 1, "content": "Impanda iravuze, Nimwumve, Nimwumve;\nIvugira mw’ ijuru, Yesu araje!\nWow’ uhunikira, Ngah’ umva, Ngah’ umva;\nKanguka, Ubyuke, Umwam’ araje!"}, {"type": "verse", "number": 2, "content": "Ese ntimwumv’ impanda, Nimwumve, Nimwumve;\nUmugen’ arayumva, Yes’ ari hafi.\nN’ ibyishimo byinshi, Nimwumve, Nimwumve;\nAraririmb’ ati: Yes’ ari hafi."}, {"type": "verse", "number": 3, "content": "Impanda iravuze, Nimwumve, Nimwumve;\nNimubyuke bwakeye, Umukw’ araje!\nN’ ibyishimo byinshi, Nimwumve, Nimwumve\nNgaho itegure, Dore araje!"}]},
  {"number": 326, "name": "Dufit’ Ibyiringiro", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/326", "key": "la bémol", "references": [{"codes": "SDAH. 214"}, {"title": "WE HAVE THIS HOPE"}], "body": [{"type": "verse", "number": 1, "content": "Dufit’ ibyiringiro by’ ukuri, Ko Yesu azagaruka,\nTwizezwa n’ uk’ ubwe yabivuze, Twizer’ isezerano rye,\nUbw’ amoko yo mw’ isi, Azarangurur’ ati:\nHaleluya, Yesu Kristo n’ Umwami w’ Abami,\nTwiringiye yuk’ Umwami wacu, Ari hafi kugaruka."}, {"type": "verse", "number": 2, "content": "Duhuriye muri Yesu Kristo, Duhujwe n’ urukundo rwe,\nAbantu bifuz’ urukundo rwe, Rwatumy’ acungur’ abantu,\nIjuru rizakinguka Kristo agaruke,\nAbantu baririmbe, Haleluya, Araje!\nDufit’ ibyiringiro mu Mana, Twibumbiye muri Kristo."}]},
  {"number": 327, "name": "Nkunda Igitabo Cyera", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/327", "key": "mi bémol", "references": [{"codes": "CH. 220"}, {"title": "I LOVE THE SACRED BOOK"}, {"codes": "HL. 186"}], "body": [{"type": "verse", "number": 1, "content": "Nkund’ igitabo cyera cy’ Imana, Ni cyo kindutir’ ibindi byose,\nKinyigish’ ibyiza byo mw’ ijuru, Nkameny’ inzira y’ agakiza."}, {"type": "verse", "number": 2, "content": "Gitabo cy’ ingenzi, muri wowe, Mpabon’ ubwiza bw’ Umwami wanjye,\nIbyanditswe byawe binyigisha, Iby’ umunezero nzagira."}, {"type": "verse", "number": 3, "content": "Ariko igihe nkiri mw’ isi, Umbwir’ iby’ urukundo rw’ Imana,\nNkarushaho gusobanukirwa, N’ umunezero wo mw’ ijuru."}, {"type": "verse", "number": 4, "content": "Ni wowe werekan’ imigambi, Yose ya Yes’ Umukiza wanjye,\nMuri wowe ni ho har’ ubwenge, N’ ubuhanga butarondorwa."}, {"type": "verse", "number": 5, "content": "Ur’ umucy’ umurikir’ ab’ isi, Ngo bave mu mwijima w’ ibyaha,\nNi wow’ umurikir’ imitima, Y’ abahabye bagahabuka."}]},
  {"number": 328, "name": "Ku Musaraba", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/328", "key": "mi", "references": [{"codes": "CS. 227"}, {"title": "AT THE CROSS"}], "body": [{"type": "verse", "number": 1, "content": "Imbere y’ Uhoraho ntabwo nkorwa n’ isoni,\nKand’ ijambo ryawe rinshimish’ ibihe byose."}, {"type": "chorus", "content": "Ku musaraba ni ho naboney’ umucyo,\nMbona gutur’ umutwaro wanjye,\nMbiboneshwa no kwizera,\nUherey’ ubu nzahora nezerewe."}, {"type": "verse", "number": 2, "content": "Yesu Mana yanjye nzi yukw’ ari ryo zina rye,\nNtazemerer’ umutima wanjye kuzimira."}, {"type": "verse", "number": 3, "content": "Yasezeranye yukw’ intebe y’ izahoraho,\nBiragaragara kw’ ibyo yavuz’ ar’ ukuri."}]},
  {"number": 329, "name": "Mana Yac’ Ur’ Umufasha", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/329", "key": "do", "references": [{"codes": "S. 513"}, {"codes": "SP. 21"}, {"title": "OUR HELP IN AGES PAST"}, {"codes": "CH. 81"}], "body": [{"type": "verse", "number": 1, "content": "Mana yac’ ur’ umufasha, Byiringiro byacu,\nBwugamo bw’ umugaru, Ni we buturo bwacu."}, {"type": "verse", "number": 2, "content": "Ku ntebe yawe y’ ubwami, Tubon’ amahoro,\nIyo dutabawe nawe, Tugir’ ihumure."}, {"type": "verse", "number": 3, "content": "Imisoz’ itarabaho, Is’ itarabumbwa,\nKuva kera kose Mana, Ur’ uko wahoze."}, {"type": "verse", "number": 4, "content": "Imyak’ igihumbi uyibona nk’ umuns’ umwe,\nNi migufi nk’ isah’ imwe, Ihita n’ ingoga."}, {"type": "verse", "number": 5, "content": "Man’ ur’ umufasha wacu, Byiringiro byacu,\nUtuber’ umuyoboz’ uzatugez’ iwacu."}]},
  {"number": 330, "name": "Ntabaza Yesu Iyo Mbabaye", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/330", "key": "ré", "references": [{"codes": "SDAH. 485"}, {"title": "I MUST TELL JESUS"}], "body": [{"type": "verse", "number": 1, "content": "Ntabaza Yesu iyo mbabaye, Ankiz’ imibabaro yanjye,\nMur’ iyo mibabaro ntampāna, Ahubw’ arantabara rwose."}, {"type": "chorus", "content": "Ntabaza Yesu, Ntabaza Yesu,\nKuko ntacyo nakwishoboza,\nNtabaza Yesu, Ntabaza Yesu,\nYesu gusa ni we wamfasha"}, {"type": "verse", "number": 2, "content": "Mu makuba yanjy’ arantabara, Kukw’ ari we nshuti y’ ukuri,\nIyo mutabaj’ arantabara, Ankiz’ imibabaro yanjye."}, {"type": "verse", "number": 3, "content": "Mbeg’ ukuntu iby’ isi binshuka, Bikanyoshya gukor’ ibyaha,\nMbibwire Yesu kand’ azamfasha, Ni w’ uzampa gutsind’ iby’ isi."}]},
  {"number": 331, "name": "Mwuka Wera", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/331", "key": "fa", "references": [{"codes": "SDAH. 262"}, {"title": "SWEET, SWEET SPIRIT"}], "body": [{"type": "verse", "number": 1, "content": "Aha hantu har’ amahoro, Kandi hari n’ Umwuka Wera w’ Uhoraho,\nKandi n’ umuntu wese uhari, Afit’ umunezero mwinshi bihebuje."}, {"type": "chorus", "content": "Mwuka Wera We, We numa nziza,\nUbane natwe, Utwuzuz’ urukundo,\nTuraguhimbaza kuk’ uduhira,\nTurataha tudashidikanya yuko duhiriwe twese."}]},
  {"number": 332, "name": "Nzabon’ Umwami", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/332", "key": "la bémol", "references": [{"codes": "SDAH. 426"}, {"title": "I SHALL SEE THE KING"}], "body": [{"type": "verse", "number": 1, "content": "Nzabon’ Umwami wanjy’ aririmbirwa n’ abamarayika,\nTuzabana na w’ iteka ryose, mu gihugu cy’ ibyiza."}, {"type": "chorus", "content": "Tuzahorana ibihe byose,\nYankirije i Kalvari.\nAmaherezo nzabon’ Umwami,\nWanyitangiye kera."}, {"type": "verse", "number": 2, "content": "Mur’ icyo gihugu cyiza nta joro rizabay’ ukundi.\nNzabana n’ Umwami wancunguje amaraso y’ akiza."}, {"type": "verse", "number": 3, "content": "Nzabana n’ Umwami wanjye nkunda, nzamureba mu maso,\nNzamuririmbira mushimira Ubuntu yangiriye."}]},
  {"number": 333, "name": "Icyampa Kugendana N’ Imana", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/333", "key": "sol", "references": [{"codes": "SDAH. 315"}, {"title": "O FOR A CLOSER WALK"}, {"codes": "CH. 383"}], "body": [{"type": "verse", "number": 1, "content": "Icyampa kugendana n’ Imana, Mu nzir’ ijya mw’ ijuru,\nNi byo byamber’ umucy’ ungeza, Ku Mwana w’ Intama."}, {"type": "verse", "number": 2, "content": "Garuka, Mukunzi garuka, Ntumwa nziza y’ amahoro,\nNang’ ibyaha byakubabaje, Bikantanya nawe."}, {"type": "verse", "number": 3, "content": "Mbega ngo ndagir’ amahoro, Ntazigera nibagirwa!\nAriko byansizemw’ imvun’ itakungwa n’ ab’ isi."}, {"type": "verse", "number": 4, "content": "Icyo nagusimbuje cyose, Uko cyaba kiri kose,\nMfasha nitandukanye na cyo, Ngusenge wenyine."}]},
  {"number": 334, "name": "Nimumenyesh’ Abantu Bose", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/334", "key": "la bémol", "references": [{"codes": "SDAH. 202"}, {"title": "HAIL HIM THE KING OF GLORY"}, {"codes": "AH. 359"}], "body": [{"type": "verse", "number": 1, "content": "Nimumenyesh’ abantu bose ko Yes’ ari hafi,\nIs’ imurikirwe n’ umucyo, Maze Yes’ agaruke."}, {"type": "chorus", "content": "Nimusingiz’ uwo Mwana w’ Intama watambwe,\nNimwamamaze ko Yes’ agiye kwima."}, {"type": "verse", "number": 2, "content": "Amahanga yasubiranyemo, Muyaburire,\nIs’ imurikirwe n’ umucyo, Maze Yes’ agaruke."}, {"type": "verse", "number": 3, "content": "Bana b’ Imana, Nimuririmbe, Muyih’ ikuzo,\nHahirw’ ababa maso, Bukarinda butandukana."}]},
  {"number": 335, "name": "Nejejwe N’ Iri Turo", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/335", "key": "mi bémol", "references": [{"codes": "HL. 334"}, {"title": "C’ EST MON JOYEUX SERVICE"}], "body": [{"type": "verse", "number": 1, "content": "Nejejwe n’ iri turo ntuy’ Umwami Yesu,\nIgitambo kizima ni cyo jyew’ ubwanjye."}, {"type": "chorus", "content": "Akir’ ituro ryanjye We Mwana w’ Imana,\nKand’ umanurire ku mucyo uv’ ahera."}, {"type": "verse", "number": 2, "content": "Mpaz’ ubugingo bwanjye, Nticuza, ntatinya,\nKubw’ ubuntu bwawe warancunguye Mwami."}, {"type": "verse", "number": 3, "content": "Yesu ngwin’ unyigishe wowe wancunguye,\nNshaka kubana naw’ ibihe bidashira."}]},
  {"number": 336, "name": "Dusingiz’ Uwiteka", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/336", "key": "sol", "references": [{"codes": "S. 765"}, {"title": "LET US WITH A GLADSOME MIND"}], "body": [{"type": "verse", "number": 1, "content": "Dusingiz’ Uwiteka, Tumushimir’ ineza ye,\nKukw’ imbabazi ze nyinshi, Zizahorahw’ iteka."}, {"type": "verse", "number": 2, "content": "Umuremyi wa byose, Uwakwij’ umucyo kw’ isi,\nAgir’ imbabazi nyinshi, Zizahorahw’ iteka."}, {"type": "verse", "number": 3, "content": "Abibeshaho byose, Akabimar’ ubukene,\nAgir’ imbabazi nyinshi, Zizahorahw’ iteka."}, {"type": "verse", "number": 4, "content": "Yahiriy’ ubwoko bwe, Ubwo bwari mu butayu,\nAgir’ imbabazi nyinshi, Zizahorahw’ iteka."}, {"type": "verse", "number": 5, "content": "Ni nyir’ impuhwe nyinshi, Ameny’ ubukene bwacu,\nAgir’ imbabazi nyinshi, Zizahorahw’ iteka."}, {"type": "verse", "number": 6, "content": "Tumusingiz’ iteka, Kubw’ imbabazi ze nyinshi,\nAhoran’ impuhwe nyinshi, Zizahorahw’ iteka."}]},
  {"number": 337, "name": "Kuber’ Iki Utindiganya?", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/337", "references": [{"codes": "HL. 475"}, {"title": "POURQUOI DONC ATTENDRE?"}], "body": [{"type": "verse", "number": 1, "content": "Kuber’ iki utindiganya? Yes’ aragushaka none,\nHaguruk’ uve mu mwijima, Aragukunda, Musange."}, {"type": "chorus", "content": "Kuki? Kuki? Utamusang’ uyu munsi?\nKuki? Kuki? Utamwitaba none?"}, {"type": "verse", "number": 2, "content": "Igihe kirahita vuba, Uyu munsi ni wo wawe,\nReka Yes’ aguhumurize, N’ ubutunzi bw’ igiciro."}, {"type": "verse", "number": 3, "content": "Ese ntiwumva mu mutima, Wuzuwe n’ Umwuka Wera?\nNtiwifuza kumurikirwa na Yesu agukomeze."}, {"type": "verse", "number": 4, "content": "Kuber’ iki wanga kwitaba? Urupfu rugusatira!\nNgwino Yes’ akumurikire, Ngwin’ aragutegereje"}]},
  {"number": 338, "name": "Ku Rutare Har’ Isoko", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/338", "key": "la", "body": [{"type": "verse", "number": 1, "content": "Ku Rutare har’ isoko, Itemb’ imar’ inyota,\nMugenzi ngwino kw’ isoko, Maz’ unywe ushir’ inyota.\nGububiramo: Yesu ni we Gitare,\nYaradupfiriye twese,\nMugenzi ngwino kw’ isoko,\nMaz’ unywe ushir’ inyota."}, {"type": "verse", "number": 2, "content": "Arahamagar’ ati: Ngwino kw’ isoko y’ ubuntu,\nMugenz’ ufit’ inyota, Mbese ntiwakwitaba Yesu?"}, {"type": "verse", "number": 3, "content": "Munyabyaha ngwino Yesu akwambuts’ ubutayu,\nUmukiz’ aragutegereje, Ngwino umusange."}]},
  {"number": 339, "name": "Ineza N’ Imbabazi", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/339", "key": "mi bémol", "references": [{"codes": "AYS. 171"}, {"title": "SURELY GOODNESS AND MERCY"}, {"codes": "GH. 131"}], "body": [{"type": "verse", "number": 1, "content": "Igihe nari nd’ inzererezi, Ngenda mu mwijima w’ ibyaha,\nNi h’ Umwungeri yantaruye, None ndi mu nzir’ ijy’ iwacu."}, {"type": "chorus", "content": "Ineza n’ imbabazi ze ni byo bizanyomaho,\nIminsi yo kubaho kwanjy’ ibihe byose,\nIneza n’ imbabazi ze ni byo bizanyomaho,\nIminsi yose nzaba ndiho.\nKandi nzaba mu nzu y’ Uwiteka iteka,\nNzarira ku meza yanteguriye kera,\nIneza n’ imbabazi ze ni byo bizanyomaho,\nIminsi yose nzaba ndiho.\n‘’Iminsi yose nzaba ndiho’’. (Ku gice cya 3)."}, {"type": "verse", "number": 2, "content": "Ansubiz’ intege mu bugingo, Anyonger’ imbarag’ iteka,\nAnjyan’ ahar’ amaz’ atuje, Arind’ intambwe zanjye zose."}, {"type": "verse", "number": 3, "content": "Mu gikombe cy’ umwijim’ ukaze, Umukiz’ azabana nanjye,\nAzanyoboz’ ukuboko kwe, Angez’ aho yanteguriye."}]},
  {"number": 340, "name": "Mur’ Iyi Si", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/340", "key": "do", "references": [{"codes": "CH. 311"}, {"title": "PEACE, PERFECT PEACE"}], "body": [{"type": "verse", "number": 1, "content": "Mur’ iyi si, yubitswe n’ ibyaha,\nDukomezwa n’ amahoro ya Yesu."}, {"type": "verse", "number": 2, "content": "Mu mihati yo mur’ iyi si mbi,\nGukor’ ibyo Yes’ ashaka, n’ ingenzi."}, {"type": "verse", "number": 3, "content": "N’ ubwo tugoswe n’ ibyago byinshi,\nMuri Yesu tuhabon’ amahoro."}, {"type": "verse", "number": 4, "content": "N’ ubw’ incuti zacu zaba kure,\nYes’ aduhor’ iruhande by’ ukuri."}, {"type": "verse", "number": 5, "content": "Yes’ ari ku ntebe ye y’ Ubwami,\nAhazaza hacu ni w’ uhafite."}]},
  {"number": 341, "name": "Yesu Niw’ Ujy’ Unyobora", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/341", "key": "sol", "references": [{"codes": "HL. 336"}, {"title": "JESUS IS MY SHEPHERD"}], "body": [{"type": "verse", "number": 1, "content": "Yesu ni w’ ujy’ unyobora, Amurikir’ inzira,\nMu ntege nke zanjye zose, Yesu ni w’ unyobora.\nGububiramo: Amurikir’ inzira, Amurikir’ inzira.\nMu ntege zanjye zose, Yesu ni w’ unyobora."}, {"type": "verse", "number": 2, "content": "Yesu ni w’ ujy’ undengera, Yamviriy’ amaraso,\nKwizera igitambo cye, Byatumye mbabarirwa.\nGububiramo: Yamviriy’ amaraso, Yamviriy’ amaraso.\nKwizera igitambo cye, Byatumye mbabarirwa."}, {"type": "verse", "number": 3, "content": "Anyezahw’ inenge zose, Igihe munambyeho,\nAmp’ ubugingo bw’ iteka, Ntandukana n’ urupfu."}, {"type": "chorus", "content": "Igihe munambyeho, Igihe munambyeho,\nAmp’ ubugingo bw’ iteka, Ntandukana n’ urupfu."}, {"type": "verse", "number": 4, "content": "Yanyishyuriy’ umwenda, Ufit’ igiciro cyinshi,\nYanteguriye umwanya, Nzabana na w’ iteka.\nGububiramo: Yesu warancunguye, Yesu warancunguye.\nYanteguriye umwanya, Nzabana na w’ iteka."}]},
  {"number": 342, "name": "Mukiza Wanjye Nyobora", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/342", "key": "si bémol", "references": [{"codes": "S. 596"}, {"title": "ANYWHERE MY SAVIOR LEAD"}], "body": [{"type": "verse", "number": 1, "content": "Mukiza wanjye, Nyobor’ ah’ ushaka,\nMfat’ ikiganza maze nkumve bugufi,\nNubw’ amahwa yampanda, Ngukurikire,\nNyobor’ ah’ ushaka, Mukiza wanjye."}, {"type": "chorus", "content": "S. : Nzagukurikira hose,\nMukiza wanjye, Ngukurikire,\nNzagukurikira Mukiza, Unyobore.\nA., T. na B. : Nzagukuriki…, …gukurikira hose,\nMukiza wanjye, Ngukurikire,\nNzagukuriki…, …rikira unyobore,\n…za unyobore, Nyobora."}, {"type": "verse", "number": 2, "content": "Mukiza wanjye, Nyobor’ ah’ ushaka,\nUkomez’ undinde unampumurize,\nNubw’ umwijima wab’ umbudits’ imbere,\nNtabwo nzatiny’ unyoboye Mukiza."}, {"type": "verse", "number": 3, "content": "Njyan’ ah’ ushaka Mwam’ icyo ngusaba,\nNyuza mu nzira ntoya ne guteshuka,\nNubwo Satan’ anyoshya anyongorera,\nMfasha njye nsubiza bwangu mpakana."}]},
  {"number": 343, "name": "Shimwa Ntama Y’ Imana", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/343", "key": "ré", "references": [{"codes": "CH. 168"}, {"title": "WORTHY, WORTHY, IS THE LAMB"}], "body": [{"type": "verse", "number": 1, "content": "Shimwa Ntama y’ Imana, Turagushima Ntama,\nShimwa Ntama y’ Imana, Turagushima cyane."}, {"type": "chorus", "content": "Shimwa haleluya,\nShimwa haleluya,\nSingizwa Mukiza,\nWowe Ntama y’ Imana."}, {"type": "verse", "number": 2, "content": "Ubwami bwawe buze, Dutsindire icyaha,\nWaradukunze cyane, Shimwa Ntama y’ Imana."}, {"type": "verse", "number": 3, "content": "Tukunambeho Mwami, Tujye tuguh’ ikuzo,\nTuri kumwe n’ Umwami, Ku musozi Siyoni."}]},
  {"number": 344, "name": "Nzahimbaza Imana", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/344", "key": "sol", "references": [{"codes": "CH. 23"}, {"title": "LORD, WITH GLOWING HEART I’D PRAISE THEE"}], "body": [{"type": "verse", "number": 1, "content": "Nzahimbaz’ Imana mfite umutima unyuzwe,\nKubw’ urukundo rwawe n’ imbabazi wangiriye,\nMfasha mu ntege nke zanjye, Unsindire icyaha.\nMurikir’ umutima wanjye, Nguhimbaze Mwami."}, {"type": "verse", "number": 2, "content": "Mutima wanjye umvira, Wubahe Uwiteka,\nUngarure hafi yawe, Ne kuyoba Mukiza,\nNarazimiye, Mvana mu nzira y’ urupfu Mwami.\nWampaye ibyiringiro igihe wampfiraga."}, {"type": "verse", "number": 3, "content": "Mfukamye imbere yawe, Ngushima Mwami wanjye,\nNdakwinginze Mwami mpa umugisha uyu munsi,\nNkeney’ urukundo n’ ubuntu biva kuri wowe.\nMaz’ imibereho yanjye ijy’ iguhesh’ ikuzo."}]},
  {"number": 345, "name": "Yesu Araguhamagara!", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/345", "key": "fa", "references": [{"codes": "AH. 167"}, {"title": "WHILE JESUS WHISPERS TO YOU"}, {"codes": "CH. 564"}], "body": [{"type": "verse", "number": 1, "content": "Yes’ arahamagara, Munyabyaha ngwino,\nUbu turagusabira, Nyamuna ngwino,\nArakwiteze munyabyaha, Ngwino, Ngwino,\nN’ igihe cyo kumumenya, Nyamuna ngwino."}, {"type": "verse", "number": 2, "content": "Nib’ uremerewe n’ ibyaha, Ngwino, Ngwino,\nYesu aragutur’ uwo mutwaro ngwino,\nYesu n’ umunyebambe, Munyabyaha ngwino,\nNi we wagucunguye, Munyabyaha ngwino."}, {"type": "verse", "number": 3, "content": "Umv’ ubury’ akwinginga, Munyabyaha ngwino,\nNgwin’ araguh’ umugisha, Nyamuna ngwino,\nAraguhamagara, Munyabyaha ngwino,\nUbu turagusabira, Nyamuna ngwino."}]},
  {"number": 346, "name": "Ndi Mu Maboko Akiza", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/346", "key": "do", "references": [{"codes": "S. 530"}, {"title": "THE HALLOW OF GOD’S HAND"}], "body": [{"type": "verse", "number": 1, "content": "Iy’ Umukiza wanjy’ anyoboye, Uko ndi kose ngir’ amahoro,\nAnkirish’ umuraba w’ ibyaha, Amaboko y’ akiza."}, {"type": "chorus", "content": "S. na A.: Ndi mu mabokw’ akiza, Amaboko y’ akiza,\nN’ ubwo naba ngeze no mu kaga,\nNdi mu mabokw’ akiza.\nT. na B.: Ndi mu mabo... ...kw’ aki... mabokw’ akiza,\nAmaboko akiza ....mabokw’ akiza,\nN’ ubwo naba ngeze no mu kaga,\nNdi mu mabokw’ akiza."}, {"type": "verse", "number": 2, "content": "Ahor’ andamiz’ amaboko ye, Akanambwiz’ ijwi ry’ ihumure,\nAti: Humura, Nzakuramiza, Amaboko akiza."}, {"type": "verse", "number": 3, "content": "Azandinda anyobor’ iteka, Ntacyo nzatinya ndi kumwe na we,\nNzi kw’ ahor’ andind’ iteka ryose, Ndi mu mabokw’ akiza."}]},
  {"number": 347, "name": "Manyur’ Umutsima", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/347", "key": "mi bémol", "references": [{"codes": "SDAH. 271"}, {"title": "BREAK THOU THE BREAD OF LIFE"}, {"codes": "CH. 218"}], "body": [{"type": "verse", "number": 1, "content": "Manyur’ umutsima w’ ubugingo,\nNk’ uko wabigize mu kibaya,\nNatw’ uduhaz’ Ibyanditswe Byera,\nTurakwifuza Jambo rizima."}, {"type": "verse", "number": 2, "content": "Mwami hir’ ukuri menyeshejwe,\nNk’ uko wahiriye wa mutsima,\nUri ku nyanja y’ i Galilaya,\nMbeshweho naw’ Ushobora byose."}, {"type": "verse", "number": 3, "content": "Mwam’ ur’ umutsima w’ ubugingo,\nIjambo ryawe rimbeshejeho,\nMpa guhazwa na ryo tuzabane,\nMpa kugukunda nzabane nawe."}, {"type": "verse", "number": 4, "content": "Amagamb’ uvuga n’ ubugingo,\nMfasha ngo nyumvire, jye nta ntege,\nNi wowe nkesh’ ubugingo bwanjye,\nIjambo ryawe rimpa gutsinda."}]},
  {"number": 348, "name": "Nakurikiye Yesu", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/348", "key": "la bémol", "references": [{"codes": "HL. 64"}, {"title": "SUIVRE JESUS"}], "body": [{"type": "verse", "number": 1, "content": "Nakurikiye Yesu mu kibaya akiz’ abarwayi,\nAc’ iminyururu y’ ibyaha no kuruhur’ imitwaro."}, {"type": "chorus", "content": "S.: Mbega ngo biranezeza gukurikira Yesu!\nAkanyoboz’ ubuntu bwe, Akangeza mw’ ijuru.\nA., T., B.: Mbega ngo biranezeza, gu – kuriki – ra Yesu! … .\nAkanyoboz’ ubuntu bwe, a - kangeza mw’ ijuru (mw’ ijuru)."}, {"type": "verse", "number": 2, "content": "Namukurikiye ku musoz’ igihe yahindurwaga,\nImana iravuga iti: Ur’ Umwana wanjye nkunda."}, {"type": "verse", "number": 3, "content": "Namukurikiy’ i Kalvari, Agend’ atukwa na benshi,\nAkomez’ inzira y’ Umwanzi, Yikorey’ umusaraba."}, {"type": "verse", "number": 4, "content": "Nzamukurikira nkiriho, Maz’ atume mpora nesha,\nKugez’ ubwo nzager’ iwacu, Ahahor’ umunezero."}]},
  {"number": 349, "name": "Nabony’ Umuntu Unaniwe", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/349", "key": "la bémol", "references": [{"codes": "SDAH. 441"}, {"title": "I SAW ONE WEARY"}, {"codes": "CH. 371"}], "body": [{"type": "verse", "number": 1, "content": "Nabony’ umunt’ unaniwe, Kand’ agenda yihanganye,\nYikorey’ umusaraba, Nyamara ntabwo yari yihebye.\nImibabar’ iba myinshi! Arik’ uw’ urahebuje!\nMubaz’ ikimuh’ intege, Ati: N’uko mfit’ ibyiringiro."}, {"type": "verse", "number": 2, "content": "Nabony’ afite n’ intwaro, Arwany’ iby’ is’ ashikamye,\nKand’ arwan’ amaramaje ngw’ azabon’ ikamba rihoraho.\nN’ubwo yari yarenganye, Ntiyigeze yivovota;\nMubaz’ ikimuh’ intege, Ati: N’uko mfit’ ibyiringiro."}, {"type": "verse", "number": 3, "content": "Nabony’ uwasiz’ inshuti ze, Bakundanaga cyane,\nAtandukana n’ iby’ isi, Ahitamw’ inzir’ imuruhije.\nN’ubw’ irimw’ ibibabaza, Arikw’ ariyumanganya,\nMubaz’ ikimuh’ intege, Ati: N’uko mfit’ ibyiringiro."}, {"type": "verse", "number": 4, "content": "Tur’ abagenzi mur’ iyi si, Y’ akaga n’ agahinda,\nIrimw’ ibyago n’ urwango, N’ ibituro byuzuyemw’ abantu,\nKugez’ ubwo Krist’ azaza, Akarokor’ abe bose,\nSe, n’ iki cyadukomeza, Atar’ ibyiringiro bishyitse?"}]},
  {"number": 350, "name": "Mugenzi Komera", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/350", "key": "sol", "references": [{"codes": "SDAH. 602"}, {"title": "O BROTHER, BE FAITHFUL"}, {"codes": "CH. 173"}], "body": [{"type": "verse", "number": 1, "content": "Mugenzi komera Yes’ ari hafi, Twamutegereje kera,\nTugiye kwitahir’ iwacu heza, Turirimbe ko dutsinze.\nTwihangane twe kumuhemukaho, Kandi w’ ataduhemukiye,\nYatwerets’ urukundo ruhebuje, Ni rwo rwatumy’ adupfira."}, {"type": "verse", "number": 2, "content": "Mugenzi komera, Utegerez’ umudugudu w’ izahabu,\nWateguriwe abakiranutsi, Ni ho tuzaruhukira.\nIhangane ntabwo tuzagum’ aha, Mu buhanya no mu miruho,\nHar’ ubw’ umwijim’ uzatamuruka, Igitondo gitangaze."}, {"type": "verse", "number": 3, "content": "Mugenzi komera dore araje, Uwo Muremyi wa byose,\nAzanye n’ abamarayika benshi, Azanye n’ ingororano.\nIhangan’ ugez’ igih’ Umukiza, Azakubwir’ aya magambo,\nNgo mugaragu mwiz’ ukiranuka, Igire mu munezero."}, {"type": "verse", "number": 4, "content": "Mugenzi ujy’ uhora wihanganye, Komeza kwizera kwawe,\nAmarira yawe ahanagurwe, Maz’ uzahabwe n’ ikamba.\nIhangane mwene Data ni koko, Isezerano rye n’ impamo;\nUzibanirayo n’ abakijijwe, Na Yes’ Umukiza wacu."}]},
  {"number": 351, "name": "Umunsi Mwiza Uri Bugufi", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/351", "key": "la bémol", "references": [{"codes": "GH. 74"}, {"title": "THERE WAITS A BETTER DAY"}], "body": [{"type": "verse", "number": 1, "content": "Dor’ umunsi mwiza ugiye kugera, Tukibera ibudapfa.\nAho tuzibera hahebuj’ ubwiza, N’ umuns’ utangaje!"}, {"type": "chorus", "content": "Umwijim’ ugiye gutamuruka,\nTukabah’ ubutazongera gupfa.\nMbega ihumure twahawe na Yesu!\nDor’ ari bugufi."}, {"type": "verse", "number": 2, "content": "Imitima yacu irahumurirwa, Ntabwo ijya igoheka.\nTurifuza kubon’ uwo munsi mwiza, Tuzaba mu bwiza."}, {"type": "verse", "number": 3, "content": "Za ntwari zasinzirany’ ibyiringiro, Tugiye kuzabonana.\nNta marir’ azongera kuturangwaho, Mu murwa w’ Imana."}]},
  {"number": 352, "name": "Nitugera Mw’ Ijuru", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/352", "key": "si bémol", "references": [{"codes": "SDAH. 633"}, {"title": "WHEN WE ALL GET IN HEAVEN"}], "body": [{"type": "verse", "number": 1, "content": "Turirimb’ urukundo rwa Yesu;\nImpuhwe ndetse n’ ubuntu bye.\nAri kudutegurir’ aho tuzaba, mw’ ijuru."}, {"type": "chorus", "content": "Nitugera mw’ ijuru, mbeg’ umunezero tuzagira!\nTuririmb’ indirimbo nziza z’abanesheje."}, {"type": "verse", "number": 2, "content": "N’ ubw’ ibicu bidukingirije,\nBitubuza kureba neza,\nTuri hafi yo gusoz’ urugendo rukomeye."}, {"type": "verse", "number": 3, "content": "Dukomeze dukorer’ Imana,\nTuzabihemberwa nta shiti;\nTuri hafi guhabw’ ubugingo bw’ iteka ryose!"}, {"type": "verse", "number": 4, "content": "Dor’ ikamba rir’ imbere yacu,\nTuzaryambikirwa mw’ ijuru,\nN’ ahantu h’ igikundiro, harahebuje rwose."}]},
  {"number": 353, "name": "Mu Maboko Ya Yesu", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/353", "key": "sol", "references": [{"codes": "S. 57"}, {"title": "SAFE IN THE ARMS OF JESUS"}, {"codes": "HL. 324"}, {"title": "SUR TOI JE ME REPOSE"}], "body": [{"type": "verse", "number": 1, "content": "Mu maboko ya Yesu, Ndi mu gituza cye!\nMpabon’ umunezero, Kubw’ urukundo rwe.\nMbega ngo ndaririmba, Nk’ abamarayika:\nAho hantu heza, Ku Nyanja ya Yasipi!"}, {"type": "chorus", "content": "Mu maboko ya Yesu,\nNdi mu gituza cye;\nMpabon’ umunezero,\nKubw’ urukundo rwe."}, {"type": "verse", "number": 2, "content": "Mu maboko ya Yesu, Anyitaho rwose;\nNtsind’ ibigeragezo, Ni ho nesh’ icyaha.\nMu maboko ya Yesu, Hehe n’ umubabaro!\nNtabwo ngishidikanya, Yes’ amar’ ubwoba."}, {"type": "verse", "number": 3, "content": "Yesu Mukunzi wanjye, Wowe nihishamo;\nNi wowe niringira, Wowe wampfiriye.\nGitare gikomeye, Ndagutegereje;\nNuza ku manywa cyangwa nijor’ uzanjyana!"}]},
  {"number": 354, "name": "Mbe! Basare Tugashya", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/354", "key": "ré", "references": [{"codes": "HL. 404"}, {"title": "MATELOTS EN VOYAGE"}], "body": [{"type": "verse", "number": 1, "content": "Mbe! Basare tugashya tugana hakurya; Nidusakirana n’ umuraba,\nHar’ aho gutsik’ ubwato, Ku cyambu gituje cyane."}, {"type": "chorus", "content": "Ibice 1, 2, 3: Ku cyambu gi-hora gitekanye iteka,\nI-wacu mw’ ijuru hahora hatuje!\nKu cyambu gituje, hahor’ amahoro! (Hahor’ amahoro.)"}, {"type": "verse", "number": 2, "content": "Twe kurangamir’ inyungu z’ igihe gito, Nta mumaro zifite haba namba!\nDushak’ aho dutsika, Ku nkombe hakury’ iwacu."}, {"type": "verse", "number": 3, "content": "Yesu ni we Nyenyeri itumurikira, Kandi ni w’ udukingir’ umuraba.\nTyo twerekez’ ubwato, kuri Yesu Murengezi."}, {"type": "verse", "number": 4, "content": "N’ ubw’ ubukana bw’ inyanja bwakara gute! Urusaku rukaba rwinshi cyane!\nNtacyo ruzadutwara, Yes’ azaruducyahira."}, {"type": "chorus", "content": "Igice 4: Mw’ ijuru n’ iwacu hakurya ku cyambu\nMw’ ijuru mw’ ijuru ni ho tuzibera.\nMw’ ijuru heza pe! Mw’ ijuru n’ iwacu (mw’ ijuru n’ iwacu)."}]},
  {"number": 355, "name": "Turakuramya Mana", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/355", "key": "sol", "references": [{"codes": "SDAH. 12"}, {"title": "JOYFUL; JOYFUL WE ADORE THEE"}], "body": [{"type": "verse", "number": 1, "content": "Tuje kukuramya Mana yacu y’ icyubahiro,\nTwubamye nk’ ukw’ indabyo zimer’ imbere y’ izuba.\nWow’ utang’ umunezero, Utubabarir’ ibyaha;\nUtumurikire Mana twe guteshuk’ inzira."}, {"type": "verse", "number": 2, "content": "Imirimo yawe Mana yigaragaza hose!\nIjuru n’ isi bihamya icyubahiro cyawe;\nInyenyeri, izuba n’ inyanja, ndetse n’ imisozi,\nN’ inyoni ziririmbira mu biti by’ inzitane."}, {"type": "verse", "number": 3, "content": "Soko y’ imigisha yose, uratubabarira!\nNi wowe Nyir’ ubuzima, ni wow’ utubeshaho.\nUtwuzuze urukundo, uduhire Mana yacu;\nUduhaz’ umunezero, turagusabye Mana."}]},
  {"number": 356, "name": "Nkomoko Y’ Ibyiza Bidateka", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/356", "key": "la bémol", "references": [{"codes": "HL. 21"}, {"title": "Ô TOI DONT LES BIENFAITS"}], "body": [{"type": "verse", "number": 1, "content": "Nkomoko y’ ibyiza bidateka, Mana y’ amahoro;\nTw’ abana bawe tuje kugusingiza;\nAkira kuramya kwacu, Mana yacu.\nTw’ abana bawe tuje kugusingiza;\nAkira kuramya kwacu, Mana yacu."}, {"type": "verse", "number": 2, "content": "Dushoboze gukor’ iby’ ushaka Mana, Uduhire.\nTukumvire rwose, tukubahe Mana;\nNaw’ uduhundagazehw’ imigisha yawe.\nTukumvire rwose, tukubahe Mana;\nNaw’ uduhundagazehw’ imigisha yawe."}]},
  {"number": 357, "name": "Ndishimye Pe! Yes’ Arankunda", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/357", "key": "sol", "references": [{"codes": "CH. 423"}, {"title": "I’M SO GLAD THAT OUR FATHER"}, {"codes": "GH. 22"}, {"title": "JESUS LOVES ME"}], "body": [{"type": "verse", "number": 1, "content": "Nishimiye ko Data wa twese, Yandikishij’ iby’ urukundo rwe.\nMu byanditswe muri Bibiliya, Nta cyaruta yuko Yes’ ankunda."}, {"type": "chorus", "content": "Ndishimye pe! Yes’ arankunda;\nArankunda, arankunda!\nNdishimye pe! Yes’ arankunda;\nAnyakir’ uko ndi."}, {"type": "verse", "number": 2, "content": "Iyo nyobye maze ngateshuka, Ntabw’ ajy’ amvirira haba namba.\nAngaruz’ ineza n’ urukundo, Nkamugarukira kukw’ ankunda."}, {"type": "verse", "number": 3, "content": "Ningera mu bwami bwo mw’ ijuru, Nzaririmb’ indirimbo z’ ikuzo.\nAriko cyane cyane nzishima, Ndirimb’ urukundo rw’ Umukiza."}]},
  {"number": 358, "name": "Yesu Yarampinduye Rwose!", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/358", "references": [{"codes": "GH. 93"}, {"title": "JESUS CHANGED MY LIFE"}], "body": [{"type": "verse", "number": 1, "content": "Nahoze ndindagira mu mwijima w’ ibyaha;\nMaze Yes’ arambatura, none narahindutse;\nNd’ umwana w’ Imana rwos’ ubu, mfit’ amahoro."}, {"type": "chorus", "content": "Yarampinduye rwose, Anyigisha gusenga.\nNzasingiz’ urukundo Rwe!\nUbu yangiz’ uwe rwose;\nNahinduts’ umuntu mushya."}, {"type": "verse", "number": 2, "content": "Nahoze nd’ ikigenge, sinari nzi gusenga;\nYes’ araz’ arampindura, Yankunze bihebuje;\nArapfa kubwanjye; Ubu narihannye rwose."}, {"type": "verse", "number": 3, "content": "Urukund’ umunezero n’ amahoro,\nNi byo byuzuy’ umutima wanjye!\nYesu yanyuzuyemw’ amp’ ubugingo bushya;\nNzibanira na w’ iteka."}]},
  {"number": 359, "name": "Umucyo Uva Mw’ Ijuru", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/359", "references": [{"codes": "CH. 628"}, {"title": "BRIGHTLY BEAMS OUR FATHER’S MERCY."}, {"codes": "HL. 92"}, {"title": "COMME UN PHARE SUR LA PLAGE"}, {"codes": "AH. 356"}], "body": [{"type": "verse", "number": 1, "content": "Umucyo uva mw’ ijuru, Uyobor’ abagenzi,\nUzadufasha tugere, Ku nkombe yo hakurya."}, {"type": "chorus", "content": "Mwami Yes’ umucyo waw’ umurikir’ abagenzi\nWinjire mu nyanja, Maz’ ubakingir’ umuraba ."}, {"type": "verse", "number": 2, "content": "Umwijim’ urabuditse, Inyanj’ irahorera;\nYes’ aduhozahw’ amas’ azadufasha twambuke."}, {"type": "verse", "number": 3, "content": "Mutyo ducan’ amatara, Dukomez’ urugendo.\nTwe kuyobywa n’ abasare, Badafit’ urumuri."}]},
  {"number": 360, "name": "Wisubika Kwihana Nshuti", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/360", "key": "sol", "references": [{"codes": "CH. 228"}, {"codes": "CS. 89"}, {"title": "ALMOST PERSUADED"}, {"codes": "GH. 132"}], "body": [{"type": "verse", "number": 1, "content": "Wisubika kwihana nshuti;\nNi nko kubwir’ Umwuka Wera,\nNgo genda rwose, jye nzihan’ undi munsi.\nMbega ng’ uribuza amahirwe!"}, {"type": "verse", "number": 2, "content": "Wisubika kwihana nshuti;\nDore Yes’ atez’ ibiganza.\nIhan’ uyu munsi, emer’ umusange;\nAguh’ ubugingo agukize."}, {"type": "verse", "number": 3, "content": "Wisubika kwihana nshuti;\nDor’ igihe kirarangiye.\nRwos’ igihe cy’ imbabazi kirashize,\nFatirana bwang’ usange Yesu."}]},
  {"number": 361, "name": "Ubuntu Butangaje!", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/361", "key": "la bémol", "references": [{"codes": "SDAH. 108"}, {"title": "AMAZING GRACE"}, {"codes": "GH. 78"}], "body": [{"type": "verse", "number": 1, "content": "Mbeg’ ubuntu butangaje cyane!\nUmutindi nkanjye gukizwa!\nNtabwo nabonaga, none ndabona.\nNakijijw’ ibyaha byanjye."}, {"type": "verse", "number": 2, "content": "N’ ubuntu bwanyerets’ aho nari;\nNari mu byaha byinshi cyane.\nKubw’ ubuntu Yesu yarandokoye;\nSingifit’ ubwoba rwose."}, {"type": "verse", "number": 3, "content": "Navanywe mu kaga nari ndimo;\nMpagaze mu buntu bwa Yesu.\nKubw’ ubwo buntu nzager’ ibudapfa;\nMw’ ijuru kwa Data heza!"}, {"type": "verse", "number": 4, "content": "Imyak’ igihumbi ndi mw’ ijuru;\nNzabanayo n’ Umwami Yesu.\nMbeg’ indirimbo nziza nzaririmba!\nNzaba nkeye cyane rwose."}]},
  {"number": 362, "name": "N’ Umutima Utuje", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/362", "key": "ré", "references": [{"codes": "HL. 177"}, {"title": "MON ÂME EN SILENCE"}], "body": [{"type": "verse", "number": 1, "content": "N’ umutim’ utuje, nj’ imbere yawe;\nUmbe hafi Yesu, nkumve bugufi."}, {"type": "verse", "number": 2, "content": "Nta rindi jwi nshaka kumva na gato;\nKerets’ ijwi ryawe, Yesu Mukiza."}, {"type": "verse", "number": 3, "content": "Amagambo yaw’ ambe mu mutima;\nYes’ ump’ ubugingo bw’ iteka ryose."}]},
  {"number": 363, "name": "Yesu Mu Bugingo Bwanjye", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/363", "key": "si bémol", "references": [{"codes": "SDAH. 189"}, {"title": "ALL THAT THRILLS MY SOUL"}], "body": [{"type": "verse", "number": 1, "content": "Mbese har’ icyanezeza, Nko kubana na Yesu?\nNta cyanezeza nko kubana n’ uwo munyakuri."}, {"type": "chorus", "content": "Niba har’ ikinezeza,\nKurut’ ibindi byose;\nYesu mu bugingo bwanjye,\nRwos’ andutira byose"}, {"type": "verse", "number": 2, "content": "Yitangiye kuncungura, Kubw’ ubuntu bw’ Imana.\nUrukundo rwe rusumb’ ijuru n’ inyanja zose."}, {"type": "verse", "number": 3, "content": "Ntacyo nshobora gukena, Mfit’ uwo Mucunguzi.\nNi w’ ump’ ibyo nkennye byose, Ni w’ unshoboza byose."}, {"type": "verse", "number": 4, "content": "Ku mugez’ ubengerana, Nzaririmb’ indirimbo;\nNdi kumwe n’ abarokotse, Turirimbir’ Imana."}]},
  {"number": 364, "name": "Nyir’ Ukwiringirwa Mana", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/364", "key": "ré bémol", "references": [{"codes": "SDAH. 100"}, {"title": "GREAT IS THY FAITHFULNESS"}], "body": [{"type": "verse", "number": 1, "content": "Nyir’ ukwiringirwa, Man’ Ihoraho,\nNtabw’ ubundikirwa n’ umwijima.\nNtuhinduka Mana yac’ idatsindwa;\nKand’ uhor’ uko wahoze Mana."}, {"type": "chorus", "content": "Nyir’ ukwiringirwa Mana ikomeye,\nNi wow’ uduh’ ibyo dukeneye.\nIkiganza cyawe, kitugabira,\nIbyo dukeneye buri munsi."}, {"type": "verse", "number": 2, "content": "Haba mu cyi cyangwa se mu muvumbi,\nInyenyeri, izuba n’ ukwezi,\nIbyo waremye byose Mana yacu,\nBihamya k’ ur’ Iman’ ikomeye."}, {"type": "verse", "number": 3, "content": "Ugir’ imbabazi n’ impuhwe nyinshi.\nUmunsi ku wund’ uraturinda.\nUduh’ ibyiringiro bikomeye;\nBy’ uko tuzabahw’ iteka ryose."}]},
  {"number": 365, "name": "Dor’ Umwami Yes’ Araje", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/365", "key": "ré", "references": [{"codes": "SDAH. 454"}, {"title": "DON’T YOU SEE MY JESUS COMING?"}], "body": [{"type": "verse", "number": 1, "content": "Dor’ Umwami Yes’ araje, Nguriya araje mu bicu.\nAshagawe n’ abamarayika, Benshi batabarika."}, {"type": "chorus", "content": "Ndatwaranira rwose,\nKugera mw’ ijuru heza.\nHaleluya Yesu nahimbazwe!"}, {"type": "verse", "number": 2, "content": "Reb’ abera bazamurwa, Baririmb’ indirimbo nziza.\nImpanda zirangurura, Mbega ngo Yes’ aramwenyura!"}]},
  {"number": 366, "name": "Isoko Itemba", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/366", "key": "si bémol", "references": [{"codes": "S. 137"}, {"title": "FLOWING EVER FLOWING"}], "body": [{"type": "verse", "number": 1, "content": "Har’ isoko y’ ubunt’ isokw’ ihor’ itemba.\nMu mitim’ inaniwe, Sokw’ iryoshye cyane.\nN’ isoko nziza cyane pe! N’ isokw’ itumar’ inyota."}, {"type": "chorus", "content": "Iyo Soko, Ihora itemba;\nUyinywaho iramukiza."}, {"type": "verse", "number": 2, "content": "Ndumv’ ijwi ryongorera, Nk’ indirimbo nziza!\nRituruka mw’ isoko nziza idakama.\nNi yo soko y’ ubugingo, Ni y’ idukiz’ ubwihebe."}, {"type": "verse", "number": 3, "content": "N’ isoko y’ umugisha, Itang’ ibyishimo.\nN’ amaraso ya Yes’ akiz’ abanyabyaha.\nN’ amaraso y’ Umukiza, Kand’ aratunganye rwose."}]},
  {"number": 367, "name": "Kubw’ Ijambo Ryawe", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/367", "key": "sol", "references": [{"codes": "S. 266"}, {"title": "THANKS FOR THE BIBLE"}], "body": [{"type": "verse", "number": 1, "content": "Kubw’ Ijambo ryawe Nyagasani, Turagushima Mwami Mana.\nUduh’ amaso abona neza, Kangur’ imitima yacu."}, {"type": "chorus", "content": "Waduhaye Bibiliya Yera,\nTuragushimye Nyagasani.\nDufashe twumv’ Ijambo ryawe,\nTuyoborwe na ryo Muremyi."}, {"type": "verse", "number": 2, "content": "Mw’ Ijambo ryawe harimw’ umucyo, Tubonamw’ amasezerano.\nN’ itabaza ry’ ibirenge byacu, Ritumurikir’ inzira."}, {"type": "verse", "number": 3, "content": "Hahirw’ abakomez’ iryo Jambo, Bazabana na Yes’ iteka.\nBazarya ku giti cy’ ubugingo; Hafi y’ umugezi mwiza."}]},
  {"number": 368, "name": "Kwizera Kwanjye", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/368", "key": "sol", "references": [{"codes": "SDAH. 523"}, {"title": "MY FAITH HAS FOUND A RESTING PLACE"}], "body": [{"type": "verse", "number": 1, "content": "Kwizera kwanjye kwabonye uburuhukiro;\nNiringiye Uhoraho wantangiy’ incungu."}, {"type": "chorus", "content": "Nta yindi ncungw’ ikenewe,\nYesu yarishye byose.\nYarapfuye, arazuka;\nYaranyitangiye."}, {"type": "verse", "number": 2, "content": "Nta bwoba ngifite namba! Yes’ arampagije.\nYankuyehw’ ibyaha byose, Kubw’ amaraso Ye."}, {"type": "verse", "number": 3, "content": "Yesu yaje gukiz’ imitima yazimiye.\nYatanz’ amaraso Ye, Kugira ngo ndokoke."}, {"type": "verse", "number": 4, "content": "Har’ Ijambo rihindura, Kandi rimp’ ituza.\nN’ Ijambo ryiza ry’ Iman’ Ijambo ry’ ubugingo."}]},
  {"number": 369, "name": "Ibyaha Byanjye Mbihaye Yesu", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/369", "key": "mi", "references": [{"codes": "CH. 278"}, {"title": "I LAY MY SINS ON JESUS"}, {"codes": "AH. 245"}], "body": [{"type": "verse", "number": 1, "content": "Ibyaha byanjye mbihaye Yes’ Umwana w’ Intama;\nByose ndabimwikoreje, Ngo mbon’ umudendezo.\nIbicumuro byanjye, Mbihay’ Umwami Yesu;\nAnyejesh’ amaraso Ye, Anyeze nse n’ urubura."}, {"type": "verse", "number": 2, "content": "Kand’ ibyo nkennye byose, Mbishyize ku birenge Bye.\nYes’ akiz’ indwara zose, Ndetse n’ ibicumuro.\nIntimba zanjye zose, Nzishyikiriza Yesu;\nKand’ imitwaro yanjye yose, Yes’ arayinyakira."}, {"type": "verse", "number": 3, "content": "Ndifuza kuba nka Yesu, Niyoroheje nka We.\nNdifuza kureba Yes’ Umwana w’ Imana Data.\nNdifuza kuzabana, Na Yes’ iyo mw’ ijuru;\nNkaririmbana n’ abera, Ntozwa n’ abamarayika."}]},
  {"number": 370, "name": "Twegerej’ Igihe", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/370", "key": "sol", "references": [{"codes": "CH. 372"}, {"title": "A FEW MORE YEARS SHALL ROLL"}], "body": [{"type": "verse", "number": 1, "content": "Twegerej’ igihe cyo gutah’ iwacu;\nAbacu twabuze tuzongera kubonana.\nMwami Yesu, Tegur’ ubugingo bwanjye;\nNyejesh’ amaraso yaw’ ankiz’ ibyaha byanjye."}, {"type": "verse", "number": 2, "content": "Dore duhanganye n’ imirab’ ikaze;\nArikw’ iri hafi kurangira bidatinze.\nTugiye kwiber’ ahatab’ amakuba;\nYesu nkiz’ ibyaha mbashe kuzager’ iwawe."}, {"type": "verse", "number": 3, "content": "Intugunda zose zigiye gushira.\nTuri hafi guhanagurw’ amarira yose.\nMwami Yesu wamviriye amaraso.\nMfasha rwose, nzabe mur’ uwo muns’ uhiriwe."}, {"type": "verse", "number": 4, "content": "N’ igihe kigufi Yes’ akagaruka.\nYaradupfiriye, kugira ngo tuzabeho.\nMwami Yesu, Tegur’ ubugingo bwanjye;\nNyejesh’ amaraso yaw’ ankiz’ ibyaha byanjye."}]},
  {"number": 371, "name": "Nagiriw’ Ubuntu", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/371", "key": "sol", "references": [{"codes": "SDAH. 109"}, {"title": "MARVELOUS GRACE"}], "body": [{"type": "verse", "number": 1, "content": "Nagiriw’ ubuntu na Yesu, N’ ubuntu bw’ ikirenga rwose.\nUmutwaro w’ ibyaha byanjye, Wasigaye i Kaluvari."}, {"type": "chorus", "content": "S. na T.: Kubw’ ubuntu bw’ Imana,\nButangaje cyane:\nMbeg’ ubuntu! Ubuntu,\nBwankijij’ ibyaha.\nA. na B.: Mbeg’ ubuntu, mbeg’ ubuntu;\nBw’ Imana butangaje cyane:\nMbeg’ ubuntu! Mbeg’ ubuntu!\nUbuntu bwankijij’ ibyaha."}, {"type": "verse", "number": 2, "content": "Ibyaha byarazimanganye; Mbese nk’ uk’ umurab’ utuza.\nKubw’ ubuntu butarondorwa; Nakize kubw’ umusaraba."}, {"type": "verse", "number": 3, "content": "Ubuntu butagereranywa, Bwahawe uwizera wese.\nUshaka kubon’ agakiza, Nasange Yes’ aramwakira."}]},
  {"number": 372, "name": "Kwa Kwizera Kw’ Abakurambere", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/372", "key": "sol", "references": [{"codes": "SDAH. 304"}, {"title": "FAITH OF OUR FATHERS"}, {"codes": "CH. 349"}], "body": [{"type": "verse", "number": 1, "content": "Kwa kwizera kw’ abakurambere, Kwa kundi kwababashishaga,\nKwemera kuzir’ akarengane; Kwicishw’ inkota n’ umuriro."}, {"type": "chorus", "content": "Uko kwizera natw’ ubu,\nTugufite mu mitima.\nTuzakunambaho rwose,\nN’ iyo byaba ngombwa gupfa."}, {"type": "verse", "number": 2, "content": "Baraboshywe baranakubitwa, Baroshywe mu mazu y’ imbohe;\nBajugunywa mu byobo by’ intare, Nyamara bagumye kwizera!"}, {"type": "verse", "number": 3, "content": "N’ ubwo batotejwe bikomeye, Nta nzika bigeze bagira!\nNtibikomy’ ababatotezaga, Babasabirag’ imigisha!"}]},
  {"number": 373, "name": "Tur’ Abagenzi", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/373", "key": "la", "references": [{"codes": "HL. 392"}, {"title": "DE CANAAN QUAND VERRONS - NOUS"}], "body": [{"type": "verse", "number": 1, "content": "Tur ‘ abagenzi mw’ iyi si, Twerekeje mw’ ijuru.\nYes’ araduhamagara, Ku nkombe ya yor’dani.\nYes’ uw’ uduhamagara, Arashaka ko tumusanga,\nTukabana mu bwiza bwe, Turirimb’ iteka."}, {"type": "chorus", "content": "Bizab’ umunezero kubana na Yesu,\nMu Bwami bwo mw’ ijuru, turirimb’ iteka.\nItorero Rye ryo mw’ ijuru, rizaririmb’ aleluya!\nRihimbaza Yes’ Umwami Mucunguzi wacu!"}, {"type": "verse", "number": 2, "content": "Mbeg’ ukuntu bizaba byiza, Kumv’ amajwi meza;\nAsingiz’ Umwana w’ Intam’ amajw’ atey’ ubwuzu!\nKand’ amajwi yac’ azab’ urwunge n’ ay’ abamarayika.\nTwese tuzaririmbira Umwami w’ abami."}, {"type": "verse", "number": 3, "content": "Abacunguwe na Kristo, Bazabon’ ubwiza bwe,\nN’ abapfuye bamwizeye, Bazakangurwa na we.\nTuzasingiz’ intsinzi ye, Twese dukikij’ intebe ye.\nTuzataramana n’ Umwam’ atuganirize."}, {"type": "verse", "number": 4, "content": "Dor’ umunsi w’ Uwiteka, Uri hafi kugera,\nKand’ abamwizeye twese, Tuzamusanganira.\nTuzasingiz’ urukundo, Rwatumye atang’ Umwana We,\nYesu Krist’ akadupfir’ akadukiz’ urupfu."}]},
  {"number": 374, "name": "Duhimbaz’ Imana Y’ Abrahamu", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/374", "references": [{"codes": "SDAH. 11"}, {"title": "THE GOD OF ABRAHAM PRAISE"}], "body": [{"type": "verse", "number": 1, "content": "Mana y’ Abrahamu, Data wo mw’ ijuru;\nMana y’ urukundo, Uhorahw’ iteka.\nUwiteka Mana, Ijuru n’ isi bikuramye.\nIzina ryawe niryubahwe, Muremyi wacu."}, {"type": "verse", "number": 2, "content": "Mana y’ Abrahamu, Mu biganza byawe,\nUgabir’ is’ umunezero nyakuri.\nUbwema n’ ikuzo, n’ ibyawe Mana yacu nziza.\nUri kw’ isonga, Nta wahwana nawe Gitare."}, {"type": "verse", "number": 3, "content": "Twese dusingiz’ Iman’ Isumba byose.\nIcyubahiro cyose, n’ icyawe Mana;\nWowe Mana Data, Man’ Umwana na Mwuka Wera;\nNyir’ ubushoboz’ uhimbazwe, Iteka ryose."}]},
  {"number": 375, "name": "Mbeg’ Urukundo!", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/375", "key": "mi bémol", "references": [{"codes": "CH. 416"}, {"title": "O PERFECT LOVE"}], "body": [{"type": "verse", "number": 1, "content": "Mbeg’ urukundo ruhebuje byose!\nTurasaba Man’ urukomeze;\nRub’ urukundo rw’ iteka n’ iteka;\nNibab’ umwe muri wowe Mana."}, {"type": "verse", "number": 2, "content": "Bah’ ubuzima bwiza Mana yacu;\nBibere mu bwishingizi bwawe.\nUbahe gushikama mu kwizera;\nBanesh’ imibabaro y’ iyi si."}, {"type": "verse", "number": 3, "content": "Bah’ ubutwari buzira kwiheba;\nBanezerwe bagir’ amahoro;\nMan’ ubahe urukundo rusāze;\nBah’ urukundo rutagajuka."}]},
  {"number": 376, "name": "Isabato Yera, Munsi W’ Uwiteka", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/376", "key": "fa", "references": [{"codes": "AH. 385"}, {"title": "THY HOLY SABBATH LORD"}, {"codes": "CH. 470"}], "body": [{"type": "verse", "number": 1, "content": "Isabato yera, Munsi w’ Uwiteka;\nDuhabw’ amahirwe, Yo kumv’ Ijambo ry’ Imana."}, {"type": "verse", "number": 2, "content": "Mbeg’ umunsi mwiza, Umunsi w’ Imana!\nUkwiye kubahwa rwose, tukaramy’ Imana."}, {"type": "verse", "number": 3, "content": "Abera b’ ijuru baterana natwe;\nTugafatanya guhimbaz’ Umuremyi wacu."}, {"type": "verse", "number": 4, "content": "Ubwo tuzava mw’ iyi si y’ igomero;\nTuzakomereza kwez’ Isabato mw’ ijuru."}]},
  {"number": 377, "name": "Shuri ry’ Isabato Nkunda", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/377", "key": "la bémol", "references": [{"codes": "HL. 179"}, {"title": "Ô CHÈRE ÉCOLE DU SABBAT"}], "body": [{"type": "verse", "number": 1, "content": "Shuri ry’ Isabato nkunda, Munezero wanjye;\nUnyongeramw’ imbaraga; Mu rugamba ndwana."}, {"type": "chorus", "content": "Mvugisha Mwami Yesu,\nNyongera kwizera.\nMw’ ishuri ryo kw’ Isabato;\nNtabwo nzacogora."}, {"type": "verse", "number": 2, "content": "Nig’ ibyigisho by’ ingenzi, Umunsi ku wundi.\nBituma nsobanukirwa, Ibyiza by’ ijuru."}, {"type": "verse", "number": 3, "content": "Mw’ ishuri ryo kw’ Isabato, Twiga Bibiliya;\nTugahabw’ amabang’ atuma twizera cyane."}]},
  {"number": 378, "name": "Mwami Ha Umugisha Uru Rugo", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/378", "key": "do", "references": [{"codes": "HL. 430"}, {"title": "SUR CES ÉPOUX, SEIGNEUR"}], "body": [{"type": "verse", "number": 1, "content": "Aba bashyingiwe, Bah’ umugisha wawe;\nWow’ ubagiz’ umwe, By’ itek’ uyu munsi.\nBarabagiranishwe n’ ubwiza bwawe.\nBagwiriz’ urukundo n’ umunezero."}, {"type": "verse", "number": 2, "content": "Bari ku birenge, Byawe Mwam’ ubahire;\nUhir’ amasezerano bagiranye.\nMu nzira y’ ubuzima bwab’ ubane na bo;\nBahore babumbatiwe naw’ iteka."}, {"type": "verse", "number": 3, "content": "Amahoro yawe, Atah’ urugo rwabo;\nKand’ Ijambo ryawe, Ribamurikire.\nYes’ abane na bo, Mu migendere yabo.\nYes’ ahore yonger’ urukundo rwabo."}, {"type": "verse", "number": 4, "content": "Baba mu mahoro, Haba se mu makuba;\nYes’ ubagumane, Mu maboko yawe.\nBe guhungabanywa n’ imiraba y’ iyi si;\nUkuboko kwawe kubahe kunesha."}]},
  {"number": 379, "name": "Mbeg’ Umunsi Mwiza!", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/379", "key": "la bémol", "references": [{"codes": "AH. 388"}, {"title": "HOW SWEET THE LIGHT"}, {"codes": "CH. 461"}], "body": [{"type": "verse", "number": 1, "content": "Mbeg’ umunsi mwiza! N’ umunsi wera de!\nMunsi wo kuruhukwa; Twongerwa mw’ imbaraga."}, {"type": "verse", "number": 2, "content": "Kand’ Umwuka Wera, Aterana natwe;\nAgatesh’ inkomyi yatubuz’ umudendezo."}, {"type": "verse", "number": 3, "content": "Mbeg’ ikiruhuko! Gituma turamya,\nImana yo mw’ ijuru, Maze tugasābana."}, {"type": "verse", "number": 4, "content": "Mbeg’ umunsi mwiza, Umunsi wejejwe!\nImitim’ irakanguka; Tukanesh’ urupfu."}]},
  {"number": 380, "name": "Umunsi W’ Isabat’ Uragarutse", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/380", "key": "mi bémol", "references": [{"codes": "AH. 391"}, {"title": "AGAIN THE DAY RETURNS"}, {"codes": "CH. 466"}], "body": [{"type": "verse", "number": 1, "content": "Umunsi w’ Isabat’ uragarutse;\nMunsi wera wahiriwe n’ Imana yacu.\nMunsi mwiza turuhuk’ imirimo;\nMunsi w’ ituze, Munsi w’ amahoro."}, {"type": "verse", "number": 2, "content": "Twite kur’ uyu munsi w’ Uwiteka;\nTwige kandi tumenye gukor’ iby’ ashaka.\nAzajya yumv’ amasengesho yacu;\nN’ indirimbo zacu zizamunyura."}, {"type": "verse", "number": 3, "content": "Uwiteka Mana, duteg’ amatwi;\nWumv’ ijwi ry’ abana bawe bagutakira.\nUdukomerez’ amasezerano;\nUbuntu bwawe busage muri twe."}, {"type": "verse", "number": 4, "content": "Data wo mw’ ijur’ ur’ Umurengezi;\nNi wowe twubatsehw’ ibyiringiro byacu.\nUr’ inshuti itadutererana;\nIcyubahiro kib’ icyawe Mana!"}]},
  {"number": 381, "name": "Mwami Nyir’ Isabato", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/381", "key": "sol", "references": [{"codes": "AH. 392"}, {"title": "LORD OF THE SABBATH"}, {"codes": "CH. 455"}], "body": [{"type": "verse", "number": 1, "content": "Mwami Nyir’ isabato yera de! Nkez’ umunsi wawe w’ ikiruhuko.\nMuns’ umpora ku mutima, N’ umuns’ ungarura mw’ intege;\nMpabwamw’ imigisha ngakomera."}, {"type": "verse", "number": 2, "content": "Munsi wuj’ amahoro n’ ituze, Umunsi wose numva nezerewe!\nIntekerezo mbi zose, Zirahunga zikanjya kure;\nNkibwir’ ibyiza byera by’ ijuru."}, {"type": "verse", "number": 3, "content": "Mbeg’ ukunt’ ar’ iby’ igikundiro, Iyo ngeze mu munsi wahiriwe!\nNkumv’ indirimbo z’ ihozo, Ntwarwa gusa n’ ibyo mw’ ijuru!\nMunsi mwiza mbonamw’ imigisha."}, {"type": "verse", "number": 4, "content": "Ntaramana nawe Mwami Yesu, Mur’ uyu munsi mwiza wahiriwe!\nJyew’ umugaragu wawe, Gukomez’ isabato yawe,\nBizampesha imigisha myinshi."}]},
  {"number": 382, "name": "Umubano Uba Mwiza", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/382", "key": "do", "references": [{"codes": "HL. 431"}, {"title": "QU’ ELLE EST DOUCE L’ HARMONIE"}], "body": [{"type": "verse", "number": 1, "content": "Umubano uba mwiza, Mu rugo Yes’ arimo;\nUrukundo ruranesha, Hab’ ituze rihamye.\nIkinyabupfura ni cyo kiranga urwo rugo,\nUmugabo n’ umugore, Iyo bubah’ Imana."}, {"type": "verse", "number": 2, "content": "Urugo rwunguts’ umwana, Hab’ ibyishimo byinshi.\nNahabw’ uburere bwiza, Ab’ umwana w’ ijuru;\nUmwan’ unezez’ Imana, Kand’ uzabana na yo;\nAbane n’ Umwami Yesu, Kand’ ayoborwe na we."}, {"type": "verse", "number": 3, "content": "Urugo rwa hano mw’ isi, n’ urw’ igihe kigufi,\nN’ ubund’ ibyo mw’ isi byose, Ntabwo biramba rwose.\nIbyiza birut’ ibindi, Kandi bizahoraho,\nTuzahurizwa mw’ ijuru; Tuzabana by’ iteka."}, {"type": "verse", "number": 4, "content": "Ibyo duhabwa n’ Imana mu rugendo turimo;\nTubyakiran’ ibyishimo, Tubyifatemo neza.\nTwirinde gutsindwa n’ ibigeragezo by’ Umwanzi;\nDusarur’ iby’ urukundo, Rw’ Imana yac’ iduha."}]},
  {"number": 383, "name": "Mu Gihe Ntugarijwe", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/383", "key": "fa", "references": [{"codes": "HL. 189"}, {"title": "QUAND LE CIEL DEVIENT MÉNAÇANT"}], "body": [{"type": "verse", "number": 1, "content": "Mu gihe ntugarijwe N’ akaga gakomeye;\nYes’ umbwiz’ ijwi ryiz’ uti:\nHumura ndahari."}, {"type": "verse", "number": 2, "content": "Iy’ umurab’ ukaramye, Ntabwo mpungabana.\nKrist’ ankomez’ ambwir’ ati:\nHumura ndahari."}, {"type": "verse", "number": 3, "content": "Umwijim’ iy’ ubuditse, Nkabur’ iyo ngana;\nNumv’ ijwi rimpabura ngo:\nHumura ndahari."}]},
  {"number": 384, "name": "Inyungu N’ Ibyubahiro …", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/384", "key": "mi bémol", "references": [{"codes": "HL. 338"}, {"title": "LES GAINS, LES HONNEURS …"}], "body": [{"type": "verse", "number": 1, "content": "Inyungu n’ ibyubahiro byo mw’ iyi si, Jye ndabizinukwa.\nIyo ndeby’ umusaraba Yes’ Umwami yabambweho;\nNsang’ iby’ is’ ar’ impfabusa."}, {"type": "verse", "number": 2, "content": "Yesu yarababajwe cyane, Intimba imen’ umutima;\nKubw’ ubuntu yangiriye, N’ urukundo ruhanitse,\nRwamuteye kuncungura."}, {"type": "verse", "number": 3, "content": "Nari narazimiye rwose, Narabuze ibyiringiro;\nAncunguz’ amaraso ye, Nanjye mpabw’ icyubahiro;\nMaz’ amahor’ aransāba."}, {"type": "verse", "number": 4, "content": "Urukundo rwawe rurera, Ruhoraho ibihe byose.\nNzahora ndwogez’ iteka, Kandi nzahora ndurata;\nSinzareka kuruvuga!"}]},
  {"number": 385, "name": "Munsi Mwiza W’ Umunezero", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/385", "key": "la bémol", "references": [{"codes": "SDAH. 382"}, {"title": "O DAY OF REST AND GLADNESS"}], "body": [{"type": "verse", "number": 1, "content": "Munsi mwiza w’ umunezero! Ur’ umunsi wera de!\nUr’ umuns’ urut’ indi yose; Munsi wo kuruhukwa.\nAbakomeye n’ aboroheje, Bunamir’ Uwiteka;\nBaririmba: Wera! Wera! Wera! Uhimbazw’ iteka."}, {"type": "verse", "number": 2, "content": "Muns’ urinzwe cyane n’ Imana; nta cyawuhungabanya.\nTugomororerw’ amasoko yo muri Paradizo.\nSoko y’ amariba mez’ afutse, Y’ amaz’ amar’ inyota.\nDuhagarara kuri Pisiga, Tureb’ i Kanani."}, {"type": "verse", "number": 3, "content": "N’ umunsi tuzirikana cyan’ urukundo rw’ Imana;\nTurushaho gutekereza ibyiza byo mw’ ijuru.\nDuhabw’ imigisha myinshi cyane, Mur’ uyu munsi mwiza;\nTwumva rwose twakwigumira, Mur’ uyu munsi wera!"}]},
  {"number": 386, "name": "Ibyaremwe Byose …", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/386", "key": "fa", "references": [{"codes": "SDAH. 560"}, {"title": "LET ALL THINGS NOW LIVING"}], "body": [{"type": "verse", "number": 1, "content": "Ibyaremwe byose nibiter’ amajwi hejuru;\nByishimir’ Umuremyi, Bimuririmbire.\nKoko yaraturemye; Kandi n’ Umurinzi wacu,\nN’ Umuyobozi wacu, Kugez’ imperuka.\nAdukingir’ ibihe byose, Atugend’ imber’ iteka.\nMu mwijim’ atuber’ inkingi y’ umuriro;\nAtamurur’ ibihu; Akadukiz’ umwijima;\nTukagendera mu mucyo wera w’ Imana."}, {"type": "verse", "number": 2, "content": "Yahanits’ inyenyeri; Ategek’ izuba kuva.\nNi we wahanz’ imisozi, N’ inyanja zose;\nImigezi n’ inzuzi n’ amasoko birasuma!\nByose kw’ itegeko ry’ Umuremy’ udukunda.\nGuhera mu bushorishori, No mu kuzimu mu nyanja;\nByose bihamy’ Imana, Yukw’ ar’ Umuremyi.\nNatwe biradukwiye, Guhanik’ amajwi yacu;\nTugasingiz’ iyo Mana; tuti: Hozana!"}]},
  {"number": 387, "name": "Iyo Ngukoreye Yesu", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/387", "key": "mi bémol", "references": [{"codes": "HL. 342"}, {"title": "QU’ IL FAIT BON À TON SERVICE"}], "body": [{"type": "verse", "number": 1, "content": "Iyo ngukoreye Yesu, Biranezeza;\nIri turo ntuye, Mwami rikunezeze."}, {"type": "chorus", "content": "Nguhay’ ubugingo bwanjye,\nBwakire Yesu\nKubw’ ubuntu bwawe Mwami,\nUndind’ ibibi."}, {"type": "verse", "number": 2, "content": "Warancunguye Mukiza, Mb’ uwawe rwose.\nNone rer’ umbashishe, Gukor’ iby’ ushaka."}, {"type": "verse", "number": 3, "content": "Ungir’ umumarayika wihuta cyane;\nNjyan’ Ijambo ryawe hose, Mvug’ ubutumwa."}, {"type": "verse", "number": 4, "content": "Rwose kuzaba mw’ ijuru, Ni byo nifuza;\nNta byago nta n’ amakuba bizantezura."}]},
  {"number": 388, "name": "Gihome Kidukingira", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/388", "key": "do", "references": [{"codes": "SDAH. 506"}, {"title": "A MIGHTY FORTRESS"}, {"codes": "HL. 358"}, {"title": "C’ EST UN REMPART"}, {"codes": "CS. 681"}], "body": [{"type": "verse", "number": 1, "content": "Mana yac’ urakomeye; Gihome kidukingira;\nUdukingir’ imiraba, Y’ ingorane n’ amakuba.\nUturind’ Umwanzi uhor’ aduhiga; Afit’ imbaraga,\nNtabwo twamwifasha; Ntitwamwibashisha na gato."}, {"type": "verse", "number": 2, "content": "Dushatse kwirwanirira, Twatsindwa rwose ruhemu.\nKeretse dufite Yesu, We mukiranutsi wera.\nYaneshej’ umwanzi; Kandi yiteguye Kuturwanirira;\nTuri kumwe na We; Nta kabuza tuzanesha."}, {"type": "verse", "number": 3, "content": "Iyi si yuzuy’ ibibi, Bishobora kuturimbura.\nNtidukwiye guhabuka; Twisung’ umucyo w’ Imana.\nNtiduterw’ ubwoba n’ Umwanzi w’ umucyo. Ni Se w’ umwijima;\nKand’ azarimburwa; Azajugunywa mu muriro!"}, {"type": "verse", "number": 4, "content": "Nta wabasha guhindura ubushake bwa Rurema;\nIbyo yategetse byose, Ntibikomwa mu nkokora.\nN’ ubwo byab’ urupfu, Cyangw’ ikindi cyose,\nIjambo ry’ Imana nta cyarivanaho, Kugez’ iteka n’ iteka."}]},
  {"number": 389, "name": "Ukomere Ub’ Intwari", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/389", "key": "sol", "references": [{"codes": "SDAH. 610"}, {"title": "STAND LIKE THE BRAVE"}], "body": [{"type": "verse", "number": 1, "content": "Mukristo byuka, Yes’ aragushaka.\nAmbar’ intwaro zose z’ urugamba;\nHangana n’ Umwanz’ udafit’ ubwoba;\nRwana; Shikama; Ntutiny’ urugamba."}, {"type": "chorus", "content": "Tyo shikama,\nUkomere ub’ intwari;\nUtsind’ Umubisha."}, {"type": "verse", "number": 2, "content": "Rwanira Yesu, Ushyizeh’ umwete;\nKand’ ube maso kugez’ iherezo;\nUjy’ aho Yes’ akuyobora hose.\nRwana; Shikama; Ntutiny’ urugamba."}, {"type": "verse", "number": 3, "content": "Ntushidikanye Yesu n’ Umugaba.\nAzakurinda; Azagukomeza,\nKand’ akuyoboresh’ urukundo rwe.\nRwana; Shikama; Ntutiny’ urugamba."}]},
  {"number": 390, "name": "Mbes’ Aho Tuzahurira Ku Cyambu? (B)", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/390", "key": "do", "references": [{"codes": "AH. 431"}, {"codes": "CH. 557"}, {"title": "SHALL WE MEET BEYOND THE RIVER?"}, {"codes": "CS. 421"}], "body": [{"type": "verse", "number": 1, "content": "Mbes’ aho tuzahurira, Ku cyambu cya rwa ruzi,\nAhahor’ umucy’ iteka, Ntihab’ umubabaro?"}, {"type": "chorus", "content": "Se koko tuzahurira hakurya y’ uruzi?\nTuzabonanirayo tuhanezererw’ iteka?"}, {"type": "verse", "number": 2, "content": "Tuzahurira ku cyamb’ urugendo rurangiye?\nMbes’ aho tuzahurirayo, Maze twiruhutse?"}, {"type": "verse", "number": 3, "content": "Mbes’ aho twese tuzahurira mu mudugudu,\nWubatswe n’ Uhoraho, Urimbishijwe Yasipi?"}, {"type": "verse", "number": 4, "content": "Abacunguwe bose, Bazaririmb’ indirimbo;\nKand’ ibiremwa byose, Bizasingiz’ Uhoraho."}, {"type": "verse", "number": 5, "content": "Mbes’ aho tuzabonana n’ abo twakundanaga?\nMaze twumv’ amajwi yabo, Tubareba mu maso?"}, {"type": "verse", "number": 6, "content": "Mbese tuzabonana na Krist’ Umukiza wacu,\nAje kujyan’ intore ze, Mu bwami buhoraho?"}]},
  {"number": 391, "name": "Data Umv’ Isengesho Ryacu", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/391", "key": "sol", "references": [{"codes": "SDAH. 693"}, {"title": "ALMIGHTY FATHER"}], "body": [{"type": "verse", "number": 1, "content": "Dat’ umv’ isengesho ryacu;\nUduhire, Uduh’ umugisha. Amen."}]},
  {"number": 392, "name": "Ducan’ Amatara Yacu", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/392", "key": "la", "references": [{"codes": "HL. 120"}, {"title": "TENONS NOS LAMPES PRÊTES"}], "body": [{"type": "verse", "number": 1, "content": "Muze dushikame, Ducany’ amatara yacu;\nUmukw’ agiye guhamagar’ Umugeni we."}, {"type": "chorus", "content": "Twitegure kuririmba tuti: Hozana!\nTuzasabwa n’ ibyishimo turirimb’ Aleluya;\nTuririmba Aleluya!"}, {"type": "verse", "number": 2, "content": "Abamarayika hamwe n’ abatoranijwe;\nBazateranira hamwe, Basingize Yesu."}, {"type": "verse", "number": 3, "content": "Yesu n’ umuneshi wacu, Yaratwitangiye.\nAfit’ umucy’ utangaje, Urabagirana."}, {"type": "verse", "number": 4, "content": "Yes’ azahamagar’ abo yacunguye bose;\nAti: Muz’ abihanganye, Mu rugo rwa Data."}]},
  {"number": 393, "name": "Bana, Nimwitonde", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/393", "key": "sol", "references": [{"codes": "HL. 557"}, {"title": "ENFANTS, SOYEZ SAGES"}], "body": [{"type": "verse", "number": 1, "content": "Bana nimwitonde,\nKandi mwishime;\nMuse n’ abo mw’ ijuru,\nMunezerwe."}, {"type": "verse", "number": 2, "content": "Mur’ abavandimwe,\nNimukundane;\nMwubah’ ababyeyi,\nKandi mwumvire."}, {"type": "verse", "number": 3, "content": "Mwirind’ umujinya;\nNtimukabeshye;\nIbyo muvuga,\nBishimishe Yesu."}]},
  {"number": 394, "name": "Gupfa Ni Ibitotsi", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/394", "key": "do", "references": [{"codes": "HL. 449"}, {"title": "NOUS MOURRONS, MAIS POUR RENAÎTRE"}], "body": [{"type": "verse", "number": 1, "content": "Gupfa n’ ibitotsi gusa, Kandi by’ akanya gato.\nN’ ubw’ urupfu rubabaza, Rugater’ agahinda;\nIjoro rizatamuruka, Maz’ umucy’ utangaze;\nAbasinziriye mu bituro, Bazakangurwa."}, {"type": "verse", "number": 2, "content": "Gupfa n’ ibitotsi gusa, Kandi by’ akanya gato.\nYesu yaneshej’ urupfu; Yavuye mu gituro.\nN’ akanya gato gasigaye, Tukigira mw’ ijuru;\nAho Yes’ azatujyana; Tuzaban’ ibudapfa."}]},
  {"number": 395, "name": "Hagarara Kigabo Nka Daniel", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/395", "key": "la bémol", "references": [{"codes": "AH. 467"}, {"title": "STANDING BY A PURPOSE TRUE"}, {"codes": "CH. 497"}, {"title": "(Dare To Be A Daniel)"}], "body": [{"type": "verse", "number": 1, "content": "Komez’ amategeko yera y’ Imana;\nShikama mu kuri kw’ Imana nka Daniel."}, {"type": "chorus", "content": "Hagarara kigabo nka Daniel;\nHamy’ Imana n’ubwo wab’ usigay’ ur’ umwe."}, {"type": "verse", "number": 2, "content": "Benshi barananiwe, Bacits’ intege;\nNtibashoboye gushikama nka Daniel."}, {"type": "verse", "number": 3, "content": "Benshi baharanira iby’ isi gusa;\nNtibazi gufat’ icyemezo nka Daniel."}, {"type": "verse", "number": 4, "content": "Twirinde cyane rwose, Kandi tuneshe;\nTwung’ ubumwe na Daniel, Tumere nka we."}]},
  {"number": 396, "name": "Ngwino Mwuka Wera We!", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/396", "key": "sol", "references": [{"codes": "CH. 701"}, {"title": "HOLY SPIRIT, FAITHFUL GUIDE"}], "body": [{"type": "verse", "number": 1, "content": "Ngwino Mwuka Wera We!\nMaz’ uture muri twe.\nTuber’ umuyobozi;\nTugan’ iwacu."}]},
  {"number": 397, "name": "Har’ Igihe Ntegereje", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/397", "key": "sol", "references": [{"codes": "HL. 283"}, {"title": "SANS ATTENDRE"}], "body": [{"type": "verse", "number": 1, "content": "Har’ igi-he ntegereje, Nza-nezerwamo;\nIcyo gi-he kiri hafi, nza-habw’ ikamba.\nAmasengesho yanjye, Imana ira-yumva;\nNzakome-za mpirimbane, Nza-habw’ ikamba."}, {"type": "verse", "number": 2, "content": "Ikamba ritegereje a-bazanesha.\nNzashika-ma, Nzakomeza nyo-boke Yesu;\nSinshaka kuza-bura mu bwami bwo mw’ i-juru;\nMu biro-ri byateguriwe abaneshi."}, {"type": "verse", "number": 3, "content": "Ndatanya, ndater’ intambwe, Si-ndeb’ inyuma.\nNyobowe na Nyagasani si-nzatezuka;\nIbirangaza by’ isi, Simbyitayeho namba!\nN’ubw’ ibi-ndwany’ ari byinshi, Mfi-t’ a-mahoro."}, {"type": "verse", "number": 4, "content": "Mana y’ u-buntu n’ impuhwe, U-murikire.\nMfatish’ u-kuboko kwawe, Ma-z’ unkomeze.\nNd’ umunyantege nkeya, Ariko nitu-bana,\nSinshidi-kanya na gato, Ma-na nzanesha."}]},
  {"number": 398, "name": "Uwiteka Ari Mu Rusengero", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/398", "key": "ré bémol", "references": [{"codes": "SDAH. 692"}, {"title": "THE LORD IS IN HIS HOLY TEMPLE"}], "body": [{"type": "verse", "number": 1, "content": "Uwitek’ ari mu rusengero;\nAri mu rusengero rwe rwera.\nIsi yose nituze; Duturiz’ imbere y’ Imana;\nTyo dutuze, dutuze, dutuze. Amen."}]},
  {"number": 399, "name": "Yesu Nikoreye Umusaraba", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/399", "key": "la", "references": [{"codes": "SDAH. 325"}, {"title": "JESUS I MY CROSS HAVE TAKEN"}], "body": [{"type": "verse", "number": 1, "content": "Yesu ndagukurikiye, Ndetse byose ndaje Mwami.\nNikorey’ umusaraba, Ndagukurikiye Mukiza.\nDor’ ibyar’ indamu zanjye, Sinkibyitayeho namba;\nMpisemo kugira Yesu, Akaba mu bugingo bwanjye."}, {"type": "verse", "number": 2, "content": "Ab’ isi barantoteza, Kuko badafite Yesu.\nBatay’ Umukiza wanjye, Barashaka kungerageza.\nN’ ubwo bampana bakandeka, Yesu ampor’ iruhande.\nYes’ ampa kwihanganira, Ingorane z’ iyi si zose."}, {"type": "verse", "number": 3, "content": "Isi yahaw’ agakiza, Yesu yarayicunguye.\nYesu yaneshej’ icyaha; Nta bwoba ngifite na gato.\nUmwuka Wer’ ari muri twe; Mbeg’ umunezero mwinshi!\nNawe yaragupfiriye, Ng’ uzabane na we mw’ ijuru!"}, {"type": "verse", "number": 4, "content": "Twar’ intwaro zo kwizera; Senga cyan’ ubudatuza;\nUgiye gutah’ ijuru, Hazab’ umunezero mwinshi!\nIbyo dukorera mw’ isi, Biri hafi kurangira.\nN’ ibyiringiro bishyitse, Tuzabona Data mw’ ijuru."}]},
  {"number": 400, "name": "Mwami Nje Ngusanga", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/400", "key": "sol", "references": [{"codes": "HL. 491"}, {"title": "JE M’ APPROCHE DE TOI"}], "body": [{"type": "verse", "number": 1, "content": "Mwami nje ngusanga, Nje bugufi bwawe.\nUmpire Mwami, Wowe soko y’ ubugingo bw’ iteka;\nUmpire Mwami; Wowe soko y’ ubugingo bw’ iteka."}, {"type": "verse", "number": 2, "content": "Mp’ umutim’ utuje, Mwami ndakwinginze.\nNgwin’ umvugishe, Unganirize, Mwami mwiza wera;\nNgwin’ umvugishe, Unganirize, Mwami mwiza wera."}, {"type": "verse", "number": 3, "content": "Umpe gusa nawe, Mpa kamere yawe;\nNdashaka rwose kumera nkawe, Mpa kumera nkawe;\nNdashaka rwose kumera nkawe, Mpa kumera nkawe."}, {"type": "verse", "number": 4, "content": "Mp’ ubutwari Mwami, Unshoboze Mwami;\nUmpe gukor’ umurimo wawe, Uko bikwiriye;\nUmpe gukor’ umurimo wawe, Uko bikwiriye."}, {"type": "verse", "number": 5, "content": "Ubw’ uzab’ uje kujyan’ intore zawe;\nNanjy’ uzanjyane Mwami w’ abami, Ubw’ uzagaruka;\nNanjy’ uzanjyane Mwami w’ abami, Ubw’ uzagaruka."}]},
  {"number": 401, "name": "Uko Duteraniye Hamwe", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/401", "key": "do", "references": [{"codes": "SDAH. 8"}, {"title": "WE GATHER TOGETHER"}], "body": [{"type": "verse", "number": 1, "content": "Uko tur’ aha, Duteraniye hamwe,\nMwami Nyagasan’ uduh’ umugisha.\nUduhana kugira ngo twihan’ ibyaha;\nN’ubwo tur’ abanyabyaha, Ntujy’ utureka."}, {"type": "verse", "number": 2, "content": "Ni wow’ uturinda, Nyagasani Mana;\nWow’ udushyira ku murimo wawe.\nNi wowe uduha kunesha ku rugamba,\nMaz’ Imana yac’ igahabw’ icyubahiro."}, {"type": "verse", "number": 3, "content": "Twererez’ izina ryawe Mana yera.\nUrind’ umukumbi waw’ amakuba,\nUtuber’ Umurengezi mu bihe byose.\nDuh’ umudendezo, Tuguhimbaze Mana."}]},
  {"number": 402, "name": "Mfat’ Ikiganza", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/402", "key": "la bémol", "references": [{"codes": "GH. 1"}, {"title": "TAKE MY HAND, PRECIOUS LORD"}], "body": [{"type": "verse", "number": 1, "content": "Mu gihe ndi hafi kubur’ ibyiringiro;\nMu gihe ntentebutse;\nYesu ndakwinginze, Wumve gutaka kwanjye;\nMfat’ ikiganza, Maz’ ungez’ iwacu."}, {"type": "chorus", "content": "Mwami mwiza cyane, Umfate unkomeze.\nNdarushye, Ndihebye, Nta ntege.\nMu mwijim’ ukaze, Umfate unkomeze;\nMfat’ ikiganza, Maz’ ungez’ iwacu."}, {"type": "verse", "number": 2, "content": "Mu gihe mbundikiwe n’ umwijima mwinshi,\nW’ ibyago n’ amakuba,\nUmpe kwambuk’ inyanja y’ ibigeragezo.\nMfat’ ikiganza, Maz’ ungez’ iwacu."}]},
  {"number": 403, "name": "Mwami Wanjye Nyakira", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/403", "key": "mi", "body": [{"type": "verse", "number": 1, "content": "Mwami wanjy’ akir’ umubiri wanjye;\nUwuhindur’ urusengero rwawe rwera.\nNywugukoreshereze kujya nguhimbaza,\nMpore nguhesh’ ikuzo."}, {"type": "verse", "number": 2, "content": "Mwami wanjy’ akira impano zanjye;\nZikoresh’ uk’ ushaka, Ziguhesh’ ikuzo.\nNgiz’ italanto zanjye, Zikuramye Mwami,\nMpore nguhesh’ ikuzo."}, {"type": "verse", "number": 3, "content": "Mwami wanjye nguhay’ igihe cyanjye;\nUmwanya wose mfite, ndawukweguriye;\nNgo kimber’ igihe cyo gukor’ iby’ ushaka,\nMpore nguhesh’ ikuzo."}, {"type": "verse", "number": 4, "content": "Mwami wanjy’ akir’ ubutunzi bwanjye;\nWabumpereye kugira ngo mbukoreshe.\nUnyonger’ imigisha, mubyo nkora byose,\nMpore nguhesh’ ikuzo."}]},
  {"number": 404, "name": "Mucunguzi Mwiza", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/404", "key": "ré", "references": [{"codes": "GH. 121"}, {"title": "BLESSED REDEEMER"}], "body": [{"type": "verse", "number": 1, "content": "Ndareb’ Umucunguzi wanjye, Azamukan’ intimba nyinshi!\nKu musozi wa Kaluvari, Bamwikorej’ umusaraba!"}, {"type": "chorus", "content": "Ndareb’ Umucunguzi wanjye,\nAbabaye; Agan’ i Kaluvari.\nYatew’ intimba n’ ibyaha byanjye;\nYarambabarijwe ngo nkire."}, {"type": "verse", "number": 2, "content": "Data mwiza, bababarire! Ni ko yasabiy’ abagome.\nAmaraso y’ arameneka, Azir’ ibyaha byanjye nawe."}, {"type": "verse", "number": 3, "content": "Yes’ Umucunguz’ arankunda; Kubw’ ibyo nanjye ndamukunda.\nNzahora muhimbaz’ iteka! Yarancunguye, nahimbazwe!"}]},
  {"number": 405, "name": "Mpa Umugisha Waw’ Ubu", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/405", "key": "fa", "references": [{"codes": "S. 491"}, {"title": "BLESS ME NOW"}], "body": [{"type": "verse", "number": 1, "content": "Mbe Data wo mw’ ijuru, Ngwin’ umpire rwos’ ubu;\nUmbabarir’ ibyaha, Unkiz’ ibicumuro."}, {"type": "chorus", "content": "Data wo mw’ ijuru,\nMp’ umugisha waw’ ubu."}, {"type": "verse", "number": 2, "content": "Nkeney’ ubuntu bwawe, Nyongerer’ imbaraga.\nNdi kwig’ Ijambo ryawe, Ngwino rwos’ umpir’ ubu."}, {"type": "verse", "number": 3, "content": "Yesu nkiz’ umvaneho imbogamizi zose.\nNi wowe ndangamiye, Nkorah’ unyez’ ibyaha."}, {"type": "verse", "number": 4, "content": "Nicishije bugufi, Mpfukamy’ imbere yawe.\nYesu ngwin’ unkiz’ ubu, Wumve gutaka kwanjye."}]},
  {"number": 406, "name": "Kuba Mu Maboko Yawe", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/406", "key": "la bémol", "references": [{"codes": "S. 878"}, {"title": "CASTING ALL YOUR CARE UPON HIM"}], "body": [{"type": "verse", "number": 1, "content": "Kuba mu maboko yawe, N’ iby’ igikundiro;\nMan’ iyo nkumva bugufi, Numva nkomeye cyane."}, {"type": "chorus", "content": "S. na A.: Umwikorez’ amaganya, Umuh’ imitwaro yawe.\nMuh’ ibikurushya byose, Kukw’ anezezwa no kukurinda.\nT. na B.: Umwiko-re-ze, Korez’ amaganya,\nUmuh’ i - h’imitwaro yawe.\nMuh’ ibikuru - bikurushya byose,\nKunezezwa no kurinda."}, {"type": "verse", "number": 2, "content": "Wemera ko nguh’ ibimbabaza byanjye byose,\nNkakwikorez’ amaganya yanjye yos’ ukw’ angana."}, {"type": "verse", "number": 3, "content": "Ndakwiringira Nyagasani, Nguhanz’ amaso;\nUcuby’ imiraba, Wumv’ amasengesho dusenga."}, {"type": "verse", "number": 4, "content": "Iby’ ejo ntibimpangayikishije na hato.\nKo ngufite Mana yanjye, Naterw’ ubwoba n’ iki?"}]},
  {"number": 407, "name": "Mwibur’ Ibyiringiro", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/407", "key": "la bémol", "references": [{"codes": "S. 727"}, {"title": "COMFORT YE ONE ANOTHER"}], "body": [{"type": "verse", "number": 1, "content": "Mwibur’ ibyiringiro, Ngo mukuk’ imitima.\nMureke guhogora, Abapfiriye muri Yesu bazazuka."}, {"type": "chorus", "content": "Humuriza bose, Bibuts’ ayo magambo;\nKo Yesu yapfuye, Arikw’ akazuka.\nTuzabana na we, Kuko yaducunguye;\nUrupfu ntiruzongera kubaho."}, {"type": "verse", "number": 2, "content": "Igihe kiri bugufi, Tyo nimube maso.\nYes’ agiye kwimika ingom’ idahanguka, Tuzaba mw’ iteka."}, {"type": "verse", "number": 3, "content": "Tyo twe gukuk’ imitima, Yesu ntazatinda,\nAzaduhanagura amarira ku maso, Nta kurir’ ukundi."}]},
  {"number": 408, "name": "Dushim’ Umwam’ Imana", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/408", "key": "fa", "references": [{"codes": "SDAH. 1"}, {"title": "PRAISE TO THE LORD"}], "body": [{"type": "verse", "number": 1, "content": "Duhimbaz’ Umwam’ Imana, Ushobora byose;\nUmutima wanjy’ urahimbaz’ Imana Data.\nTumuramye, Tumuh’ icyubahiro,\nKukw’ ar’ Umwami w’ abami."}, {"type": "verse", "number": 2, "content": "Duhimbaz’ Umwam’ utegek’ ibyaremwe byose;\nAtubundikishij’ amabab’ araturinda.\nMbeg’ uburyo ibyo yaremye byose,\nByumvir’ amategeko Ye!"}, {"type": "verse", "number": 3, "content": "Duhimbaz’ Umwami, Nyir’ ibyiza bihebuje!\nImbabazi ze n’ impuhwe bihorahw’ iteka.\nTuzirikan’ ibyiz’ adukorera,\nN’ inshut’ itagereranwa."}]},
  {"number": 409, "name": "Nimuze Kwa Yes’ Arabakunda", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/409", "key": "si bémol", "references": [{"codes": "HL. 257"}, {"title": "VENEZ AU SAUVEUR"}], "body": [{"type": "verse", "number": 1, "content": "Nimuze kwa Yes’ arabakunda, Nimucik’ ingoyi z’ umwanzi;\nYesu yiteguye kubakira, Atez’ ibiganza."}, {"type": "chorus", "content": "Mbeg’ umuns’ uneje-je cyane!\nKwibera mu mabo-ko ye!\nMu nzu ya Data ni heza cyane,\nHar’ umunezero."}, {"type": "verse", "number": 2, "content": "Yemwe banyabyaha nimwitabe, Yes’ abafitiy’ urukundo.\nMwe kwigomeka nimumusange, Mwisubir’ inyuma."}, {"type": "verse", "number": 3, "content": "Dor’ igihe kirihuta bwangu, Nimureke kwirindiriza.\nYes’ arahari nimumusange, Rwos’ arabakira."}]},
  {"number": 410, "name": "Iby’ Imana Ikora", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/410", "key": "mi bémol", "references": [{"codes": "AH. 63"}, {"title": "GOD MOVES IN A MYSTERIOUS WAY"}, {"codes": "CH. 84"}], "body": [{"type": "verse", "number": 1, "content": "Iby’ Iman’ ikor’ ibikora mu buryo bwayo!\nIter’ intambwe mu nyanj’ umurab’ ugahunga."}, {"type": "verse", "number": 2, "content": "Ntabw’ abubah’ Imana, Bakwiye kuyitinya,\nNi yo Nyir’ impuhwe nyinshi, Itang’ imigisha."}, {"type": "verse", "number": 3, "content": "Kubw’ ubuntu, Tubasha kuyisobanukirwa.\nIyo tuyirengagije, Tugir’ igihombo."}, {"type": "verse", "number": 4, "content": "N’ Iman’ itabura gusohoz’ ibyo yavuze,\nIdufitiy’ imigambi myiz’ ikiranuka."}, {"type": "verse", "number": 5, "content": "Umunt’ udafite kwizera, Ntiyayimenya.\nIhishurir’ abayikund’ imigambi yayo."}]},
  {"number": 411, "name": "Nkeneye Umukiza", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/411", "key": "la bémol", "references": [{"codes": "SDAH. 539"}, {"title": "I WILL EARLY SEEK THE SAVIOUR"}], "body": [{"type": "verse", "number": 1, "content": "Nkeney’ Umukiza Yesu, Nshaka kumwigiraho;\nNkager’ ikirenge mu cye, Nca mu nzir’ ifunganye."}, {"type": "chorus", "content": "Arankunda, Arankunda,\nYes’ arankunda cyane!\nYarapfuy’ ari jy’ azira;\nNi yo mpamvu mukunda."}, {"type": "verse", "number": 2, "content": "Nzajy’ ahw’ azantuma hose, Nzahora niteguye.\nSindi muto byatuma ntabasha kujy’ ahw’ antuma."}, {"type": "verse", "number": 3, "content": "Dor’ ahagaze ku rugi, Kand’ arampamagara.\nNgo musange anyakire, Ankiz’ ibyaha byanjye."}]},
  {"number": 412, "name": "Abarembejwe N’ Ibyaha", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/412", "key": "sol", "references": [{"codes": "SDAH. 279"}, {"title": "ONLY TRUST HIM"}], "body": [{"type": "verse", "number": 1, "content": "Abarembejwe n’ ibyaha, Musang’ Umukiza,\nArabaruhura, Nimumwiringira rwose."}, {"type": "chorus", "content": "Mwiringire Yesu,\nNimumwiringire rwose.\nMwiringire Yesu,\nMumwiringire mukire."}, {"type": "verse", "number": 2, "content": "Yabaviriy’ amaraso, Ahesh’ umugisha;\nMwiyuhagire mo, Arabeza nk’ urubura."}, {"type": "verse", "number": 3, "content": "Yesu ni we kuri, Ni we nzira y’ amahoro,\nNimumwizer’ azabah’ ubugingo bw’ iteka."}, {"type": "verse", "number": 4, "content": "Nimusang’ abera, Maze musingize Yesu,\nNi bwo muzatura, Mu gihugu cy’ amahoro."}]},
  {"number": 413, "name": "Ngwino Hafi Y’ Umusaraba", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/413", "key": "la bémol", "references": [{"codes": "HL. 225"}, {"title": "VIENS À LA CROIX"}], "body": [{"type": "verse", "number": 1, "content": "Tyo ngwino hafi y’ umusaraba, Wa munyabyaha we;\nIkiganza cya Yesu cyiteguye kugukiza."}, {"type": "verse", "number": 2, "content": "Wowe wahumanijwe n’ ibyaha, Ngwino Yes’ akweze;\nWihane Yes’ akugire mushya mu kanya gato!"}, {"type": "verse", "number": 3, "content": "Ngwino Yes’ agutur’ umutwaro, Maz’ akuruhure;\nHafi y’ umusaraba ni h’ uzabon’ amahoro."}, {"type": "verse", "number": 4, "content": "Uhor’ ufata hirya no hino, Wabuz’ ishyikizo;\nNgwino hafi y’ umusaraba ubon’ agakiza."}]},
  {"number": 414, "name": "Wari Aho Babamby’ Umwami Wanjye?", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/414", "key": "mi bémol", "references": [{"codes": "SDAH. 158"}, {"title": "WHERE YOU THERE?"}, {"codes": "GH. 64"}], "body": [{"type": "verse", "number": 1, "content": "War’ aho babamby’ Umwami Yesu?\nWar’ aho babamby’ Umwami wanjye?\nWar’ uhari? Binter’ umubabaro mwinshi.\nMbese koko war’ aho babamby’ Umwami wanjye?"}, {"type": "verse", "number": 2, "content": "War’ uhari abambwa ku giti?\nWar’ uhari abambwa ku giti?\nWar’ uhari? Binter’ umubabaro mwinshi.\nMbese koko war’ aho babamby’ Umwami wanjye?"}, {"type": "verse", "number": 3, "content": "Wari yo bamucumit’ icumu?\nWari yo bamucumit’ icumu?\nWar’ uhari? Binter’ umubabaro mwinshi.\nMbese koko war’ aho babamby’ Umwami wanjye?"}, {"type": "verse", "number": 4, "content": "Wariy’ igih’ izuba ryijima?\nWariy’ igih’ izuba ryijima?\nWar’ uhari? Binter’ umubabaro mwinshi.\nMbese koko war’ aho babamby’ Umwami wanjye?"}, {"type": "verse", "number": 5, "content": "War’ uhar’ igihe bamuhamba?\nWar’ uhar’ igihe bamuhamba?\nWar’ uhari? Binter’ umubabaro mwinshi.\nMbese koko war’ aho babamby’ Umwami wanjye?"}]},
  {"number": 415, "name": "Nimuzan’ Icyacumi", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/415", "key": "fa", "references": [{"codes": "CS. 239"}, {"title": "BRING YE ALL THE TITHES"}], "body": [{"type": "verse", "number": 1, "content": "Nimwumv’ amagambo y’ ibyanditswe kera, Avug’ ati: Muzan’ icyacumi.\nNimwih’ Imana mwezwe, Ngo mubon’ uko muhabw’ umugisha mwinshi."}, {"type": "chorus", "content": "Nimuzan’ icyacumi gishyitse.\nIman’ iti: Mungerageze.\nIzabasukahw’ imigisha,\nMaze mubur’ aho muzayikwiza."}, {"type": "verse", "number": 2, "content": "Nimushak’ imbaraga y’ Umwuka Wera, Nimuzan’ icyacumi gishyitse.\nKandi nimukizane nk’ uko byanditswe, Ibasukehw’ imigisha."}, {"type": "verse", "number": 3, "content": "Se har’ icyabatandukanya n’ Imana? Nimuzan’ icyacumi gishyitse;\nMubone kubana n’ Imana iteka, Isohoz’ isezerano."}, {"type": "verse", "number": 4, "content": "Nimwegurire Yes’ imitima yanyu; Nimuzan’ icyacumi gishyitse;\nNimwizer’ isezerano ry’ Uhoraho, Bizabah’ umunezero."}]},
  {"number": 416, "name": "Hirya No Hino Har’ Umukumbi", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/416", "key": "fa", "references": [{"codes": "SDAH. 447"}, {"title": "LONG UPON THE MOUNTAINS"}], "body": [{"type": "verse", "number": 1, "content": "Hirya no hino har’ umukumbi, Ugoswe n’ amakub’ akomeye,\nN’ ubutayu bucuz’ umwijima, Dor’ inzira ntabw’ igaragara.\nWumv’ amajwi mensh’ aratabaza, Bakeney’ umutabazi;\nHar’ ijwi ryiza rihumuriza, Ribabwira riti: Mukomere."}, {"type": "verse", "number": 2, "content": "Uwo mukumb’ ukeney’ umucyo, Ku mategeko cumi y’ Imana,\nYukw’ ar’ ayera kand’ aboneye; Bakwiriye kuyakurikiza.\nMw’ uru rugendo rujya mw’ ijuru, Bakeneye Yesu Kristo,\nKung’ ubumw’ urukundo kwizera, Bakicisha buguf’ imbere Ye."}, {"type": "verse", "number": 3, "content": "Har’ ahantu hahebuj’ ubwiza, Mu rurembo rurabagirana;\nAmarembo yarw’ aruguruye, N’ ahantu heza h’ igikundiro;\nHazirana n’ icyaha n’ urupfu; Nta mubabar’ uzabayo.\nAho ni ho tuzateranira, Ntabwo tuzongera gupf’ ukundi."}, {"type": "verse", "number": 4, "content": "Dore Yes’ agiye kugaruka hamwe n’ ibic’ azur’ abapfuye.\nAbacunguwe bazazamurwa, Baririmbana umunezero.\nNgwino Mwami, Ngwin’ udutabare; Twigir’ iwacu mw’ ijuru,\nTuragutegereje Mukiza, Utujyane kwibera mw’ ijuru."}]},
  {"number": 417, "name": "Tur’ Abasirikari Mu Ngabo Za Yesu", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/417", "key": "sol", "body": [{"type": "verse", "number": 1, "content": "Tur’ abasirikari mu ngabo za Yesu; Ku rugamba tuyobowe na Yesu;\nTugamije gutsinda Satani n’ ingabo ze, Kandi ntiduteze gusubir’ inyuma."}, {"type": "chorus", "content": "Dushyire hamwe, Twitabir’ urugamba.\nYesu ni w’ utuyoboy’ atur’ imbere,\nN’ubw’ urugamba rwakomera rute,\nTuzarutsinda kubw’ Umwami Yesu."}, {"type": "verse", "number": 2, "content": "Abanzi b’ Ubutumwa barahagurutse; Bagambiriye kutugamburuza.\nBafit’ ishyari ryinshi, n’ umujiny’ utavugwa, Dukomez’ ibirindiro tuzanesha."}, {"type": "verse", "number": 3, "content": "Tugendere munsi y’ ibendera rya Yesu; Dufit’ intwaro zirabagirana;\nZacuriwe mu ruganda rutoz’ urukundo, Duharanir’ ikamba ritangirika."}, {"type": "verse", "number": 4, "content": "Turaharanira kuzataha mw’ ijuru; Mu bwami bw’ Umukiza wacu Yesu.\nMubivuge hose mwamamaz’ ubutumwa bwe, Abantu babumenye bakizw’ ibyaha."}]},
  {"number": 418, "name": "N’ Iki Cyatuma Tumwirengagiza?", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/418", "key": "mi bémol", "references": [{"codes": "S. 1135"}, {"title": "HOW CAN WE FORGET HIM?"}], "body": [{"type": "verse", "number": 1, "content": "N’ iki cyatuma twirengagiz’ Umukiza, Se har’ icyadutera kumwibagirwa?\nKand’ aturinda ku manywa na nijoro, Aturagira nk’ Umwunger’ udakenesha."}, {"type": "chorus", "content": "Tuzagendera mu mucyo w’ Umwami wacu iteka,\nTuzitangira kumukorera,\nTuramwumvira ngw’ aduhe k’ Umwuka we,\nTubone kumuhesh’ icyubahiro cyinshi."}, {"type": "verse", "number": 2, "content": "N’ iki cyatuma twirengagiz’ Umukiza, Tukibagirwa uwatubabarijwe,\nUbu yicaye ku ntebe ye ya cyami, N’ Umuhuza wacu w’ ibihe bidashira."}, {"type": "verse", "number": 3, "content": "N’ iki cyatuma twirengagiz’ Umukiza, Kand’ ahor’ abera maso kuturinda.\nN’ inshuti nziza irut’ izindi zose, Nta muntu n’ umwe yigera ahemukira."}]},
  {"number": 419, "name": "Inanga Z’ Izahabu Ziracurangwa", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/419", "key": "la", "references": [{"codes": "S. 87"}, {"title": "GOLDEN HARPS ARE SOUNDING"}], "body": [{"type": "verse", "number": 1, "content": "Inanga z’ izahabu ziracurangwa, Amaremb’ arakinguk’ arinjira.\nUmwami w’ imbabazi n’ urukundo, Yaratabarutse atsinz’ urupfu."}, {"type": "chorus", "content": "Yesu yasohoj’ umurimo we,\nNon’ ari mw’ ijuru, Tumuhimbaze."}, {"type": "verse", "number": 2, "content": "Yavukiye mw’ isi ngw’ aturokore, Arapf’ arazuka, ajya mw’ ijuru.\nVuz’ impundu koko yaranesheje, Nasingizwe n’ abo mw’ iyi si n’ ijuru."}, {"type": "verse", "number": 3, "content": "Twes’ abana b’ ahor’ adusabira, Muze tweger’ intebe ye y’ ubwami.\nYaduteguriye amazu meza, Ngo tuzabaneyo mu munezero."}]},
  {"number": 420, "name": "Yesu Ngwino Ubane N’ Itorero Ryawe", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/420", "key": "ré", "references": [{"codes": "SDAH. 374"}, {"title": "JESUS, WITH THY CHURCH ABIDE"}], "body": [{"type": "verse", "number": 1, "content": "Yesu ngwin’ ubane n’ itorero ryawe ryose.\nRifashe, ribashe gutsind’ ibigeragezo."}, {"type": "verse", "number": 2, "content": "Ribashe gutunganya nez’ inshingano zaryo;\nRiburir’ abo mw’ isi, Bitegur’ urubanza."}, {"type": "verse", "number": 3, "content": "Ryite ku batabona, N’ abakene bo mw’ isi;\nRihabur’ abahabye, Ribabwir’ ibya Yesu."}, {"type": "verse", "number": 4, "content": "Ryuzur’ Umwuka Wera, Maze rinesh’ icyaha,\nRihuze mw’ isi yose, Yesu turakwinginze."}]},
  {"number": 421, "name": "Duhimbaze Yesu", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/421", "key": "sol", "references": [{"codes": "SDAH. 249"}, {"codes": "AH. 140"}, {"title": "PRAISE HIM! PRAISE HIM!"}, {"codes": "CH. 645"}, {"codes": "CS. 226"}], "body": [{"type": "verse", "number": 1, "content": "PRAISE HIM! PRAISE HIM!"}, {"type": "verse", "number": 1, "content": "Duhimbaze Yesu Mucunguzi wacu,\nTuririmb’ urukundo rwe rwinshi.\nAfit’ icyubahiro giheranije;\nIzina rye ryera risingizwe!\nN’ Umwungeri mwiza wita ku ntama ze,\nArind’ abana b’ ibihe byose."}, {"type": "chorus", "content": "Tumuhimbaze tumuh’ ikuzo ryinshi,\nTumutur’ indirimbo y’ ishimwe."}, {"type": "verse", "number": 2, "content": "Duhimbaze Yesu Mucunguzi wacu,\nYatew’ intimb’ arapfa ku bwacu!\nNi we byiringiro by’ agakiza kacu,\nNi yubahwe yaratubambiwe.\nYarababajwe apfa mu cyimbo cyacu,\nKubw’ urukundo rwe rutangaje!"}, {"type": "verse", "number": 3, "content": "Duhimbaze Yesu Mucunguzi wacu,\nIjuru ryasābwe n’ ibyishimo!\nN’ intwari n’ umuneshi yambay’ ikamba.\nN’ Umwami wac’ utuvuganira,\nUmwami Yesu ugiye kugaruka,\nAzaza mu cyubahiro cyinshi!"}]},
  {"number": 422, "name": "Ukw’ Ibihe Bigenda Bihita", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/422", "key": "ré", "references": [{"codes": "SDAH. 532"}, {"title": "DAY BY DAY"}], "body": [{"type": "verse", "number": 1, "content": "Ukw’ ibihe bigenda bihita, Mpangana n’ ibigeragezo;\nAriko kubwo kwisung’ Imana, Nshobozwa kubitsinda byose.\nKubwo kwiringir’ Imana Data, Sinshobora kwiheba rwose;\nIrankunda birenz’ urugero; Imp’ amahoro n’ ibyishimo!"}, {"type": "verse", "number": 2, "content": "Uwitek’ Umwami wanjye mwiza, Ntasiba kungirir’ impuhwe.\nYita ku mitwaro yanjye yose, Amber’ umujyanama mwiza.\nNi w’ urind’ imibereho yanjye, Kand’ afit’ imbaraga nyinshi;\nKumugira n’ ubutunzi bwinshi, Ni we mahirwe yanjye yose."}, {"type": "verse", "number": 3, "content": "Mfasha Data nkomeze nkwizere, N’ ubwo nanyura mu makuba,\nNiringir’ isezerano ryawe, Niringir’ ihumure ryawe.\nUnkiz’ umuraba w’ amakuba, Mbashisha guhangana neshe;\nKw’ iherez’ uzangeze mw’ ijuru, Mu gihugu cy’ isezerano."}]},
  {"number": 423, "name": "Mfit’ Umukiza N’ Inshut’ Inkunda", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/423", "key": "sol", "references": [{"codes": "HL. 255"}, {"title": "SI VOUS SAVIEZ"}], "body": [{"type": "verse", "number": 1, "content": "Mfit’ Umukiza kand’ adukunda twese,\nIyaba namwe mwari mumumenye.\nAramvuganira kwa Data wo mw’ ijuru,\nIcyampa namw’ akababer’ inshuti."}, {"type": "chorus", "content": "Yes’ aragukunda,\nUmugir’ inshuti.\nKand’ abe kw’ isonga;\nAzajy’ agufasha."}, {"type": "verse", "number": 2, "content": "Yesu yampay’ amahoro mu mutima,\nIyab’ ibyo mwari mubizi neza.\nKubw’ amaraso yaviriy’ i Gologota,\nNawe numwakira urayahabwa."}, {"type": "verse", "number": 3, "content": "Har’ ibyiringiro duhabwa n’ Imana,\nIyab’ ibyo mwari mubizi neza.\nIjwi riduhamagara rihumuriza,\nRitang’ amahoro yo mu mutima."}, {"type": "verse", "number": 4, "content": "Mumeny’ ubury’ Umwami Yes’ abakunda,\nUmutwar’ aguha nturemereye.\nUmubwire n’ abandi na bo bamumenye,\nMaz’ ubabwir’ ibyo yagukoreye."}]},
  {"number": 424, "name": "Urukundo Rwawe Mana", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/424", "key": "ré", "references": [{"codes": "SDAH. 396"}, {"title": "LORD GOD, YOUR LOVE HAS CALLED US HERE"}], "body": [{"type": "verse", "number": 1, "content": "Urukundo rwawe Mana, Ni rwo ruduhamagara.\nNi muri rwo twaremewe, Ni na rwo rutubeshaho.\nN’ ubwo twagucumuyeho, Tugaruts’ imbere yawe."}, {"type": "verse", "number": 2, "content": "Tuje kugutur’ intimba z’ imitima imenetse;\nTugoswe n’ ingoyi nyinshi, Zitubuz’ umudendezo;\nUtuvane mu bwigunge, Uduhaz’ ibyiringiro."}, {"type": "verse", "number": 3, "content": "Mana Data muri Yesu watugiz’ abana bawe;\nNtacyo twakoze na kimwe, Cyaduhesh’ ayo mahirwe;\nN’ ubuntu bwawe Nyagasani, Twese tugupfukamire!"}, {"type": "verse", "number": 4, "content": "Imitima yacu Mana, Icishwe bugufi cyane;\nDusingize mu ndirimbo, Imana yakunz’ ab’ isi;\nYatugize inshuti zayo, Natwe tuyikunde cyane."}, {"type": "verse", "number": 5, "content": "Ni y’ iduh’ umudendezo, Muri Yes’ Umwana wayo;\nKubw’ amaraso yavuye, Twagizwe bashya muri we;\nKubw’ ubugingo bwe yatanze, Twagizw’ abana b’ Imana!"}]},
  {"number": 425, "name": "Ni Mutyo Turirimbe…", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/425", "key": "sol", "references": [{"codes": "HL. 50"}, {"title": "CHANTONS, CHANTONS SANS CESSE…"}], "body": [{"type": "verse", "number": 1, "content": "Nimutyo turirimbe ineza ya Yesu, Ibyishimo bisābe imitima yacu.\nTwabony’ agakiza, Kavuye mw’ ijuru; Twahaw’ Umukiza, Twahaw’ Umukiza."}, {"type": "verse", "number": 2, "content": "N’ umunezero mwinshi, twarababariwe; Imana yadukuyehw’ iteka ryo gupfa.\nYesu yikorey’ imitwaro y’ ibyaha; Yaradupfiriye, Yaradupfiriye,"}, {"type": "verse", "number": 3, "content": "Ku ntebe y’ ubwami kwa Data wo mw’ ijuru, Dufit’ Umuvugizi utuvuganira;\nUturwanirira kandi n’ Umuneshi; Yaradutsindiye, n’ Umuneshi wacu."}, {"type": "verse", "number": 4, "content": "Yambik’ abo yacunguye bos’ ubwiza bwe, Akabah’ imico ye iboneye rwose.\nKubw’ ubuntu bw’ atuyoboz’ Umwuka we, N’ukuri kwe kwera, N’ukuri kwe kwera."}, {"type": "verse", "number": 5, "content": "Yes’ ari hafi kugaruka mu bwiza bwe; Azaza kutujyana tw’ abo yacunguye;\nTwimane na we mu bwami bwo mw’ ijuru; Tuzamwirebera, Tuzamwirebera."}]},
  {"number": 426, "name": "Har’ Urukundo Rutangaje", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/426", "key": "sol", "references": [{"codes": "S. 919"}, {"title": "PERFECT LOVE"}], "body": [{"type": "verse", "number": 1, "content": "Har’ urukundo rutangaje, Runzamura mu bitekerezo,\nNkamera amababa, Nkumva nigereye mw’ ijuru,\nNkibona ndi hamwe n’ Umukiza, Ndi gusangira na we."}, {"type": "verse", "number": 2, "content": "Ndi ku musozi muremure, Maze ndeb’ iburasirazuba,\nMbon’ igihugu cyiza, N’ igihugu gitey’ ubwuzu.\nN’ igihugu cy’ amata n’ ubuki, N’ imbuto z’ agahozo."}, {"type": "verse", "number": 3, "content": "Ibyo kurya by’ icyo gihugu, Twabiteguriwe n’ Uwiteka.\nNi byiza bitavugwa! Iman’ izatumwenyurira,\nTuzaba turi kumwe na Yesu, Mu bwami bwo mw’ ijuru."}, {"type": "verse", "number": 4, "content": "Nshaka kwambuka yorodani, Ngatandukana n’ imibabaro,\nN’ amakuba by’ iyi si, Y’ ibyago no gushidikanya;\nN’ ubutayu n’ isi y’ igomero, Mw’ iyi si si hw’ iwacu."}]},
  {"number": 427, "name": "Icyampa Igihe Kikihuta Bwangu", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/427", "key": "fa", "references": [{"codes": "S. 920"}, {"title": "WE’ LL WORK TILL JESUS COMES"}], "body": [{"type": "verse", "number": 1, "content": "Icyamp’ igihe kikihuta bwangu, Nkigira iwacu!\nNkibera mu mahoro nta kuganya, Ndahakumbuye."}, {"type": "chorus", "content": "Sop: Tuzakomeza dukorer’ Umwami wacu Yesu,\nKugez’ ubw’ azatugeza mw’ ijuru.\nAlto: Tuzakomeza du - rer’ U - mwami wacu, wacu,\nKugez’ ubw’ a - tugeza mw’ ijuru.\nTenor: Tuzakomeza dukorer’ U - mwami wacu Ye - Yesu,\nKugez’ ubw’ azatugeza mw’ ijuru.\nBass: Tuzakomeza du - rer’ Umwami wacu Ye - Yesu,\nKugez’ ubw’ atu - geza mw’ ijuru."}, {"type": "verse", "number": 2, "content": "Mur’ iyi si nta mutekan’ ubamo, N’ is’ irimw’ akaga;\nN’ isi yuzuyemo imibabaro, S’ iyo guturwa."}, {"type": "verse", "number": 3, "content": "Nzibera mu ruhande rw’ Umukiza, Sinzamurekura;\nAzambashisha kunesha urupfu, Ntashye mw’ ijuru."}]},
  {"number": 428, "name": "Haguruka, Haguruka", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/428", "key": "ré", "references": [{"codes": "HL. 501"}, {"title": "LEVE – TOI, LEVE - TOI"}], "body": [{"type": "verse", "number": 1, "content": "Umwam’ araguhamagara haguruka.\nAkuyobora mu mucyo, Mu nzira yo kwizera;\nMu rugendo rwo mw’ iyi si, Wigir’ ubwoba rwose;\nNgaho haguruka."}, {"type": "verse", "number": 2, "content": "Komera shikama b’ intwari ku rugamba;\nN’ ubwo Satan’ atontoma, Yarangije gutsindwa;\nYesu yaramunesheje, Komez’ ibendera Rye;\nKomera shikama."}, {"type": "verse", "number": 3, "content": "Komeza komeza, Rwanan’ ibyiringiro;\nRirimb’ indirimb’ igutera gushikama cyane.\nNtugashidikanye rwose, Gir’ umutim’ utuje;\nKomez’ ukomere!"}]},
  {"number": 429, "name": "Intekerezo Zanjye Zibera Mw’ Ijuru", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/429", "key": "ré", "references": [{"codes": "HL. 451"}, {"title": "PLUS HAUT QUE L’AZUR DES CIEUX"}], "body": [{"type": "verse", "number": 1, "content": "Dor’ intekerezo zanjye zibera mw’ ijuru,\nIbyiringiro byanjye ni ho bituriza;\nMu mucyo w’ Uwiteka, Yes’ azaduhuriza;\nMw’ ijuru, ibudapfa ni ho tuzibera."}, {"type": "verse", "number": 2, "content": "Mw’ ijuru nta mibabaro, Tuzaba dutuje;\nTuzahanagurw’ amarira tugezeyo.\nNta rupfu ruzabayo, nta kiduhungabanya;\nTuzabana by’ iteka, Turi mu mahoro."}, {"type": "verse", "number": 3, "content": "Mbeg’ ukuntu tuzishima, Twongeye guhura,\nN’ abo twari twaratandukanijwe kera!\nMw’ iteraniro ryiza, Maze duhoberane,\nTwibere mu byishimo bitazahinduka."}, {"type": "verse", "number": 4, "content": "Mbeg’ inanga z’ izahabu zizacurangwayo!\nUbw’ abacunguwe bazaba bateranye.\nYes’ azatuzamura, Atugeze mw’ ijuru,\nDusingiz’ urukundo, Twakunzwe n’ Imana."}]},
  {"number": 430, "name": "Nabara Nte Uburyo Yesu Yapfuye?", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/430", "key": "do", "references": [{"codes": "SDAH. 255"}, {"title": "I CAN NOT TELL WHY"}], "body": [{"type": "verse", "number": 1, "content": "Time Signature ─ Arr. By John Bernard"}, {"type": "verse", "number": 1, "content": "Nabara nte uburyo Yesu yapfuye? Uw’ abamarayika baramya!\nN’ Umwunger’ ushak’ uwari wazimiye, Ngw’ amucyur’ agaruke mu rugo.\nSe ntiyabyawe n’ umukobwa Mariya, Mu muvure i Betelehemu!\nKandi se ntiyakuriy’ i Nazareti! Ng’ uk’ uko yaje hano mw’ isi y’ ibyaha!"}, {"type": "verse", "number": 2, "content": "Mvuge nt’ uko yababajw’ akituriza! Agakiz’ iyi si y’ amarira;\nN’ umutim’ umenetse ku musaraba, Yesu yambitsw’ ikamba ry’ amahwa!\nNi w’ ukiza ab’ imitim’ imenetse, Kand’ akiz’ ubwob’ umunyabyaha!\nAdukiz’ imitwaro yose y’ ibyaha, N’ ub’ ari hano rwos’ ari kumwe natwe."}, {"type": "verse", "number": 3, "content": "Nabara nte uko yireherejeho amahanga yose yo mw’ iyi si!\nYahaw’ ubutware mw’ isi no mw’ ijuru, Nta na hamwe Yes’ atar’ Umwami.\nAri hafi kugaruka mu bwiza bwe, Kand’ amaso yos’ azamubona;\nAzab’ aje kujyan’ abe bamwizeye; Babane mu bwiza burabagirana!"}, {"type": "verse", "number": 4, "content": "Nabara nte ukw’ isi yos’ imuramya! Ukw’ acyah’ umurab’ ugahunga!\nNiw’ ushyir’ umunezero mu mitima, Kubw’ urukundo rwe rutangaje!\nMwa bari mw’ isi mwe, ni mumuhimbaze, Amajw’ ibihumb’ amusingize!\nIjuru ni rihamy’ icyubahiro cye; Yukw’ ar’ Umwami n’ Umucunguzi w’ isi."}]},
  {"number": 431, "name": "Twese Hamwe", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/431", "key": "si bémol", "references": [{"codes": "HL. 159"}, {"title": "FRERES, APPROCHONS - NOUS"}], "body": [{"type": "verse", "number": 1, "content": "Twese hamwe muze dushyire hamwe; Dusang’ Umwam’ Imana yacu.\nIyo Mana irakomeye, Muze tuyih’ icyubahiro."}, {"type": "verse", "number": 2, "content": "Iyo tur’ imbere y’ Imana yacu, Nta bugoryi buturangwaho.\nTwibera mu buturo bwera, Kubwo kwizera turakirwa."}, {"type": "verse", "number": 3, "content": "Turi hamwe twambaz’ Imana yacu, Tukabon’ ubwiza bwa Jambo.\nKubw’ Umwuka Wera w’ Imana, Duhabw’ imbarag’ ikomeye."}, {"type": "verse", "number": 4, "content": "Dat’ utwumve, Data mwiz’ udukunda! Nyamuna uduteg’ amatwi;\nWumve gusenga kwacu Data, Mw’ izina rya Yes’ uduhire."}]},
  {"number": 432, "name": "Duhore Twishimye", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/432", "key": "mi", "references": [{"codes": "CS. 284"}, {"title": "ALWAYS CHEERFUL"}], "body": [{"type": "verse", "number": 1, "content": "Mureke duhore twishimye, Imitima yac’ inezerwe.\nMbese n’ iki cyatubabaza, Kand’ Iman’ idukunda?"}, {"type": "chorus", "content": "Dukwiriye guhora twishimye,\nMu mibereho yacu yose.\nKandi mu nshingano zacu zose,\nTunezerwe twishime."}, {"type": "verse", "number": 2, "content": "Dor’ ukuboko k’ Uwiteka, Kuturind’ imyambi y’ ibyaha;\nKubw’ ubuntu araturinda, Kand’ atuma tunesha."}, {"type": "verse", "number": 3, "content": "Kand’ iyo turets’ inshingano, Iman’ iratuguyaguya;\nN’ ubwo tuba twitey’ akaga, Itureban’ impuhwe."}, {"type": "verse", "number": 4, "content": "Dukurikiz’ inama nziza, Tub’ abantu beza b’ intwari;\nMu rukundo kandi twishimye, Dukorere mu kuri."}]},
  {"number": 433, "name": "Nyenyeri Yo Mu Ruturuturu", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/433", "key": "sol", "references": [{"codes": "HL. 304"}, {"title": "BRILLANTE ETOILE"}], "body": [{"type": "verse", "number": 1, "content": "Nyenyeri yo mu ruturuturu unyobore;\nIgih’ inzir’ icuz’ umwijima unyobore.\nUmfash’ ukubok’ ukanyobora,\nMbese nabur’ ibyiringiro nte?"}, {"type": "verse", "number": 2, "content": "Jye ntabwo nagushidikanyaho unyobore;\nUmpumure maze mbon’ inzira unyobora.\nNatinze rwose kukuyoboza,\nUbu ndaje noneho nyobora."}, {"type": "verse", "number": 3, "content": "Mu bihanamanga mu bitare unyobore;\nMu bishanga ndetse no mu bihu unyobore.\nNdashaka kumv’ ijwi ryawe Yesu;\nWe Muyobozi mwiz’ utayobya."}, {"type": "verse", "number": 4, "content": "Mu gihe ntentebutse mbabaye unyobore;\nNdi mu cyunamo nabuz’ abanjye unyobore.\nNzi k’ undeba nez’ uri mw’ ijuru;\nNtey’ intambwe ngusang’ unyobore."}, {"type": "verse", "number": 5, "content": "Kubw’ urukundo rwawe, Mukiza unyobore;\nNdakwiyeguriye Mwami mwiza unyobore.\nYesu wabambwe ku musaraba,\nMuri byose komez’ unyobore."}]},
  {"number": 434, "name": "Bakristo Twite Ku Batishoboye", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/434", "key": "do", "references": [{"codes": "CS. 694"}, {"title": "THE NEEDY POOR"}], "body": [{"type": "verse", "number": 1, "content": "Bakristo, Bakristo twite ku batishoboye;\nNib’ umuken’ agez’ iwaw’ aje kugusaba,\nBurya har’ und’ uhagaz’ iruhande rw’ utabona!\nKumwakir’ iwawe bizaguhesh’ umugisha."}, {"type": "verse", "number": 2, "content": "Ijish’ ureb’ umukene Yes’ ab’ arireba.\nIy’ umwugururiy’ iremb’ akinjir’ iwawe,\nYesu yinjirana na w’ akazamur’ ibiganza,\nMaz’ akaguh’ umugisha mu by’ utunze byose."}, {"type": "verse", "number": 3, "content": "Yes’ azaguhir’ iteka mu buzima bwawe,\nKand’ azanaguh’ ikamba ry’ abakiranutsi.\nVub’ ah’ amarembo y’ ijur’ agiye gufunguka;\nYes’ azagororer’ abamukoreye neza."}]},
  {"number": 435, "name": "Agira Neza", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/435", "key": "sol", "references": [{"codes": "CS. 367"}, {"title": "HIS LOVING KINDNESS"}], "body": [{"type": "verse", "number": 1, "content": "Kanguka mutima wanjy’ ishime! Maz’ usingiz’ Umucunguzi wawe;\nAkwiriy’ indirimbo kubw’ ineza ye, N’ ubunt’ agira bw’ igitangaza.\nAgira neza kubw’ urukundo rwe rwinshi, Muze tumuririmbire."}, {"type": "verse", "number": 2, "content": "Yantabaye nar’ uwo gupfa, Maz’ arankiz’ ambeshahw’ amp’ ubugingo.\nYankuye mw’ isayo y’ ibyaha, Maz’ arankiza kubw’ urukundo rwe rwinshi.\nAgira neza kubw’ urukundo rwe rwinshi, Muze tumuririmbire."}, {"type": "verse", "number": 3, "content": "N’ ubw’ imbaraga z’ ikuzimu zampagurukira, Ntabwo zanshobora.\nN’ ubw’ abanzi bandwanya bakanyibasira, Ntabwo bashobora kunesha.\nAgira neza kubw’ urukundo rwe rwinshi, Muze tumuririmbire."}, {"type": "verse", "number": 4, "content": "N’ ubw’ imirabyo n’ inkuba byahinda, Ntabwo nzagir’ ubwoba na gato.\nYes’ ampora bugufi akarind’ ubugingo, Sinzagir’ ubwoba namba.\nAgira neza kubw’ urukundo rwe rwinshi, Muze tumuririmbire."}]},
  {"number": 436, "name": "Yewe Nzimizi We, Garuka", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/436", "key": "si bémol", "references": [{"codes": "S. 456"}, {"title": "RETURN, O WANDERER"}], "body": [{"type": "verse", "number": 1, "content": "Yewe nzimizi we, garuka; Umubyey’ aragushaka.\nN’ Umubyeyi ugukunda, Kand’ aragutegereje.\nNgwino! Ngwino!"}, {"type": "verse", "number": 2, "content": "Yewe nzimizi we, garuka; So aguteze amatwi.\nYita cyane ku bafite imitima imenetse.\nNgwino! Ngwino!"}, {"type": "verse", "number": 3, "content": "Yewe nzimizi we, garuka; Umukiz’ aragushaka.\nAz’ intege nkeya zawe, Jya ku birenge bya Yesu.\nNgwino! Ngwino!"}, {"type": "verse", "number": 4, "content": "Yewe nzimizi we, garuka; Uhanagurw’ amarira.\nNi So uguhamagara; Kand’ aragukunda cyane.\nNgwino! Ngwino!"}]},
  {"number": 437, "name": "Ntabwo Nzakureka", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/437", "key": "mi bémol", "references": [{"codes": "CH. 397"}, {"title": "I WILL NEVER LEAVE THEE"}], "body": [{"type": "verse", "number": 1, "content": "Ntabwo nzakureka, ntabwo nzakuvaho. Ntabwo nzagusiga wenyine.\nNzakurinda kandi nzajya ngukomeza, Nzajya nkwitaho ngushoboze.\nWitiny’ ahubwo kurikiza amabwiriza n’ inama byanjye."}, {"type": "verse", "number": 2, "content": "Igih’ umugaru uguteragana, Koresh’ isengesh’ ubimbwire.\nNzakubumbatiza amaboko yanjye, Nzakurinda kandi nkwiteho.\nN’ igih’ uzajy’ ugeragezwa, Nzajya nkubonesherez’ inzira."}, {"type": "verse", "number": 3, "content": "Ijuru rizakinguruka habone, Uhishurirw’ ubwiza bwanjye.\nUzabon’ amahor’ atemba nk’ uruzi, Byose bizaba byiza gusa.\nNzajya mbana nawe iteka, Kandi nzajya ndind’ intambwe zawe."}, {"type": "verse", "number": 4, "content": "Mu gih’ ubugingo bwawe busakiranye n’ umwijim’ ukaze cyane,\nNzajya ntamurur’ umwijim’ ukugose, Nzakuyoboz’ umucyo waka.\nNzagukund’ urukundo, Nzajya nkumurikira ah’ ujya hose."}]},
  {"number": 438, "name": "Hano Mur’ Iyi Si Sihw’ Iwacu", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/438", "key": "sol", "references": [{"codes": "CH. 659"}, {"title": "I’M BUT A STRANGER HERE"}], "body": [{"type": "verse", "number": 1, "content": "Hano mur’ iyi si si hw’ iwacu;\nAhubwo mw’ ijuru ni hw’ iwacu.\nMw’ isi y’ umubabaro n’ intimba zidashira,\nKwa Data mw’ ijuru ni hw’ iwacu."}, {"type": "verse", "number": 2, "content": "Mw’ ijuru n’ iwacu nta kabuza;\nN’ igihe gitoya ngatahayo.\nIbi bihe ducamo biri hafi gushira,\nNgiye kuger’ iwacu mw’ ijuru."}, {"type": "verse", "number": 3, "content": "Mw’ ijuru kwa Yesu ni ho nzaba;\nMw’ ijuru nzahaboner’ ikuzo.\nTuzabana n’ abera, n’ inshuti twakundaga;\nNzaruhukirayo ni hw’ iwacu."}]},
  {"number": 439, "name": "Ubugingo Bwanjye Buratakamba", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/439", "key": "ré bémol", "references": [{"codes": "HL. 335"}, {"title": "LE CRI DE MON ÂME"}], "body": [{"type": "verse", "number": 1, "content": "Ubugingo bwanjye buratakamba,\nBuragukeneye Mwami Yesu we!\nUmutwaro wawe uroroheje!\nMwungeri mwiza umbe mu mutima."}, {"type": "verse", "number": 2, "content": "Mwami Yes’ unyobor’ intambwe zanjye;\nKand’ umber’ igihome kinkingira,\nMu mwijim’ ukaze mfat’ ikiganza,\nUmurikire mu nzir’ ijy’ iwawe."}, {"type": "verse", "number": 3, "content": "Soko y’ ubuging’ uturuk’ ahera,\nMutsima w’ ubuging’ uva mw’ ijuru.\nNi ho mbon’ amahoro mu mutima,\nKugez’ ubw’ umusek’ uzatambika."}]},
  {"number": 440, "name": "Mutima Wanjye Singiza Imana", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/440", "key": "ré", "references": [{"codes": "SDAH. 4"}, {"title": "PRAISE, MY SOUL, THE KING OF HEAVEN"}], "body": [{"type": "verse", "number": 1, "content": "Mutima wanjye singiza Imana yo mw’ ijuru.\nIbabarir’ ibyaha, kand’ ikiz’ indwara zose;\nNta wahwany’ icyubahiro nawe Man’ ikomeye."}, {"type": "verse", "number": 2, "content": "Uwitek’ Imana yacu igir’ ibambe ryinshi!\nIrakiranuka, kand’ ic’ imanza zitabera.\nIkwiriy’ icyubahiro, Nihimbazw’ Aleluya."}, {"type": "verse", "number": 3, "content": "Idukingir’ ababisha, Iz’ intege nke zacu.\nTuri mu maboko yayo, Iturind’ abagome.\nNihimbazwe Aleluya! Igir’ impuhwe nyinshi."}, {"type": "verse", "number": 4, "content": "Bamarayika nimuze mudufashe kuramya,\nUmuremyi wahanz’ izub’ ukwezi n’ inyenyeri.\nIbyaremwe byose ni bisingiz’ uwo Muremyi."}]},
  {"number": 441, "name": "Namaramaje Gutaha", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/441", "key": "sol", "references": [{"codes": "HL. 96"}, {"title": "JE SUIS SCELLE POUR LA GLOIRE"}], "body": [{"type": "verse", "number": 1, "content": "Namaramaje gutaha mu gihugu cy’ ibyiza,\nIbyo mpora mvug’ iteka, N’ urukundo rwa Yesu."}, {"type": "chorus", "content": "Yesu n’ Umukunzi wanjye,\nTwarabisezeranye.\nArankunda ndamukunda,\nNk’ intama n’ umwungeri."}, {"type": "verse", "number": 2, "content": "Nari narapfuye rwose, Nta Mana nta cyizere!\nNazuts’ ubwo nabwirwaga ko Yesu yampfiriye!"}, {"type": "verse", "number": 3, "content": "Umutima winangira Yesu yawunkuyemo;\nYampay’ umutima mushya, Yesu ni w’ unyobora."}, {"type": "verse", "number": 4, "content": "Kuv’ ubwo nemeye Yesu, Nagiye ngeragezwa,\nAriko Umwami Yesu, Ni w’ umpesha kunesha."}, {"type": "verse", "number": 5, "content": "Mwami Yes’ udahemuka, Nyuzuzamw’ urukundo\nRuntere kugir’ umwete, Wo kugukurikira."}]},
  {"number": 442, "name": "Ugururira Yesu", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/442", "key": "ré bémol", "references": [{"codes": "S. 358"}, {"title": "OPEN WIDE THE DOOR"}], "body": [{"type": "verse", "number": 1, "content": "Ugururira Yesu araguhamagara, Ahagaze ku rugi umukingurire."}, {"type": "chorus", "content": "Sop: Mwugururire, Mwugururire.\nYaje kugucungura, Tyo mwugururire.\nAlto: Mwuguru… Mwugururire, Mwuguru… Mwugururire;\nYaje kugucungura, Mwuguru… Mwugururire.\nTenor: Mwugururire, Mwugururire; Mwugururire, Mwugururire.\nYaje kugucungura, Tyo mwugururire, Mwugururire.\nBass: Mwugururire, Mwugururire; Mwugururire, Mwugururire.\nYaje kugucungura, Mwugururire …rire."}, {"type": "verse", "number": 2, "content": "Kugira ngw’ agukize yatanz’ ubugingo bwe;\nYatsinz’ urupfu, none mwemer’ umwakire."}, {"type": "verse", "number": 3, "content": "Mwumv’ aracyakomanga, Mwiyegurire rwose.\nKingur’ umutima waw’ umwiyegurire."}, {"type": "verse", "number": 4, "content": "Tyo reka kuzarira wikwitesh’ amahirwe.\nWikwitesh’ agakiza ashaka kuguha."}]},
  {"number": 443, "name": "Nshuti Zanjye Munsabire", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/443", "key": "do", "references": [{"codes": "SDAH. 505"}, {"title": "I NEED THE PRAYERS"}], "body": [{"type": "verse", "number": 1, "content": "Ndi mu ntambar’ ikomeye, Intambara yo kwizera;\nNimunsabire ku Mana, Rwose nd’ uwo gusabirwa."}, {"type": "chorus", "content": "Nshuti zanjye munsabire,\nKugira ngo mbashe kunesha.\nNi munsabire ku Mana,\nRwose nd’ uwo gusabirwa."}, {"type": "verse", "number": 2, "content": "Ndi mu ntambar’ ikomeye, Intambara yo kwizera;\nNshuti zanjye bavandimwe, Muntwerer’ amasengesho."}, {"type": "verse", "number": 3, "content": "Buri gihe mba mpanganye n’ ibigeragezo byinshi;\nNdifuza kubashishwa kunyura mu nzir’ ifunganye."}]},
  {"number": 444, "name": "Har’ Icyo Nsobanukiwe", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/444", "key": "sol", "references": [{"codes": "S. 626"}, {"title": "SOMETHING EVERY HEART IS LOVING"}], "body": [{"type": "verse", "number": 1, "content": "Har’ icyo nsobanukiwe, Yes’ amp’ ikiruhuko.\nMwami nguy’ umutima wanjye, Uwitegekere."}, {"type": "verse", "number": 2, "content": "Iby’ isi mbisiz’ inyuma, Niberey’ uwa Yesu;\nAhebuj’ ibintu byose, Ni w’ ump’ umunezero."}, {"type": "verse", "number": 3, "content": "Arabagirana cyane, Akwiy’ icyubahiro;\nAgir’ urukundo rwinshi, N’ imbabazi n’ impuhwe."}, {"type": "verse", "number": 4, "content": "Yesu yarankunze cyane, Bitum’ aza kumpfira;\nKubw’ urukundo rw’ Imana, Se kuki ntamukunda?"}, {"type": "verse", "number": 5, "content": "Yesu ndakwiyeguriye, Nkomeza nkunambeho;\nUbuzima bwanjye bwose, Buhishwe muri wowe."}]},
  {"number": 445, "name": "Bigiye Gusobanuka", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/445", "key": "la bémol", "references": [{"codes": "S. 740"}, {"title": "SOME TIME WE’LL UNDERSTAND"}], "body": [{"type": "verse", "number": 1, "content": "Turi hafi kujy’ aheza, Mu gihugu cyiza cyane.\nNtituzongera kurira, Bigiye gusobanuka!"}, {"type": "chorus", "content": "Twiringir’ Imana gusa, Ntitugir’ ubwoba rwose.\nN’ ubwo duhura n’ ibiruhije, Bigiye gusobanuka!"}, {"type": "verse", "number": 2, "content": "Ibyiza twari twahombye, Tuzongera kubihabwa.\nMw’ ijuru tuzanezerwa, Bigiye gusobanuka!"}, {"type": "verse", "number": 3, "content": "Tuzamenya nez’ impamvu, Twahuraga n’ amakuba,\nIndirimbo zigatuza, Bigiye gusobanuka!"}, {"type": "verse", "number": 4, "content": "Ibijya bidushobera, Tukibaz’ impamvu yabyo,\nTukabur’ ibyiringiro, Bigiye gusobanuka!"}, {"type": "verse", "number": 5, "content": "Imana yac’ iz’ inzira, Ni y’ ifit’ urufunguzo,\nIzadukiz’ amarira, Bigiye gusobanuka!"}]},
  {"number": 446, "name": "Mwami W’ Amahanga Yose", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/446", "key": "do", "references": [{"codes": "SDAH. 588"}, {"title": "LORD OF ALL NATIONS"}], "body": [{"type": "verse", "number": 1, "content": "Mwami w’ amahanga yose, Uduhe gukunda bose;\nUturinde kurobanura, No kuvangurana mu moko."}, {"type": "verse", "number": 2, "content": "Kurah’ urusika Mwami, Rwabasha gutandukanya,\nAbana bawe wacunguye; Utugir’ umwe dukundane."}, {"type": "verse", "number": 3, "content": "Mwami ngusaby’ imbabazi, Nataniye mu bwanganyi;\nMfasha menye ibyaha byanjye, Ne kukubamb’ ubwa kabiri."}, {"type": "verse", "number": 4, "content": "Mbashisha kuvuganira, Abanyantege nke bose,\nBarenganwa ntibitabweho; Mpa gushikama mbavugire."}, {"type": "verse", "number": 5, "content": "Unyuzuz’ Umwuka Wera, Mbashe gukor’ ibikwiye,\nAho mba hos’ igihe cyose, Nkorah’ unkoresh’ ibikwiye."}]},
  {"number": 447, "name": "Nimuze Dushim’ Uwiteka", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/447", "key": "si bémol", "references": [{"codes": "SDAH. 112"}, {"title": "LET US WITH A GLADSOME MIND"}], "body": [{"type": "verse", "number": 1, "content": "Nimuze dushim’ Uwiteka, Kubw’ ibambe rye ryinshi!\nKukw’ ineza y’ ihoraho, N’ umurava w’ uhoraho!"}, {"type": "verse", "number": 2, "content": "Kandi ni w’ utegeka byose; Akwiz’ umucyo hose!\nKukw’ ineza y’ ihoraho, N’ umurava w’ uhoraho!"}, {"type": "verse", "number": 3, "content": "Ni w’ utung’ ibyaremwe byose, Ni w’ ubigaburira.\nKukw’ ineza y’ ihoraho, N’ umurava w’ uhoraho!"}, {"type": "verse", "number": 4, "content": "Nuko rero tumuhimbaze; Uwiteka ni mwiza!\nKukw’ ineza y’ ihoraho, N’ umurava w’ uhoraho!"}]},
  {"number": 448, "name": "Ninde Utegek’ Izuba", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/448", "key": "fa", "references": [{"codes": "HL. 22"}, {"title": "QUI DIT AU SOLEIL"}], "body": [{"type": "verse", "number": 1, "content": "Nind’ utegek’ izuba kuva, Rikamurikira abantu?\nMbese ninde utegek’ ijoro? N’ Uwiteka Imana yacu.\nN’ Uwiteka Imana yacu."}, {"type": "verse", "number": 2, "content": "Mbese ninde wahanz’ ijuru, Maz’ agahanik’ ikirere?\nNind’ ubashish’ ibyatsi gutoha? N’ Uwiteka Imana yacu.\nN’ Uwiteka Imana yacu."}, {"type": "verse", "number": 3, "content": "Nind’ ujy’ uduhoz’ amarira, Atuber’ Umuhumuriza?\nNind’ ufit’ ijambo rikomeye? N’ Uwiteka Imana yacu.\nN’ Uwiteka Imana yacu."}]},
  {"number": 449, "name": "Dusingize Yesu Nyir’ Ukunesha", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/449", "key": "do", "references": [{"codes": "HL. 214"}, {"title": "CHANTONS LA VICTOIRE"}], "body": [{"type": "verse", "number": 1, "content": "Dusingize Yesu Nyir’ ukunesha!\nYaratwitangiye tumuhimbaze.\nTwubur’ amaso turebe hejuru,\nTuzirikan’ urukundo rwa Yesu.\nKand’ urukundo rwe rurahanitse,\nUbwami bw’ Imana buri muri twe."}, {"type": "verse", "number": 2, "content": "Kand’ isi yac’ igez’ ahakomeye,\nDor’ amahoro rwos’ ayishizemo.\nIs’ ikeney’ umucy’ uva mw’ ijuru,\nTuyerek’ Umukiza Emanweli.\nBwoko bw’ Imana nitwitange rwose,\nTuvug’ ubutumwa twitange rwose."}, {"type": "verse", "number": 3, "content": "Tujy’ ahantu hose tubabwirize,\nHirya hino hakeney’ ubutumwa.\nBenshi ntacyo bazi cyo gucungurwa,\nBakwiriye kubwirw’ iby’ agakiza;\nBakameny’ ibyo gucungurwa kwabo.\nNimutyo dutwaze tubagereho."}, {"type": "verse", "number": 4, "content": "Abavugabutumwa bakeneye,\nAmasengesho n’ urukundo rwinshi.\nTubazirikane tubasabire,\nTubashyigikire, tubakomeze.\nYes’ agiye kuza mu cyubahiro,\nTwe kugir’ ubwoba tub’ abaneshi."}]},
  {"number": 450, "name": "Kera Ntabwo Nagutekerezaga", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/450", "key": "sol", "references": [{"codes": "S. 293"}, {"title": "ONCE MORE AT REST"}], "body": [{"type": "verse", "number": 1, "content": "Kera ntabwo nagutekerezaga, None nameny’ urukundo rwawe.\nKand’ umucyo wawe warandasiye, Nanjye nguhay’ umutima wanjye."}, {"type": "chorus", "content": "Mwami numvis’ Ijambo ryawe ryera,\nMaze numva rindemy’ umutima;\nUbwo nari ntafit’ ibyiringiro,\nIjambo ryawe riranyobora."}, {"type": "verse", "number": 2, "content": "Ubwo nari maze gucik’ intege, Iby’ isi bimaze kuncogoza,\nWarankomeje ngumya kukwizera; Mwam’ iby’ ushaka byose bibeho."}, {"type": "verse", "number": 3, "content": "Nimara kuger’ iwacu mw’ ijuru, Nzahora ndi mu rukundo rwawe.\nUmutima wanjye ntuzacogora, Ntabwo nzongera kuruh’ ukundi."}]},
  {"number": 451, "name": "Kwibera Hafi Ya Yesu", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/451", "key": "si bémol", "references": [{"codes": "SDAH. 310"}, {"title": "I WOULD DRAW NEARER TO JESUS"}], "body": [{"type": "verse", "number": 1, "content": "Kwibera hafi ya Yesu, Kwibera mu bwiza bwe;\nKwibera mu murimo we, ni bwo numva ntekanye."}, {"type": "chorus", "content": "Kwibera hafi ya Yesu,\nNi byo numva nifuza;\nBuri gihe mbane na we,\nMpore ndi kumwe na we."}, {"type": "verse", "number": 2, "content": "Kwibera hafi ya Yesu, Nta cyabasha kuntanya,\nN’ urukundo n’ ubuntu bye, Mpore hafi ya Yesu."}, {"type": "verse", "number": 3, "content": "Kwibera hafi ya Yesu, Mbasha gukiranuka;\nMbwir’ aband’ iby’ ineza ye, Nkurikiz’ iby’ ashaka."}]},
  {"number": 452, "name": "Mbeg’ Umuns’ Utey’ Ubwuzu", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/452", "key": "la bémol", "references": [{"codes": "GH. 108"}, {"title": "WHAT A DAY THAT WILL BE"}], "body": [{"type": "verse", "number": 1, "content": "Umunsi w’ ihozo dore uri bugufi;\nKurira, kuganya, gusuhuz’ umutima,\nBizatamururwaho, twibere mu mahoro.\nMbeg’ umuns’ uzab’ utey’ ubwuzu!"}, {"type": "verse", "number": 2, "content": "Mu bwami bw’ ijuru, nta marir’ azabayo;\nIgihu kizadutamuruka mu maso.\nTuzaba mu mahoro atagir’ impinduka.\nMbeg’ umuns’ uzab’ utey’ ubwuzu!"}]},
  {"number": 453, "name": "Senga", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/453", "key": "sol", "references": [{"codes": "GH. 15"}, {"title": "WHISPER A PRAYER"}], "body": [{"type": "verse", "number": 1, "content": "Senga mu gitondo kare,\nUjy’ usenga no ku manywa.\nSenga na nimugoroba,\nIman’ ihora yumva."}, {"type": "verse", "number": 2, "content": "Haba mu gitondo kare,\nHaba ndetse no ku manywa,\nHaba na nimugoroba,\nIman’ ihora yumva."}, {"type": "verse", "number": 3, "content": "Igih’ icy’ ari cyo cyose,\nYesu yakugenderera;\nAhor’ agutez’ amatwi,\nNtucogore gusenga."}]},
  {"number": 454, "name": "Iyo Ngenda Mba Ndi Kumwe N’ Imana", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/454", "key": "do", "references": [{"codes": "GH. 33"}, {"title": "MY GOD AND I"}], "body": [{"type": "verse", "number": 1, "content": "Iyo ngenda mba ndi kumwe n’ Imana,\nKandi tugenda twiganirira.\nTurasabana rwose, tukishima,\nN’ iyo haba mu mugaru mwinshi.\nTurasabana rwose, tukishima,\nIbihe byose turagendana."}, {"type": "verse", "number": 2, "content": "Inyibutsa amateka ya kera,\nUmugambi wabaye mw’ ijuru,\nWo kuncungura ngo mbon’ ubugingo.\nWabayeho jyewe ntarabaho,\nNjya kuremwa ntabwo byar’ impanuka,\nHabay’ umugambi wo kundema."}, {"type": "verse", "number": 3, "content": "Mw’ ijuru nzatemberana n’ Imana,\nDufatanye na yo mu biganza.\nIyi si turimo izakurwaho,\nNzabana n’ Iman’ iteka ryose.\nIyi si dutuyemw’ izakurwaho,\nHazaz’ indi tuzabamw’ iteka."}]},
  {"number": 455, "name": "Ndumv’ Ijwi Rinyongorera", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/455", "key": "do", "body": [{"type": "verse", "number": 1, "content": "Har’ ijwi rya Marayika, Rimbwira ryongorera.\nIryo jwi rirankomeza, Rinter’ ibyiringiro.\nN’ ubw’ ijoro ryegereje, N’ umurab’ ar’ icyago;\nBigiye gutamuruka, Maz’ umucy’ utangaze."}, {"type": "chorus", "content": "Sop: Ijwi numva, Rinter’ ibyiringiro;\nRinter’ ibyishimo, Mu – mu mutima.\nAlto: Ijwi numva, …jwi numva ry’ ihozo,\nRintera ibyiri – byiringiro;\nRinter’ ibyi – byishimo pe!\n…shimo mu mutima.\nTenor na Bass: Ijwi numva – mva ry’ ihozo,\nRintera ibyiri – byiringiro;\nRinter’ ibyi – byishimo pe!\n…shimo mu muti… mu mutima."}, {"type": "verse", "number": 2, "content": "No mu gihe cy’ akabwibwi, Umucy’ urengarenga;\nInyenyer’ ifit’ umucyo, Izamurika cyane.\nIjoro niribudika, Ntugir’ ubwoba rwose;\nHasigay’ igihe gito, Umucy’ ugatangaza."}, {"type": "verse", "number": 3, "content": "Ibyo byiringiro bitsika mu mutima wanjye;\nBitamurur’ umwijima, Umucy’ ugatangaza!\nIy’ Umwami yimye mu mutima waw’ ushavuye,\nIbyiringiro bishyitse biguma mu mutima."}]},
  {"number": 456, "name": "Yes’ Arankunda", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/456", "key": "sol", "references": [{"codes": "HL. 101"}, {"title": "M’ AIMANT …"}], "body": [{"type": "verse", "number": 1, "content": "Iy’ inzir’ icuz’ umwijima,\nYes’ aranyeger’ akambwira;\nAti: “Komera mwana wanjye,\nNdagukunda.”"}, {"type": "verse", "number": 2, "content": "Arankunda bihebuje pe!\nUrukundo rutadohoka.\nAmpaz’ umunezero mwinshi,\nArankunda!"}, {"type": "verse", "number": 3, "content": "Mu minsi mib’ arandengera,\nAkandwanaho mu makuba.\nAndokora mu byago byose,\nArankunda!"}, {"type": "verse", "number": 4, "content": "Ibyo mw’ isi birarangira,\nBikayonga bigashiraho.\nArik’ urukundo rwa Yesu,\nRuhoraho."}, {"type": "verse", "number": 5, "content": "Yaryamishijwe mu muvure,\nYabambwe no ku musaraba.\nNi jye yagiriraga rwose,\nArankunda."}, {"type": "verse", "number": 6, "content": "Kand’ azagaruka mu bicu,\nAje kunjyana iwe mw’ ijuru.\nTuzasingiz’ urukundo rwe,\nMu ndirimbo."}]},
  {"number": 457, "name": "Nd’ Umugenzi Mur’ Iyi Si", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/457", "key": "do", "references": [{"codes": "HL. 407"}, {"title": "PÈLERIN SUR CETTE TERRE"}], "body": [{"type": "verse", "number": 1, "content": "Nd’ umugenzi mur’ iyi si, Nerekeye mw’ ijuru;\nMu gihugu gihoramw’ umucy’ utazima!\nN’ ubwo ngoswe n’ abagome; N’ ubw’ is’ inyibasiye;\nNta cyambuza gukomeza, Yes’ arankunda!"}, {"type": "verse", "number": 2, "content": "Data wa twes’ arankunda, Kandi niw’ unyobora.\nAnkomereza kwizera, N’ ukuboko kwe.\nMu mugaru, mu bishuko, Mu gahinda mu byago;\nIjwi ry’ Umukiza wanjye rirankomeza."}, {"type": "verse", "number": 3, "content": "Gukorer’ Umwami nk’ uwo, Ntibigir’ uko bisa!\nNifuza kumumenya, Nkanamwigiraho.\nN’ ibyishimo bitavugwa; Umucunguzi wanjye,\nAzanyambutsa rwa ruzi, Ngere hakurya!"}, {"type": "verse", "number": 4, "content": "Ku cyambu gituje cyane, Ni ho ngiye kwambuka.\nNta marir’ azagerayo, Krist’ arahari!\nKand’ imibabaro yose, Tugirira mw’ iyi si;\nYes’ araje bidatinze, Adutabare."}]},
  {"number": 458, "name": "Wafashe Kamere Yanjye", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/458", "key": "sol", "references": [{"codes": "HL. 579"}, {"title": "TOI QUI VEUX ÊTRE NOTRE FRÈRE"}], "body": [{"type": "verse", "number": 1, "content": "N’ ubw’ ur’ Iman’ ikomey’ ite!\nWafashe kamere yanjye!\nMwami wumv’ isengesho ryanjye,\nUmwana wawe ngusaba."}, {"type": "verse", "number": 2, "content": "Uz’ intege nke zanjye Yesu!\nUzi amakub’ angose,\nUndinde kubw’ ineza yawe;\nMwunger’ utajy’ uzimiza."}, {"type": "verse", "number": 3, "content": "Kand’ inshyimbo n’ inkoni byawe,\nBihora bimpumuriza.\nNtacyo nzatinya Mwami\nMwiz’ ubwo ndi mu maboko yawe."}, {"type": "verse", "number": 4, "content": "Unyobora ku mazi meza,\nY’ ubugingo buhoraho.\nUrambohora ukankiza,\nMu maboko y’ umubisha!"}]},
  {"number": 459, "name": "Ndi Umukristo Ucumbitse Mur’ Iyi Si", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/459", "key": "fa", "references": [{"codes": "HL. 409"}, {"title": "POUR MOI CHRÉTIEN"}], "body": [{"type": "verse", "number": 1, "content": "Nd’ umukristo ncumbitse mw’ iyi si, Ku bwanjye byose ni byiza!\nN’ ubwo nsakirana n’ ingorane, Ku bwanjye byose ni byiza!\nKuki narira cyangwa nkinuba? Krist’ ari hamwe nanjy’ ibihe byose.\nNdi hafi yo kwigira mw’ ijuru; Ku bwanjye byose ni byiza!"}, {"type": "verse", "number": 2, "content": "N’ ubw’ amarir’ ari menshi mw’ isi, Ku bwanjye byose ni byiza!\nNdater’ intambwe ngan’ i Kanani, Ku bwanjye byose ni byiza!\nN’ ubw’ iyi s’ ibeshy’ abayituye, N’ ubw’ ishaka kumbabariz’ umutima;\nAmaso yanjye nyahanze Yesu; Ku bwanjye byose ni byiza!"}, {"type": "verse", "number": 3, "content": "Ndi hafi yo kugera ku ntego, Ku bwanjye byose ni byiza!\nNzahabw’ igihugu cy’ agakiza, Ku bwanjye byose ni byiza!\nIyi s’ iri hafi yo gushira, Mugenzi we! Komera wihangane.\nMu man’ uzahabw’ ikiruhuko; Ku bwanjye byose ni byiza!"}]},
  {"number": 460, "name": "Wow’ Uruhijwe N’ Iby’ Isi …", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/460", "key": "sol", "references": [{"codes": "HL. 524"}, {"title": "POUR TOI QU’ UN TOURMENT OPPRESSE …"}], "body": [{"type": "verse", "number": 1, "content": "Wow’ uruhijwe n’ iby’ is’ urushy’ umutima,\nNtuzi ko Yesu yakuruhur’ umutima?"}, {"type": "verse", "number": 2, "content": "Ko nkeneye Yesu Kristo, namubona nte?\nHang’ amaso ku musarab’ i Kaluvari."}, {"type": "verse", "number": 3, "content": "Mbes’ ikamba ry’ uwo Mwami rimeze rite?\nDore yambitsw’ ikamba ry’ amahwa ku bwawe."}, {"type": "verse", "number": 4, "content": "Mukurikiye mw’ iyi si bigenda bite?\nN’ ukwemera ukamunambaho by’ iteka."}, {"type": "verse", "number": 5, "content": "Mbes’ ukurikiy’ uwo Mwam’ azahabw’ iki?\nN’ amahoro adashira n’ umunezero."}, {"type": "verse", "number": 6, "content": "Mwami mwiza nkyumv’ ijwi ryawe ndakwitabye.\nUngir’ uwawe, nshyira mu bawe by’ iteka."}]},
  {"number": 461, "name": "Nyongerera Kwizera", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/461", "key": "la bémol", "references": [{"codes": "HL. 502"}, {"title": "OUI, JÉSUS C’EST VERS TOI"}], "body": [{"type": "verse", "number": 1, "content": "Mwami Yesu nyongerera kwizera.\nAkira kwizera kwanjye Yesu we!\nNyamururahw’ ibimboshye byose Mwami;\nUngeze ku rugero ruhanitse."}, {"type": "verse", "number": 2, "content": "Yesu ni wow’ umar’ umubabaro;\nNi wow’ unezez’ umutima wanjye!\nMu rugamba ndwana, urwany’ abankwena;\nUngeze ku rugero ruhanitse."}, {"type": "verse", "number": 3, "content": "Uzi nez’ icyifuzo cyanjye Mwami;\nNyongerera kwizera Mwami mwiza!\nMu mwijima w’ icuraburindi mfasha;\nMpore mbon’ umucyo wawe Yesu we!"}, {"type": "verse", "number": 4, "content": "Kristo Yes’ arambwir’ ati: Twarana!\nNtucik’ intege komez’ uhatane!\nAri hafi kuza kunjyana mw’ ijuru;\nAzanjyan’ iwe mw’ ijuru ahw’ aba!"}]},
  {"number": 462, "name": "Impano Y’ Ijuru", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/462", "key": "si bémol", "references": [{"codes": "HL. 126"}, {"title": "DON DU CIEL"}], "body": [{"type": "verse", "number": 1, "content": "Ngwino Soko y’ ubugingo, Ngwino Mpano y’ ijuru;\nUduhire Mwuka Wera, Duhishurire Kristo."}, {"type": "verse", "number": 2, "content": "Mwuka Wer’ ur’ urumuri, Ntacy’ ubasha guhishwa;\nNtacy’ usobwa, Mwuka Wera utuboneshereze."}, {"type": "verse", "number": 3, "content": "Utuyobore kwa Data, Tumusange twishimye;\nMu masengesho dusenga, Tuber’ Umuyobozi."}, {"type": "verse", "number": 4, "content": "Hindura byose bishyashya, Duhabwe gusa nawe!\nUzatugeze mw’ ijuru, Mu Bwami buhoraho."}]},
  {"number": 463, "name": "Wikwishimira Kunyura Inzira Mbi", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/463", "key": "mi", "references": [{"codes": "HL. 456"}, {"title": "LA ROUTE EST GLISSANTE"}], "body": [{"type": "verse", "number": 1, "content": "Wikwishimira kunyura inzira mbi;\nKandi Yes’ ari hw’ aguhamagara.\nWishaka kujya mu mwijima;\nNone itaba Yesu, Aragukunda."}, {"type": "verse", "number": 2, "content": "Kuki waremererwa n’ umutwaro,\nUkadandabiranwa n’ ubusinzi?\nYes’ arakiza, humura pe!\nUmva ubutumwa bwe, Maz’ umusange."}, {"type": "verse", "number": 3, "content": "Wabaye nk’ uburabyo bwumagaye;\nWagendanye n’ abanzi b’ ubutumwa;\nAriko Yesu ugukunda,\nMuh’ umutima wawe, Arawakira."}]},
  {"number": 464, "name": "Icyampa Ngahora Hafi Y’ Imana", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/464", "key": "do", "references": [{"codes": "AH. 268"}, {"codes": "CH. 322"}, {"title": "O, COULD I FIND FROM TODAY"}], "body": [{"type": "verse", "number": 1, "content": "Icyampa ngahora hafi y’ Imana ibihe byose;\nNgahora nibera mw’ Ijambo ryayo umunsi ku wundi."}, {"type": "verse", "number": 2, "content": "Mbe Mwami, nshaka kwibanira nawe ibihe byose;\nNi bwo ntazigera mbur’ amahoro umunsi ku wundi."}, {"type": "verse", "number": 3, "content": "Mwami ngwin’ ugeng’ umutima wanjye wugire mushya;\nUmpe kutazatandukana nawe iteka n’ iteka."}]},
  {"number": 465, "name": "Reb’ Umutim’ Ubabaye", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/465", "key": "sol", "references": [{"codes": "HL. 238"}, {"title": "REGARDE, ÂME ANGOISSÉE"}], "body": [{"type": "verse", "number": 1, "content": "Reb’ umutim’ ubabaye cyan’ i Kaluvari,\nReba Yes’ ari ku musaraba;\nYabambwe ku bwawe, Nta wundi yaziraga;\nNumureba urakira rwose!\nReba, Reba; Wizer’ imbabazi zituruk’ i Kalvari;\nTyo reba, Reba ku musaraba."}, {"type": "verse", "number": 2, "content": "Ujya wibaz’ impamvu Yesu yakubiswe,\nKand’ akambikwa n’ ikamba ry’ amahwa?\nN’ impamvu yabambw’ ari nta cyaha yakoze?\nTyo byibaze, Ubitekereze.\nReba, Reba; Yaragucunguye apfa mu cyimbo cyawe.\nTyo reba, Reba ku musaraba."}, {"type": "verse", "number": 3, "content": "Amarira n’ amaraso byawe ntibyashobora,\nKwez’ ibyaha byawe na gato.\nKeretse wizeye Yesu wakubambwiwe,\nNumwizera urakira rwose!\nReba, Reba Yes’ araguhanagur’ amarira Yose,\nTyo mwizer’ urakira rwose."}]},
  {"number": 466, "name": "Umusaruro Uratubutse", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/466", "key": "la", "references": [{"codes": "HL. 205"}, {"title": "OUI, LA MOISSON DU MONDE …"}], "body": [{"type": "verse", "number": 1, "content": "Dor’ umusarur’ uratubutse, Hakenewe abasaruzi.\nManur’ Umwuka wawe Mana, Twongerer’ abasaruzi.\nAhw’ abakozi bawe bari, Man’ ubah’ imigisha yawe."}, {"type": "verse", "number": 2, "content": "Ubambik’ imbarag’ ikomeye, Ubambike ukuri kwawe.\nBah’ umurava ku nshingano, Kandi bagir’ urukundo.\nAho bakwiriye hose, Man’ ubah’ imigisha yawe."}, {"type": "verse", "number": 3, "content": "Ijisho ryawe ribahoreho, Mu bihugu bakoreramo;\nImitim’ icishwe bugufi, Izanwe ku musaraba.\nUhire abakozi bawe, Man’ ubah’ imigisha yawe."}, {"type": "verse", "number": 4, "content": "Data tebutsa wa munsi mwiza, Wo kugaruka kw’ Umukiza.\nAmavi yos’ azapfukama, Indimi zigusingize!\nYes’ azahora yererezwa, Azahoran’ icyubahiro."}]},
  {"number": 467, "name": "Turi Ab’ Umwami Yesu", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/467", "key": "do", "references": [{"codes": "HL. 162"}, {"title": "NOUS SOMMES AU SEIGNEUR"}], "body": [{"type": "verse", "number": 1, "content": "Ntabwo tur’ abacu, Tur’ ab’ Umwami Yesu.\nYesu ni w’ utugenga, Twaramwiyeguriye;\nN’ aho rwab’ urupfu, Tuzamunambaho rwose;\nUmusaraba we, Ni wo tuzirata!"}, {"type": "verse", "number": 2, "content": "Icyubahiro cye, Kitugaragaremo;\nDupfe ku cyaha cyose, Duharanir’ ijuru.\nBaragwa b’ ijuru, Twer’ imbuto z’ abihannye;\nMureke twibere mu Man’ Ihoraho."}, {"type": "verse", "number": 3, "content": "Tw’ ab’ Umwami Yesu, Ntitugacik’ intege;\nN’ iyo twaba mu kaga cyangwa mu munezero;\nTuri kumwe na we nta kabuza tuzanesha!\nAzabana natwe ntazaturekura!"}]},
  {"number": 468, "name": "Tang’ Ubuto Bwawe", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/468", "key": "sol", "references": [{"codes": "AH. 238"}, {"codes": "CH. 270"}, {"title": "GIVE THY YOUTH TO GOD"}], "body": [{"type": "verse", "number": 1, "content": "Tang’ ubuto bwawe, Ukorer’ Imana;\nUmutima wawe wos’ uwegurir’ Imana."}, {"type": "verse", "number": 2, "content": "Uwitek’ ashaka umutima wawe,\nNumuh’ umutima waw’ araguh’ amahoro."}, {"type": "verse", "number": 3, "content": "Mu by’ ukora byose, Iman’ ib’ imbere;\nNa y’ izajy’ ikwikorerer’ imitwaro yawe."}]},
  {"number": 469, "name": "Turakuramya", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/469", "key": "si bémol", "references": [{"codes": "HL. 151"}, {"title": "NOUS T’ ADORONS …"}], "body": [{"type": "verse", "number": 1, "content": "Turakuramya Mwami udukunda; Dusonzey’ ukwera kwawe.\nMwami Nyir’ imigisha, Mwami mwiza,\nDukeneye kuzuzw’ urukundo; Tumurikirwe n’ ubwiza bwawe."}, {"type": "verse", "number": 2, "content": "Mwigisha mwiza utagereranywa; Uduhire, Mwam’ utweze.\nDuh’ umutima mushya, twiyoroshye.\nDukeneye kuzuzw’ urukundo; Tumurikirwe n’ ubwiza bwawe."}, {"type": "verse", "number": 3, "content": "Dusagiz’ urukundo rwawe Mwami; Urukundo rudashira.\nRuzan’ abanyabyaha kuri Yesu.\nDukeneye kuzuzw’ urukundo; Tumurikirwe n’ ubwiza bwawe."}, {"type": "verse", "number": 4, "content": "Mwam’ abazajya batubona bose, Batangare batubonye;\nDufit’ ubumwe nyabwo, dufatanya.\nDukeneye kuzuzw’ urukundo; Tumurikirwe n’ ubwiza bwawe."}, {"type": "verse", "number": 5, "content": "Wumve Mwami amasengesho yacu, Utwuzuz’ Umwuka wawe;\nTwigish’ Ijambo ryawe, turimenye.\nDukeneye kuzuzw’ urukundo; Tumurikirwe n’ ubwiza bwawe."}]},
  {"number": 470, "name": "Nta Ntwaro Dawidi Yajyanye", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/470", "key": "si bémol", "references": [{"codes": "HL. 567"}, {"title": "DAVID N’ AVAIT RIEN QUE SA FRONDE"}], "body": [{"type": "verse", "number": 1, "content": "Nta ntwaro Dawidi yajyanye, Guter’ umufilistiya!\nAtar’ umuhumetso we, Wahangamuy’ igihangange;\nCyasuzugurag’ Imana, Iman’ ikomeye y’ abisirayeli."}, {"type": "verse", "number": 2, "content": "Aratanya gusakirana n’ uwo mufilisitiya,\nWasuzugurag’ Imana, Ari na kw’ ayishongoraho.\nYitakumag’ atamenye ko Dawidi yatoranijwe n’ Imana."}, {"type": "verse", "number": 3, "content": "Dawidi nta gususumira, Asatira Goliyati.\nAreker’ ibuye rimwe, Rihitan’ icyo gihangange!\nImana yihesh’ ikuzo, Binyuze mu mwana mutoya Dawidi."}, {"type": "verse", "number": 4, "content": "Umwami Yes’ aragushaka, Ngo witabir’ urugamba;\nN’ ubwo wab’ umwana muto, Tinyuka winjir’ urugamba!\nUzaber’ is’ igihamya, K’ uri mu ruhande rw’ Iman’ idatsindwa."}, {"type": "verse", "number": 5, "content": "Nitugotwa n’ abanzi benshi, Turi hafi kugwabira;\nTujye ku mavi dusenge, Yesu ntazadutererana.\nYumv’ amasengesho yacu, Azatugir’ abaneshi ku rugamba."}]},
  {"number": 471, "name": "Yes’ Uradukunda!", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/471", "key": "sol", "references": [{"codes": "HL. 152"}, {"title": "TU NOUS AIMES, SEIGNEUR!"}], "body": [{"type": "verse", "number": 1, "content": "Yes’ uradukunda nka Data wa twese,\nKand’ urukundo rwawe, Ruradukomeza,\nIy’ imitim’ itentebutse.\nAmaraso yawe urayatwejesha; Kubw’ urukundo rwawe,\nWemeye kwitanga; Ni twe wagiriraga Mwami."}, {"type": "verse", "number": 2, "content": "Ugiye kugenda wasiz’ uvuz’ uti:\n“Muzajye mukundana nk’ uko nabakunze.”\nNta wakunda nkawe Mwami we!\nDuhe gukundana, Nk’uko wadukunze; Uduhe gufatanya,\nBitum’ is’ imenya, Y’ uko tur’ abana ba Yesu."}, {"type": "verse", "number": 3, "content": "Mbe, Mwami mwiza we! N’ iby’ igikundiro,\nY’ uko tugukorera, Dusengera hamwe,\nTwita no ku nshingano zacu.\nTwite ku murimo; Tuzi neza y’ uko uduhora bugufi,\nUkatubashisha gutungany’ inshingano zacu."}]},
  {"number": 472, "name": "Nje Kugushima", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/472", "key": "fa", "references": [{"codes": "AH. 42"}, {"title": "EVEN SONG"}], "body": [{"type": "verse", "number": 1, "content": "Nje kugushima Mwami Mana, Nkuzaniy’ ishimwe ryanjye;\nN’ ubw’ umwijima wabudika, Wow’ uramboneshereza.\nWangiz’ umwana wawe Mana, Unyitaho buri munsi;\nNi wowe soko y’ imigisha, Ngushimiy’ imigish’ umpa."}, {"type": "verse", "number": 2, "content": "Ngushimira k’ uhor’ undinda, N’ ukuboko kwawe Mana.\nIy’ umutim’ ucits’ intege, Unsubizamw’ imbaraga;\nIyo nabuze kivurira, Undwanah’ ukanduhura;\nDor’ ukuboko kw’ Uwiteka, Ntikwananiwe gukiza."}, {"type": "verse", "number": 3, "content": "Ngushimiy’ impuhw’ ungirira, Unkurahw’ ibicumuro.\nIy’ utambabarir’ ibyaha, Nari guhungira he se?\nData ntabwo nzagutenguha, Warankijije ndakira.\nMu maraso y’ Umwami Yesu, Ni ho mboner’ agakiza."}, {"type": "verse", "number": 4, "content": "Nzi neza rwos’ uwo nizeye, Ni we umboneshereza;\nNi we Gitare kinkingira, Ni we byiringiro byanjye;\nKabone n’ ubwo nacogozwa, Ntazabura kunyitaho.\nYampay’ ubugingo bw’ iteka, Nzajya mushimir’ iteka."}]},
  {"number": 473, "name": "Indirimbo N’ Amasengesho Byacu", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/473", "key": "ré bémol", "references": [{"codes": "HL. 153"}, {"title": "QUE NOS CHANTS ET NOS PRIÈRES"}], "body": [{"type": "verse", "number": 1, "content": "Indirimbo n’ amasengesho byacu bizamuke;\nIman’ ibyakire, Yo yatugiz’ abavandimwe."}, {"type": "verse", "number": 2, "content": "Kuko dufite Dat’ umwe, n’ Umwami wacu Yesu;\nMu kwizera, tuyoborwa n’ Umwuk’ umwe wa Kristo."}, {"type": "verse", "number": 3, "content": "Ibyiringiro bihire ni byo bidukomeza;\nKu rugamba tuyoborwa n’ urukundo rwa Yesu."}, {"type": "verse", "number": 4, "content": "Urwo rukundo ruganze, rudusabemo twese;\nRuduhuze, kandi rutume duhora twishimye!"}]},
  {"number": 474, "name": "Urukundo rwa Kristo", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/474", "key": "la", "references": [{"codes": "HL. 154"}, {"title": "L’ AMOUR DE JÉSUS - CHRIST"}], "body": [{"type": "verse", "number": 1, "content": "Urukundo rwa Kristo ruduhata;\nDore yitangiy’ umukumbi we.\nTumukurikire Ntama w’ Imana,\nTwese dufatanye ubudahwema."}, {"type": "verse", "number": 2, "content": "Tyo bavandimwe kubw’ Umucunguzi,\nMutyo dufatane mu biganza;\nTugendane kugeza kw’ iherezo;\nTubonesherejwe na Yesu Kristo."}, {"type": "verse", "number": 3, "content": "Data, turebe twebw’ abana bawe,\nTwiyeguriye Umwana wawe,\nNgwin’ udufashe utwuzuz’ Umwuka,\nDuh’ urukundo, twongerer’ umwete."}, {"type": "verse", "number": 4, "content": "Turitanze Mukiza utwakire;\nTugir’ umwe tube muri wowe.\nUture mu mitima yacu Mwami;\nMwuka Wer’ atwez’ atugire bashya."}]},
  {"number": 475, "name": "Twererez’ Umusaraba Mwiza", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/475", "key": "do", "references": [{"codes": "SDAH. 362"}, {"title": "LIFT HIGH THE CROSS"}], "body": [{"type": "chorus", "content": "Twererez’ umusaraba mwiza.\nTuvug’ urukundo rw’ Umwami Yesu"}, {"type": "verse", "number": 1, "content": "Muze bakristo, dukurikire,\nUmugaba wac’ Umwana w’ Imana."}, {"type": "verse", "number": 2, "content": "Tuyobowe n’ umusaraba we,\nNta shiti rwose tuzab’ abaneshi."}, {"type": "verse", "number": 3, "content": "Umusaraba n’ ikimenyetso,\nGifitwe n’ abavuts’ ubwa kabiri."}, {"type": "verse", "number": 4, "content": "Turirimbe cyane indirimbo,\nDusingize Uwatuneshereje."}]},
  {"number": 476, "name": "Dor’ Umwami Yes’ Araje", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/476", "key": "ré", "references": [{"codes": "SDAH. 211"}, {"title": "LO! HE COMES"}], "body": [{"type": "verse", "number": 1, "content": "Dor’ Umwami Yes’ araje; Nguy’ araje mu bicu!\nKand’ azanye n’ abamarayika batabarika.\nHalleluya, Halleluya; Yes’ aje kwim’ ingoma ye."}, {"type": "verse", "number": 2, "content": "Kand’ ijisho ryose rizabon’ icyubahiro Cye!\nKand’ abamubambye n’ abamutey’ imisumari;\nBazabon’ icyubahiro cye, Maze banyinyirirwe!"}, {"type": "verse", "number": 3, "content": "Ubw’ impand’ izavug’ ijuru n’ isi bizahunga!\nAbanze kwakira Yesu bazabur’ iyo bajya!\nKuk’ urubanza rukomeye rurabategereje."}, {"type": "verse", "number": 4, "content": "Mureke twese turamy’ Iman’ ishobora byose.\nNgwino Mwami, Dusonzey’ ingoma yaw’ itangaje!\nNgwino Mwami, Ngwino bwangu wimike ubwami bwawe."}]},
  {"number": 477, "name": "Umunsi Ku Wundi", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/477", "key": "fa", "references": [{"codes": "HL. 299"}, {"title": "JOUR APRÈS JOUR"}], "body": [{"type": "verse", "number": 1, "content": "Umunsi ku wundi turi mu rugendo;\nTuguman’ urukundo n’ ibyiringiro.\nMw’ ijoro riganje, Mu mwijima mwinshi,\nDukomez’ urugendo rujya mw’ ijuru,\nUmunsi ku munsi turukomeze."}, {"type": "verse", "number": 2, "content": "Umunsi ku wundi dukomez’ imbere;\nIbihe birahita ntibigaruka.\nDukomere kw’ Ijambo ry’ Imana yacu,\nRituyobore rinatumurikire;\nDukomez’ urugendo buri munsi."}, {"type": "verse", "number": 3, "content": "Umunsi ku munsi kugeza kw’ isonga;\nTwihangane ntituzasubir’ inyuma.\nBaturajuru n’ ubwo turi mw’ iyi si;\nYemwe basirikare b’ Umwami Yesu,\nDukomez’ urugendo buri munsi."}, {"type": "verse", "number": 4, "content": "Umunsi ku wundi tugamij’ ijuru;\nKugeza kuri wa munsi tuzataha,\nNi bwo tuzaragw’ ubugingo bw’ iteka.\nTuzahabw’ imigisha tutazanyagwa;\nDukomez’ urugendo buri munsi."}]},
  {"number": 478, "name": "Mu Gihe Itorero", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/478", "key": "si bémol", "references": [{"codes": "HL. 438"}, {"title": "OH! PENDANT QUE POUR EUX"}], "body": [{"type": "verse", "number": 1, "content": "For the last stanza"}, {"type": "verse", "number": 1, "content": "Mu gih’ itorero ririho risenga,\nRisabir’ abatoranijwe gukor’ inshingano,\nUbeze Mwam’ Imana, Ubah’ imbaraga,\nBayoborwe n’ Umwuka wawe!"}, {"type": "verse", "number": 2, "content": "Abatoranijwe n’ Umwami w’ abami,\nKwatura no guhamya mw’ izina ry’ Umwami Yesu;\nMwakir’ inshingano mwerejwe uyu munsi;\nMub’ indahemuka ku murimo wa Yesu,\nYes’ azabahira, azabashoboza."}, {"type": "verse", "number": 3, "content": "Iman’ ibambike imbaraga yayo,\nMwuzur’ Umwuka Wera, Ibambike imbaraga nshya;\nUyu munsi mwatangiy’ inshingano zanyu,\nIjuru riranezerewe cyane rwose,\nAriko Satani ntabwo abyishimiye."}, {"type": "verse", "number": 4, "content": "Muzirikane ko is’ itabakunze,\nIzahuriza hamw’ imbaraga zo kubarwanya;\nNtimugir’ ubwoba Yes’ azajy’ abarinda,\nNi we mutwe w’ itorer’ ubwe yihangiye;\nMuhore ku mavi nibwo muzanesha."}, {"type": "verse", "number": 5, "content": "Mwitegur’ imvune muzahura na zo,\nNi mugir’ urukundo kandi mugire kwizera,\nMurabukw’ ikamba mugiye kuzahabwa,\nNi mushir’ ubwoba, Mutsind’ urugamba,\nMw’ izina rya Yesu muzanesha rwose. Amen"}]},
  {"number": 479, "name": "Umwami W’ I Siyoni", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/479", "key": "ré", "references": [{"codes": "SDAH. 7"}, {"title": "THE LORD IN ZION REIGNETH"}], "body": [{"type": "verse", "number": 1, "content": "Umwami w’ i Siyoni ni w’ utegek’ isi;\nIsi yose yishim’ amav’ amupfukamire!\nImbere y’ intebe y’ ubuntu, Imitim’ iranezerwa,\nIkaruhuka, Mutyo mwese tumuramye."}, {"type": "verse", "number": 2, "content": "Umwami w’ i Siyoni ni w’ utegek’ isi;\nNta wahwanya n’ uwo Mwami gukomera rwose!\nImpera z’ isi, ikuzimu hamwe n’ inyanja zose,\nBiri mu biganza by’ uwo Mwami ukomeye!"}, {"type": "verse", "number": 3, "content": "Umwami w’ i Siyoni ni w’ utegek’ isi;\nNi we mugenga w’ ibihe, tumutaramire!\nTyo nimuze mu ngoro ye, Muririmbe mwese;\nMuze mu marembo ye mwishimye, mumupfukamire."}]},
  {"number": 480, "name": "Tweze Mwami Yesu", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/480", "key": "mi bémol", "references": [{"codes": "SDAH. 69"}, {"title": "LORD, MAKE US MORE HOLY"}], "body": [{"type": "verse", "number": 1, "content": "Tweze Mwami Yesu, Tweze Mwami Yesu;\nTweze Mwami Yesu, Kugez’ ubw’ uzatujyana."}, {"type": "verse", "number": 2, "content": "Tub’ abiringirwa, Mw’ izina rya Yesu;\nTub’ abiringirwa, Kugez’ ubw’ uzatujyana."}, {"type": "verse", "number": 3, "content": "Ducishwe bugufi, Mw’ izina rya Yesu;\nDucishwe bugufi, Kugez’ ubw’ uzatujyana."}, {"type": "verse", "number": 4, "content": "Twuzuz’ urukundo, Mw’ izina rya Yesu;\nTwuzuz’ urukundo, Kugez’ ubw’ uzagaruka;\nTumere nkawe Mwami, Kugez’ ubw’ uzatujyana."}]},
  {"number": 481, "name": "Singizwa Data", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/481", "key": "la bémol", "references": [{"codes": "SDAH. 70"}, {"title": "PRAISE YE FATHER"}], "body": [{"type": "verse", "number": 1, "content": "Data ugira neza, Mana yacu;\nMunyebambe nyinshi, Natw’ uratumenya!\nWowe usingizwa n’ abera bo mw’ ijuru;\nSingizwa Yehova!"}, {"type": "verse", "number": 2, "content": "Tuguhimbaze Murengezi wacu,\nUhor’ utwitaho, Twebw’ ubwoko bwawe!\nAbat’ abakuze, Inkumi n’ abasore;\nYesu we, Singizwa!"}, {"type": "verse", "number": 3, "content": "Mwuka Wera we! Turaguhimbaza!\nImana Data hamwe n’ Imana Mwana,\nBarakuduhaye ng’ utuber’ umufasha!\nMugiz’ Iman’ imwe!"}]},
  {"number": 482, "name": "Mwam’ Ushobora Byose", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/482", "key": "fa", "references": [{"codes": "SDAH. 71"}, {"title": "COME, THOU ALMIGHTY KING"}], "body": [{"type": "verse", "number": 1, "content": "Mwam’ ushobora byose, Duhe kukuririmbira;\nDuhimbaza, Dat’ usumba byose;\nNyir’ icyubahiro, Mutegeka wac’ ibihe byose."}, {"type": "verse", "number": 2, "content": "Mw’ Ijambo ryawe Mwami, Kandi ni ryo nkota yawe.\nMu gusenga, Hir’ ubwoko bwawe;\nHir’ Ijambo ryawe, Umwuka Wer’ atumanukire."}, {"type": "verse", "number": 3, "content": "Mwuka Wera w’ Imana, Ur’ Umuhamy’ ukomeye.\nMw’ uyu mwanya, Ngwin’ ubane natwe;\nTuragukeneye, Ngwino wuzur’ imitima yacu."}, {"type": "verse", "number": 4, "content": "Ur’ umwe mu Butatu, Uhor’ usingizwa Mana.\nNyakubahwa! Gahor’ usingizwa!\nIshimwe n’ iryawe! Tuzahora tukuramy’ iteka!"}]},
  {"number": 483, "name": "Nd’ Umukozi Mutoya", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/483", "key": "ré", "references": [{"codes": "HL. 566"}, {"title": "ME VOICI, JEUNE OUVRIER"}], "body": [{"type": "verse", "number": 1, "content": "Nd’ umukozi mutoya, Mwami ntiwankoresha?\nN’ ubwo nta ntege mfite, Ndagukunda cyane pe!\nMfit’ akaganza gato, Yesu ugakoreshe."}, {"type": "chorus", "content": "Nd’ umukozi mutoya;\nMwami ntiwankoresha?"}, {"type": "verse", "number": 2, "content": "Nigire buri munsi, Mu rukund’ udukunda;\nNgender’ imbere yawe, Nkuririmbire Mwami;\nMfat’ ikiganza Mwami, Uhor’ umpa gutsinda."}, {"type": "verse", "number": 3, "content": "Unyigishe gukunda, Mpa kwera no gutuza;\nUmpe ku Mwuka wawe, Umbemo buri gihe;\nMwigisha unyigishe, Kugukorera neza."}]},
  {"number": 484, "name": "Basirikare Ba Yesu …", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/484", "key": "fa", "references": [{"codes": "HL. 300"}, {"title": "VAILLANTS SOLDATS …"}], "body": [{"type": "verse", "number": 1, "content": "Basirikare ba Yesu, Tyo nimushikame, Tyo duhaguruke,\nTurwane tunezerewe; Dukurikiy’ Umwami Yesu."}, {"type": "chorus", "content": "Ngabo mwe, ngabo mwe! Nta mususu namba!\nTugire kwizera, Yes’ atur’ imbere.\nDore tugiye kuririmb’ indirimbo yo gucungurwa."}, {"type": "verse", "number": 2, "content": "Niduhura n’ ingorane, Tukumva turushye, Cyane tunaniwe;\nTwihangane duhangane, Ntitugwabire ku rugamba."}, {"type": "verse", "number": 3, "content": "Niba dukiz’ imitima, Byasaba kunyura mu marira menshi,\nDor’ ukuboko k’ Umukiza, Kuzaduhesha kunesha."}]},
  {"number": 485, "name": "Kwizera Gutum’ Inkike …", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/485", "key": "mi", "references": [{"codes": "HL. 301"}, {"title": "LA FOI"}], "body": [{"type": "verse", "number": 1, "content": "Kwizera gutum’ inkike ziriduka tubireba;\nKwizera gutuma tunesh’ urugamba rukomeye."}, {"type": "verse", "number": 2, "content": "Kwizera kutwugururir’ ubutunzi bukomeye;\nKwizera gutum’ abanyantege nke bab’ abatunzi."}, {"type": "verse", "number": 3, "content": "Dufit’ ingab’ ikomeye idukingir’ amakuba;\nTuri mu bwihisho bw’ Imana nta cyaduhungabanya."}]},
  {"number": 486, "name": "Bivuge Ku Musozi", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/486", "key": "fa", "references": [{"codes": "SDAH. 121"}, {"title": "GO TELL IT ON THE MOUNTAIN"}], "body": [{"type": "chorus", "content": "Bivuge ku musozi,\nBivuge hejuru ku tununga;\nBivuge ku musozi,\nYuko Yesu yavutse."}, {"type": "verse", "number": 4, "content": "Abungeri baragiy’ amatungo yabo,\nMw’ ijuru haz’ umucyo urabagirana."}, {"type": "verse", "number": 5, "content": "Bakibon’ ibyongibyo, Bamarwa n’ ubwoba;\nMarayik’ ababwira ko Yesu yavutse."}, {"type": "verse", "number": 6, "content": "Babony’ Umwana Yes’ aryamye mu muvure,\nBamutur’ amaturo, Bashim’ ivuka rye!"}]},
  {"number": 487, "name": "Yes’ Adusaba Kub’ Urumuri", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/487", "key": "mi bémol", "references": [{"codes": "CS. 501"}, {"title": "LIKE A LITTLE CANDLE"}], "body": [{"type": "verse", "number": 1, "content": "Yes’ adusaba kub’ urumuri;\nUmucyo ubonesha mu mwijima.\nTugomba kub’ umucyo w’ isi,\nMu midugudu y’ iwacu."}, {"type": "verse", "number": 2, "content": "Yes’ adusaba kujyan’ umucyo;\nHirya hino hose mu mpande z’ isi;\nBarababaye cyane rwose;\nTubagezeho umucyo."}, {"type": "verse", "number": 3, "content": "Bury’ iyo tumurikiy’ abandi,\nYesu ntacy’ ahishwa ab’ abireba;\nAho yibereye mw’ ijuru,\nBurya nta na kimw’ asobwa."}, {"type": "verse", "number": 4, "content": "Yesu n’ intwari, aradukunda;\nTub’ umucyo iyo tumurebyeho.\nTumurik’ umucyo we waka,\nHirya no hino mw’ iyi si."}]},
  {"number": 488, "name": "Mwami Yesu Nshimishwa …", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/488", "key": "la", "references": [{"codes": "HL. 508"}, {"title": "SEIGNEUR, MON ÂME SOUPIRE"}], "body": [{"type": "verse", "number": 1, "content": "Mwami Yesu nshimishwa no kub’ iruhande rwawe;\nNgateg’ amatw’ iby’ umbwira, Ndi ku birenge byawe."}, {"type": "chorus", "content": "Mpugura menye kugukorera,\nMukiza wanjye;\nMp’ Umwuka waw’ umbashishe,\nKubwiriz’ ubutumwa."}, {"type": "verse", "number": 2, "content": "Mwami Yesu ndagusabye, Nyuzuz’ Umwuka Wera;\nKand’ ibyaha byanjye byos’ ubitwikish’ umuriro."}, {"type": "verse", "number": 3, "content": "Mu cyanya cyawe gitoshye, Ab’ ari h’ unyobora;\nNd’ uwawe nd’ imbata yawe, Narakwiyeguriye."}]},
  {"number": 489, "name": "Kiruhuko Cyiza", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/489", "key": "mi bémol", "references": [{"codes": "HL. 170"}, {"title": "REPOS SI DOUX"}], "body": [{"type": "verse", "number": 1, "content": "Kiruhuko cyiza gihire, Twagabiwe n’ Umuremyi wacu;\nSabato we, mpano y’ akataraboneka! Munsi wuj’ amahoro!"}, {"type": "verse", "number": 2, "content": "Kiruhuko cyiza gihire, Duhishurirw’ ubwiza bw’ Imana;\nN’ iby’ Uwiteka yadukoreye, Sabato, muns’ uhebuj’ ubwiza!"}, {"type": "verse", "number": 3, "content": "Kiruhuko cyiza gihire, Kingurukanir’ intekerezo;\nZikagera hakurya mw’ ijuru, Iwabo w’ Umwami w’ amahoro."}, {"type": "verse", "number": 4, "content": "Sabato munsi wahiriwe, Munsi wera, muns’ urut’ iyindi;\nMu rugendo rugana mw’ ijuru, Twumva turuhutse mu mitima."}]},
  {"number": 490, "name": "Nd’ Umwana W’ Umwami", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/490", "key": "mi bémol", "references": [{"codes": "SDAH. 468"}, {"title": "A CHILD OF THE KING"}], "body": [{"type": "verse", "number": 1, "content": "Dat’ afit’ amazu menshi cyane; Kand’ akungahaye no ku masambu.\nAfit’ ubukungu bwinshi cyane, Zahabu na feza n’ umutungo we."}, {"type": "chorus", "content": "Nd’ umwana w’ Umwami! Yes’ Umukiza,\nNd’ umwana w’ Imana, Nd’ igikomangoma!"}, {"type": "verse", "number": 2, "content": "Yes’ Umwana w’ Iman’ Umukiza, Ni we Mucunguzi w’ abanyabyaha.\nUb’ ari mw’ ijur’ adusabira, Aradutegurir’ aho tuzaba."}, {"type": "verse", "number": 3, "content": "Nar’ igicibwa narazimiye, Nar’ umunyabyaha narazimiye;\nNone nagizw’ umwana w’ Imana, Nzambikw’ ikanzu yera de, n’ ikamba!"}, {"type": "verse", "number": 4, "content": "Mbese ni kuki nagir’ ubwoba; Ngw’ aha nta cumbi mfite mur’ iyi si!\nMfit’ ubutunzi nateguriwe, Ntacyo bintwaye nd’ igikomangoma!"}]},
  {"number": 491, "name": "Tuzabon’ Imana Mw’ Ijuru", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/491", "key": "la", "references": [{"codes": "HL. 394"}, {"title": "COMTEMPLER MON DIEU"}], "body": [{"type": "verse", "number": 1, "content": "Nzabon’ Imana mw’ ijuru, Yicaye ku ntebe y’ ubwami.\nKu birenge bya Yesu Mukiza, Ni ho nzarambik’ ikamba!"}, {"type": "chorus", "content": "Mw’ ijuru, Mw’ ijuru,\nTuzibanira na Yesu (mw’ ijuru);\nMw’ ijuru (mw’ ijuru), Mw’ ijuru kwa Yesu,\nTuzahoran’ ibyishimo!"}, {"type": "verse", "number": 2, "content": "Amajwi yac’ azab’ urwunge, N’ amajwi y’ abamarayika;\nTuzahora dusingiz’ Imana, Mu munezer’ udashira!"}, {"type": "verse", "number": 3, "content": "Tuzataramana n’ inshuti, Twari twaratandukanijwe;\nNtituzongera gutandukana, Tuzahoran’ ibyishimo."}, {"type": "verse", "number": 4, "content": "Tuzabon’ abera bakikij’ intebe y’ ubwami y’ Imana;\nTuzaban’ ubuziraherezo, Mu munezer’ uhoraho."}]},
  {"number": 492, "name": "Twinjire Mw’ Ishuri", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/492", "key": "sol", "references": [{"codes": "HL. 582"}, {"title": "ENTRONS À L’ ÉCOLE"}], "body": [{"type": "verse", "number": 1, "content": "Tyo twinjire mw’ ishuri, Mu munsi wera,\nTwig’ Ijambo ry’ Imana dushyizeh’ umwete.\nKuva tukiri batoya twibwir’ iby’ ijuru,\nKuk’ umwan’ uz’ ubwenge ahora yishimye."}, {"type": "verse", "number": 2, "content": "Dufungur’ igitabo cyera dusenge,\nTuramye Yes’ Umwam’ Umucunguzi wacu.\nYes’ utanga amahoro iyo tumwizeye,\nKand’ azajy’ atwigisha amategeko ye."}, {"type": "verse", "number": 3, "content": "Yes’ ubwe yagiz’ ati: Murek’ abana,\nBaze banyisangire, Kuko nkund’ abana.\nTuririmb’ icyubahiro cye giheranije;\nYuj’ urukundo rwinshi rw’ uwo Mwami mwiza."}]},
  {"number": 493, "name": "Uwiteka Mana, Data Mukiza", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/493", "key": "fa", "references": [{"codes": "HL. 308"}, {"title": "ETERNEL DIEU, MON SAUVEUR"}], "body": [{"type": "verse", "number": 1, "content": "Uwiteka Mana, Data Mukiza, Mpfukamy’ imbere yawe ngushima.\nNubwo nd’ umunyabyaha bikabije, Urankunda Data wera.\nUrukundo rwawe rwarancunguye, Rumvana mu bubata bw’ icyaha."}, {"type": "verse", "number": 2, "content": "Simfit’ ubwoba, mfit’ ibyiringiro, Wangiriy’ ubunt’ ump’ agakiza.\nNzahora ndirimbir’ Iman’ ishimwe, Rizamuke rigere mw’ ijuru;\nIndirimbo nziza y’ umunezero, Iger’ ahera cyane mw’ ijuru."}, {"type": "verse", "number": 3, "content": "Muze muvome kw’ isōko y’ ubuntu, Imitima yany’ ishir’ inyota.\nIbyaha byanyu mubibabarirwe, N’ Uwitek’ Imana y’ amahoro;\nMuzahabwa ubugingo bw’ iteka, N’ Iman’ itabera y’ amahoro!"}, {"type": "verse", "number": 4, "content": "Nimureke duhimbaz’ Uwiteka, Maze duhanik’ amajwi yacu!\nDutere hejuru tumusingize, Twogez’ izina rye rikomeye.\nTwamamaz’ impuhwe n’ imbabazi ze, N’ Iman’ ikomey’ ihabw’ ikuzo."}]},
  {"number": 494, "name": "Igihe Yesu Azahamagara Intore Ze", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/494", "key": "do", "references": [{"codes": "CS. 922"}, {"title": "WHAT A MEETING THAT WILL BE"}], "body": [{"type": "verse", "number": 1, "content": "Igihe Yes’ azahamagar’ intore ze,\nAkazijyan’ iwe, aho yaziteguriye;"}, {"type": "chorus", "content": "S. na B.: Tuzahurira mw’ ijuru kwa Data;\nMw’ ijuru heza, ni ho tuzahurira.\nA. na T.: Tuzahurira – hurirayo,\nMw’ ijuru ku Mana Data.\nN’ ahantu h’ icyubahiro,\nAho ni ho tuzahurira."}, {"type": "verse", "number": 2, "content": "Tuzahura n’ inshuti twari twaratanye,\nTuzahurira mw’ iteraniro rikomeye."}, {"type": "verse", "number": 3, "content": "Abahanuzi n’ abami tuzababona,\nN’ abahow’ Imana batigeze bayivaho."}, {"type": "verse", "number": 4, "content": "Tuzabon’ ubwiza bubengerana cyane;\nBw’ Uwitanze kugira ng’ umwizera adapfa."}]},
  {"number": 495, "name": "Ntabwo Nzaguhāna", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/495", "key": "mi bémol", "references": [{"codes": "CS. 697"}, {"title": "I WILL NEVER LEAVE THEE"}], "body": [{"type": "verse", "number": 1, "content": "Ntabwo nzaguhāna sinzakureka, Sinzagutererana na hato;\nNzahora nkurinda, nzajya nkurengera, Nzubahirish’ izina ryanjye,\nNd’ Uwiteka ntugir’ ubwoba, Umvira gus’ iby’ Iman’ ivuga."}, {"type": "verse", "number": 2, "content": "Umurab’ usheze nugotwa n’ ibyago, Utabaz’ Imana usenge,\nIzakubumbatiz’ amaboko yayo, Kand’ izakurind’ ikwiteho,\nMu bishuko nugeragezwa, Iman’ izajy’ ikwerek’ inzira."}, {"type": "verse", "number": 3, "content": "Nuhabw’ imigisha iva mw’ ijuru, Menya yukw’ Iman’ ikuba hafi,\nNiwumva wishimye ufit’ amahoro, iyo byose bigenda neza,\nUwiteka ntazakureka, Azajy’ arinda intambwe zawe."}, {"type": "verse", "number": 4, "content": "Igih’ ubugingo bugoswe n’ ijoro, nugotwa n’ ibicu komera.\nUwitek’ azajya akumurikira, azakuyobora mu mucyo!\nHumur’ urukundo rw’ Imana, Ntabwo ruzigera rukuvaho."}]},
  {"number": 496, "name": "Ndakwihaye", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/496", "key": "sol", "references": [{"codes": "HL. 497"}, {"title": "JE SUIS À TOI"}], "body": [{"type": "verse", "number": 1, "content": "Ndakwihaye ndakwiyeguriy’ ubu, Nkwishyize mu maboko unkoreshe!\nMber’ ingabo undinde abashaka gutuma ndeka kwizera kwanjye."}, {"type": "chorus", "content": "Yesu yarankijije kubw’ ubuntu;\nYes’ Umwami yameney’ amaraso;\nNdi hafi ye, na w’ ampora bugufi;\nIjwi rye rirankomeza cyane."}, {"type": "verse", "number": 2, "content": "Ndakwihaye umbabarir’ ibyaha, Bimveho ntibizongere kwibukwa;\nMuri Yesu byose bibe bishyashya, Uranyeze Mwami nere rwose."}, {"type": "verse", "number": 3, "content": "Nguhay’ impagarike n’ ubugingo, Sinkiri uwanjye ngira umwe nawe!\nUnyuzuz’ umuriro wawe waka, Maze nkugarurir’ inzimizi."}, {"type": "verse", "number": 4, "content": "Mwam’ utagereranywa ndakwihaye, Mbese nakwanga nte kugukorera?\nNubwo twasakirana n’ ibirushya, Ntuzajy’ ubura kuturengera."}]},
  {"number": 497, "name": "Nzogera Murangurure", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/497", "key": "fa", "references": [{"codes": "HL. 213"}, {"title": "CLOCHES, SONNEZ L’ÉVANGILE"}], "body": [{"type": "verse", "number": 1, "content": "Nzogera murangurure, Mutangaz’ ubutumwa!\nMu byaro mu mijyi hose, Humvikan’ indirimbo.\nDor’ Imana yakunz’ isi, Yatanz’ Umwana wayo,\nAza mw’ isi kudupfira, Is’ ishim’ iyo Mana."}, {"type": "chorus", "content": "Sop.: Nimurangurure, Muvug’ iby’ amahoro!\nNimurangurure, Nimuvug’ iby’ agakiza!\nA. T. na B.: Nimura-ngurure, Muvug’ iby’ amahoro!\nNimura-ngurure, Muvuge i - gakiza!"}, {"type": "verse", "number": 2, "content": "Nzogera nimutangaze ivuka ry’ Umukiza;\nKubw’ ineza yagiriye umunyabyaha wese.\nMubivug’ ahantu hose, N’ inkuru y’ imbabazi.\nIjuru n’ isi nibyamamaz’ iyo neza nyinshi."}, {"type": "verse", "number": 3, "content": "Mureb’ Umukiza Yesu, Mureb’ asuzugurwa,\nKand’ ar’ Umwana w’ Imana, Tukabon’ agakiza.\nYaducunguj’ amaraso ye y’ igiciro cyinshi;\nTurangurure tuvuge iby’ uko gucungurwa."}, {"type": "verse", "number": 4, "content": "Nimugende mujye hose, Mugere mw’ isi yose;\nMwingingir’ abigometse, Bagarukir’ Imana.\nDore bari mu makuba, Bakeney’ agakiza;\nBemer’ Umukiza Yesu, Abah’ umudendezo!"}]},
  {"number": 498, "name": "Muze Dusingiz’ Umwami Wacu", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/498", "key": "la bémol", "references": [{"codes": "HL. 287"}, {"title": "EXALTONS NOTRE DIVIN MAÎTRE"}], "body": [{"type": "verse", "number": 1, "content": "Muze dusingiz’ Umwami wacu, Wadukunze bitarondoreka!\nKumumenya bituma dutuza, Dore ni we Mwungeri wacu!"}, {"type": "chorus", "content": "S. na A.: Dusingiz’ Umucunguzi,\nYes’ Umwami, Nyir’ ukunesha!\nYaduhaye ibyishimo,\nN’ imigisha yo mw’ ijuru\nT. na B. : Dusingiz’ Umucunguzi, Mucunguz’ Umwami wacu,\nYes’ Umwami, Yes’ Umwami, Nyir’ u(ku)nesha, ukunesha!\nYaduhaye – yaduhaye ibyishimo – ibyishimo,\nN’ imigisha – n’ imigisha yo mw’ ijuru – yo mw’ ijuru."}, {"type": "verse", "number": 2, "content": "Mu byaha ndetse no mu bujiji, Tutizera nta byiringiro;\nYameny’ ibyacu aratwegera, Maz’ adukiz’ imibabaro."}, {"type": "verse", "number": 3, "content": "Yamurikiy’ imitima yacu, Tumenya nez’ ukuri kwera!\nMaz’ uwo Mwam’ ab’ Umuvandimwe; Yatuberey’ Umucunguzi."}, {"type": "verse", "number": 4, "content": "Ubu ntitugitwarwa n’ ubwoba, Kuko yaduciriy’ akanzu;\nDuhore dutez’ ijwi Ry’ amatwi, Ntabwo tuzigera tuyoba."}]},
  {"number": 499, "name": "Duhimbaze Yes’ Umucunguzi!", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/499", "key": "la bémol", "references": [{"codes": "CS. 226"}, {"title": "PRAISE HIM! PRAISE HIM!"}], "body": [{"type": "verse", "number": 1, "content": "Duhimbaze Yes’ Umucunguzi wacu, Twamamaze twes’ urukundo rwe!\nAfit’ icyubahiro giheranije, Izina rye ryera niryubahwe!\nNk’ uk’ umwungeri arind’ umukumbi we, Ni ko Yesu arind’ abana be!\nDuhimbaze Yes’ Umucunguzi wacu, Twamamaze twes’ urukundo rwe!"}, {"type": "verse", "number": 2, "content": "Duhimbaze Yes’ Umucunguzi wacu, Watubabarijw’ akadupfira!\nNi we Gitare cy’ ibyiringiro byacu, By’ agakiza gahorahw’ iteka.\nYikorey’ imibabaro yacu yose, Kubw’ urukundo rwe rwinshi cyane.\nDuhimbaze Yes’ Umucunguzi wacu, Watubabarijw’ akadupfira!"}, {"type": "verse", "number": 3, "content": "Duhimbaze Yes’ Umucunguzi mwiza, Mw’ ijur’ indirimbo zihanikwe!\nYaranesheje rwose yambay’ ikamba, N’ Umutware Nyir’ icyubahiro!\nDor’ agiye kugaruka bidatinze, Abengerana mu cyubahiro.\nDuhimbaze Yes’ Umucunguzi mwiza, Mw’ ijur’ indirimbo zihanikwe!"}]},
  {"number": 500, "name": "Ku Marembo Y’ Ijuru", "url": "https://indirimbo.rw/song/sdah-kinyarwanda/500", "key": "la bémol", "references": [{"codes": "GH. 114"}, {"title": "THE EASTERN GATE"}], "body": [{"type": "verse", "number": 1, "content": "Tuzahura mu gitondo, Ku marembo y’ ijuru;\nB’ umugenzi wo kwizerwa, Utazakerererwa."}, {"type": "chorus", "content": "Sop. : Tuzahura mu gitondo,\nDuhurire kw’ irembo ry’ ijuru.\nTuzahura mu gitondo,\nDuhurire mw’ ijuru mu byishimo.\nA., T. na B. : Tuzahura mu gitondo, Mu gitondo, mu gitondo,\nDuhurire kw’ irembo ry’ ijuru (ry’ ijuru).\nTuzahura mu gitondo, Mu gitondo, mu gitondo,\nDuhurire mw’ ijuru mu byishimo."}, {"type": "verse", "number": 2, "content": "Nimutebutse kuza kwe, Mwe gutinda mu nzira;\nDor’ araza mu gitondo, Aradutegereje."}, {"type": "verse", "number": 3, "content": "Rek’ umucyo wawe wake, Yes’ arategereje.\nTuzabana na w’ iteka, Mw’ iteraniro ryiza!"}, {"type": "verse", "number": 4, "content": "Naza n’ ibyishimo byinshi, Ku marembo y’ ijuru;\nMbeg’ iteraniro ryiza, Turi kumwe n’ abera!"}]}
];

export default songs;
